INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-1','The lion and the rabbit','Sư tử và thỏ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_001.mp3',NULL,'00:00:00.000','00:02:11.000','4000-essential-english-words','YES',1) */
	('The lion and the rabbit','Sư tử và thỏ','00:00:00.960','00:00:03.800','4000-essential-english-words-1'),
	('A cruel lion lived in the forest','Một con sư tử hung ác sống trong khu rừng','00:00:03.800','00:00:06.900','4000-essential-english-words-1'),
	('Every day, he killed and ate a lot of animals','Mỗi ngày, nó giết và ăn thịt rất nhiều loài động vật','00:00:06.900','00:00:11.300','4000-essential-english-words-1'),
	('The other animals were afraid the lion would kill them all','Các loài động vật khác sợ rằng sư tử sẽ giết tất cả chúng','00:00:11.300','00:00:16.400','4000-essential-english-words-1'),
	('The animals told the lion','Các loài động vật nói với sư tử','00:00:16.400','00:00:18.800','4000-essential-english-words-1'),
	('"Let\'s make a deal"','"Chúng ta hãy thỏa thuận đi"','00:00:18.800','00:00:20.400','4000-essential-english-words-1'),
	('"If you promise to eat only one animal each day, then one of us will come to you every day"','"Nếu như ngài hứa chỉ ăn một con vật mỗi ngày, thì một trong số chúng tôi sẽ đến gặp ngài mỗi ngày"','00:00:20.400','00:00:27.900','4000-essential-english-words-1'),
	('"Then you don\'t have to hunt and kill us"','"Nên là ngài không cần phải đi săn và giết chúng tôi nữa"','00:00:27.900','00:00:31.400','4000-essential-english-words-1'),
	('The plan sounded well thought out to the lion, so he agreed, but he also said "If you don\'t come every day, I promise to kill all of you the next day"','Kế hoạch nghe có vẻ tính toán khá ổn với sư tử, nên nó đã đồng ý, nhưng nó cũng nói rằng: "Nếu các người không đến mỗi ngày, ta thề rằng sẽ giết tất cả các ngươi vào ngày hôm sau"','00:00:31.400','00:00:43.800','4000-essential-english-words-1'),
	('Each day after that, one animal went to the lion so that the lion could eat it','Mỗi ngày kể từ đó, một con vật lại đến gặp sư tử để cho sư tử có thể ăn thịt','00:00:43.800','00:00:50.000','4000-essential-english-words-1'),
	('Then, all the other animals were safe','Thế là, tất cả các loài vật khác đều an toàn','00:00:50.000','00:00:53.400','4000-essential-english-words-1'),
	('Finally, it was the rabbit\'s turn to go to the lion','Cuối cùng, đến lượt thỏ đi gặp sư tử','00:00:53.400','00:00:58.000','4000-essential-english-words-1'),
	('The rabbit went very slowly that day, so the lion was angry when the rabbit finally arrived','Ngày hôm đó, thỏ đi rất chậm, nên là sư tử rất tức giận khi thỏ cuối cùng cũng đến','00:00:58.000','00:01:05.800','4000-essential-english-words-1'),
	('The lion angrily asked the rabbit, "Why are you late?"','Sư tử giận dữ hỏi thỏ: "Tại sao mày đến muộn?"','00:01:05.800','00:01:10.600','4000-essential-english-words-1'),
	('"I was hiding from another lion in the forest"','"Tôi đang trốn khỏi một con sư tử khác trong rừng"','00:01:10.600','00:01:14.400','4000-essential-english-words-1'),
	('"That lion said he was the king, so I was afraid"','"Con sư tử đó nói nó là vua, vậy nên tôi sợ hãi"','00:01:14.400','00:01:19.000','4000-essential-english-words-1'),
	('The lion told the rabbit, "I am the only King here"','Sư tử bảo thỏ: "Ta là vị vua duy nhất ở đây"','00:01:19.100','00:01:23.700','4000-essential-english-words-1'),
	('"Take me to that other lion, and I will kill him"','Hãy dẫn ta đến chỗ con sư tử kia, và ta sẽ giết nó','00:01:23.700','00:01:28.000','4000-essential-english-words-1'),
	('The rabbit replied, "I will be happy to show you where he lives"','Thỏ đáp lại: "Tôi rất vui cho ngài biết nơi hắn ta sống"','00:01:28.000','00:01:33.200','4000-essential-english-words-1'),
	('The rabbit led the lion to an old well in the middle of the forest','Thỏ dẫn sư tử đến một cái giếng cũ ở giữa khu rừng','00:01:33.200','00:01:38.300','4000-essential-english-words-1'),
	('The well was very deep with water at the bottom','Cái giếng rất sâu và có nước ở đáy','00:01:38.300','00:01:42.000','4000-essential-english-words-1'),
	('The rabbit told the lion, "Look in there"','Thỏ bảo sư tử: "Ngài hãy nhìn vào đây"','00:01:42.000','00:01:45.200','4000-essential-english-words-1'),
	('"The lion lives at the bottom"','Con sư tử đó sống ở dưới đáy','00:01:45.200','00:01:47.600','4000-essential-english-words-1'),
	('When the lion looked in the well, he could see his own face in the water','Khi sư tử nhìn vào giếng, nó có thể thấy khuôn mặt của chính mình trong nước','00:01:47.600','00:01:53.400','4000-essential-english-words-1'),
	('He thought that was the other lion','Nó tưởng đó là con sư tử kia','00:01:53.400','00:01:56.200','4000-essential-english-words-1'),
	('Without waiting another moment, the lion jumped into the well to attack the other lion','Không chờ đợi thêm giây phút nào khác nữa, sư tử nhảy xuống giếng để tấn công con sư tử kia','00:01:56.200','00:02:02.500','4000-essential-english-words-1'),
	('He never came out','Nó không bao giờ thoát ra được nữa','00:02:02.500','00:02:04.500','4000-essential-english-words-1'),
	('All of the other animals in the forest were very pleased with their rabbit\'s clever trick','Tất cả các loài vật khác trong rừng đều rất hài lòng với mưu kế thông minh của thỏ','00:02:04.500','00:02:11.000','4000-essential-english-words-1'),

	/* (UUID(),'4000-essential-english-words-2','The laboratory','Phòng thí nghiệm','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_002.mp3',NULL,'00:00:00.000','00:02:13.800','4000-essential-english-words','YES',2) */
	('The laboratory','Phòng thí nghiệm','00:00:00.960','00:00:03.000','4000-essential-english-words-2'),
	('Mia\'s father had a laboratory, but she had no idea what was in it','Bố của Mia có một phòng thí nghiệm, nhưng cô bé không biết có thứ gì bên trong đó','00:00:03.000','00:00:08.600','4000-essential-english-words-2'),
	('Her dad always closed and locked the door when he went in','Bố cô ấy luôn đóng và khóa cửa khi ông đi vào','00:00:08.600','00:00:13.000','4000-essential-english-words-2'),
	('She knew that he used it to do projects for work','Cô bé biết rằng ông dùng nó để làm các dự án dành cho công việc','00:00:13.000','00:00:16.400','4000-essential-english-words-2'),
	('He never told Mia what these projects were','Ông chưa bao giờ nói cho Mia biết những dự án đó là gì','00:00:16.400','00:00:20.400','4000-essential-english-words-2'),
	('One night, Mia approached the door to the laboratory','Một đêm nọ, Mia tiến đến gần cửa phòng thí nghiệm','00:00:20.400','00:00:24.800','4000-essential-english-words-2'),
	('She stopped and thought, "I wonder what crazy experiment he is doing now?"','Cô bé dừng lại và nghĩ, "Mình thắc mắc là bố đang làm thí nghiệm điên rồ gì bây giờ nhỉ?"','00:00:24.800','00:00:30.200','4000-essential-english-words-2'),
	('Suddenly, she heard a loud noise','Bỗng nhiên, cô bé nghe thấy một tiếng động lớn','00:00:30.200','00:00:33.000','4000-essential-english-words-2'),
	('It sounded like an evil laugh','Nghe như là một tiếng cười nham hiểm','00:00:33.000','00:00:35.800','4000-essential-english-words-2'),
	('The noise scared her, so she walked quickly back to her room','Tiếng động làm cô bé hoảng sợ, vậy là cô bé bước nhanh về phòng của mình','00:00:35.800','00:00:40.600','4000-essential-english-words-2'),
	('The next night, her friend Liz came to her house','Đêm hôm sau, bạn của cô bé, Liz, đến nhà cô','00:00:40.600','00:00:44.300','4000-essential-english-words-2'),
	('When Liz arrived, Mia told her about the night before','Khi Liz tới, Mia kể cho cô bé nghe về chuyện tối hôm trước','00:00:44.300','00:00:48.300','4000-essential-english-words-2'),
	('"Oh, it was terrible," she said','"Ôi, thật kinh khủng," cô bé nói','00:00:48.300','00:00:52.000','4000-essential-english-words-2'),
	('"Why don\'t we see what is in there?" Liz asked','"Sao chúng ta không vào xem trong đó có gì nhỉ?" Liz hỏi','00:00:52.000','00:00:56.000','4000-essential-english-words-2'),
	('"It will be a fun adventure"',' "Đó sẽ là một cuộc phiêu lưu thú vị"','00:00:56.000','00:00:58.700','4000-essential-english-words-2'),
	('Mia felt nervous about going into her father\'s laboratory, but she agreed','Mia cảm thấy lo lắng khi bước vào phòng thí nghiệm của cha mình, nhưng rồi cô bé đã đồng ý','00:00:58.700','00:01:04.000','4000-essential-english-words-2'),
	('As always, the door was locked','Như mọi khi, cửa đã bị khóa','00:01:04.000','00:01:06.600','4000-essential-english-words-2'),
	('They waited until Mia\'s father left the laboratory to eat dinner','Hai người đợi tới khi cha của Mia rời khỏi phòng thí nghiệm để ăn tối','00:01:06.600','00:01:10.800','4000-essential-english-words-2'),
	('"He didn\'t lock the door" Liz said',' "Ông ấy không khóa cửa kìa" Liz nói','00:01:10.800','00:01:13.900','4000-essential-english-words-2'),
	('"Let\'s go"','"Đi nào"','00:01:13.900','00:01:15.300','4000-essential-english-words-2'),
	('The laboratory was dark','Phòng thí nghiệm thì tối om','00:01:15.300','00:01:17.600','4000-essential-english-words-2'),
	('The girls walked down the stairs carefully',' Hai cô bé bước xuống cầu thang một cách cẩn thận','00:01:17.600','00:01:20.800','4000-essential-english-words-2'),
	('Mia smelled strange chemicals','Mia ngửi thấy mùi hóa chất lạ','00:01:20.800','00:01:23.400','4000-essential-english-words-2'),
	('What terrible thing was her father creating?','Có thứ gì đó rất khủng khiếp mà bố cô ấy đang tạo ra?','00:01:23.400','00:01:26.800','4000-essential-english-words-2'),
	('Suddenly, they heard an evil laugh','Bất chợt, họ nghe thấy tiếng cười độc ác','00:01:26.800','00:01:30.200','4000-essential-english-words-2'),
	('It was even worse than the one Mia heard the night before','Thậm chí còn tệ hơn cả tiếng cười mà Mia nghe thấy đêm hôm trước','00:01:30.200','00:01:34.000','4000-essential-english-words-2'),
	('What if a monster was going to kill them?','Nếu như một con quái vật sắp giết họ thì sao nhỉ?','00:01:34.000','00:01:37.200','4000-essential-english-words-2'),
	('Mia had to do something','Mia buộc phải làm gì đó','00:01:37.200','00:01:39.000','4000-essential-english-words-2'),
	('She shouted for help','Cô bé hét lên cầu cứu','00:01:39.000','00:01:40.800','4000-essential-english-words-2'),
	('Mia\'s father ran into the room and turned on the lights','Cha của Mia chạy vào phòng và bật đèn','00:01:40.800','00:01:44.100','4000-essential-english-words-2'),
	('"Oh, no," he said','"Ôi, không," ông ấy nói','00:01:44.100','00:01:46.600','4000-essential-english-words-2'),
	('"You must have learned my secret"','Con hẳn là đã biết bí mật của bố rồi','00:01:46.600','00:01:49.400','4000-essential-english-words-2'),
	('"Your monster tried to kill us," Mia said','"Con quái vật của bố đã cố giết chúng ta," Mia nói','00:01:49.400','00:01:52.900','4000-essential-english-words-2'),
	('"Monster?" he asked',' "Quái vật nào? ông ấy hỏi','00:01:53.040','00:01:55.500','4000-essential-english-words-2'),
	('"You mean this?"','"Ý con là gì?"','00:01:55.500','00:01:57.300','4000-essential-english-words-2'),
	('He had a pretty doll in his hands','Ông có một con búp bê xinh đẹp trong tay','00:01:57.300','00:02:00.000','4000-essential-english-words-2'),
	('The doll laughed','Con búp bê cười','00:02:00.000','00:02:01.400','4000-essential-english-words-2'),
	('The laugh didn\'t sound so evil anymore','Tiếng cười nghe không còn độc ác nữa','00:02:01.400','00:02:04.800','4000-essential-english-words-2'),
	('"I made this for your birthday"','"Bố làm cái này cho sinh nhật con"','00:02:04.800','00:02:07.300','4000-essential-english-words-2'),
	('"I wanted to give it to you then, but you can have it now"','"Bố muốn tặng nó cho con sau, nhưng con có thể nhận nó ngay bây giờ"','00:02:07.300','00:02:11.360','4000-essential-english-words-2'),
	('"I hope you like it"','"Bố hi vọng con thích nó"','00:02:11.360','00:02:13.800','4000-essential-english-words-2'),

	/* (UUID(),'4000-essential-english-words-3','The report','Báo cáo','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_003.mp3',NULL,'00:00:00.000','00:02:11.000','4000-essential-english-words','YES',3) */
	('The report','Báo cáo','00:00:00.960','00:00:02.800','4000-essential-english-words-3'),
	('Lee sat among the books at the library and thought about his group project','Lee ngồi giữa những cuốn sách trong thư viện và nghĩ về dự án của nhóm mình','00:00:02.800','00:00:08.700','4000-essential-english-words-3'),
	('They had to turn it in soon, but he hadn\'t even started his part','Họ phải nộp sớm, nhưng cậu ta thậm chí còn chưa bắt đầu phần của mình','00:00:08.700','00:00:13.700','4000-essential-english-words-3'),
	('Jack and Claire were in his group','Jack và Claire ở trong nhóm của cậu','00:00:13.700','00:00:16.900','4000-essential-english-words-3'),
	('They had worked hard','Họ đã làm việc rất chăm chỉ','00:00:16.900','00:00:18.500','4000-essential-english-words-3'),
	('They were also very smart and Lee didn\'t want them to get a bad grade','Họ cũng rất thông minh và Lee không muốn họ bị điểm kém','00:00:18.500','00:00:24.000','4000-essential-english-words-3'),
	('Jack did the report','Jack đã làm báo cáo','00:00:24.000','00:00:25.900','4000-essential-english-words-3'),
	('He wrote a lot of very good sentences and described things with great adjectives','Cậu ấy đã viết nhiều câu từ rất hay và miêu tả mọi thứ với những tính từ tuyệt vời','00:00:25.900','00:00:32.000','4000-essential-english-words-3'),
	('Claire drew a nice map of the stars','Claire thì vẽ một bản đồ với những ngôi sao rất đẹp','00:00:32.000','00:00:35.000','4000-essential-english-words-3'),
	('Now, Lee needed to do his part of the project','Bây giờ, Lee cần hoàn thành phần dự án của mình','00:00:35.000','00:00:38.700','4000-essential-english-words-3'),
	('"Well, I suppose I need to start my model," Lee thought','"Chà, tôi cho là mình cần phải bắt đầu mô hình của mình," Lee nghĩ','00:00:38.700','00:00:43.400','4000-essential-english-words-3'),
	('Making a model of a planet was really hard','Làm mô hình một hành tinh thật sự rất khó','00:00:43.400','00:00:47.000','4000-essential-english-words-3'),
	('Lee tried to read several books, but he couldn\'t comprehend any of the charts','Lee đã cố gắng đọc một vài cuốn sách, nhưng cậu ấy không thể hiểu bất kỳ một biểu đồ nào','00:00:47.000','00:00:53.000','4000-essential-english-words-3'),
	('"We\'re going to fail because of me" Lee said','"Chúng ta sẽ thất bại vì mình mất thôi" Lee nói','00:00:53.000','00:00:57.500','4000-essential-english-words-3'),
	('He put his head down on the table and said, "I wish I could see a planet, instead of having to read about it"','Cậu ấy gục đầu xuống bàn và nói, "Ước gì mình có thể nhìn thấy một hành tinh, thay vì phải đọc về nó"','00:00:57.500','00:01:05.800','4000-essential-english-words-3'),
	('Suddenly, there was a bright light','Đột nhiên, có một ánh sáng chói lòa','00:01:05.800','00:01:09.000','4000-essential-english-words-3'),
	('Lee was pulled from his chair, through the roof, and right into a strange ship','Lee bị kéo khỏi ghế, xuyên qua mái nhà, và chạm ngay vào một con tàu kỳ lạ','00:01:09.000','00:01:15.500','4000-essential-english-words-3'),
	('"Hello, kid," said an alien','"Xin chào, nhóc," một người ngoài hành tinh nói','00:01:15.500','00:01:18.000','4000-essential-english-words-3'),
	('"Did you ask for help?"','"Cậu cần giúp đỡ có phải không?"','00:01:18.000','00:01:19.800','4000-essential-english-words-3'),
	('Lee told the friendly alien all about his project','Lee kể cho người ngoài hành tinh thân thiện tất cả về dự án của mình','00:01:19.900','00:01:24.500','4000-essential-english-words-3'),
	('The alien agreed to help Lee solve his problem','Người ngoài hành tinh đồng ý giúp Lee giải quyết vấn đề của cậu ta','00:01:24.500','00:01:28.000','4000-essential-english-words-3'),
	('"First, we\'ll fly through space to view the universe"',' "Đầu tiên, chúng ta sẽ bay qua không gian để ngắm nhìn vũ trụ"','00:01:28.000','00:01:31.760','4000-essential-english-words-3'),
	('"Then, I can help you make a model of my planet"','"Sau đó, tôi có thể giúp cậu làm mô hình hành tinh của tôi"','00:01:31.830','00:01:35.700','4000-essential-english-words-3'),
	('Soon, they were going through the clouds','"Chẳng mấy chốc, họ đã đi qua những đám mây"','00:01:35.700','00:01:38.700','4000-essential-english-words-3'),
	('They passed the moon','Họ đã đi qua mặt trăng','00:01:38.700','00:01:40.210','4000-essential-english-words-3'),
	('Then they viewed Mars','Sau đó, họ đã ngắm nhìn sao Hỏa','00:01:40.270','00:01:42.300','4000-essential-english-words-3'),
	('Lee was very excited','Lee rất háo hức','00:01:42.400','00:01:44.700','4000-essential-english-words-3'),
	('Instead of a bad grade, his group would have the best project ever','Thay vì nhận điểm kém, nhóm của cậu ấy sẽ có dự án tốt nhất từ trước đến nay','00:01:44.700','00:01:49.900','4000-essential-english-words-3'),
	('"It\'s time to go home, the alien finally said','"Đã đến lúc về nhà rồi," người ngoài hành tinh cuối cùng cũng nói','00:01:49.900','00:01:54.020','4000-essential-english-words-3'),
	('On the way back, he helped Lee make a model of the planet Mars','Trên đường về, cậu ấy đã giúp Lee làm một mô hình hành tinh Sao Hỏa','00:01:54.020','00:01:59.500','4000-essential-english-words-3'),
	('Soon, they were on Earth','Chẳng mấy chốc, họ đã ở trên Trái Đất','00:01:59.500','00:02:02.000','4000-essential-english-words-3'),
	('"Thanks," Lee said','"Cảm ơn," Lee nói','00:02:02.000','00:02:03.600','4000-essential-english-words-3'),
	('"My model will be awesome"','"Mô hình của tôi sẽ tuyệt vời"','00:02:03.670','00:02:06.000','4000-essential-english-words-3'),
	('Then he took his model and said goodbye to his new friend','Sau đó, cậu ấy lấy mô hình của mình và nói lời tạm biệt với người bạn mới','00:02:06.000','00:02:11.000','4000-essential-english-words-3'),

	/* (UUID(),'4000-essential-english-words-4','The dog\'s bell','Chiếc chuông của chú chó','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_004.mp3',NULL,'00:00:00.000','00:02:03.000','4000-essential-english-words','YES',4) */
	('The dog\'s bell','Chiếc chuông của chú chó','00:00:00.960','00:00:03.000','4000-essential-english-words-4'),
	('John\'s dog was a bad dog','Chó của John là một con chó tồi tệ','00:00:03.000','00:00:06.000','4000-essential-english-words-4'),
	('He bit people frequently','Nó thường xuyên cắn người','00:00:06.000','00:00:08.500','4000-essential-english-words-4'),
	('John had great concern about this','John rất lo lắng về điều này','00:00:08.500','00:00:11.100','4000-essential-english-words-4'),
	('It was not an appropriate way for a dog to behave','Đây không phải là cách cư xử thích hợp cho một chú chó','00:00:11.100','00:00:14.700','4000-essential-english-words-4'),
	('His friends in the village always expected the dog to bite them','Bạn bè trong làng của anh luôn đoán trước được con chó sẽ cắn họ','00:00:14.700','00:00:19.400','4000-essential-english-words-4'),
	('The news about John\'s dog spread through the village','Tin tức về con chó của Jon lan truyền khắp làng','00:00:19.400','00:00:22.900','4000-essential-english-words-4'),
	('None of the people wanted to go to John\'s house','Không ai muốn đến nhà John','00:00:22.900','00:00:26.300','4000-essential-english-words-4'),
	('John tried to instruct the dog to behave, but it never worked','John đã cố gắng hướng dẫn cho con chó cách cư xử, nhưng nó chưa bao giờ hiệu quả','00:00:26.300','00:00:30.800','4000-essential-english-words-4'),
	('He tried to be patient and teach the dog to be calm','Anh cố gắng kiên nhẫn và dạy con chó bình tĩnh','00:00:30.800','00:00:35.000','4000-essential-english-words-4'),
	('That also didn\'t work','Cách đó cũng không hiệu quả','00:00:35.000','00:00:37.100','4000-essential-english-words-4'),
	('John didn\'t want to punish the dog','John không muốn trừng phạt con chó','00:00:37.100','00:00:40.000','4000-essential-english-words-4'),
	('"How will I stop my dog\'s bad habit?" John asked himself','"Làm cách nào để tôi ngăn chặn thói quen xấu của con chó?" John tự hỏi bản thân','00:00:40.000','00:00:45.200','4000-essential-english-words-4'),
	('John\'s friend came to talk to him about the issue','Bạn của John đến để nói chuyện với anh ấy về vấn đề này','00:00:45.200','00:00:48.900','4000-essential-english-words-4'),
	('During their important meeting, his friend said, "The people in the village asked me to represent them"','Trong cuộc họp quan trọng của họ, người bạn của anh ấy nói, "Người dân trong làng đã yêu cầu mình đại diện cho họ"','00:00:48.900','00:00:55.400','4000-essential-english-words-4'),
	('"We want your dog to stop this habit"','"Chúng tôi muốn con chó của cậu dừng ngay thói quen này lại"','00:00:55.400','00:00:58.100','4000-essential-english-words-4'),
	('"Why don\'t you put a bell around the dog\'s neck?"','"Tại sao cậu không đeo một chiếc chuông quanh cổ con chó?"','00:00:58.100','00:01:01.000','4000-essential-english-words-4'),
	('"This way, we would hear your dog coming down the street"','"Với cách này, chúng ta sẽ nghe thấy tiếng con chó của cậu đang đi xuống phố','00:01:01.000','00:01:04.800','4000-essential-english-words-4'),
	('John thought this was a great idea','John nghĩ rằng đây quả là một ý kiến tuyệt vời','00:01:04.800','00:01:07.600','4000-essential-english-words-4'),
	('Now people could stay away from the dog, it would not be able to bite anyone anymore','Giờ thì mọi người có thể tránh xa con chó, nó sẽ không thể cắn ai nữa','00:01:07.600','00:01:14.000','4000-essential-english-words-4'),
	('The dog liked the bell, too','Con chó cũng thích cái chuông','00:01:14.000','00:01:16.000','4000-essential-english-words-4'),
	('People looked at him when they heard his bell','Mọi người nhìn nó khi họ nghe thấy tiếng chuông','00:01:16.000','00:01:19.500','4000-essential-english-words-4'),
	('This made the dog very content','Điều này khiến con chó rất hài lòng','00:01:19.500','00:01:21.700','4000-essential-english-words-4'),
	('He liked the song the bell played when he walked','Nó thích bài hát mà tiếng chuông bắt đầu vang lên khi nó bước đi','00:01:21.700','00:01:25.000','4000-essential-english-words-4'),
	('One day John\'s dog strolled through the village and met some other dogs','Một ngày nọ, con chó của John đi dạo qua làng và gặp những con chó khác','00:01:25.000','00:01:30.000','4000-essential-english-words-4'),
	('He expected them to want a bell like his','Nó mong đợi bọn chúng sẽ muốn một cái chuông y như của nó','00:01:30.000','00:01:32.800','4000-essential-english-words-4'),
	('But they laughed at his bell','Nhưng bọn chúng cười nhạo cái chuông của nó','00:01:32.800','00:01:35.000','4000-essential-english-words-4'),
	('They said the bell made people avoid him','Chúng nói rằng chiếc chuông khiến cho mọi người tránh xa nó','00:01:35.000','00:01:37.900','4000-essential-english-words-4'),
	('John\'s dog shook his head','Con chó của John lắc đầu','00:01:37.900','00:01:40.000','4000-essential-english-words-4'),
	('"No, they look at me because they like the bell"','Không, họ nhìn tôi vì họ thích chiếc chuông này','00:01:40.000','00:01:43.900','4000-essential-english-words-4'),
	('The other dogs said, "You have the wrong idea of what makes you popular"','Những con chó khác nói: "Mày hiểu nhầm về điều đã khiến mày nổi tiếng rồi đấy"','00:01:43.900','00:01:49.000','4000-essential-english-words-4'),
	('"Of course they like your bell"','Tất nhiên là họ thích cái chuông của mày','00:01:49.000','00:01:51.000','4000-essential-english-words-4'),
	('"It tells them where you are so they can avoid you"','Nó báo cho họ biết mày đang ở đâu thế là họ có thể tránh xa mày','00:01:51.000','00:01:54.000','4000-essential-english-words-4'),
	('"You aren\'t able to bite them anymore"','"Mày không thể cắn họ nữa"','00:01:54.000','00:01:57.000','4000-essential-english-words-4'),
	('You see, being popular isn\'t something positive when it\'s for the wrong reason','Mày thấy đấy, nổi tiếng không phải là điều gì tích cực khi nó xuất phát từ lý do sai lầm','00:01:57.000','00:02:03.000','4000-essential-english-words-4'),

	/* (UUID(),'4000-essential-english-words-5','The jackal and the sun child','Chú chó rừng và đứa con Mặt trời','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_005.mp3',NULL,'00:00:00.000','00:02:11.600','4000-essential-english-words','YES',5) */
	('The Jackal and the Sun Child','Chú chó rừng và đứa con Mặt trời','00:00:00.960','00:00:04.000','4000-essential-english-words-5'),
	('A jackal is a wild dog with a big black back','Chó rừng là một loài chó hoang dã với cái lưng đen to lớn','00:00:04.000','00:00:08.600','4000-essential-english-words-5'),
	('It resides in the desert','Nó sinh sống ở sa mạc','00:00:08.600','00:00:10.600','4000-essential-english-words-5'),
	('But how did the jackal get his black back?','Nhưng làm thế nào mà chó rừng có cái lưng đen vậy?','00:00:10.650','00:00:14.600','4000-essential-english-words-5'),
	('This was how it happened','Đây là cách mọi chuyện đã xảy ra','00:00:14.600','00:00:17.000','4000-essential-english-words-5'),
	('One day, the jackal saw a girl','Một ngày nọ, chó rừng nhìn thấy một cô bé','00:00:17.000','00:00:20.300','4000-essential-english-words-5'),
	('She was sitting upon a rock','Cô bé đang ngồi trên một tảng đá','00:00:20.300','00:00:22.300','4000-essential-english-words-5'),
	('She was not a normal child','Cô bé không phải là một đứa trẻ bình thường','00:00:22.380','00:00:24.800','4000-essential-english-words-5'),
	('She was a rare and beautiful sun child','Cô bé là một đứa trẻ mặt trời hiếm có và xinh đẹp','00:00:24.850','00:00:28.300','4000-essential-english-words-5'),
	('She was bright and warm like the sun','Cô bé tỏa sáng và ấm áp như mặt trời','00:00:28.300','00:00:31.500','4000-essential-english-words-5'),
	('The child saw the jackal and smiled','Đứa trẻ thấy chó rừng và mỉm cười','00:00:31.700','00:00:34.620','4000-essential-english-words-5'),
	('She said, "Jackal, I have been relaxing on this rock for too long"','Cô bé nói: "Chó rừng ơi, tôi đã thư giãn trên phiến đá này quá lâu rồi"','00:00:34.650','00:00:40.700','4000-essential-english-words-5'),
	('"I must get home soon"','"Tôi phải về nhà sớm thôi"','00:00:40.700','00:00:42.900','4000-essential-english-words-5'),
	('"But, I am slow and you are fast"','"Nhưng, tôi thì chậm chạp còn bạn lại nhanh nhẹn"','00:00:43.000','00:00:46.020','4000-essential-english-words-5'),
	('"You will likely get me home more quickly"','"Bạn sẽ có thể đưa tôi về nhà nhanh hơn nhiều"','00:00:46.300','00:00:49.700','4000-essential-english-words-5'),
	('Then she requested, "Will you carry me home?"','"Rồi cô bé đề nghị: "Bạn sẽ đưa tôi về nhà chứ?"','00:00:49.830','00:00:53.410','4000-essential-english-words-5'),
	('If you do, I\'ll give you a gift','"Nếu bạn làm được, tôi sẽ tặng bạn một món quà"','00:00:53.600','00:00:56.450','4000-essential-english-words-5'),
	('"This necklace belongs to me, but I will give it to you"','"Chiếc vòng cổ này là của tôi, nhưng tôi sẽ đưa nó cho bạn"','00:00:56.600','00:01:01.600','4000-essential-english-words-5'),
	('The wild jackal agreed','"Chó rừng hoang dã đồng ý"','00:01:01.600','00:01:03.800','4000-essential-english-words-5'),
	('So the sun child sat on the dog\'s back','"Vậy là đứa bé mặt trời ngồi lên lưng chú chó"','00:01:03.800','00:01:07.300','4000-essential-english-words-5'),
	('They started to walk','Họ bắt đầu đi dạo','00:01:07.300','00:01:08.700','4000-essential-english-words-5'),
	('But soon, the jackal felt ill','Nhưng không lâu sau, chó rừng cảm thấy không khỏe','00:01:08.800','00:01:11.200','4000-essential-english-words-5'),
	('The sun child was very hot on his back','Đứa trẻ mặt trời ngày càng vô cùng nóng ở trên lưng nó','00:01:11.240','00:01:14.780','4000-essential-english-words-5'),
	('The heat was hurting his back very badly','Sức nóng đã làm tổn thương chiếc lưng của nó rất tồi tệ','00:01:14.780','00:01:18.000','4000-essential-english-words-5'),
	('"I made a terrible error in judgment" he thought','"Tôi đã mắc một lỗi sai khủng khiếp trong việc phán đoán" nó nghĩ','00:01:18.000','00:01:23.000','4000-essential-english-words-5'),
	('He shouldn\'t have agreed to carry her','Nó không nên đồng ý trở cô','00:01:23.000','00:01:25.330','4000-essential-english-words-5'),
	('So he asked her to get off','Thế là nó yêu cầu cô bước xuống','00:01:25.350','00:01:27.800','4000-essential-english-words-5'),
	('But she did not','Nhưng cô bé đã không làm thế','00:01:27.800','00:01:29.500','4000-essential-english-words-5'),
	('The jackal\'s back continued to get hotter and hotter','Lưng của chó rừng tiếp tục ngày càng nóng hơn','00:01:29.500','00:01:32.800','4000-essential-english-words-5'),
	('He had to get away from the sun child','Nó phải tránh xa khỏi đứa trẻ mặt trời','00:01:32.800','00:01:35.800','4000-essential-english-words-5'),
	('So he made a plan','Thế là nó đưa ra một kế hoạch','00:01:35.800','00:01:37.700','4000-essential-english-words-5'),
	('First, he ran as fast as he could','Đầu tiên, nó chạy nhanh nhất có thể','00:01:37.700','00:01:40.210','4000-essential-english-words-5'),
	('He hoped the sun child would fall off','Nó hy vọng đứa trẻ mặt trời sẽ ngã xuống','00:01:40.270','00:01:42.830','4000-essential-english-words-5'),
	('But she did not','Nhưng cô bé không ngã','00:01:42.970','00:01:44.400','4000-essential-english-words-5'),
	('So when the sun child was looking at the sky, not aware of the jackal\'s next plan, he jumped into a field of flowers','Thế là khi đứa trẻ mặt trời ngước nhìn lên trời, không nhận thức được kế hoạch tiếp theo của chó rừng, nó đã nhảy vào một cánh đồng hoa','00:01:44.450','00:01:53.300','4000-essential-english-words-5'),
	('As a result, the child rolled off his back','Kết quả là, đứa trẻ đã lăn xuống khỏi lưng nó','00:01:53.300','00:01:56.600','4000-essential-english-words-5'),
	('The jackal ran away','Chó rừng bỏ chạy','00:01:56.600','00:01:58.800','4000-essential-english-words-5'),
	('But the sun child left a mark on the jackal\'s back, a visible black mark','Nhưng đứa trẻ mặt trời đã để lại một dấu vết trên lưng của chó rừng, một vết đen luôn hiện hữu','00:01:58.800','00:02:04.900','4000-essential-english-words-5'),
	('Ever since his experience with the sun child, the jackal has had a black back','Kể từ lúc trải nghiệm với đứa trẻ mặt trời, chó rừng đã có chiếc lưng màu đen','00:02:04.950','00:02:11.600','4000-essential-english-words-5');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-6','The friendly ghost','Hồn ma thân thiện','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_006.mp3',NULL,'00:00:00.000','00:02:11.300','4000-essential-english-words','YES',6) */
	('The friendly ghost','Hồn ma thân thiện','00:00:00.960','00:00:03.000','4000-essential-english-words-6'),
	('A nice woman lived by a large river','Có một người phụ nữ tốt bụng sống bên cạnh một con sông lớn','00:00:03.000','00:00:06.600','4000-essential-english-words-6'),
	('She loved children','Bà rất yêu trẻ con','00:00:06.600','00:00:08.800','4000-essential-english-words-6'),
	('She wanted to help them in any way','Bà luôn mong muốn giúp đỡ chúng bằng bất cứ cách nào','00:00:08.800','00:00:11.800','4000-essential-english-words-6'),
	('She loved her community, and everyone in the community loved her','Bà yêu thương cộng đồng của mình, và tất cả mọi người trong cộng đồng đều yêu quý bà','00:00:11.800','00:00:16.800','4000-essential-english-words-6'),
	('She lived a very long time and became very wise','Bà đã sống ở đây rất lâu rồi và đã trở nên vô cùng thông thái','00:00:16.800','00:00:21.800','4000-essential-english-words-6'),
	('When she died, she became a ghost','Khi bà mất, bà trở thành một hồn ma','00:00:21.800','00:00:24.800','4000-essential-english-words-6'),
	('She was dead, but every night she returned to her community','Bà đã mất rồi, nhưng hằng đêm bà vẫn quay lại cộng đồng của mình','00:00:24.800','00:00:29.800','4000-essential-english-words-6'),
	('She wanted to help children and not to cause them fright','Bà ấy mong muốn giúp đỡ lũ trẻ chứ không muốn khiến chúng sợ','00:00:29.800','00:00:33.600','4000-essential-english-words-6'),
	('But she had a scary voice','Nhưng bà có một giọng nói rất rùng rợn','00:00:33.600','00:00:36.000','4000-essential-english-words-6'),
	('Children were afraid of her, but the ghost was a good one','Lũ trẻ rất sợ bà, nhưng bà là một hồn ma tốt','00:00:36.000','00:00:40.400','4000-essential-english-words-6'),
	('She only scared them to help them','Bà ấy chỉ doạ chúng để muốn giúp chúng mà thôi','00:00:40.400','00:00:43.200','4000-essential-english-words-6'),
	('One night, some children and a dog were playing by the river','Một đêm, vài đứa trẻ và một chú chó đang đùa nghịch gần bờ sông','00:00:43.200','00:00:47.800','4000-essential-english-words-6'),
	('They were having fun with their pet','Chúng đang vui vẻ với thú cưng','00:00:47.800','00:00:50.000','4000-essential-english-words-6'),
	('But they were far from home','Nhưng chúng ở khá xa nhà','00:00:50.000','00:00:52.800','4000-essential-english-words-6'),
	('Then the weather became bad','Cùng lúc đó thời tiết bỗng trở nên tồi tệ','00:00:52.800','00:00:55.000','4000-essential-english-words-6'),
	('It rained and rained','Trời ngày càng mưa','00:00:55.000','00:00:57.600','4000-essential-english-words-6'),
	('The river was rising','Nước sông đang dần dâng lên','00:00:57.600','00:00:59.800','4000-essential-english-words-6'),
	('It was very dark','Trời thì vô cùng tối','00:00:59.800','00:01:01.600','4000-essential-english-words-6'),
	('The children knew they were lost','Lũ trẻ nhận ra rằng chúng đã bị lạc','00:01:01.600','00:01:04.000','4000-essential-english-words-6'),
	('They needed to go north, but they didn\'t know which direction it was','Chúng cần phải đi về hướng Bắc, nhưng chúng không biết hướng Bắc ở đâu','00:01:04.000','00:01:09.000','4000-essential-english-words-6'),
	('When the moon came out, they saw a ghost by the river','Khi Mặt trăng xuất hiện, chúng nhìn thấy một hồn ma ở dòng sông','00:01:09.000','00:01:13.200','4000-essential-english-words-6'),
	('The ghost said, "Go away"','Hồn ma quát: "Cút ngay"','00:01:13.200','00:01:16.700','4000-essential-english-words-6'),
	('The children felt great fright','Lũ trẻ cảm thấy vô cùng sợ hãi','00:01:16.700','00:01:19.500','4000-essential-english-words-6'),
	('They knew it was a ghost','Chúng biết đó là một hồn ma','00:01:19.500','00:01:21.600','4000-essential-english-words-6'),
	('Then the ghost moved closer','Rồi hồn ma tiến lại gần chúng','00:01:21.600','00:01:23.700','4000-essential-english-words-6'),
	('She yelled again, "Go away"','Hồn ma lại quát lên lần nữa: "Cút ngay"','00:01:23.700','00:01:27.800','4000-essential-english-words-6'),
	('The children became very upset','Lũ trẻ trở nên rất buồn bã','00:01:27.800','00:01:30.200','4000-essential-english-words-6'),
	('Some of them began to cry','Vài đứa bắt đầu khóc','00:01:30.200','00:01:32.500','4000-essential-english-words-6'),
	('The children knew they had a choice: they could escape, or they could stay and face this scary individual in the dark','Lũ trẻ biết chúng chỉ có một lựa chọn: Chúng có thế chạy trốn, hoặc chúng có thể ở lại và đối mặt với cái cá thể đáng sợ trong bóng tối kia','00:01:32.500','00:01:39.800','4000-essential-english-words-6'),
	('The children ran a long distance away','Lũ trẻ chạy đi một quãng rất xa','00:01:39.900','00:01:43.500','4000-essential-english-words-6'),
	('The ghost followed them all the way','Hồn ma đi theo chúng trên suốt chặng đường','00:01:43.500','00:01:46.000','4000-essential-english-words-6'),
	('Finally, the children reached home','Cuối cùng, lũ trẻ đã về tới nhà','00:01:46.000','00:01:48.800','4000-essential-english-words-6'),
	('The ghost was very happy','Hồn ma thấy rất vui','00:01:48.800','00:01:50.800','4000-essential-english-words-6'),
	('Soon, the river rose higher and higher','Chẳng mấy chốc, nước sông dâng lên ngày càng cao','00:01:50.800','00:01:54.300','4000-essential-english-words-6'),
	('It was very dangerous','Điều này cực kỳ nguy hiểm','00:01:54.300','00:01:56.000','4000-essential-english-words-6'),
	('The ghost had helped the children survive','Hồn ma đã giúp lũ trẻ sống sót','00:01:56.000','00:01:59.200','4000-essential-english-words-6'),
	('She had saved them from the rising water','Bà ấy đã cứu chúng khỏi dòng nước đang dâng lên','00:01:59.200','00:02:02.000','4000-essential-english-words-6'),
	('She also used her power to lead them home','Bà cũng sử dụng sức mạnh của mình để dẫn chúng về nhà','00:02:02.000','00:02:04.800','4000-essential-english-words-6'),
	('Sometimes, meeting a ghost has some advantages','Đôi khi, gặp một hồn ma cũng có một vài lợi thế','00:02:04.800','00:02:08.300','4000-essential-english-words-6'),
	('A ghost can save your life','Một hồn ma có thể cứu mạng sống của bạn đấy','00:02:08.300','00:02:11.300','4000-essential-english-words-6'),

	/* (UUID(),'4000-essential-english-words-7','The best prince','Chàng hoàng tử tốt nhất','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_007.mp3',NULL,'00:00:00.000','00:02:17.200','4000-essential-english-words','YES',7) */
	('The best prince','Chàng hoàng tử tốt nhất','00:00:00.960','00:00:03.300','4000-essential-english-words-7'),
	('King Minos was very sick','Vua Minos đang bị ốm nặng','00:00:03.300','00:00:05.700','4000-essential-english-words-7'),
	('His condition was getting worse','Tình trạng của ông ngày càng xấu hơn','00:00:05.700','00:00:08.200','4000-essential-english-words-7'),
	('He had three sons','Ông có ba người con trai','00:00:08.200','00:00:09.900','4000-essential-english-words-7'),
	('He loved them all','Ông yêu thương tất cả bọn họ','00:00:09.900','00:00:11.300','4000-essential-english-words-7'),
	('He had to announce who would become king','Ông phải tuyên bố ai sẽ trở thành vua','00:00:11.370','00:00:14.600','4000-essential-english-words-7'),
	('Two of the princes stood waiting outside the king\'s room','Hai vị hoàng tử đứng chờ bên ngoài phòng của vua','00:00:14.600','00:00:18.670','4000-essential-english-words-7'),
	('Theseus was the oldest and strongest','Theseus là người lớn tuổi nhất và là người khỏe nhất','00:00:18.700','00:00:21.770','4000-essential-english-words-7'),
	('He thought his father would make him king','Chàng nghĩ rằng cha sẽ chọn mình làm vua','00:00:21.800','00:00:24.700','4000-essential-english-words-7'),
	('Pelias, the second son, thought differently','Pelias, người con trai thứ hai, lại nghĩ khác','00:00:24.700','00:00:28.300','4000-essential-english-words-7'),
	('He was an expert with weapons','Chàng là một chuyên gia về vũ khí','00:00:28.340','00:00:30.700','4000-essential-english-words-7'),
	('He thought the king would choose him','Chàng nghĩ rằng cha mình sẽ chọn mình làm vua','00:00:30.720','00:00:33.200','4000-essential-english-words-7'),
	('"When I\'m king," Theseus told Pelias, "I\'ll let you contribute to the defense of our country"','"Khi ta lên làm vua rồi," Theseus nói với Pelias, "ta sẽ để đệ đóng góp đội quân phòng vệ cho đất nước"','00:00:33.200','00:00:40.000','4000-essential-english-words-7'),
	('"You can lead the army"','"Đệ có thể lãnh đạo đội quân"','00:00:40.000','00:00:41.800','4000-essential-english-words-7'),
	('Pelias became angry','Pelias tức giận','00:00:41.800','00:00:44.200','4000-essential-english-words-7'),
	('"Father knows I\'m famous for my sword skills"','"Cha biết rằng ta nổi tiếng về các kỹ năng sử dụng kiếm thuật"','00:00:44.200','00:00:47.850','4000-essential-english-words-7'),
	('"He\'ll make me king"','Người sẽ chọn ta làm vua','00:00:48.000','00:00:49.800','4000-essential-english-words-7'),
	('"You?" Theseus yelled','"Đệ ư?" Theseus hét lên','00:00:49.800','00:00:51.800','4000-essential-english-words-7'),
	('"He won\'t choose you"','"Người sẽ không chọn đệ đâu"','00:00:51.910','00:00:53.800','4000-essential-english-words-7'),
	('"The kingdom is mine" Pelias claimed','"Vương quốc này là của ta" Pelias tuyên bố','00:00:53.800','00:00:57.000','4000-essential-english-words-7'),
	('"Father will give it to me - or I\'ll use force to take it"','"Cha sẽ trao nó cho ta - hoặc là ta sẽ dùng vũ lực để đoạt lấy"','00:00:57.000','00:01:02.000','4000-essential-english-words-7'),
	('Theseus made a sudden move to take out his sword','Theseus đột ngột rút kiếm ra','00:01:02.000','00:01:05.400','4000-essential-english-words-7'),
	('Then Pelias did the same','Và rồi Pelias cũng làm như vậy','00:01:05.400','00:01:07.800','4000-essential-english-words-7'),
	('"Beating me will be a challenge," Theseus said','"Đánh bại ta sẽ là một thách thức đấy," Theseus nói','00:01:07.800','00:01:11.800','4000-essential-english-words-7'),
	('"Fight me now"','"Hãy đấu với ta ngay bây giờ"','00:01:11.800','00:01:13.200','4000-essential-english-words-7'),
	('"The winner gets the kingdom" Pelias agreed','"Người chiến thắng sẽ có được vương quốc" Pelias đồng ý','00:01:13.200','00:01:16.800','4000-essential-english-words-7'),
	('King Minos could hear his sons fighting','Vua Minos có thể nghe thấy các con trai mình đang đánh nhau','00:01:16.800','00:01:19.800','4000-essential-english-words-7'),
	('The youngest son, Jason, stood beside him','Người con trai nhỏ tuổi nhất, Jason, đứng bên cạnh ông','00:01:19.800','00:01:22.900','4000-essential-english-words-7'),
	('He sensed his father\'s sadness','Chàng có thể cảm nhận được nỗi buồn của cha mình','00:01:22.950','00:01:25.900','4000-essential-english-words-7'),
	('The king laid his hand flat on Jason\'s arm','Nhà vua đặt tay mình lên cánh tay của Jason','00:01:25.900','00:01:29.300','4000-essential-english-words-7'),
	('"Your brothers fight too much," the king told him','"Các anh của con đấu đá nhau rất nhiều," nhà vua nói','00:01:29.300','00:01:32.800','4000-essential-english-words-7'),
	('"I must protect my kingdom from all harm"','"Ta phải bảo vệ vương quốc của mình khỏi tất cả mối nguy hại"','00:01:32.800','00:01:36.200','4000-essential-english-words-7'),
	('"They\'ll divide it between them"','"Chúng sẽ chia cắt vương quốc này ra mất"','00:01:36.300','00:01:38.250','4000-essential-english-words-7'),
	('"The people won\'t know what to do"','"Người dân sẽ chẳng biết phải làm gì"','00:01:38.300','00:01:40.700','4000-essential-english-words-7'),
	('"There\'ll be war"','"Chiến tranh sẽ xảy ra"','00:01:40.700','00:01:42.100','4000-essential-english-words-7'),
	('"I can\'t allow either of them to be king"','"Cha không thể cho phép bất cứ ai trong chúng làm vua"','00:01:42.200','00:01:45.700','4000-essential-english-words-7'),
	('"Therefore, I\'m making you king"','"Bởi vậy, cha sẽ để con làm vua"','00:01:45.700','00:01:48.800','4000-essential-english-words-7'),
	('"Your kindness has always made you special"','"Lòng nhân hậu của con đã luôn khiến con trở nên đặc biệt"','00:01:48.800','00:01:51.800','4000-essential-english-words-7'),
	('"It\'s the difference between you and your brothers"','"Đó là sự khác biệt giữa con và các anh trai của con"','00:01:51.800','00:01:55.400','4000-essential-english-words-7'),
	('"You can bring peace"','"Con có thể mang đến hòa bình"','00:01:55.450','00:01:56.990','4000-essential-english-words-7'),
	('"They can\'t"','"Chúng nó thì không thể"','00:01:57.100','00:01:58.600','4000-essential-english-words-7'),
	('Then the king died','Sau đó nhà vua qua đời','00:01:58.600','00:02:00.500','4000-essential-english-words-7'),
	('Theseus and Pelias heard that their youngest brother was king','Theseus và Pelias nghe nói rằng cậu em trai nhỏ nhất được làm vua','00:02:00.500','00:02:04.300','4000-essential-english-words-7'),
	('They were surprised','Họ đều bất ngờ','00:02:04.300','00:02:05.780','4000-essential-english-words-7'),
	('They realized that their fighting was wrong','Họ nhận ra cuộc chiến của họ là sai lầm','00:02:05.860','00:02:08.600','4000-essential-english-words-7'),
	('It had kept them from saying goodbye to their father','Điều đó khiến họ không thể nói lời tạm biệt tới cha mình','00:02:08.600','00:02:11.800','4000-essential-english-words-7'),
	('They agreed to have Jason as their king','Họ đồng ý Jason làm vua','00:02:11.800','00:02:14.800','4000-essential-english-words-7'),
	('He was the best choice','Chàng là sự lựa chọn tốt nhất','00:02:14.800','00:02:17.200','4000-essential-english-words-7'),

	/* (UUID(),'4000-essential-english-words-8','How the sun and the moon were made?','Mặt trời và mặt trăng được sinh ra bằng cách nào?','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_008.mp3',NULL,'00:00:00.000','00:02:10.000','4000-essential-english-words','YES',8) */
	('How the sun and the moon were made?','Mặt trời và mặt trăng được sinh ra bằng cách nào?','00:00:00.960','00:00:04.000','4000-essential-english-words-8'),
	('Do you ever wonder where the moon and the sun came from?','Bạn có từng tự hỏi Mặt Trăng và Mặt Trời đến từ đâu không?','00:00:04.000','00:00:08.800','4000-essential-english-words-8'),
	('The Inuit people of Alaska have a theory','Người dân Inuit ở Alaska có một giả thuyết như thế này','00:00:08.800','00:00:11.650','4000-essential-english-words-8'),
	('They tell a story about a beautiful girl','Họ kể một câu chuyện về một cô gái xinh đẹp','00:00:11.650','00:00:15.300','4000-essential-english-words-8'),
	('She was very nice','Cô ấy rất tốt bụng','00:00:15.100','00:00:17.400','4000-essential-english-words-8'),
	('In contrast, her brother was a mean little boy','Nhưng ngược lại, anh trai cô lại là một cậu bé xấu tính','00:00:17.400','00:00:21.800','4000-essential-english-words-8'),
	('One day he proposed something','Một ngày nọ anh ta đề nghị một điều rằng','00:00:21.800','00:00:24.300','4000-essential-english-words-8'),
	('"We should go to a party," he said','"Chúng ta hãy đi dự tiệc đi," anh ta nói','00:00:24.300','00:00:27.900','4000-essential-english-words-8'),
	('The girl accepted','Cô gái đồng ý','00:00:27.900','00:00:29.400','4000-essential-english-words-8'),
	('First, it was necessary for her to prepare','Trước tiên, cô cần chuẩn bị','00:00:29.400','00:00:32.600','4000-essential-english-words-8'),
	('She arranged her hair and put on nice clothes','Cô sửa soạn mái tóc và khoác lên mình những bộ quần áo thật đẹp','00:00:32.600','00:00:35.800','4000-essential-english-words-8'),
	('This required a lot of time','Việc này yêu cầu khá nhiều thời gian','00:00:35.800','00:00:38.500','4000-essential-english-words-8'),
	('But the girl worked hard, and soon she had success','Nhưng cô bé đã làm việc chăm chỉ và chẳng mấy chốc đã thành công','00:00:38.500','00:00:42.600','4000-essential-english-words-8'),
	('She looked perfect','Trông cô ấy thật hoàn hảo','00:00:42.600','00:00:44.800','4000-essential-english-words-8'),
	('They attended the party together','Họ tham gia bữa tiệc cùng nhau','00:00:44.800','00:00:47.300','4000-essential-english-words-8'),
	('The girl was having fun','Cô gái rất vui','00:00:47.300','00:00:49.300','4000-essential-english-words-8'),
	('Later, she walked into the bathroom','Lát sau, cô đi vào trong phòng tắm','00:00:49.300','00:00:52.200','4000-essential-english-words-8'),
	('Suddenly, the lights were turned off','Bất chợt, tất cả đèn trong phòng đều vụt tắt','00:00:52.200','00:00:54.750','4000-essential-english-words-8'),
	('Someone grabbed her hair and tore her clothes','Có ai đó đã nắm tóc và xé quần áo của cô','00:00:54.800','00:00:58.600','4000-essential-english-words-8'),
	('She ran out of the bathroom','Cô vội chạy ra khỏi phòng tắm','00:00:58.600','00:01:00.700','4000-essential-english-words-8'),
	('She wanted to know who did this to her','Cô muốn biết ai đã làm điều này với mình','00:01:00.700','00:01:03.500','4000-essential-english-words-8'),
	('Then she had an idea','Rồi cô nảy ra một ý tưởng','00:01:03.500','00:01:05.350','4000-essential-english-words-8'),
	('She fixed her hair again','Cô sửa sang lại mái tóc một lần nữa','00:01:05.350','00:01:07.800','4000-essential-english-words-8'),
	('This time it was even more beautiful','Lần này thậm chí còn xinh đẹp hơn bội phần','00:01:07.800','00:01:10.300','4000-essential-english-words-8'),
	('She even balanced beautiful jewels in it','Thậm chí cô còn chỉnh các món trang sức tuyệt đẹp cân xứng với mái tóc','00:01:10.300','00:01:13.350','4000-essential-english-words-8'),
	('She wanted to encourage the person to grab it again','Cô muốn cổ vũ người đó nắm tóc thêm lần nữa','00:01:13.350','00:01:16.800','4000-essential-english-words-8'),
	('She put black dirt in her hair','Cô bôi đất bẩn lên tóc mình','00:01:16.800','00:01:19.800','4000-essential-english-words-8'),
	('The purpose of this was to catch the person','Mục đích của việc này là để bắt lấy kẻ kia','00:01:19.800','00:01:22.800','4000-essential-english-words-8'),
	('She went to the bathroom again, and it was the same pattern','Cô lại đi vào phòng tắm lần nữa, và vẫn y như kiểu trước','00:01:22.800','00:01:26.700','4000-essential-english-words-8'),
	('The lights went off, and someone grabbed her hair','Những bóng đèn lại vụt tắt, có ai đó túm lấy tóc cô','00:01:26.700','00:01:29.800','4000-essential-english-words-8'),
	('When he released it, his hand was black','Khi hắn thả nó ra, tay của hắn đen thui','00:01:29.800','00:01:33.200','4000-essential-english-words-8'),
	('The girl returned to the party','Cô gái quay trở lại bữa tiệc','00:01:33.200','00:01:35.200','4000-essential-english-words-8'),
	('She knew there was only a single person with a black hand','Cô biết là chỉ có duy nhất một người với bàn tay màu đen','00:01:35.200','00:01:39.200','4000-essential-english-words-8'),
	('When she saw that person, he was very familiar','Khi cô nhìn thấy hắn, hắn rất quen thuộc','00:01:39.200','00:01:42.750','4000-essential-english-words-8'),
	('It was her brother','Đó là anh trai của cô','00:01:42.750','00:01:44.700','4000-essential-english-words-8'),
	('He ran into the woods','Hắn liền bỏ chạy vào rừng','00:01:44.700','00:01:46.600','4000-essential-english-words-8'),
	('The girl ran after him','Cô gái đuổi theo sau hắn','00:01:46.600','00:01:48.400','4000-essential-english-words-8'),
	('They both carried fire so they could see in the dark','Cả hai người đều mang theo đuốc vì thế họ có thể nhìn thấy trong bóng tối','00:01:48.400','00:01:51.500','4000-essential-english-words-8'),
	('The smoke went into the air','Khói liền hòa vào không khí','00:01:51.500','00:01:53.800','4000-essential-english-words-8'),
	('As they ran, they grew','Trong khi họ mải miết chạy, họ đã lớn lên','00:01:53.800','00:01:55.740','4000-essential-english-words-8'),
	('They became huge','Họ biến thành khổng lồ','00:01:55.740','00:01:57.740','4000-essential-english-words-8'),
	('Then they went into space','Rồi họ tiến vào không gian','00:01:57.740','00:01:59.710','4000-essential-english-words-8'),
	('When the girl\'s fire went out, she hung in the sky','Khi ngọn đuốc của cô gái tắt, cô đã treo lơ lửng ở trên bầu trời','00:01:59.710','00:02:03.300','4000-essential-english-words-8'),
	('She became the moon, and her brother became the sun','Cô biến thành Mặt Trăng, còn anh trai cô trở thành Mặt Trời','00:02:03.300','00:02:07.000','4000-essential-english-words-8'),
	('They chase each other forever','Họ cứ đuổi nhau mãi như vậy','00:02:07.000','00:02:10.000','4000-essential-english-words-8'),

	/* (UUID(),'4000-essential-english-words-9','The starfish','Chú sao biển','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_009.mp3',NULL,'00:00:00.000','00:01:52.000','4000-essential-english-words','YES',9) */
	('The starfish','Chú sao biển','00:00:00.960','00:00:02.900','4000-essential-english-words-9'),
	('Last summer I took a trip to an island','Mùa hè năm ngoái tôi đã đi du lịch đến một hòn đảo','00:00:02.900','00:00:06.300','4000-essential-english-words-9'),
	('I had a lot of fun','Tôi đã rất vui','00:00:06.300','00:00:08.300','4000-essential-english-words-9'),
	('I sat and watched the waves and listened to the ocean','Tôi ngồi và ngắm nhìn sóng biển và lắng nghe đại dương','00:00:08.350','00:00:12.300','4000-essential-english-words-9'),
	('I learned to identify birds','Tôi học cách nhận biết các loài chim','00:00:12.300','00:00:14.800','4000-essential-english-words-9'),
	('I discovered pretty things and enjoyed the taste of new foods','Tôi đã khám phá ra những điều rất thú vị và thích hương vị của những món ăn mới lạ','00:00:14.800','00:00:19.400','4000-essential-english-words-9'),
	('It was a very nice time','Đó là khoảng thời gian rất tuyệt vời','00:00:19.400','00:00:21.800','4000-essential-english-words-9'),
	('One evening I took a pleasant walk by the ocean','Một buổi tối nọ, tôi thích thú đi dạo bên bờ biển','00:00:21.800','00:00:25.400','4000-essential-english-words-9'),
	('When the waves came in, many starfish fell on the beach','Khi những cơn sóng xô tới, rất nhiều con sao biển bị dạt vào bờ','00:00:25.450','00:00:29.800','4000-essential-english-words-9'),
	('Some starfish went back into the water, and they were safe','Một vài con sao biển đã quay trở lại làn nước, và chúng được an toàn','00:00:29.800','00:00:34.400','4000-essential-english-words-9'),
	('But other starfish were still on the sand','Nhưng những con sao biển khác vẫn còn nằm trên cát','00:00:34.400','00:00:37.800','4000-essential-english-words-9'),
	('They would die if they did not get into the water','Chúng sẽ chết nếu không được đưa xuống nước','00:00:37.800','00:00:41.000','4000-essential-english-words-9'),
	('There were many starfish on the beach that night','Có rất nhiều sao biển ở trên bờ biển vào tối hôm đó','00:00:41.000','00:00:44.300','4000-essential-english-words-9'),
	('It made me sad, but I knew I could not fix the problem','Điều này làm tôi cảm thấy buồn, nhưng tôi biết tôi không thể giải quyết vấn đề này được','00:00:44.300','00:00:48.450','4000-essential-english-words-9'),
	('I stepped very carefully so I did not damage them','Tôi bước rất cẩn thận để không làm tổn thương chúng','00:00:48.550','00:00:52.400','4000-essential-english-words-9'),
	('Then I saw a little girl','Rồi tôi thấy một cô bé','00:00:52.400','00:00:54.930','4000-essential-english-words-9'),
	('She was also sad about the starfish','Cô bé cũng buồn vì những con sao biển','00:00:54.950','00:00:57.900','4000-essential-english-words-9'),
	('She wanted to prevent all of them from dying','Cô muốn ngăn tất cả chúng khỏi việc chết dần','00:00:57.900','00:01:01.400','4000-essential-english-words-9'),
	('She asked me if I could perhaps help her','Cô bé hỏi tôi rằng liệu tôi có thể giúp cô không','00:01:01.400','00:01:04.700','4000-essential-english-words-9'),
	('"To be frank, I don\'t think we can do anything," I said','"Thật lòng thì chú không nghĩ chúng ta có thể làm được điều gì đâu," tôi nói','00:01:04.700','00:01:08.800','4000-essential-english-words-9'),
	('The little girl started to cry','Cô bé bắt đầu khóc','00:01:08.800','00:01:11.100','4000-essential-english-words-9'),
	('She sat back against a rock and thought for a while','Cô ngồi dựa lưng vào một tảng đá và nghĩ một lúc','00:01:11.100','00:01:15.000','4000-essential-english-words-9'),
	('Finally, the emotion was gone','Cuối cùng, khi cảm xúc đó qua đi','00:01:15.000','00:01:17.700','4000-essential-english-words-9'),
	('She stopped crying and stood up','Cô bé ngừng khóc và đứng dậy','00:01:17.700','00:01:20.700','4000-essential-english-words-9'),
	('Then she picked up a starfish and threw it into the water','Rồi cô bé nhặt một con sao biển lên và ném nó xuống nước','00:01:20.720','00:01:24.600','4000-essential-english-words-9'),
	('"What are you doing?" I asked her','"Cháu đang làm gì vậy?" tôi hỏi cô bé','00:01:24.600','00:01:27.100','4000-essential-english-words-9'),
	('But she did not answer me','Nhưng cô nhóc không trả lời tôi','00:01:27.100','00:01:28.550','4000-essential-english-words-9'),
	('She just threw as many starfish as she could','Cô bé chỉ ném nhiều sao biển xuống nước hết sức có thể','00:01:28.650','00:01:31.800','4000-essential-english-words-9'),
	('"You cannot save all of them" I said','"Cháu không thể cứu tất cả chúng" tôi nói','00:01:31.900','00:01:35.100','4000-essential-english-words-9'),
	('She stopped to look at me','Cô bé dừng lại nhìn tôi','00:01:35.100','00:01:37.000','4000-essential-english-words-9'),
	('"No, I cannot save them all," she replied','"Không, cháu không thể cứu tất cả," cô bé đáp lại','00:01:37.000','00:01:40.450','4000-essential-english-words-9'),
	('Then she picked up a very big starfish and said, "But I can save this one"','Rồi cô nhặt một con sao biển rất lớn lên và nói: "Nhưng cháu có thể cứu sống con này"','00:01:40.520','00:01:45.800','4000-essential-english-words-9'),
	('And then she smiled and threw the starfish as far as she could into the ocean','Và rồi cô bé mỉm cười và ném con sao biển ấy xa nhất có thể vào đại dương bao la','00:01:45.800','00:01:52.000','4000-essential-english-words-9'),

	/* (UUID(),'4000-essential-english-words-10','The first peacock','Con công đầu tiên','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_010.mp3',NULL,'00:00:00.000','00:02:01.000','4000-essential-english-words','YES',10) */
	('The First Peacock','Con công đầu tiên','00:00:00.960','00:00:03.000','4000-essential-english-words-10'),
	('Argos lived in Ancient Greece','Argos sống ở Hy Lạp cổ đại','00:00:03.000','00:00:05.900','4000-essential-english-words-10'),
	('He was a husband and a proud father','Anh ấy là một người chồng và một người cha đáng tự hào','00:00:05.900','00:00:08.900','4000-essential-english-words-10'),
	('He worked hard and did well at his job','Anh ấy làm việc chăm chỉ và làm tốt công việc của mình','00:00:08.900','00:00:11.900','4000-essential-english-words-10'),
	('But one thing about him wasn\'t normal','Nhưng có một điều không bình thường về anh ấy','00:00:11.900','00:00:14.700','4000-essential-english-words-10'),
	('He was born with 100 eyes','Anh ấy sinh ra với 100 con mắt','00:00:14.700','00:00:17.600','4000-essential-english-words-10'),
	('Having many eyes was usually a benefit to him','Việc có nhiều mắt thường mang lại lợi ích cho anh ấy','00:00:17.600','00:00:21.300','4000-essential-english-words-10'),
	('He had a chance to see many things','Anh có cơ hội nhìn thấy nhiều thứ','00:00:21.300','00:00:24.000','4000-essential-english-words-10'),
	('Also, since he had so many eyes, he was very good at guarding things','Hơn nữa, vì có nhiều mắt nên anh ấy rất giỏi canh gác mọi thứ','00:00:24.000','00:00:29.300','4000-essential-english-words-10'),
	('While sleeping, he only rested a few eyes at a time','Trong khi ngủ, anh chỉ nghỉ ngơi lần lượt vài con mắt','00:00:29.300','00:00:33.400','4000-essential-english-words-10'),
	('The others stayed awake','Những con mắt khác vẫn thức','00:00:33.400','00:00:35.200','4000-essential-english-words-10'),
	('He worked for Hera, a great goddess','Anh làm việc cho Hera, một nữ thần vĩ đại','00:00:35.200','00:00:38.000','4000-essential-english-words-10'),
	('His primary function was to guard a special cow','Nhiệm vụ chính của anh là bảo vệ một con bò đặc biệt','00:00:38.000','00:00:41.600','4000-essential-english-words-10'),
	('The cow was very important to Hera','Con bò rất quan trọng đối với Hera','00:00:41.600','00:00:43.880','4000-essential-english-words-10'),
	('It was her favorite pet','Đó là thú cưng yêu thích của cô','00:00:43.900','00:00:45.800','4000-essential-english-words-10'),
	('The most essential part of his job was to keep the cow alone','Phần quan trọng nhất trong công việc của anh là giữ con bò một mình','00:00:45.800','00:00:49.800','4000-essential-english-words-10'),
	('It had to be kept separate from all the other cows and far away from people','Nó phải được giữ tách biệt khỏi tất cả những con bò khác và cách xa mọi người','00:00:49.800','00:00:55.0000','4000-essential-english-words-10'),
	('This was an easy job for Argos','Đây là một công việc dễ dàng đối với Argos','00:00:55.000','00:00:57.800','4000-essential-english-words-10'),
	('The cow just ate grass all day','Con bò chỉ ăn cỏ cả ngày','00:00:57.800','00:01:00.800','4000-essential-english-words-10'),
	('But the god Zeus wanted the cow','Nhưng thần Zeus lại muốn con bò','00:01:00.800','00:01:03.200','4000-essential-english-words-10'),
	('He wanted to take it away from Hera','Ông ta muốn lấy nó khỏi Hera','00:01:03.200','00:01:05.900','4000-essential-english-words-10'),
	('He had a plan','Ông có một kế hoạch','00:01:05.900','00:01:07.900','4000-essential-english-words-10'),
	('He found a great music player','Ông tìm thấy một người chơi nhạc tuyệt vời','00:01:07.900','00:01:10.900','4000-essential-english-words-10'),
	('He asked the man to play a beautiful song for Argos','Ông yêu cầu người đàn ông chơi một bài hát thật hay cho Argos nghe','00:01:10.900','00:01:14.900','4000-essential-english-words-10'),
	('Zeus was certain Argos would go to sleep','Zeus chắc chắn Argos sẽ chìm vào giấc ngủ','00:01:14.900','00:01:18.300','4000-essential-english-words-10'),
	('The song had an immediate effect','Bài hát có tác dụng ngay lập tức','00:01:18.300','00:01:21.000','4000-essential-english-words-10'),
	('Argos couldn\'t focus on his job','Argos không thể tập trung vào công việc','00:01:21.000','00:01:23.800','4000-essential-english-words-10'),
	('He fell asleep','Anh đã ngủ quên','00:01:23.800','00:01:25.700','4000-essential-english-words-10'),
	('Zeus saw this, and he took the cow','Zeus thấy vậy và lấy đi con bò','00:01:25.700','00:01:28.600','4000-essential-english-words-10'),
	('Hera was very angry with Argos','Hera rất tức giận với Argos','00:01:28.600','00:01:31.600','4000-essential-english-words-10'),
	('She turned him into a peacock','Cô biến anh thành một con công','00:01:31.600','00:01:34.000','4000-essential-english-words-10'),
	('She put his many eyes on his tail','Cô đặt nhiều mắt trên chiếc đuôi anh','00:01:34.000','00:01:37.000','4000-essential-english-words-10'),
	('Argos was very sad','Argos rất buồn','00:01:37.000','00:01:39.700','4000-essential-english-words-10'),
	('Zeus saw how much trouble he had caused Argos','Zeus thấy mình đã gây ra bao nhiêu rắc rối cho Argos','00:01:39.700','00:01:43.500','4000-essential-english-words-10'),
	('He made another plan','Ông đã thực hiện một kế hoạch khác','00:01:43.500','00:01:45.400','4000-essential-english-words-10'),
	('He turned Argos into a group of stars','Ông biến Argos thành một tốp các ngôi sao','00:01:45.400','00:01:48.400','4000-essential-english-words-10'),
	('He wanted Argos to remain in the sky forever','Ông muốn Argos vẫn luôn ở trên bầu trời mãi mãi','00:01:48.400','00:01:51.900','4000-essential-english-words-10'),
	('Even today, Argos\' image remains there, above the site where all his problems began','Thậm chí cho tới ngày nay, hình ảnh của Argos vẫn còn ở đó, ngay trên nơi mà tất cả những rắc rối của anh bắt đầu','00:01:51.900','00:01:58.500','4000-essential-english-words-10'),
	('We can still see him in the night sky','Chúng ta vẫn có thể nhìn thấy anh ấy trên bầu trời đêm','00:01:58.500','00:02:01.000','4000-essential-english-words-10');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-11','Princess Rose and the creature','Công chúa Hoa Hồng và các sinh Vật','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_011.mp3',NULL,'00:00:00.000','00:02:04.000','4000-essential-english-words','NO',11) */
	('Princess Rose and the Creature','Công chúa Hoa Hồng và Sinh Vật','00:00:00.960','00:00:03.800','4000-essential-english-words-11'),
	('There was once a beautiful princess named Rose','Thuở xa xưa có một nàng công chúa xinh đẹp tên là Rose','00:00:03.800','00:00:07.400','4000-essential-english-words-11'),
	('Her mother, the queen, however, was not as beautiful as the princess','Mẹ của nàng, hoàng hậu, trái lại, không xinh đẹp bằng công chúa','00:00:07.400','00:00:12.500','4000-essential-english-words-11'),
	('The queen felt bad that she was not the most beautiful woman in the kingdom anymore','Nữ hoàng cảm thấy tồi tệ vì bà không còn là người phụ nữ đẹp nhất trong vương quốc nữa','00:00:12.500','00:00:18.000','4000-essential-english-words-11'),
	('She was tired of competing with her daughter','Bà kiệt sức vì phải tranh đấu với con gái','00:00:18.000','00:00:21.400','4000-essential-english-words-11'),
	('She made a decision','Bà đã đưa ra một quyết định','00:00:21.400','00:00:23.200','4000-essential-english-words-11'),
	('She prepared a drink for the princess','Bà chuẩn bị đồ uống cho công chúa','00:00:23.200','00:00:26.200','4000-essential-english-words-11'),
	('After the princess drank it, she fell asleep','Sau khi công chúa uống hết, nàng đã ngủ thiếp đi','00:00:26.200','00:00:29.600','4000-essential-english-words-11'),
	('Then the queen took the princess to the forest','Sau đó hoàng hậu đưa công chúa vào rừng','00:00:29.600','00:00:32.530','4000-essential-english-words-11'),
	('She left the princess there','Bà ta bỏ lại công chúa ở đó','00:00:32.680','00:00:34.400','4000-essential-english-words-11'),
	('It was a very serious thing to do','Đó là một điều rất nghiêm trọng','00:00:34.800','00:00:37.100','4000-essential-english-words-11'),
	('"Either she will be killed by animals or she will get lost in the forest," the queen thought','"Hoặc là nàng sẽ bị giết bởi các loài vật, hoặc là nàng sẽ lạc lối ở trong rừng," hoàng hậu thầm nghĩ','00:00:37.100','00:00:43.330','4000-essential-english-words-11'),
	('The princess had a dream','Công chúa mơ một giấc mơ','00:00:43.400','00:00:45.100','4000-essential-english-words-11'),
	('She dreamed about a man with brown hair and brown eyes','Nàng mơ thấy một người đàn ông tóc nâu và mắt nâu','00:00:45.100','00:00:49.000','4000-essential-english-words-11'),
	('It was the man she would wed','Đó là người đàn ông nàng sẽ kết hôn','00:00:49.050','00:00:50.930','4000-essential-english-words-11'),
	('The princess woke up','Công chúa chợt tỉnh giấc','00:00:50.950','00:00:52.800','4000-essential-english-words-11'),
	('She saw a strange creature on the ground','Nàng thấy một sinh vật kỳ lạ trên mặt đất','00:00:52.800','00:00:55.800','4000-essential-english-words-11'),
	('It looked like a man, but he was hairy and green','Thoạt nhìn giống như một người đàn ông, nhưng hắn ta lại đầy lông lá và có màu xanh lục','00:00:55.800','00:00:59.800','4000-essential-english-words-11'),
	('He had horns on his head and a pig\'s nose','Hắn có cặp sừng ở trên đầu và một chiếc mũi lợn','00:00:59.800','00:01:03.300','4000-essential-english-words-11'),
	('The creature said, "Did I scare you?"','Sinh vật đó lên tiếng: "Ta làm ngươi sợ à?"','00:01:03.300','00:01:06.800','4000-essential-english-words-11'),
	('"I hope not"','Ta mong rằng không phải vậy','00:01:06.850','00:01:08.200','4000-essential-english-words-11'),
	('"Let me introduce myself"','Cho phép ta tự giới thiệu về mình','00:01:08.200','00:01:10.230','4000-essential-english-words-11'),
	('"I am Henry"','Ta tên là Henry','00:01:10.300','00:01:11.500','4000-essential-english-words-11'),
	('"I am not scared"','Ta không sợ gì cả','00:01:11.500','00:01:13.400','4000-essential-english-words-11'),
	('"To tell you the truth, I think you are cute," said Rose','"Thật lòng mà nói, ta nghĩ nàng rất dễ thương," Rose nói','00:01:13.400','00:01:17.450','4000-essential-english-words-11'),
	('Rose and Henry spent the day together','Rose và Henry đã dành cả ngày bên nhau','00:01:17.650','00:01:20.400','4000-essential-english-words-11'),
	('They collected berries, caught fish, and had lunch','Họ thu nhặt quả mọng, bắt cá và ăn trưa','00:01:20.400','00:01:24.300','4000-essential-english-words-11'),
	('They had a very good day filled with nice conversations','Họ đã có một ngày vô cùng tốt đẹp tràn ngập những cuộc trò chuyện thú vị','00:01:24.300','00:01:28.900','4000-essential-english-words-11'),
	('"Rose, I have to go home," said Henry','"Rose, ta phải về nhà rồi," Henry nói','00:01:29.000','00:01:32.900','4000-essential-english-words-11'),
	('"My ship will sail home soon"','Con tàu của ta sẽ sớm ra khơi trở về nhà','00:01:32.900','00:01:35.250','4000-essential-english-words-11'),
	('"I can\'t leave you here in the forest alone"','Ta không thể bỏ em lại đây một mình trong rừng được','00:01:35.300','00:01:38.300','4000-essential-english-words-11'),
	('"Will you come with me?"','"Em sẽ đi cùng ta chứ?"','00:01:38.300','00:01:40.200','4000-essential-english-words-11'),
	('Rose was very happy','Rose vô cùng hạnh phúc','00:01:40.200','00:01:42.200','4000-essential-english-words-11'),
	('She gave Henry a kiss right on his pig nose','Nàng trao cho Henry một nụ hôn ngay lên chiếc mũi heo của anh','00:01:42.200','00:01:45.600','4000-essential-english-words-11'),
	('As soon as she kissed Henry, he began to change','Ngay lúc nàng hôn Henry, anh ta đã bắt đầu biến đổi','00:01:45.600','00:01:49.600','4000-essential-english-words-11'),
	('His pig nose turned into a man\'s nose','Chiếc mũi heo của anh ta biến thành chiếc mũi người','00:01:49.600','00:01:52.600','4000-essential-english-words-11'),
	('His horns and green hair went away','Cặp sừng và mái tóc xanh của anh ta biến mất','00:01:52.600','00:01:55.600','4000-essential-english-words-11'),
	('Standing in front of her was the man Rose had dreamt about','Đứng trước mặt nàng là người đàn ông mà Rose đã mơ thấy','00:01:55.600','00:02:00.000','4000-essential-english-words-11'),
	('Rose and Henry were married, and they lived happily','Rose và Henry kết hôn, và họ sống hạnh phúc','00:02:00.000','00:02:04.000','4000-essential-english-words-11'),

	/* (UUID(),'4000-essential-english-words-12','The crazy artist','Người nghệ sĩ điên','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_012.mp3',NULL,'00:00:00.000','00:02:11.500','4000-essential-english-words','NO',12) */
	('The Crazy Artist','Người nghệ sĩ điên','00:00:00.960','00:00:03.800','4000-essential-english-words-12'),
	('Frenhofer was the best artist in the world','Frenhofer là nghệ sĩ giỏi nhất thế giới','00:00:03.800','00:00:06.800','4000-essential-english-words-12'),
	('Everyone loved him','Mọi người đều yêu mến anh ấy','00:00:06.800','00:00:08.800','4000-essential-english-words-12'),
	('The quality of his paintings was very high','Chất lượng các bức tranh của anh ấy rất cao','00:00:08.800','00:00:12.000','4000-essential-english-words-12'),
	('He always used the best materials','Anh luôn sử dụng những nguyên liệu tốt nhất','00:00:12.000','00:00:15.000','4000-essential-english-words-12'),
	('He made a big profit from his paintings','Anh kiếm được một khoản lợi nhuận lớn từ những bức tranh của mình','00:00:15.000','00:00:18.000','4000-essential-english-words-12'),
	('He had delicious meals with his rich neighbors','Anh có những bữa ăn ngon cùng những người hàng xóm giàu có','00:00:18.000','00:00:21.300','4000-essential-english-words-12'),
	('He taught art classes','Anh dạy các lớp vẽ','00:00:21.300','00:00:23.200','4000-essential-english-words-12'),
	('Life was good','Cuộc sống rất tốt đẹp','00:00:23.200','00:00:25.000','4000-essential-english-words-12'),
	('Then his attitude changed','Rồi thái độ của anh ấy thay đổi','00:00:25.000','00:00:27.400','4000-essential-english-words-12'),
	('He stopped selling paintings and teaching','Anh không còn bán tranh và dạy học nữa','00:00:27.400','00:00:30.000','4000-essential-english-words-12'),
	('He tried a new method of painting','Anh đã thử một phương pháp vẽ tranh mới','00:00:30.000','00:00:32.800','4000-essential-english-words-12'),
	('He stayed alone in his apartment all day','Anh ở một mình trong căn hộ cả ngày','00:00:32.800','00:00:35.800','4000-essential-english-words-12'),
	('He worked all day and all night, rarely eating','Anh làm việc cả ngày lẫn đêm, hiếm khi ăn','00:00:35.800','00:00:39.300','4000-essential-english-words-12'),
	('Soon Frenhofer became very thin','Không lâu sau Frenhofer dần trở nên vô cùng gầy gò','00:00:39.300','00:00:42.200','4000-essential-english-words-12'),
	('But he kept working on the same painting for many years','Nhưng anh vẫn tiếp tục làm việc trên cùng bức tranh trong nhiều năm','00:00:42.200','00:00:46.000','4000-essential-english-words-12'),
	('He worked as hard as he could','Anh làm việc chăm chỉ nhất có thể','00:00:46.000','00:00:48.400','4000-essential-english-words-12'),
	('Finally, he finished the painting','Cuối cùng, anh đã hoàn thành bức tranh','00:00:48.400','00:00:51.300','4000-essential-english-words-12'),
	('He was very happy and invited other artists to see it','Anh vô cùng vui mừng và mời những họa sĩ khác đến xem','00:00:51.300','00:00:54.800','4000-essential-english-words-12'),
	('"I want your professional opinion," he said','"Tôi muốn ý kiến chuyên môn của mọi người" anh ấy nói','00:00:54.800','00:00:57.800','4000-essential-english-words-12'),
	('He wanted them to judge it and compare it to other paintings','Anh muốn họ đánh giá và so sánh nó với những bức tranh khác','00:00:57.800','00:01:01.800','4000-essential-english-words-12'),
	('Everyone was very excited as they went up the stairs to his apartment','Mọi người đều rất háo hức khi họ đi lên cầu thang tới căn hộ của anh ấy','00:01:01.800','00:01:06.400','4000-essential-english-words-12'),
	('Frenhofer was excited to show his painting, and the artists were excited to see it','Frenhofer rất háo hức khoe bức tranh của mình, và các nghệ sĩ cũng rất mong mỏi được xem nó','00:01:06.400','00:01:11.400','4000-essential-english-words-12'),
	('"They\'ll love it," he thought','"Họ sẽ thích nó," anh ta nghĩ','00:01:11.400','00:01:14.400','4000-essential-english-words-12'),
	('But they did not','Nhưng họ thì không','00:01:14.400','00:01:16.800','4000-essential-english-words-12'),
	('They were surprised by his painting','Họ ngạc nhiên bởi bức vẽ của anh','00:01:16.800','00:01:19.400','4000-essential-english-words-12'),
	('There was no white anywhere','Không hề có màu trắng ở đâu cả','00:01:19.500','00:01:21.900','4000-essential-english-words-12'),
	('Frenhofer filled the whole painting with lines and colors','Frenhofer lấp đầy toàn bộ bức tranh bằng những đường nét và màu sắc','00:01:21.900','00:01:25.800','4000-essential-english-words-12'),
	('There was no space for a normal picture','Không hề có khoảng trống cho một bức tranh bình thường','00:01:25.800','00:01:28.800','4000-essential-english-words-12'),
	('It was full of strange shapes','Nó đầy những hình thù kỳ lạ','00:01:28.800','00:01:30.800','4000-essential-english-words-12'),
	('It looked bad to the other artists','Với các nghệ sĩ khác, nó trông tệ hại','00:01:30.800','00:01:33.800','4000-essential-english-words-12'),
	('He used symbols, and they didn\'t understand them','Anh sử dụng các ký hiệu và họ không hiểu chúng','00:01:33.800','00:01:37.300','4000-essential-english-words-12'),
	('They thought it was terrible','Họ nghĩ nó thật tệ hại','00:01:37.300','00:01:39.400','4000-essential-english-words-12'),
	('"Why did you paint this strange picture?" someone asked','"Tại sao cậu lại vẽ bức tranh kỳ lạ này?" ai đó hỏi','00:01:39.400','00:01:43.000','4000-essential-english-words-12'),
	('They didn\'t understand its beauty','Họ không thể hiểu được vẻ đẹp của nó','00:01:43.050','00:01:45.500','4000-essential-english-words-12'),
	('But after some time, many people began to like his painting','Nhưng sau một lúc, nhiều người bắt đầu thích tranh của anh ấy','00:01:45.500','00:01:49.500','4000-essential-english-words-12'),
	('People wrote articles about it in magazines','Mọi người viết bài báo về nó trên tạp chí','00:01:49.500','00:01:52.500','4000-essential-english-words-12'),
	('They said it was his best work','Họ nói đó là tác phẩm hay nhất của anh ấy','00:01:52.500','00:01:54.400','4000-essential-english-words-12'),
	('They loved his strange symbols','Họ yêu thích những biểu tượng kỳ lạ của anh','00:01:54.400','00:01:56.800','4000-essential-english-words-12'),
	('They loved his strange colors','Họ yêu thích những màu sắc kỳ lạ của anh','00:01:56.800','00:01:58.700','4000-essential-english-words-12'),
	('Frenhofer\'s painting reminded everyone that just because something was new didn\'t mean that it was bad','Bức tranh của Frenhofer nhắc nhở mọi người rằng chỉ vì một thứ gì đó mới mẻ thì không có nghĩa là nó tồi tệ','00:01:58.700','00:02:04.900','4000-essential-english-words-12'),
	('He also helped them to realize that sometimes it takes people a little time to understand great things','Anh cũng giúp họ nhận ra rằng đôi khi cần một chút thời gian để mọi người hiểu những điều tuyệt vời','00:02:04.900','00:02:11.500','4000-essential-english-words-12'),

	/* (UUID(),'4000-essential-english-words-13','The farmer and the cats','Người nông dân và những con mèo','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_013.mp3',NULL,'00:00:00.000','00:02:03.600','4000-essential-english-words','NO',13) */
	('The farmer and the cats','Người nông dân và những con mèo','00:00:00.960','00:00:03.500','4000-essential-english-words-13'),
	('Arthur was a responsible farmer, and Maria was a nice lady','Arthur là một người nông dân có trách nhiệm, và Maria là một người phụ nữ tốt bụng','00:00:03.600','00:00:09.000','4000-essential-english-words-13'),
	('But they were poor','Nhưng họ nghèo lắm','00:00:09.000','00:00:10.570','4000-essential-english-words-13'),
	('They owed the town lord money for their land','Họ nợ lãnh chúa thị trấn tiền đất','00:00:10.600','00:00:13.600','4000-essential-english-words-13'),
	('One summer, their farm burned','Một mùa hè nọ, trang trại của họ bị thiêu rụi','00:00:13.630','00:00:16.150','4000-essential-english-words-13'),
	('One structure caught fire, and most of the animals ran away',' Một công trình bị bốc cháy, và hầu hết các con vật đều bỏ chạy','00:00:16.250','00:00:20.800','4000-essential-english-words-13'),
	('Only the cats stayed','Chỉ có đàn mèo ở lại','00:00:20.800','00:00:22.700','4000-essential-english-words-13'),
	('So Arthur and Maria had to bring in their crops without an animal\'s help','Vậy là Arthur và Maria phải thu hoạch nông sản của họ mà không có sự giúp đỡ của các con vật','00:00:22.700','00:00:27.800','4000-essential-english-words-13'),
	('On a fall day, the lord demanded his money','Vào một ngày mùa thu, lãnh chúa đòi tiền của ông','00:00:27.800','00:00:31.300','4000-essential-english-words-13'),
	('Arthur asked if the lord could wait until he brought in his crops','Arthur hỏi liệu lãnh chúa có thể đợi đến khi ông thu hoạch mùa vụ','00:00:31.300','00:00:35.900','4000-essential-english-words-13'),
	('The lord was angry','Lãnh chúa trở nên tức giận','00:00:35.900','00:00:37.800','4000-essential-english-words-13'),
	('He raised his hands high and yelled, "Pay me by the end of the week"','Ông ta giơ tay cao và hét lên, "Phải trả tiền cho tao vào cuối tuần"','00:00:37.800','00:00:42.400','4000-essential-english-words-13'),
	('"If you don\'t, I will increase the money you have to pay"','Còn nếu mày không làm được, tao sẽ tăng số tiền mà mày phải trả lên','00:00:42.400','00:00:46.100','4000-essential-english-words-13'),
	('"I might put you in a jail cell"','"Tao có thể tống mày vào một cái phòng giam đấy"','00:00:46.100','00:00:49.100','4000-essential-english-words-13'),
	('So Arthur and Maria worked until there was blood on their hands','Thế là Arthur và Maria đã làm việc cho đến khi bàn tay họ đã rướm máu','00:00:49.100','00:00:53.600','4000-essential-english-words-13'),
	('They finished four lines of corn and went to bed','Họ xong được bốn hàng cây ngô và lên giường đi ngủ','00:00:53.600','00:00:57.100','4000-essential-english-words-13'),
	('But the next morning, eight lines were finished','Nhưng đến sáng hôm sau, tám hàng đã xong','00:00:57.100','00:01:00.600','4000-essential-english-words-13'),
	('"Maria, didn\'t we stop in this spot here?" Arthur asked','"Maria, chẳng phải chúng ta dừng ở chỗ này hay sao?" Arthur hỏi','00:01:00.600','00:01:05.200','4000-essential-english-words-13'),
	('"Yes, that is correct"','"Phải, đúng vậy mà"','00:01:05.280','00:01:07.250','4000-essential-english-words-13'),
	('"And the tools were in a different position, too," Maria said','"Và các cái dụng cụ thì ở vị trí khác nữa kìa," Maria nói ','00:01:07.450','00:01:11.500','4000-essential-english-words-13'),
	('They were surprised and happy','Họ rất bất ngờ và vui sướng','00:01:11.600','00:01:14.050','4000-essential-english-words-13'),
	('That day, they worked hard and finished five lines','Ngày hôm đó, họ làm việc chăm chỉ và xong được 5 hàng','00:01:14.100','00:01:17.800','4000-essential-english-words-13'),
	('But in the morning, ten lines were done','Nhưng vào buổi sáng, có mười hàng đã được làm xong','00:01:17.800','00:01:20.800','4000-essential-english-words-13'),
	('Each day they did a lot of work','Mỗi ngày họ làm rất nhiều việc','00:01:20.800','00:01:23.800','4000-essential-english-words-13'),
	('Each night, someone else did an equal amount of work','Mỗi đêm, có người đã làm một lượng công việc tương tự','00:01:23.800','00:01:27.800','4000-essential-english-words-13'),
	('In a week, the whole field was finished','Trong một tuần, toàn bộ cánh đồng đã hoàn tất','00:01:27.800','00:01:30.800','4000-essential-english-words-13'),
	('"Tomorrow I will sell the crops and pay the lord," Arthur said','"Ngày mai anh sẽ đi bán nông sản và trả tiền cho lãnh chúa," Arthur nói','00:01:30.800','00:01:35.400','4000-essential-english-words-13'),
	('But that morning, the crops were gone','Nhưng sáng hôm đó, nông sản đã biến mất','00:01:35.400','00:01:37.830','4000-essential-english-words-13'),
	('A bag was in the middle of the field','Có một cái túi ở giữa cánh đồng','00:01:37.850','00:01:40.800','4000-essential-english-words-13'),
	('It contained money','Nó đựng tiền trong đó','00:01:40.640','00:01:42.400','4000-essential-english-words-13'),
	('"Maria, let\'s see who has helped us work"','"Maria, hãy xem ai là người đã giúp chúng ta làm việc nào"','00:01:42.400','00:01:45.800','4000-essential-english-words-13'),
	('Through a hole in the wall, they saw a funny sight','Qua một cái lỗ ở trên tường, họ nhìn thấy một cảnh tượng khôi hài','00:01:45.800','00:01:49.300','4000-essential-english-words-13'),
	('The cats were dancing in the field and eating corn','Lũ mèo đang nhảy múa trên cánh đồng và đang ăn ngô','00:01:49.300','00:01:53.000','4000-essential-english-words-13'),
	('Now Arthur knew what had happened','Giờ thì Arthur biết chuyện gì đã xảy ra','00:01:53.100','00:01:55.800','4000-essential-english-words-13'),
	('The cats had worked at night','Đàn mèo đã làm việc vào ban đêm','00:01:55.800','00:01:57.750','4000-essential-english-words-13'),
	('After that, Arthur was very nice to his cats and fed them lots of corn','Kể từ đó, Arthur rất tốt với những con mèo của anh và cho chúng ăn rất nhiều ngô','00:01:57.780','00:02:03.600','4000-essential-english-words-13'),

	/* (UUID(),'4000-essential-english-words-14','A magical book','Cuốn sách phép thuật','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_014.mp3',NULL,'00:00:00.000','00:02:12.000','4000-essential-english-words','NO',14) */
	('A magical book','Cuốn sách phép thuật','00:00:00.960','00:00:03.000','4000-essential-english-words-14'),
	('Sarah loved to read','Sarah thích đọc sách','00:00:03.000','00:00:05.100','4000-essential-english-words-14'),
	('She read novels and poems','Cô bé đọc tiểu thuyết và thơ','00:00:05.100','00:00:08.000','4000-essential-english-words-14'),
	('She loved the beautiful descriptions and phrases','Cô bé yêu thích những đoạn miêu tả và cụm từ lôi cuốn','00:00:08.000','00:00:11.200','4000-essential-english-words-14'),
	('She loved reading work from poets and novelists','Cô bé cũng yêu thích đọc những tác phẩm của các nhà thơ và tiểu thuyết gia','00:00:11.200','00:00:15.000','4000-essential-english-words-14'),
	('She didn\'t like video games or technology','Cô bé Sarah lại không thích trò chơi điện tử hay công nghệ','00:00:15.000','00:00:18.000','4000-essential-english-words-14'),
	('She was on the basketball team, but she didn\'t like sports','Sarah là thành viên của đội bóng rổ, nhưng cô bé lại không thích chơi thể thao','00:00:18.000','00:00:22.600','4000-essential-english-words-14'),
	('Her parents made her play basketball','Bố mẹ bắt cô bé chơi bóng rổ','00:00:22.600','00:00:25.100','4000-essential-english-words-14'),
	('In fact, Sarah\'s parents made her do many things','Thực ra thì, bố mẹ của Sarah buộc cô bé làm rất nhiều thứ','00:00:25.100','00:00:28.600','4000-essential-english-words-14'),
	('But she didn\'t want to do those things','Nhưng cô lại không muốn làm những điều đó','00:00:28.600','00:00:31.600','4000-essential-english-words-14'),
	('She just wanted to sit and read all day','Cô bé chỉ muốn ngồi một chỗ và đọc sách cả ngày thôi','00:00:31.600','00:00:34.600','4000-essential-english-words-14'),
	('One day, a small book came in the mail','Một ngày nọ, có một cuốn sách nhỏ được gửi đến hộp thư','00:00:34.600','00:00:37.600','4000-essential-english-words-14'),
	('It was for Sarah','Nó dành cho Sarah','00:00:37.600','00:00:39.400','4000-essential-english-words-14'),
	('The book looked very special','Quyển sách trông rất đặc biệt','00:00:39.400','00:00:41.450','4000-essential-english-words-14'),
	('It was printed on sheets of gold','Nó được in bằng những tờ giấy bằng vàng','00:00:41.500','00:00:44.000','4000-essential-english-words-14'),
	('Sarah began to read','Sarah bắt đầu đọc','00:00:44.000','00:00:45.800','4000-essential-english-words-14'),
	('The outline of the story was simple','Bố cục câu chuyện khá đơn giản','00:00:45.800','00:00:48.500','4000-essential-english-words-14'),
	('It was about a magical place','Nó kể về một vùng đất phép thuật','00:00:48.600','00:00:51.500','4000-essential-english-words-14'),
	('Strange things happened there','Những điều kỳ lạ đã diễn ra ở đó','00:00:51.500','00:00:53.800','4000-essential-english-words-14'),
	('One example from the book was about a boy who could control people','Một ví dụ từ cuốn sách nói về một cậu bé có thể điều khiển người khác','00:00:53.800','00:00:57.800','4000-essential-english-words-14'),
	('In one scene, he made his friends tell funny jokes','Trong một khung cảnh, cậu ta đã khiến cho bạn mình phải kể ra những câu chuyện cười hài hước','00:00:57.800','00:01:01.800','4000-essential-english-words-14'),
	('Sarah loved the book','Sarah rất thích cuốn sách','00:01:01.800','00:01:03.600','4000-essential-english-words-14'),
	('She read it all the time','Cô lúc nào cũng đọc nó','00:01:03.600','00:01:05.560','4000-essential-english-words-14'),
	('Then something strange happened','Rồi một chuyện lạ lùng đã xảy ra','00:01:05.560','00:01:07.800','4000-essential-english-words-14'),
	('The book gave Sarah a special power','Quyển sách tặng cho Sarah một năng lực đặc biệt','00:01:07.800','00:01:11.200','4000-essential-english-words-14'),
	('She could control other people','Cô có thể điều khiển được người khác','00:01:11.200','00:01:13.700','4000-essential-english-words-14'),
	('She was like the boy in the book','Cô trở nên giống hệt như cậu bé ở trong sách','00:01:13.700','00:01:16.200','4000-essential-english-words-14'),
	('During one exam, she made her friend tell silly jokes','Trong suốt buổi kiểm tra, cô khiến cho bạn mình phải kể những câu chuyện đùa ngớ ngẩn','00:01:16.200','00:01:20.500','4000-essential-english-words-14'),
	('Her friend got in trouble','Bạn bè của cô gặp rắc rối','00:01:20.500','00:01:22.400','4000-essential-english-words-14'),
	('After school, Sarah did not make a direct trip home','Tan học, Sarah không đi thẳng về nhà','00:01:22.400','00:01:26.200','4000-essential-english-words-14'),
	('On the way, she went to the local store','Trên đường đi, cô ấy đã đến một cửa hàng trong vùng','00:01:26.200','00:01:29.200','4000-essential-english-words-14'),
	('She wanted to play more tricks on people','Cô muốn chơi khăm mọi người','00:01:29.200','00:01:31.700','4000-essential-english-words-14'),
	('She caused problems','Cô đã gây ra rất nhiều rắc rối','00:01:31.700','00:01:33.600','4000-essential-english-words-14'),
	('She made people fall down','Cô làm cho mọi người bị trượt ngã','00:01:33.900','00:01:35.900','4000-essential-english-words-14'),
	('She laughed and had fun','Cô bật cười và rất vui vẻ','00:01:35.900','00:01:38.200','4000-essential-english-words-14'),
	('Finally she left and started to walk home','Cuối cùng, Sarah rời khỏi đó và bắt đầu đi bộ về nhà','00:01:38.200','00:01:41.500','4000-essential-english-words-14'),
	('Then she saw something','Rồi cô nhìn thấy cái gì đó','00:01:41.500','00:01:43.300','4000-essential-english-words-14'),
	('Her basketball coach was about to walk in front of a bus','Huấn luyện viên bóng rổ của cô sắp đi tới phía trước một cái xe buýt','00:01:43.300','00:01:47.200','4000-essential-english-words-14'),
	('He was looking the other way','Ông ấy đang nhìn sang hướng khác','00:01:47.200','00:01:49.000','4000-essential-english-words-14'),
	('She had to stop him','Cô phải ngăn ông lại','00:01:49.000','00:01:50.800','4000-essential-english-words-14'),
	('She used her power','Cô sử dụng năng lực của mình','00:01:50.800','00:01:52.800','4000-essential-english-words-14'),
	('She controlled him','Cô đã kiểm soát được ông','00:01:52.800','00:01:54.800','4000-essential-english-words-14'),
	('She made him stop walking','Cô khiến cho ông dừng bước','00:01:54.800','00:01:56.800','4000-essential-english-words-14'),
	('Sarah learned something that day','Sarah đã học được một điều vào ngày hôm đó','00:01:56.800','00:01:59.300','4000-essential-english-words-14'),
	('It was better to help people than make them suffer','Giúp đỡ người khác sẽ tốt hơn là việc khiến họ bị tổn thương','00:01:59.300','00:02:02.800','4000-essential-english-words-14'),
	('So, she put a limit on how she used her power','Vì thế, cô bé đặt ra giới hạn cho việc cô dùng sức mạnh của mình','00:02:02.800','00:02:05.800','4000-essential-english-words-14'),
	('She did not want to do bad things with it anymore','Cô bé không muốn làm những điều xấu với nó nữa','00:02:05.800','00:02:09.200','4000-essential-english-words-14'),
	('She only wanted to do good','Cô chỉ muốn làm những điều tốt mà thôi','00:02:09.200','00:02:12.000','4000-essential-english-words-14'),

	/* (UUID(),'4000-essential-english-words-15','The big race','Cuộc đua lớn','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_015.mp3',NULL,'00:00:00.000','00:02:07.000','4000-essential-english-words','NO',15) */
	('The big race','Cuộc đua lớn','00:00:00.960','00:00:03.000','4000-essential-english-words-15'),
	('A dog saw a group of animals across the road','Một chú chó nhìn thấy một nhóm các loài vật ở bên kia đường','00:00:03.000','00:00:06.500','4000-essential-english-words-15'),
	('He walked over to meet them','Chú bèn tiến lại để gặp chúng','00:00:06.600','00:00:08.800','4000-essential-english-words-15'),
	('"What are you doing?" he asked them','"Mấy cậu đang làm gì vậy?" chú chó hỏi','00:00:08.800','00:00:11.800','4000-essential-english-words-15'),
	('"I just sold them tickets to a race between the rabbit and the turtle," the duck responded','"Tôi vừa mới bán cho họ vé xem cuộc đua giữa thỏ và rùa," chú vịt trả lời','00:00:11.800','00:00:17.800','4000-essential-english-words-15'),
	('This news excited the dog','Tin tức này khiến chú chó thích thú','00:00:17.800','00:00:20.300','4000-essential-english-words-15'),
	('He felt fortunate that he happened to be there','Chú cảm thấy may mắn vì tình cờ ở đây','00:00:20.300','00:00:23.800','4000-essential-english-words-15'),
	('"I don\'t have anything to do today," the dog said','"Hôm nay, tôi chẳng có bất cứ việc gì để làm" chú chó nói','00:00:23.800','00:00:26.800','4000-essential-english-words-15'),
	('"I want to buy a ticket, too"','"Tôi cũng muốn mua một vé"','00:00:27.000','00:00:29.300','4000-essential-english-words-15'),
	('The dog sat down to observe the race','Chú chó ngồi xuống để theo dõi cuộc đua','00:00:29.300','00:00:32.300','4000-essential-english-words-15'),
	('The race would be extreme','Cuộc đua sẽ rất khắc nghiệt','00:00:32.300','00:00:34.100','4000-essential-english-words-15'),
	('It would be many kilometers in length','Nó sẽ kéo dài nhiều cây số','00:00:34.200','00:00:37.000','4000-essential-english-words-15'),
	('The rabbit and the turtle stood next to each other','Chú thỏ và chú rùa đứng cạnh nhau','00:00:37.000','00:00:40.300','4000-essential-english-words-15'),
	('They waited for the race to start','Họ chờ cho cuộc đua bắt đầu','00:00:40.400','00:00:42.820','4000-essential-english-words-15'),
	('The dog wondered why the turtle agreed to run against the rabbit','Chú chó thắc mắc tại sao chú rùa lại đồng ý chạy đua với chú thỏ','00:00:42.820','00:00:47.400','4000-essential-english-words-15'),
	('Being fast was not a characteristic of turtles','Nhanh nhẹn không phải là một đặc điểm của loài rùa','00:00:47.500','00:00:51.500','4000-essential-english-words-15'),
	('The rabbit was going to win easily','Chú thỏ sẽ chiến thắng dễ dàng','00:00:51.500','00:00:54.000','4000-essential-english-words-15'),
	('Suddenly, the race began','Đột nhiên, cuộc đua bắt đầu','00:00:54.000','00:00:56.400','4000-essential-english-words-15'),
	('The rabbit ran extremely quickly','Chú thỏ chạy cực kỳ nhanh','00:00:56.440','00:00:59.200','4000-essential-english-words-15'),
	('The turtle walked slowly','Chú rùa bước đi chậm chạp','00:00:59.200','00:01:01.400','4000-essential-english-words-15'),
	('After a minute, the rabbit looked back','Sau một phút, chú thỏ nhìn lại','00:01:01.400','00:01:04.200','4000-essential-english-words-15'),
	('He saw that the turtle was far behind him and was breathing quickly because he was so tired','Chú thấy chú rùa còn cách mình rất xa phía sau và đang thở gấp vì nó quá mệt','00:01:04.200','00:01:10.400','4000-essential-english-words-15'),
	('The rabbit smiled and slowed to a walk','Chú thỏ mỉm cười và đi chậm lại','00:01:10.400','00:01:13.400','4000-essential-english-words-15'),
	('A minute later, the rabbit said, "I\'m winning, so I\'ll take a rest"','Một phút sau, chú thỏ nói, "Ta thắng chắc rồi nên ta nghỉ một lát đã"','00:01:13.400','00:01:18.020','4000-essential-english-words-15'),
	('He sat and began to consume some grass','Chú ngồi xuống và bắt đầu ăn vài ngọn cỏ','00:01:18.040','00:01:20.890','4000-essential-english-words-15'),
	('Then, he let his eyes close','Rồi chú nhắm mắt lại','00:01:20.920','00:01:22.900','4000-essential-english-words-15'),
	('He wasn\'t the winner yet','Chú vẫn chưa phải là người chiến thắng','00:01:23.100','00:01:24.800','4000-essential-english-words-15'),
	('But there was no risk of him losing the race',' Nhưng không có bất kỳ nguy cơ nào để chú thua cuộc đua này','00:01:24.800','00:01:28.300','4000-essential-english-words-15'),
	('He went to sleep','Chú chìm vào giấc ngủ','00:01:28.300','00:01:29.700','4000-essential-english-words-15'),
	('Hours later, a loud sound woke him','Vài giờ sau, một tiếng động lớn đánh thức chú','00:01:29.700','00:01:33.200','4000-essential-english-words-15'),
	('All of the animals were yelling and looking at the field','Tất cả mọi con vật đều đang la hét và nhìn về phía cánh đồng','00:01:33.200','00:01:36.950','4000-essential-english-words-15'),
	('He felt fear for the first time','Lần đầu tiên trong đời chú cảm thấy sợ hãi','00:01:37.000','00:01:39.600','4000-essential-english-words-15'),
	('The turtle was almost at the finish line','Chú Rùa đa gần tới vạch đích','00:01:39.600','00:01:42.600','4000-essential-english-words-15'),
	('Now, the rabbit realized his mistake','Đến bây giờ, chú thỏ đã nhận ra sai lầm của mình','00:01:42.600','00:01:45.500','4000-essential-english-words-15'),
	('But the race was over','Nhưng cuộc đua đã kết thúc','00:01:45.500','00:01:47.200','4000-essential-english-words-15'),
	('He gave the turtle an opportunity to win, and the turtle took it','Chú đã tặng Rùa cơ hội chiến thắng, và Rùa đã nắm lấy cơ hội đó','00:01:47.200','00:01:52.000','4000-essential-english-words-15'),
	('The duck handed the turtle his prize','Chú vịt trao giải thưởng cho Rùa','00:01:52.000','00:01:54.490','4000-essential-english-words-15'),
	('It was the happiest day of the turtle\'s life','Đó là ngày hạnh phúc nhất trong cuộc đời của Rùa','00:01:54.500','00:01:57.800','4000-essential-english-words-15'),
	('The dog was happy for the turtle','Chú chó mừng cho chú rùa','00:01:57.800','00:02:00.270','4000-essential-english-words-15'),
	('"He isn\'t fast," the dog thought','"Anh ấy không hề nhanh nhẹn," chú chó nghĩ','00:02:00.300','00:02:02.820','4000-essential-english-words-15'),
	('"But he tried his best and did something great"','"Nhưng anh ấy đã cố hết sức mình và làm nên những điều tuyệt vời"','00:02:02.900','00:02:06.870','4000-essential-english-words-15');

