INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-16','Adams county\'s gold','Vàng ở quận Adams','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_016.mp3',NULL,'00:00:00.000','00:02:11.200','4000-essential-english-words','NO',16) */
	('Adams county\'s gold','Vàng ở quận Adams','00:00:00.960','00:00:03.000','4000-essential-english-words-16'),
	('Adams Academy was a good school','Học viện Adams là một trường học tuyệt vời','00:00:03.000','00:00:06.500','4000-essential-english-words-16'),
	('Boys lived there and took classes','Các bé trai sống ở đó và tham gia các lớp học','00:00:06.500','00:00:09.500','4000-essential-english-words-16'),
	('Tom worked hard all week','Tom đã làm việc chăm chỉ cả tuần','00:00:09.600','00:00:12.000','4000-essential-english-words-16'),
	('On a spring Saturday, he wanted to do something fun','Vào một ngày thứ 7 của mùa xuân, cậu bé muốn làm gì đó thật vui','00:00:12.000','00:00:15.800','4000-essential-english-words-16'),
	('He asked his friend Jeff to go to the movie theater','Tom rủ bạn cậu, Jeff, đi tới rạp chiếu phim','00:00:15.800','00:00:19.000','4000-essential-english-words-16'),
	('"Sorry," Jeff answered','"Xin lỗi cậu," Jeff trả lời','00:00:19.000','00:00:21.300','4000-essential-english-words-16'),
	('"I\'m going to a concert"','"Tớ sẽ đi xem hòa nhạc"','00:00:21.300','00:00:23.000','4000-essential-english-words-16'),
	('So Tom asked Joe to go to the movies','Nên Tom rủ John đi xem phim','00:00:23.000','00:00:26.000','4000-essential-english-words-16'),
	('But Joe\'s soccer team had a game','Nhưng đội bóng đá của Joe có một trận đấu','00:00:26.000','00:00:28.500','4000-essential-english-words-16'),
	('Next, Tom went down the hall to Brad\'s room','Sau đó, Tom đi dọc theo sảnh tới phòng Brad','00:00:28.500','00:00:32.500','4000-essential-english-words-16'),
	('Brad was reading a very large old book','Brad đang đọc cuốn sách cũ rất to','00:00:32.500','00:00:35.800','4000-essential-english-words-16'),
	('"Hi, Brad," Tom said','"Chào Brad," Tom nói','00:00:35.800','00:00:38.300','4000-essential-english-words-16'),
	('"Are you reading a dictionary?"','"Cậu đang đọc từ điển à?"','00:00:38.300','00:00:40.200','4000-essential-english-words-16'),
	('"It looks ancient"','"Nó trông cổ nhỉ?"','00:00:40.300','00:00:42.200','4000-essential-english-words-16'),
	('"No"','"Không"','00:00:42.200','00:00:43.140','4000-essential-english-words-16'),
	('"This is called The Wealth of Adams County"','"Nó được gọi là Sự giàu có của thành phố Adams"','00:00:43.200','00:00:46.200','4000-essential-english-words-16'),
	('"It\'s about hidden gold in Adams County"','"Nó nói về số vàng bị cất giấu ở thành phố Adams"','00:00:46.200','00:00:49.200','4000-essential-english-words-16'),
	('"It\'s more than a century old"','"Nó hơn 100 năm tuổi rồi đó"','00:00:49.200','00:00:51.800','4000-essential-english-words-16'),
	('"It was published in 1870"','"Nó được xuất bản năm 1870"','00:00:51.800','00:00:54.500','4000-essential-english-words-16'),
	('"Look, it even has the original cover on it"','"Nhìn này, nó thậm chí còn có cả bìa gốc nữa"','00:00:54.500','00:00:58.000','4000-essential-english-words-16'),
	('Tom asked, "Where did you get it?"','Tom liền hỏi, "Cậu lấy nó ở đâu thế?"','00:00:58.000','00:01:01.000','4000-essential-english-words-16'),
	('"It\'s from my dad\'s friend"','"Từ bạn của bố mình đấy"','00:01:01.000','00:01:03.020','4000-essential-english-words-16'),
	('"He is a nice gentleman, an officer in the army," answered Brad','"Chú ấy là một quý ông tốt bụng, một sĩ quan trong quân đội đấy" Brad đáp lại','00:01:03.070','00:01:07.700','4000-essential-english-words-16'),
	('"The gold doesn\'t really exist, does it?" Tom asked','"Số vàng đó không thực sự tồn tại, đúng không?" Tom hỏi tiếp','00:01:07.700','00:01:12.800','4000-essential-english-words-16'),
	('"I don\'t know, but maybe"','"Tớ không biết, nhưng có thể có"','00:01:12.800','00:01:15.200','4000-essential-english-words-16'),
	('"There are clues to it in this book"','"Có những manh mối về nó trong cuốn sách đấy"','00:01:15.200','00:01:17.200','4000-essential-english-words-16'),
	('"Let\'s find it"','"Mình thử tìm nhé"','00:01:17.200','00:01:18.800','4000-essential-english-words-16'),
	('"Looking for gold sounded like fun"','"Việc tìm vàng nghe có vẻ vui mà"','00:01:18.800','00:01:21.400','4000-essential-english-words-16'),
	('The first clue was to find a flat tree underground','Manh mối đầu tiên là việc tìm một cái cây nằm ngang dưới mặt đất','00:01:21.400','00:01:25.200','4000-essential-english-words-16'),
	('"It must be in the forest," Tom said','"Nó nhất định là ở trong rừng," Tom nói','00:01:25.200','00:01:28.600','4000-essential-english-words-16'),
	('Brad said, "The flat tree could be a board under the dirt"','Brad lại nói, "Cây nằm ngang à, có lẽ là chiếc phản dưới chỗ bùn kia"','00:01:28.650','00:01:33.200','4000-essential-english-words-16'),
	('"It could cover the gold"','"Nó có thể che đi chỗ vàng đấy"','00:01:33.200','00:01:35.200','4000-essential-english-words-16'),
	('Tom and Brad dug in the dirt all morning','Tom và Brad đào tung chỗ bùn cả buổi sáng','00:01:35.200','00:01:38.500','4000-essential-english-words-16'),
	('The process of looking for gold made them hungry','Quá trình tìm vàng khiến họ đói bụng','00:01:38.500','00:01:41.800','4000-essential-english-words-16'),
	('They were ready to stop for lunch','Chúng chuẩn bị dừng lại để ăn trưa','00:01:41.800','00:01:44.000','4000-essential-english-words-16'),
	('But then Brad hit something hard','Nhưng rồi Brad va phải vật gì đó cứng','00:01:44.000','00:01:46.400','4000-essential-english-words-16'),
	('It was a board','Đó là tấm phản','00:01:46.400','00:01:47.800','4000-essential-english-words-16'),
	('Brad pounded on the board until it broke','Brad đập mạnh vào tấm phản cho đến khi nó bị vỡ','00:01:47.840','00:01:51.200','4000-essential-english-words-16'),
	('There was a small hole under it','Có một chiếc lỗ nhỏ dưới đó','00:01:51.200','00:01:53.600','4000-essential-english-words-16'),
	('"Look"','"Nhìn kìa"','00:01:53.600','00:01:54.810','4000-essential-english-words-16'),
	('He held up a gold coin','Cậu bé nhặt lên một đồng xu vàng','00:01:54.840','00:01:57.100','4000-essential-english-words-16'),
	('Tom saw a piece of paper in the hole','Tom nhìn thấy một mẩu giấy trong lỗ','00:01:57.100','00:02:00.000','4000-essential-english-words-16'),
	('"Brad. There\'s more"','"Brad. Còn nữa đấy"','00:02:00.000','00:02:01.840','4000-essential-english-words-16'),
	('"It\'s a map to the rest of the gold"','"Đó là bản đồ tới số vàng còn lại"','00:02:01.840','00:02:04.200','4000-essential-english-words-16'),
	('Brad smiled','Brad mỉm cười','00:02:04.200','00:02:06.000','4000-essential-english-words-16'),
	('"Let\'s go"','"Đi thôi"','00:02:06.000','00:02:07.800','4000-essential-english-words-16'),
	('And they hurried to find the wealth of Adams County','Và chúng vội vã đi tìm số tài sản ở quận Adams','00:02:07.800','00:02:11.200','4000-essential-english-words-16'),

	/* (UUID(),'4000-essential-english-words-17','The race for water','Cuộc đua giành nước','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_017.mp3',NULL,'00:00:00.000','00:02:10.300','4000-essential-english-words','NO',17) */
	('The race for water','Cuộc đua giành nước','00:00:00.960','00:00:03.400','4000-essential-english-words-17'),
	('There was a town next to a river','Có một thị trấn nhỏ bên cạnh một dòng sông','00:00:03.400','00:00:06.400','4000-essential-english-words-17'),
	('The people there had a lot of water','Mọi người ở đây có rất nhiều nước','00:00:06.400','00:00:09.400','4000-essential-english-words-17'),
	('But they wasted it','Nhưng họ lại lãng phí nó','00:00:09.400','00:00:11.300','4000-essential-english-words-17'),
	('That made the Sky angry','Điều đó đã làm Trời nổi giận','00:00:11.300','00:00:13.800','4000-essential-english-words-17'),
	('It said, "If you waste water, I will take it away from you"','Người nói rằng : "Nếu các người hoang phí nước, ta sẽ lấy nó từ các ngươi"','00:00:13.800','00:00:18.800','4000-essential-english-words-17'),
	('But the people didn\'t listen','Nhưng không ai lắng nghe','00:00:18.800','00:00:21.200','4000-essential-english-words-17'),
	('When the season changed from spring to summer, the clouds disappeared','Khi thời tiết thay đổi từ mùa xuân sang mùa hạ, những đám mây dần biến mất','00:00:21.200','00:00:26.200','4000-essential-english-words-17'),
	('The bright sun was hot and made the river dry','Mặt trời chói chang nóng rực khiến cho dòng sông khô cạn','00:00:26.200','00:00:30.200','4000-essential-english-words-17'),
	('There was no water available','Không còn nguồn nước sẵn có nữa','00:00:30.200','00:00:32.600','4000-essential-english-words-17'),
	('People asked, "When will the rain fall?"','Mọi người hỏi: "Bao giờ thì mưa sẽ rơi?"','00:00:32.600','00:00:36.150','4000-essential-english-words-17'),
	('The Sky\'s response was, "You don\'t appreciate water"','Trời đáp lại rằng : "Các ngươi không trân trọng nước"','00:00:36.200','00:00:40.450','4000-essential-english-words-17'),
	('"You waste it, and now I will never make rain again"','"Các ngươi đã hoang phí nó, và giờ ta sẽ không bao giờ làm mưa nữa"','00:00:40.540','00:00:44.800','4000-essential-english-words-17'),
	('A boy determined that this wasn\'t fair','Một cậu bé xác nhận rằng điều này không công bằng chút nào','00:00:44.800','00:00:47.800','4000-essential-english-words-17'),
	('He thought of a solution','Cậu đã nghĩ ra một cách','00:00:47.800','00:00:49.650','4000-essential-english-words-17'),
	('He asked the Sky to race him','Cậu bé yêu cầu Trời hãy chạy thi với mình','00:00:49.650','00:00:51.800','4000-essential-english-words-17'),
	('He said, "If I get to the top of that hill before your rain can form puddles, you must fill our river"','Cậu bé nói : "Nếu tôi tới đỉnh đồi đó trước khi mưa của ông có thể tạo thành những vũng nước, thì ông phải cho đầy nước xuống dòng sông của chúng tôi"','00:00:51.800','00:00:59.600','4000-essential-english-words-17'),
	('The Sky laughed','Trời bật cười','00:00:59.600','00:01:01.020','4000-essential-english-words-17'),
	('"Little boy, I am the Sky"','"Này cậu bé, ta là Trời"','00:01:01.080','00:01:03.520','4000-essential-english-words-17'),
	('"I am above everything else"','"Ta ở trên tất cả mọi thứ khác"','00:01:03.560','00:01:05.760','4000-essential-english-words-17'),
	('"You cannot beat me"','"Ngươi không thể đánh bại được ta đâu"','00:01:05.800','00:01:07.800','4000-essential-english-words-17'),
	('But the boy knew he would win','Nhưng cậu bé biết chắc mình sẽ thắng','00:01:07.800','00:01:10.300','4000-essential-english-words-17'),
	('When the race began, the boy ran forward','Khi cuộc đua bắt đầu, cậu bé chạy về phía trước','00:01:10.300','00:01:13.800','4000-essential-english-words-17'),
	('The Sky started raining on the hill','Trời bắt đầu đổ mưa lên ngọn đồi','00:01:13.800','00:01:16.070','4000-essential-english-words-17'),
	('But puddles did not form there','Thế nhưng những vũng nước không thể hình thành ở đó được','00:01:16.200','00:01:18.400','4000-essential-english-words-17'),
	('When it rained on the hill, the water went down','Khi mưa ở đồi, nước cứ thế chảy xuống','00:01:18.450','00:01:21.980','4000-essential-english-words-17'),
	('The Sky kept raining','Trời lại tiếp tục mưa','00:01:22.000','00:01:24.200','4000-essential-english-words-17'),
	('The water flowed down into the river','Nước chảy xuống dòng sông','00:01:24.300','00:01:26.950','4000-essential-english-words-17'),
	('When the boy reached the top of the hill, the river was full','Khi cậu bé tới đỉnh đồi, nước ở sông đã đầy','00:01:26.970','00:01:31.350','4000-essential-english-words-17'),
	('The people began to celebrate','Người dân bắt đầu ăn mừng','00:01:31.360','00:01:33.800','4000-essential-english-words-17'),
	('It was the highest level the river had ever been at before','Đây là mức nước cao nhất mà dòng sông từng có trước đây','00:01:33.800','00:01:38.300','4000-essential-english-words-17'),
	('The Sky was angry','Trời nổi giận','00:01:38.300','00:01:40.100','4000-essential-english-words-17'),
	('"A boy can\'t beat me"','"Cậu bé không thể thắng được ta"','00:01:40.100','00:01:42.000','4000-essential-english-words-17'),
	('"I won\'t fill your river," it said','"Ta sẽ không lấp đầy dòng sông của các ngươi," trời nói','00:01:42.060','00:01:45.000','4000-essential-english-words-17'),
	('Now the boy laughed','Giờ thì cậu bé bật cười','00:01:45.120','00:01:46.800','4000-essential-english-words-17'),
	('"It doesn\'t matter whether you want to fill it or not," he said','"Điều đó không quan trọng là dù Ngài có muốn lấp đầy dòng sông hay không," cậu bé nói','00:01:46.800','00:01:50.920','4000-essential-english-words-17'),
	('"You already did"','"Ngài đã làm nó rồi"','00:01:51.100','00:01:52.570','4000-essential-english-words-17'),
	('The Sky looked at the full river','Trời nhìn thấy dòng sông tràn đầy nước','00:01:52.610','00:01:55.100','4000-essential-english-words-17'),
	('"You tricked me," it said','"Ngươi đã lừa ta," trời nói','00:01:55.100','00:01:57.400','4000-essential-english-words-17'),
	('It asked the people, "Do you appreciate water now?"','Ngài hỏi người dân: "Các người giờ sẽ trân trọng nước chứ?"','00:01:57.450','00:02:01.400','4000-essential-english-words-17'),
	('"Yes," they said','"Vâng," họ nói','00:02:01.400','00:02:03.400','4000-essential-english-words-17'),
	('"We won\'t waste it"','"Chúng tôi sẽ không phí phạm nó nữa"','00:02:03.400','00:02:04.850','4000-essential-english-words-17'),
	('That is how a lone boy saved his town and won the race for water','Đó là cách cậu bé đơn độc cứu thị trấn của mình và giành chiến thắng trong cuộc đua giành nước','00:02:04.900','00:02:10.300','4000-essential-english-words-17'),

	/* (UUID(),'4000-essential-english-words-18','The little red chicken','Cô gà đỏ bé nhỏ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_018.mp3',NULL,'00:00:00.000','00:01:57.200','4000-essential-english-words','NO',18) */
	('A little red chicken had a store in a small town','Một con gà đỏ bé nhỏ có một cửa hàng trong một thị trấn nhỏ','00:00:02.800','00:00:07.300','4000-essential-english-words-18'),
	('She sold many different items to people in the town','Cô ta bán nhiều sản phẩm khác nhau cho mọi người trong thị trấn','00:00:07.300','00:00:11.300','4000-essential-english-words-18'),
	('The people loved her products','Mọi người đều thích những sản phẩm của cô','00:00:11.300','00:00:13.800','4000-essential-english-words-18'),
	('One day, a cat came to her property','Một ngày nọ, một chú mèo đã đến nhà của cô','00:00:13.800','00:00:16.800','4000-essential-english-words-18'),
	('He saw the sign that indicated where the chicken\'s store was located','Cậu ta thấy một ký hiệu chỉ đường đến nơi cửa hàng của cô gà nằm','00:00:16.800','00:00:21.300','4000-essential-english-words-18'),
	('He wanted to purchase bread, but the chicken\'s store was almost empty','Cậu ấy muốn mua bánh mì, nhưng cửa hàng của cô gà hầu như đã trống rỗng','00:00:21.300','00:00:25.800','4000-essential-english-words-18'),
	('She had only a bag of wheat','Cô ấy chỉ còn lại một túi lúa mì','00:00:25.800','00:00:28.700','4000-essential-english-words-18'),
	('"You can use the wheat to make bread," the chicken said','"Cậu có thể dùng lúa mì để làm bánh mì", cô gà nói','00:00:28.700','00:00:32.800','4000-essential-english-words-18'),
	('"No, I don\'t want to work," the cat said','"Không, tôi không muốn làm việc", con mèo nói','00:00:32.800','00:00:36.700','4000-essential-english-words-18'),
	('"I just want to buy bread"','"Tôi chỉ muốn mua bánh mì"','00:00:36.700','00:00:38.800','4000-essential-english-words-18'),
	('The cat became angry and left the store','Con mèo giận dữ và rời khỏi cửa hàng','00:00:38.800','00:00:42.200','4000-essential-english-words-18'),
	('Later, the little red chicken saw the cat in a crowd','Lát sau, cô gà đỏ bé nhỏ đã thấy chú mèo trong đám đông','00:00:42.200','00:00:46.800','4000-essential-english-words-18'),
	('"I will help you make the bread," she said','"Tôi sẽ giúp cậu làm bánh mì", cô ấy nói','00:00:46.800','00:00:50.300','4000-essential-english-words-18'),
	('But the cat treated her badly','Nhưng chú mèo đối xử với cô ấy rất tệ','00:00:50.300','00:00:52.800','4000-essential-english-words-18'),
	('He did not even communicate with her','Cậu ấy thậm chí còn không nói chuyện với cô','00:00:52.800','00:00:55.300','4000-essential-english-words-18'),
	('He did not want to do any work','Cậu ấy không muốn làm bất cứ việc gì','00:00:55.300','00:00:57.800','4000-essential-english-words-18'),
	('So the chicken decided to make the bread','Vì thế cô gà đã quyết định làm chiếc bánh mì','00:00:57.800','00:01:00.700','4000-essential-english-words-18'),
	('She selected the exact amount of wheat to make fresh bread','Cô chọn chính xác lượng lúa mì để làm bánh mì tươi','00:01:00.700','00:01:04.700','4000-essential-english-words-18'),
	('She used a stone to pound the wheat to get it ready','Cô dùng một hòn đá nghiền nhỏ lúa mì để chuẩn bị','00:01:04.700','00:01:08.400','4000-essential-english-words-18'),
	('Soon, her bread was ready','Chẳng bao lâu sau, bánh mì của cô ấy đã chuẩn bị sẵn sàng','00:01:08.400','00:01:11.200','4000-essential-english-words-18'),
	('The cat came and saw the bread on a dish','Chú mèo đến và thấy chiếc bánh mì ở trong đĩa','00:01:11.200','00:01:14.400','4000-essential-english-words-18'),
	('"Give me some of your bread," he said','"Hãy cho tôi một ít bánh mì," anh ấy nói','00:01:14.500','00:01:17.800','4000-essential-english-words-18'),
	('"No," said the little red chicken','"Không được," cô gà đỏ bé nhỏ nói','00:01:17.800','00:01:20.800','4000-essential-english-words-18'),
	('"You did not help me make the bread"','"Cậu đã không giúp tôi làm bánh mì"','00:01:20.800','00:01:23.200','4000-essential-english-words-18'),
	('"So you shall not have any to eat"','"Vì thế cậu sẽ chẳng có gì để ăn cả"','00:01:23.200','00:01:25.400','4000-essential-english-words-18'),
	('The cat argued with the chicken','Chú mèo tranh cãi với cô gà','00:01:25.400','00:01:27.800','4000-essential-english-words-18'),
	('He tried to offer a price for it','Cậu ấy đã cố gắng đề nghị một mức giá cho chiếc bánh','00:01:27.800','00:01:29.800','4000-essential-english-words-18'),
	('But the little red chicken did not want to sell her bread','Nhưng cô gà đỏ nhỏ bé không muốn bán chiếc bánh mì của cô','00:01:29.800','00:01:33.300','4000-essential-english-words-18'),
	('"Don\'t depend on others to do work for you," said the little red chicken','"Đừng dựa dẫm vào người khác làm việc cho cậu," cô gà đỏ bé nhỏ nói','00:01:33.300','00:01:38.800','4000-essential-english-words-18'),
	('"Then how will I get bread?" the cat asked','"Vậy làm sao để tôi nhận được chiếc bánh mì?" chú mèo hỏi','00:01:38.800','00:01:42.800','4000-essential-english-words-18'),
	('"I recommend doing some work," said the little red chicken','"Tôi khuyên cậu nên làm một vài việc," cô gà đỏ bé nhỏ nói','00:01:42.800','00:01:46.800','4000-essential-english-words-18'),
	('"Use a tool to plant your own wheat"','"Dùng một dụng cụ để trồng lúa mì của chính cậu"','00:01:46.800','00:01:49.100','4000-essential-english-words-18'),
	('"When it grows big, you can gather it and make your own bread"','"Khi chúng lớn lên, cậu có thể thu hoạch chúng và làm bánh mì của riêng mình"','00:01:49.100','00:01:53.100','4000-essential-english-words-18'),
	('"You need to learn to do work for what you want"','"Cậu cần học cách làm việc cho những gì cậu muốn"','00:01:53.100','00:01:57.200','4000-essential-english-words-18'),

	/* (UUID(),'4000-essential-english-words-19','Shipwrecked','Đắm tàu','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_019.mp3',NULL,'00:00:00.000','00:02:14.800','4000-essential-english-words','NO',19) */
	('Shipwrecked','Đắm tàu','00:00:00.960','00:00:02.900','4000-essential-english-words-19'),
	('Simon Yates was a lawyer','Simon Yates là một luật sư','00:00:02.900','00:00:05.000','4000-essential-english-words-19'),
	('He helped many people','Ông ta giúp đỡ rất nhiều người','00:00:05.000','00:00:06.930','4000-essential-english-words-19'),
	('However, he was not a nice man','Tuy nhiên, ông ta không phải là một người tốt','00:00:07.000','00:00:10.000','4000-essential-english-words-19'),
	('His policy was to help only rich people','Chính sách của ông ta là chỉ giúp những người giàu có','00:00:10.000','00:00:14.000','4000-essential-english-words-19'),
	('He didn\'t bother about social injustice','Ông chẳng thèm bận tâm đến sự bất công xã hội','00:00:14.000','00:00:17.000','4000-essential-english-words-19'),
	('He made a lot of money, but many people didn\'t like him','Ông kiếm được rất nhiều tiền, nhưng mọi người chẳng ưa gì ông ta cả','00:00:17.000','00:00:21.800','4000-essential-english-words-19'),
	('Even people on his staff didn\'t like him','Ngay cả những người trong số nhân viên của ông ta cũng không hề ưa ông chút nào','00:00:21.800','00:00:25.200','4000-essential-english-words-19'),
	('They wanted bad things to happen to him','Họ chỉ mong những điều tồi tệ sẽ xảy đến với ông ta mà thôi','00:00:25.250','00:00:28.200','4000-essential-english-words-19'),
	('In fact, they were glad when he got into trouble','Thật ra, họ đã rất vui mừng khi ông ta gặp rắc rối','00:00:28.220','00:00:32.300','4000-essential-english-words-19'),
	('Simon had a very bad day','Simon đã có một ngày cực kỳ tồi tệ','00:00:32.300','00:00:35.200','4000-essential-english-words-19'),
	('He did many things wrong and lost his job','Ông ta đã làm nhiều điều sai lầm và mất việc','00:00:35.200','00:00:38.270','4000-essential-english-words-19'),
	('Soon, he didn\'t have any money','Không lâu sau, ông ta chẳng còn một xu dính túi','00:00:38.400','00:00:41.400','4000-essential-english-words-19'),
	('His wife, Mrs.Yates, began to have doubts about him','Vợ của ông ta, bà Yates, bắt đầu nghi ngờ ông','00:00:41.400','00:00:45.760','4000-essential-english-words-19'),
	('Simon wanted to start a new life','Simon muốn bắt đầu một cuộc sống mới','00:00:45.800','00:00:48.320','4000-essential-english-words-19'),
	('He planned to leave the country','Ông ta dự định sẽ rời khỏi quê hương','00:00:48.380','00:00:50.600','4000-essential-english-words-19'),
	('He mentioned his plan to the captain of a ship','Ông ta bày tỏ ý định này với thuyền trưởng của con tàu','00:00:50.600','00:00:54.000','4000-essential-english-words-19'),
	('The captain was exploring the world','Thuyền trưởng đã từng khám phá thế giới','00:00:54.000','00:00:57.000','4000-essential-english-words-19'),
	('The captain felt bad for Simon and said, "I will take you to foreign countries"','Thuyền trưởng cảm thấy tội nghiệp cho Simon và nói: "Tôi sẽ đưa cậu tới những quốc gia khác"','00:00:57.000','00:01:03.100','4000-essential-english-words-19'),
	('They left the next day','Họ rời đi vào ngày hôm sau','00:01:03.100','00:01:05.400','4000-essential-english-words-19'),
	('Near the conclusion of their international trip, the weather turned bad','Khi gần kết thúc chuyến hành trình quốc tế, thời tiết bỗng trở nên tồi tệ','00:01:05.400','00:01:10.800','4000-essential-english-words-19'),
	('A wave pushed Simon off the boat','Một cơn sóng đẩy Simon ra khỏi thuyền','00:01:10.800','00:01:13.800','4000-essential-english-words-19'),
	('But he was alive','Nhưng ông ta vẫn sống sót','00:01:13.900','00:01:15.600','4000-essential-english-words-19'),
	('He swam toward an island','Ông ta bơi về phía một hòn đảo','00:01:15.600','00:01:17.600','4000-essential-english-words-19'),
	('After a longtime he got there','Sau một lúc lâu ông ta đã tới đó','00:01:17.800','00:01:20.800','4000-essential-english-words-19'),
	('At first he was upset','Ban đầu, ông ta thấy rất buồn bực','00:01:20.800','00:01:23.200','4000-essential-english-words-19'),
	('He was lost and alone','Ông ta đã bị lạc và lại còn cô đơn','00:01:23.200','00:01:25.700','4000-essential-english-words-19'),
	('"I\'ll never go home again," he thought','"Mình sẽ không bao giờ trở về nhà được nữa", ông ta nghĩ','00:01:25.700','00:01:28.800','4000-essential-english-words-19'),
	('He had a lot of problems, but he survived','Simon gặp rất nhiều vấn đề nhưng ông ta vẫn sống sót','00:01:28.800','00:01:32.920','4000-essential-english-words-19'),
	('He built a house in a tree','Ông xây một ngôi nhà trên cây','00:01:32.950','00:01:35.350','4000-essential-english-words-19'),
	('He lived on a diet of fish','Ông sống bằng chế độ dinh dưỡng từ cá','00:01:35.350','00:01:38.200','4000-essential-english-words-19'),
	('He made tools from wood and bones','Ông chế tạo công cụ từ gỗ và xương','00:01:38.200','00:01:40.800','4000-essential-english-words-19'),
	('He made a cup to drink rainwater','Ông còn làm một chiếc cốc để uống nước mưa','00:01:40.800','00:01:43.800','4000-essential-english-words-19'),
	('Slowly he learned to be happy on the island','Dần dần ông đã học được cách để vui vẻ trên hòn đảo','00:01:43.800','00:01:47.320','4000-essential-english-words-19'),
	('He swam every day','Ông bơi lội hàng ngày','00:01:47.400','00:01:49.300','4000-essential-english-words-19'),
	('He had trouble sometimes, but he always found a way to fix the problem','Đôi khi ông ấy gặp rắc rối, nhưng ông luôn tìm được cách giải quyết rắc rối','00:01:49.400','00:01:54.500','4000-essential-english-words-19'),
	('Life was simple','Cuộc sống thật đơn giản','00:01:54.600','00:01:56.000','4000-essential-english-words-19'),
	('He liked it','Ông ta thích điều đó','00:01:56.130','00:01:57.500','4000-essential-english-words-19'),
	('Finally, people on a ship saw Simon on the island','Cuối cùng, những người ở trên thuyền cũng thấy Simon trên hòn đảo','00:01:57.500','00:02:01.600','4000-essential-english-words-19'),
	('They wanted to take him home','Họ muốn đưa ông về nhà','00:02:01.600','00:02:03.600','4000-essential-english-words-19'),
	('But Simon was happy','Nhưng Simon đang rất hạnh phúc','00:02:03.600','00:02:05.420','4000-essential-english-words-19'),
	('He gave them a long speech about life','Ông ấy còn tặng họ một bài diễn văn dài về cuộc sống','00:02:05.450','00:02:08.420','4000-essential-english-words-19'),
	('He said he wanted to stay','Ông nói ông muốn ở lại','00:02:08.450','00:02:10.500','4000-essential-english-words-19'),
	('He liked his new, simple life more than his old life','Ông thích cuộc sống mới, đơn giản này hơn cuộc sống trước kia','00:02:10.600','00:02:14.800','4000-essential-english-words-19'),

	/* (UUID(),'4000-essential-english-words-20','The seven cities of gold','Bảy thành phố vàng','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_020.mp3',NULL,'00:00:00.000','00:02:05.000','4000-essential-english-words','NO',20) */
	('Many years ago, a Spanish officer named Coronado heard the story of seven great cities','Rất nhiều năm về trước, một sĩ quan Tây Ban Nha tên là Coronado nghe được câu chuyện về bảy thành phố lớn','00:00:03.800','00:00:09.800','4000-essential-english-words-20'),
	('"The walls of these cities are made of gold," his friends told him','"Những bức tường của những thành phố này được làm bằng vàng," những người bạn đã nói với anh','00:00:09.800','00:00:13.800','4000-essential-english-words-20'),
	('"The people eat meat from golden plates and dress in nice clothes," they said','Họ nói: "Người dân ăn thịt từ những chiếc đĩa bằng vàng và mặc trang phục đẹp"','00:00:13.800','00:00:18.800','4000-essential-english-words-20'),
	('They called these cities the Seven Cities of Gold','Họ đã gọi những thành phố này là bảy thành phố vàng','00:00:18.800','00:00:22.000','4000-essential-english-words-20'),
	('Were the cities real?','Liệu những thành phố này có thực không?','00:00:22.000','00:00:23.800','4000-essential-english-words-20'),
	('Coronado never considered asking his friends','Coronado chưa bao giờ nghĩ đến việc hỏi những người bạn mình','00:00:23.800','00:00:26.800','4000-essential-english-words-20'),
	('Coronado thought to himself, "The things in these cities must be worth a lot of money"','Coronado nghĩ thầm, "Những thứ bên trong các thành phố này hẳn là đáng giá rất nhiều tiền"','00:00:26.800','00:00:31.800','4000-essential-english-words-20'),
	('So he went to find the Seven Cities of Gold','Nên anh ta đã đi tìm Bảy thành phố vàng đó','00:00:31.800','00:00:34.870','4000-essential-english-words-20'),
	('He took along three hundred men, many horses, and extra food','Anh ta dẫn theo ba trăm người đàn ông, rất nhiều ngựa và kèm theo đồ ăn','00:00:34.920','00:00:38.970','4000-essential-english-words-20'),
	('They headed west','Họ tiến về phía Tây','00:00:38.980','00:00:40.770','4000-essential-english-words-20'),
	('Coronado wanted to achieve his goal very badly','Coronado muốn đạt được mục tiêu của anh ta rất nhiều','00:00:40.780','00:00:44.000','4000-essential-english-words-20'),
	('Coronado and his men rode for many days','Coronado và những người đàn ông cưỡi ngựa đi trong nhiều ngày','00:00:44.000','00:00:46.980','4000-essential-english-words-20'),
	('Then they saw some cities','Rồi họ nhìn thấy một vài thành phố','00:00:47.000','00:00:49.200','4000-essential-english-words-20'),
	('"We found the Seven Cities of Gold," his men yelled, but Coronado wasn\'t happy','"Chúng ta đã tìm thấy Bảy thành phố vàng," những người đàn ông hét lên, nhưng Coronado không thấy vui','00:00:49.200','00:00:55.000','4000-essential-english-words-20'),
	('He had a different opinion','Anh ta có một quan điểm khác','00:00:55.000','00:00:56.800','4000-essential-english-words-20'),
	('"These can\'t be the Seven Cities of Gold," he said','"Đây không thể là Bảy thành phố vàng," anh ta nói,','00:00:56.800','00:01:00.700','4000-essential-english-words-20'),
	('"Look, they\'re made of dirt"','"Nhìn đi, chúng được làm bằng đất"','00:01:00.700','00:01:02.700','4000-essential-english-words-20'),
	('Coronado was right','Coronado đã đúng','00:01:02.730','00:01:04.230','4000-essential-english-words-20'),
	('The cities weren\'t bright and golden','Những thành phố này không tỏa sáng và bằng vàng','00:01:04.250','00:01:06.700','4000-essential-english-words-20'),
	('They were dirty and brown','Chúng trông bẩn và phủ màu nâu','00:01:06.700','00:01:08.430','4000-essential-english-words-20'),
	('The people didn\'t eat meat from golden plates','Người dân thì không ăn thịt từ những chiếc đĩa vàng','00:01:08.450','00:01:11.500','4000-essential-english-words-20'),
	('They ate vegetables from regular bowls','Họ ăn rau từ những chiếc bát thông thường','00:01:11.500','00:01:14.400','4000-essential-english-words-20'),
	('They wore the most basic clothes','Họ mặc những đồ cơ bản nhất','00:01:14.400','00:01:16.800','4000-essential-english-words-20'),
	('Coronado regarded the cities as ugly places','Coronado coi những thành phố đó là những nơi xấu xí','00:01:16.800','00:01:20.300','4000-essential-english-words-20'),
	('"What happened to the cities of gold?" he thought','"Chuyện gì đã xảy ra với những thành phố vàng vậy?" anh ta nghĩ','00:01:20.300','00:01:23.300','4000-essential-english-words-20'),
	('"Did someone destroy them?"','"Có phải ai đó đã phá hủy chúng?"','00:01:23.300','00:01:25.200','4000-essential-english-words-20'),
	('"Was there a war?"','"Có phải là một cuộc chiến?"','00:01:25.200','00:01:26.600','4000-essential-english-words-20'),
	('"Did someone already come and take the gold?"','"Có ai đó đã tới và lấy toàn bộ vàng?"','00:01:26.600','00:01:29.200','4000-essential-english-words-20'),
	('That night, the people of the cities entertained Coronado and his men and served them food','Đêm hôm đó, người dân trong những thành phố chiêu đãi Coronado và người của anh ta và phục vụ họ đồ ăn','00:01:29.200','00:01:34.930','4000-essential-english-words-20'),
	('They advised Coronado to go home','Họ khuyên Coronado về nhà','00:01:34.960','00:01:37.800','4000-essential-english-words-20'),
	('"There is no gold here," they told him','"Không có vàng ở đây đâu," họ nói với anh ta','00:01:37.800','00:01:40.300','4000-essential-english-words-20'),
	('Coronado was angry','Coronado rất tức giận','00:01:40.320','00:01:42.200','4000-essential-english-words-20'),
	('Did his friends lie to him?','Có phải bạn bè đã nói dối anh?','00:01:42.200','00:01:44.600','4000-essential-english-words-20'),
	('He left the next morning','Anh ta rời đi sáng hôm sau','00:01:44.600','00:01:46.500','4000-essential-english-words-20'),
	('He looked back at the cities one more time','Anh nhìn lại những thành phố đó một lần nữa','00:01:46.600','00:01:49.600','4000-essential-english-words-20'),
	('The sun reflected light on the dirt houses','Mặt trời phản chiếu ánh sáng lên những ngôi nhà bẩn thỉu đó','00:01:49.600','00:01:52.500','4000-essential-english-words-20'),
	('Coronado thought he saw a bit of gold','Coronado nghĩ rằng anh đã nhìn thấy một ít vàng','00:01:52.500','00:01:55.400','4000-essential-english-words-20'),
	('Were his friends right after all?','Có phải bạn bè của anh ta cuối cùng cũng đúng không?','00:01:55.400','00:01:57.800','4000-essential-english-words-20'),
	('"No," he told himself','"Không," anh ta tự nói với bản thân','00:01:57.800','00:02:00.000','4000-essential-english-words-20'),
	('"It\'s just the sun"','"Nó chỉ là do mặt trời thôi"','00:02:00.000','00:02:01.800','4000-essential-english-words-20'),
	('Then he turned away and went home','Rồi anh ta quay đi và trở về nhà','00:02:01.800','00:02:04.800','4000-essential-english-words-20');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-21','Katy','Katy','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_021.mp3',NULL,'00:00:00.000','00:02:02.000','4000-essential-english-words','NO',21) */
	('I first met 8-year-old Katy on a rainy afternoon','Tôi gặp cô bé Katy 8 tuổi lần đầu vào một buổi chiều mưa','00:00:02.800','00:00:06.800','4000-essential-english-words-21'),
	('I was a nurse at a hospital','Lúc đấy tôi là một y tá tại một bệnh viện','00:00:06.800','00:00:09.500','4000-essential-english-words-21'),
	('The clerk at the desk told me about Katy','Lễ tân tại bàn làm việc đã nói với tôi về Katy','00:00:09.600','00:00:12.800','4000-essential-english-words-21'),
	('She was there because she felt a lot of pain','Cô bé ở đó bởi vì cảm thấy quá đau','00:00:12.800','00:00:16.300','4000-essential-english-words-21'),
	('The doctors located a problem at the base of her brain','Các bác sĩ xác định được vấn đề nằm đáy não cô bé','00:00:16.300','00:00:20.900','4000-essential-english-words-21'),
	('I knew she was special, even before she got better','Tôi biết cô bé rất đặc biệt, kể cả trước khi cô bình phục','00:00:20.900','00:00:24.800','4000-essential-english-words-21'),
	('I\'ll always remember Katy as a hero','Tôi sẽ luôn mãi nhớ Katy như một người hùng','00:00:24.800','00:00:27.750','4000-essential-english-words-21'),
	('When I entered Katy\'s room, she was not in her bed','Khi tôi vào phòng của Katy, cô bé không ở trên giường của mình','00:00:27.750','00:00:31.800','4000-essential-english-words-21'),
	('She was in a chair next to Tommy, a little boy','Cô bé ngồi trên ghế cạnh Tommy','00:00:31.800','00:00:35.700','4000-essential-english-words-21'),
	('Though Katy did not feel well, she was playing with Tommy and his toys','Mặc dù Katy cảm thấy không khỏe, cô bé vẫn chơi cùng Tommy và đống đồ chơi của cậu','00:00:35.700','00:00:40.900','4000-essential-english-words-21'),
	('It took a lot of effort for her just to sit in the chair','Cô bé đã tốn rất nhiều công sức chỉ để ngồi trên ghế','00:00:40.900','00:00:45.000','4000-essential-english-words-21'),
	('But she played with Tommy because it made him happy','Nhưng cô bé vẫn chơi cùng Tommy bởi vì điều đó làm cô bé hạnh phúc','00:00:45.000','00:00:48.900','4000-essential-english-words-21'),
	('Katy was always smiling and never appeared to be in pain','Katy luôn luôn tươi cười và dường như chưa từng tỏ ra đau đớn','00:00:48.900','00:00:53.800','4000-essential-english-words-21'),
	('She refused to just lie in bed','Cô từ chối việc chỉ nằm mãi trên giường bệnh','00:00:53.800','00:00:56.900','4000-essential-english-words-21'),
	('One day, I found her painting a picture','Một ngày nọ, tôi thấy cô bé đang vẽ một bức tranh','00:00:56.900','00:01:00.400','4000-essential-english-words-21'),
	('Later, she gave it to one of the older patients','Sau đó, cô bé tặng nó cho một trong những bệnh nhân lớn tuổi','00:01:00.400','00:01:04.700','4000-essential-english-words-21'),
	('Another day she went outside to get flowers for another sick little girl','Một ngày khác, cô ấy đi ra ngoài để hái những bông hoa cho cô bé đang bị bệnh khác','00:01:04.700','00:01:10.000','4000-essential-english-words-21'),
	('Katy made everyone smile','Katy khiến mọi người buồn cười','00:01:10.000','00:01:12.800','4000-essential-english-words-21'),
	('The doctors hurried to fix the problem in Katy\'s brain','Các bác sĩ cũng mau chóng giải quyết được vấn đề trong não của Katy','00:01:12.800','00:01:16.800','4000-essential-english-words-21'),
	('The operation was successful','Ca phẫu thuật đã thành công','00:01:16.800','00:01:19.700','4000-essential-english-words-21'),
	('The doctors informed the hospital staff of the good news','Các bác sĩ đã thông báo với nhân viên bệnh viện tin tốt','00:01:19.700','00:01:23.800','4000-essential-english-words-21'),
	('Katy was fine','Katy đã khỏe','00:01:23.800','00:01:25.290','4000-essential-english-words-21'),
	('She soon felt excellent','Cô ấy sẽ sớm cảm thấy tuyệt vời','00:01:25.320','00:01:27.800','4000-essential-english-words-21'),
	('She got better and was able to leave the hospital a month later','Katy đã hồi phục và có thể rời khỏi bệnh viện một tháng sau đó','00:01:27.800','00:01:32.800','4000-essential-english-words-21'),
	('I have had a long career as a nurse','Tôi đã có một sự nghiệp dài với tư cách là một y tá','00:01:32.800','00:01:36.100','4000-essential-english-words-21'),
	('I have met many patients','Tôi đã gặp nhiều bệnh nhân','00:01:36.100','00:01:38.200','4000-essential-english-words-21'),
	('However, I have never met another girl like Katy','Tuy nhiên tôi chưa hề gặp cô gái nào như Katy cả','00:01:38.200','00:01:42.100','4000-essential-english-words-21'),
	('Even after she got well, she still came to the hospital','Ngay cả sau khi cô ấy bình phục, cô vẫn tiếp tục đến thăm bệnh viện','00:01:42.100','00:01:46.600','4000-essential-english-words-21'),
	('She played various games with the young patients','Cô ấy chơi nhiều trò chơi cùng các bệnh nhân trẻ tuổi','00:01:46.600','00:01:50.200','4000-essential-english-words-21'),
	('She read many books to the older patients','Cô ấy đọc nhiều loại sách cho các bệnh nhân lớn tuổi','00:01:50.200','00:01:53.260','4000-essential-english-words-21'),
	('Katy\'s kind heart helped her get better so quickly','Tấm lòng nhân hậu của Katy đã giúp cô ấy hồi phục rất nhanh','00:01:53.300','00:01:56.920','4000-essential-english-words-21'),
	('She is a hero to me and everyone else at the hospital','Cô ấy là một anh hùng đối với tôi và những người khác ở bệnh viện','00:01:56.920','00:02:01.800','4000-essential-english-words-21'),

	/* (UUID(),'4000-essential-english-words-22','A better reward','Một phần thưởng tuyệt vời hơn','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_022.mp3',NULL,'00:00:00.000','00:02:06.000','4000-essential-english-words','NO',22) */
	('Jenny delivered food for a restaurant','Jenny là giao đồ ăn cho một nhà hàng','00:00:03.000','00:00:05.800','4000-essential-english-words-22'),
	('She read the newspaper and said, "Uh oh"','Một ngày, cô ấy đọc báo và thốt lên: "Ồ"','00:00:05.800','00:00:09.100','4000-essential-english-words-22'),
	('There was a story about a thief','Đó là câu chuyện về một tên trộm','00:00:09.100','00:00:11.600','4000-essential-english-words-22'),
	('He stole food, and no one had seen him','Hắn ta lấy trộm đồ ăn, và chưa một ai nhìn thấy hắn cả','00:00:11.600','00:00:14.800','4000-essential-english-words-22'),
	('Even the police couldn\'t catch him','Thậm chí cả cảnh sát cũng chưa bắt được hắn','00:00:14.800','00:00:17.200','4000-essential-english-words-22'),
	('Jenny was a little scared','Jenny cảm thấy hơi sợ','00:00:17.200','00:00:19.500','4000-essential-english-words-22'),
	('She worked close to that area','Cô làm việc gần khu vực đó','00:00:19.500','00:00:21.800','4000-essential-english-words-22'),
	('The newspaper included a message from the police: "If anything strange occurs, call us"','Tờ báo kèm theo một tin nhắn từ cảnh sát: "Nếu điều gì bất thường xảy ra, hãy gọi cho chúng tôi"','00:00:21.800','00:00:27.800','4000-essential-english-words-22'),
	('"If you help us catch the thief, you\'ll earn a reward"','"Nếu bạn giúp chúng tôi bắt được tên trộm, bạn sẽ nhận được một phần thưởng"','00:00:27.800','00:00:31.730','4000-essential-english-words-22'),
	('Jenny talked to Jim','Jenny nói chuyện với Jim','00:00:31.770','00:00:33.800','4000-essential-english-words-22'),
	('He managed the restaurant','Anh ấy quản lý một nhà hàng','00:00:33.800','00:00:36.000','4000-essential-english-words-22'),
	('"Do you know about the thief?"','"Anh có biết kẻ trộm không?"','00:00:36.000','00:00:38.000','4000-essential-english-words-22'),
	('"Yes," he said','"Có", Jim nói','00:00:38.000','00:00:40.100','4000-essential-english-words-22'),
	('"But he steals more than one person can eat"','"Nhưng hắn ta trộm nhiều hơn đồ một người có thể ăn được"','00:00:40.100','00:00:42.800','4000-essential-english-words-22'),
	('"And why haven\'t the police stopped him yet?"','"Vậy sao cảnh sát vẫn chưa ngăn hắn ta lại?"','00:00:42.800','00:00:45.100','4000-essential-english-words-22'),
	('"It\'s a mystery"','"Đó là một bí ẩn"','00:00:45.100','00:00:46.900','4000-essential-english-words-22'),
	('"If you see him, contact the police"','"Nếu cô trông thấy hắn, hãy liên lạc với cảnh sát"','00:00:46.900','00:00:49.700','4000-essential-english-words-22'),
	('"Don\'t run after him"','"Đừng đuổi theo hắn"','00:00:49.700','00:00:51.200','4000-essential-english-words-22'),
	('Jenny drove to a customer\'s house','Jenny lái xe đến nhà của khách hàng','00:00:51.200','00:00:53.800','4000-essential-english-words-22'),
	('She left her car and opened the gate to the house','Cô để ô tô ở ngoài và mở cổng vào nhà','00:00:53.800','00:00:56.800','4000-essential-english-words-22'),
	('But then she heard a noise by her car','Nhưng rồi cô nghe thấy có tiếng động gần ô tô của mình','00:00:56.800','00:00:59.150','4000-essential-english-words-22'),
	('She yelled, "Thief"','Cô la lên: "Trộm"','00:00:59.150','00:01:01.800','4000-essential-english-words-22'),
	('She wasn\'t scared','Cô không thấy sợ chút nào','00:01:01.800','00:01:03.100','4000-essential-english-words-22'),
	('She wanted the reward','Cô muốn có phần thưởng','00:01:03.100','00:01:04.900','4000-essential-english-words-22'),
	('She did the opposite of what Jim told her to do','Cô làm ngược lại những gì Jim nói mình làm','00:01:04.900','00:01:07.800','4000-essential-english-words-22'),
	('"Hey," she yelled','"Này," cô hét to','00:01:07.800','00:01:09.900','4000-essential-english-words-22'),
	('"Get back here"','"Quay lại đây"','00:01:09.900','00:01:11.700','4000-essential-english-words-22'),
	('She set the food on the ground and ran to her car','Cô đặt đồ ăn xuống đất và chạy lại chiếc xe','00:01:11.700','00:01:14.700','4000-essential-english-words-22'),
	('But the thief had already left with the food','Nhưng tên trộm đã rời đi cùng đống đồ ăn','00:01:14.700','00:01:17.400','4000-essential-english-words-22'),
	('Jenny followed a noise around the corner','Jenny đi theo tiếng động quanh góc đường','00:01:17.400','00:01:20.100','4000-essential-english-words-22'),
	('She was amazed','Cô ngạc nhiên','00:01:20.100','00:01:21.800','4000-essential-english-words-22'),
	('She saw a dog and some puppies','Cô thấy một con chó to cùng vài chú cún con','00:01:21.800','00:01:24.800','4000-essential-english-words-22'),
	('They were eating her food','Chúng đang ăn số đồ ăn vừa bị trộm','00:01:24.800','00:01:26.800','4000-essential-english-words-22'),
	('They looked thin and scared','Chúng trông rất gầy và hoảng sợ','00:01:26.800','00:01:29.000','4000-essential-english-words-22'),
	('"The actual thief is just a dog"','"Kẻ trộm thực ra chỉ là một con chó"','00:01:29.000','00:01:31.850','4000-essential-english-words-22'),
	('"She\'s feeding her puppies," she said','"Nó đang cho lũ chó con ăn," cô nói','00:01:31.850','00:01:34.800','4000-essential-english-words-22'),
	('"That\'s why she steals so much food"','"Thế nên nó mới trộm nhiều đồ ăn như vậy"','00:01:34.800','00:01:37.800','4000-essential-english-words-22'),
	('Jenny felt bad','Jenny cảm thấy có lỗi','00:01:37.800','00:01:39.200','4000-essential-english-words-22'),
	('She tried to comfort the dogs with another plate of food','Cô cố gắng vỗ về những chú chó bằng một đĩa thức ăn khác','00:01:39.200','00:01:42.800','4000-essential-english-words-22'),
	('Then she took them back to the store','Sau đó cô đưa chúng quay lại cửa hàng','00:01:42.800','00:01:44.900','4000-essential-english-words-22'),
	('Everyone there took a puppy home','Mỗi người ở đó mang về nhà một chú chó con','00:01:44.900','00:01:47.800','4000-essential-english-words-22'),
	('Jenny called the police','Jenny gọi cho cảnh sát','00:01:47.800','00:01:49.800','4000-essential-english-words-22'),
	('She told them there was no real thief','Cô nói với họ rằng thật ra không có tên trộm nào cả','00:01:49.800','00:01:52.700','4000-essential-english-words-22'),
	('Jenny didn\'t do it to receive the reward anymore','Jenny không làm việc này để nhận phần thưởng nữa','00:01:52.700','00:01:55.900','4000-essential-english-words-22'),
	('She said, "It was just a dog"','Cô nói: "Đó chỉ là một con chó thôi"','00:01:55.900','00:01:58.800','4000-essential-english-words-22'),
	('"But there\'s no charge for catching this thief" she said','"Nhưng không có thù lao cho việc bắt được tên trộm này cả," cô nói','00:01:58.800','00:02:02.700','4000-essential-english-words-22'),
	('"My new dog is a better reward"','"Chú chó mới này là phần thưởng tuyệt vời hơn nhiều"','00:02:02.700','00:02:05.700','4000-essential-english-words-22'),

	/* (UUID(),'4000-essential-english-words-23','The camp','Lều trại','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_023.mp3',NULL,'00:00:00.000','00:02:05.000','4000-essential-english-words','NO',23) */
	('Stacie wanted to stay at a nice hotel for vacation','Stacie muốn ở một khách sạn thật đẹp trong kỳ nghỉ này','00:00:03.000','00:00:06.900','4000-essential-english-words-23'),
	('But her parents sent her to a terrible camp instead','Thế nhưng, thay vào đó bố mẹ cô đã gửi cô đến một trại hè tệ hại','00:00:06.900','00:00:10.800','4000-essential-english-words-23'),
	('For breakfast, Stacie liked fresh juice and chocolate milk, but she got water at the camp','Bữa sáng, Stacie thích nước ép trái cây và sữa socola, nhưng cô chỉ được uống nước lọc ở trại hè','00:00:10.800','00:00:17.800','4000-essential-english-words-23'),
	('In the afternoon she wanted to write poems, but she had to swim','Buổi chiều, Stacie muốn viết thơ nhưng cô lại phải đi bơi','00:00:17.800','00:00:22.800','4000-essential-english-words-23'),
	('The camp was near an airport with loud planes','Trại hè này ở gần một sân bay với những chiếc máy bay ồn ào','00:00:22.800','00:00:26.400','4000-essential-english-words-23'),
	('Spiderwebs hung over her bed','Thậm chí còn có mạng nhện trên giường cô bé nữa','00:00:26.500','00:00:29.500','4000-essential-english-words-23'),
	('To her, the kids\' average behavior was very bad','Cách hành xử của đám trẻ với cô bé cũng rất tệ','00:00:29.500','00:00:33.500','4000-essential-english-words-23'),
	('No girl matched her personality','Chẳng có cô bé nào hợp với tính cách của cô','00:00:33.500','00:00:36.300','4000-essential-english-words-23'),
	('She hated it','Cô bé rất ghét trại hè','00:00:36.300','00:00:37.600','4000-essential-english-words-23'),
	('One day, they had a class','Một ngày nọ, họ phải tham gia một lớp học','00:00:37.600','00:00:39.800','4000-essential-english-words-23'),
	('Mental exercise sounded good to Stacie','Những bài tập rèn luyện tinh thần nghe có vẻ hay với Stacie','00:00:39.800','00:00:42.800','4000-essential-english-words-23'),
	('But it was a course on water safety','Nhưng hóa ra nó lại là một khóa đào tạo kỹ năng an toàn dưới nước','00:00:42.800','00:00:45.800','4000-essential-english-words-23'),
	('They learned how to be safe passengers on a boat','Họ đã học cách bảo đảm an toàn cho mình khi đi thuyền','00:00:45.800','00:00:49.400','4000-essential-english-words-23'),
	('Stacie didn\'t ever plan to go on a boat','Stacie còn chẳng chuẩn bị trước là mình sẽ lên thuyền nữa','00:00:49.400','00:00:52.800','4000-essential-english-words-23'),
	('The next day, they played a game','Ngày tiếp theo, họ cùng nhau chơi một trò chơi','00:00:52.800','00:00:54.800','4000-essential-english-words-23'),
	('There were a red team and a blue team','Có 2 đội, một đôi xanh và đội còn lại là đội đỏ','00:00:54.800','00:00:58.800','4000-essential-english-words-23'),
	('Stacie was on the blue team','Stacie là thành viên của đội xanh','00:00:58.800','00:01:01.800','4000-essential-english-words-23'),
	('Each team had to try to remove the other team\'s flag from a pole','Mối đội phải cố gắng giật lấy cờ đang cắm ở trong 1 cái hố của đội kia ','00:01:01.800','00:01:05.800','4000-essential-english-words-23'),
	('They also had to use water guns','Họ cũng phải sử dụng súng nước nữa','00:01:05.800','00:01:09.400','4000-essential-english-words-23'),
	('"I\'m not much of an athlete," she said','"Tớ không phải người giỏi thể thao đâu" cô bé nói','00:01:09.400','00:01:12.100','4000-essential-english-words-23'),
	('But she still had to play','Thế nhưng cô bé vẫn phải chơi','00:01:12.100','00:01:14.600','4000-essential-english-words-23'),
	('Stacie took a water gun and looked for somewhere to hide','Stacie cầm một cây súng nước và tìm nơi nào đó để trốn','00:01:14.600','00:01:18.300','4000-essential-english-words-23'),
	('A boy said, "Stacie, you advance to the middle"','Một câu bé nói "Stacie, cậu di chuyển đến khu trung tâm nhé"','00:01:18.300','00:01:22.200','4000-essential-english-words-23'),
	('"I will go right"','"Tớ sẽ qua cánh phải"','00:01:22.200','00:01:23.600','4000-essential-english-words-23'),
	('"Those two will go left"','"Hai bạn kia sẽ qua cánh trái"','00:01:23.600','00:01:25.600','4000-essential-english-words-23'),
	('Stacie still didn\'t want to play','Stacie vẫn không muốn chơi','00:01:25.600','00:01:27.800','4000-essential-english-words-23'),
	('She walked into the forest and saw a red team player coming','Cô bé đi vào rừng và thấy một thành viên đội đỏ đang tiến tới','00:01:27.800','00:01:32.500','4000-essential-english-words-23'),
	('Stacie hid behind a tree and then jumped out and shot the other player','Stacie trốn sau một cái cây, sau đó cô bé nhảy ra và bắn đối thủ của mình','00:01:32.500','00:01:37.600','4000-essential-english-words-23'),
	('"This is fun" Stacie thought','"Vui thật đấy" Stacie nghĩ','00:01:37.600','00:01:40.600','4000-essential-english-words-23'),
	('Several minutes after advancing further, Stacie saw the red flag','Sau vài phút tiến lên, Stacie đã thấy được chiếc cờ đỏ','00:01:40.600','00:01:44.700','4000-essential-english-words-23'),
	('A red team member was watching over it','Có một thành viên đội đỏ đang canh chừng chiếc cờ đó','00:01:44.700','00:01:47.800','4000-essential-english-words-23'),
	('She shot him with her water gun','Và cô bé bắn cậu bằng súng nước','00:01:47.800','00:01:50.500','4000-essential-english-words-23'),
	('Then she lowered the flag and ran back to her team','Rồi cô bé cầm chiếc cờ xuống và chạy về với đội của mình','00:01:50.500','00:01:53.800','4000-essential-english-words-23'),
	('"I got it" she yelled','"Tớ lấy được rồi này" Cô bé hét lên','00:01:53.800','00:01:55.800','4000-essential-english-words-23'),
	('The blue team won','Đội xanh đã thắng rồi','00:01:55.800','00:01:57.600','4000-essential-english-words-23'),
	('Stacie was the hero','Stacie chính là anh hùng của cả đội','00:01:57.600','00:01:59.700','4000-essential-english-words-23'),
	('For the rest of the week, Stacie had fun','Và từ đó cho tới hết tuần, Stacie đã rất vui vẻ','00:01:59.700','00:02:02.700','4000-essential-english-words-23'),
	('She even made new friends','Cô bé thậm chí còn kết thêm nhiều bạn mới nữa','00:02:02.700','00:02:05.000','4000-essential-english-words-23'),

	/* (UUID(),'4000-essential-english-words-24','A strong friendship','Tình bạn mạnh mẽ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_024.mp3',NULL,'00:00:00.000','00:02:05.600','4000-essential-english-words','NO',24) */
	('Tim was the strongest man in the town','Tim là một chàng trai khỏe mạnh nhất trong thị trấn','00:00:03.000','00:00:06.000','4000-essential-english-words-24'),
	('When he played sports, he always won','Khi anh ấy chơi thể thao, anh ấy luôn luôn giành chiến thắng','00:00:06.000','00:00:09.000','4000-essential-english-words-24'),
	('He performed and exercised in the public park','Anh ấy biểu diễn và luyện tập ở công viên công cộng','00:00:09.000','00:00:12.800','4000-essential-english-words-24'),
	('He did this to show everyone how strong he was','Anh ấy làm điều này để cho mọi người biết anh ta khỏe như thế nào','00:00:12.800','00:00:15.800','4000-essential-english-words-24'),
	('Most people liked him, but one man didn\'t','Hầu hết mọi người đều quý anh, nhưng có một người thì không','00:00:15.800','00:00:19.200','4000-essential-english-words-24'),
	('His name was Jack','Anh ta tên là Jack','00:00:19.200','00:00:20.800','4000-essential-english-words-24'),
	('Jack hated Tim','Jack không thích Tim','00:00:20.800','00:00:22.500','4000-essential-english-words-24'),
	('Jack was a movie critic and the smartest man in town','Jack là một nhà phê bình điện ảnh và cũng thông minh nhất thị trấn','00:00:22.500','00:00:26.000','4000-essential-english-words-24'),
	('He could solve complex math problems','Anh ta có thể giải quyết những vấn đề toán học phức tạp','00:00:26.000','00:00:28.800','4000-essential-english-words-24'),
	('But no one cared','Nhưng không ai biết về điều đó','00:00:28.800','00:00:30.600','4000-essential-english-words-24'),
	('Jack wanted to be famous like Tim','Jack muốn được nổi tiếng như Tim','00:00:30.600','00:00:32.900','4000-essential-english-words-24'),
	('One day, there was an unusual event','Một ngày nọ, có một việc bất thường xảy đến','00:00:32.900','00:00:36.400','4000-essential-english-words-24'),
	('A big storm came suddenly','Một cơn bão lớn đột nhiên xuất hiện','00:00:36.400','00:00:38.800','4000-essential-english-words-24'),
	('Snow covered the town','Tuyết che phủ cả thị trấn','00:00:38.800','00:00:40.600','4000-essential-english-words-24'),
	('No one could get out','Không ai có thể ra khỏi thị trấn','00:00:40.600','00:00:42.700','4000-essential-english-words-24'),
	('They needed food','Họ cần có thức ăn để sống','00:00:42.700','00:00:44.400','4000-essential-english-words-24'),
	('The people said, "This is a task for a strong man"','Người dân nói, "Đây là một nhiệm vụ dành cho những người đàn ông khỏe mạnh"','00:00:44.400','00:00:48.700','4000-essential-english-words-24'),
	('Tim was under pressure to save them','Tim phải chịu áp lực rằng phải cứu họ','00:00:48.700','00:00:51.000','4000-essential-english-words-24'),
	('But Jack wanted to be the hero, so they both went','Nhưng Jack, người luôn muốn trở thành một anh hùng, nên cả hai bọn họ đã đi tìm cùng nhau','00:00:51.000','00:00:54.800','4000-essential-english-words-24'),
	('Tim said, "You can\'t help because of your lack of strength"','Tim nói: "Cậu không thể giúp mọi người vì cậu không khỏe mạnh"','00:00:54.800','00:00:59.000','4000-essential-english-words-24'),
	('But Jack found some small passages under the snow','Nhưng Jack tìm thấy một vài đường hầm nhỏ dưới tuyết','00:00:59.000','00:01:01.950','4000-essential-english-words-24'),
	('One of them led toward another town','Một trong số chúng dẫn đến thị trấn khác','00:01:01.950','00:01:04.800','4000-essential-english-words-24'),
	('That town had food','Thị trấn đó có thức ăn','00:01:04.800','00:01:06.800','4000-essential-english-words-24'),
	('Because Tim was so big and strong, he almost couldn\'t fit inside','Vì thân hình Tim quá to lớn và vạm vỡ nên anh ấy gần như không thể chui vừa','00:01:06.800','00:01:11.800','4000-essential-english-words-24'),
	('They walked until there was a block of ice in their way','Họ đi bộ cho tới khi có một tảng băng lớn trên đường đi','00:01:11.800','00:01:14.800','4000-essential-english-words-24'),
	('Jack said, "We can\'t get past it"','Jack nói: "Chúng ta không thể vượt qua chỗ này được"','00:01:14.800','00:01:17.800','4000-essential-english-words-24'),
	('"But if you strike it, it might break"','"Bởi vì khi cậu chạm mạnh vào tảng băng, nó có thể sẽ sụp xuống"','00:01:17.800','00:01:19.800','4000-essential-english-words-24'),
	('Tim knew that was probable','Tim biết điều đó là có thể xảy ra','00:01:19.800','00:01:21.800','4000-essential-english-words-24'),
	('He broke it','Anh ta phá vỡ những tảng băng','00:01:21.800','00:01:23.400','4000-essential-english-words-24'),
	('When there were more ice blocks, Tim broke them','Tim vẫn phá vỡ các tảng băng cho dù càng ngày càng nhiều hơn','00:01:23.400','00:01:26.900','4000-essential-english-words-24'),
	('That made him tired','Điều này làm anh ấy mệt mỏi','00:01:26.900','00:01:28.700','4000-essential-english-words-24'),
	('He couldn\'t walk anymore','Anh ấy không thể đi tiếp được nữa','00:01:28.700','00:01:30.600','4000-essential-english-words-24'),
	('Jack said, "Let\'s unite and support each other"','Jack nói, "Chúng ta hãy đoàn kết và hỗ trợ lẫn nhau"','00:01:30.600','00:01:34.200','4000-essential-english-words-24'),
	('"I\'ll get the food alone"','"Tôi sẽ đi lấy thức ăn một mình"','00:01:34.200','00:01:36.000','4000-essential-english-words-24'),
	('"You rest here"','"Cậu hãy ngồi nghỉ ở đây"','00:01:36.000','00:01:37.800','4000-essential-english-words-24'),
	('Jack came back with food','Jack quay lại với thức ăn lấy được','00:01:37.800','00:01:39.600','4000-essential-english-words-24'),
	('Tim couldn\'t remember which passage led home','Tim không thể nhớ đường hầm nào dẫn về nhà','00:01:39.600','00:01:42.800','4000-essential-english-words-24'),
	('He needed Jack to be his guide','Anh ta cần Jack làm người dẫn đường','00:01:42.800','00:01:45.000 ','4000-essential-english-words-24'),
	('The men became friends by working together','Họ trở thành bạn bè từ việc làm chung với nhau','00:01:45.000','00:01:48.000','4000-essential-english-words-24'),
	('In town, people saw Jack with the food and cheered','Ở thị trấn, mọi người thấy Jack trở về cùng với thức ăn, họ cùng ăn mừng','00:01:48.000','00:01:51.800','4000-essential-english-words-24'),
	('They called Jack a hero','Họ gọi Jack là anh hùng','00:01:51.800','00:01:53.800','4000-essential-english-words-24'),
	('But Jack didn\'t care','Nhưng Jack không hề để ý tới điều đó','00:01:53.800','00:01:55.700','4000-essential-english-words-24'),
	('He was thinking of something else','Anh đang nghĩ tới điều khác','00:01:55.700','00:01:57.800','4000-essential-english-words-24'),
	('He said to Tim, "I thought I was smart, but I learned a new term today: friendship"','Anh ta nói với Tim, "Tôi đã nghĩ mình thật thông minh nhưng hôm nay tôi đã học được một bài học mới: Tình bạn"','00:01:57.800','00:02:05.600','4000-essential-english-words-24'),

	/* (UUID(),'4000-essential-english-words-25','Joe\'s pond','Ao của Joe','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_025.mp3',NULL,'00:00:00.000','00:02:02.100','4000-essential-english-words','NO',25) */
	('Joe made the world a better place','Joe chung tay xây dựng nên một thế giới tốt đẹp hơn','00:00:03.000','00:00:05.900','4000-essential-english-words-25'),
	('He got the idea to do that at school','Cậu đã có ý tưởng thực hiện việc này khi còn đang đi học','00:00:05.900','00:00:08.900','4000-essential-english-words-25'),
	('He watched a video there','Cậu đã từng được xem một đoạn phim ngắn lúc đó','00:00:08.900','00:00:11.100','4000-essential-english-words-25'),
	('It was about a factory','Nó nói về một nhà máy','00:00:11.100','00:00:13.000','4000-essential-english-words-25'),
	('This factory produced a lot of trash and put it in a river','Nhà máy này đã sản sinh ra rất nhiều rác và thải xuống một dòng sông','00:00:13.000','00:00:18.000','4000-essential-english-words-25'),
	('The trash and water were a bad mix','Rác và nước sông đã hòa trộn lẫn vào nhau','00:00:18.000','00:00:21.000','4000-essential-english-words-25'),
	('People populated the area by the river and drank its water','Số người cư trú ở khu vực gần dòng sông này rất đông và họ đều uống nước được lấy từ đó','00:00:21.000','00:00:25.300','4000-essential-english-words-25'),
	('This made them sick','Thói quen này làm cho họ nhiễm bệnh','00:00:25.300','00:00:27.300','4000-essential-english-words-25'),
	('Many of them needed medicine and made regular visits to doctors','Rất nhiều người trong số đó phải uống thuốc để điều trị và phải thường xuyên đến thăm khám bác sĩ','00:00:27.300','00:00:31.800','4000-essential-english-words-25'),
	('But the video wasn\'t all bad news','Nhưng trong đoạn phim đó, không phải mọi thông tin đều tiêu cực','00:00:31.800','00:00:34.800','4000-essential-english-words-25'),
	('It showed ways to pick up trash and why it\'s important to do this','Đoạn phim cũng đưa ra cách để thu lượm rác thải và tầm quan trọng của công việc này','00:00:34.800','00:00:38.800','4000-essential-english-words-25'),
	('It said people can make a difference to their environment','Nội dung đưa ra là con người có thể tạo ra thay đổi với môi trường họ đang sinh sống','00:00:38.800','00:00:42.800','4000-essential-english-words-25'),
	('The video\'s important features made Joe associate trash with hurting people','Những thông điệp quan trọng trong video đó đã khiến Joe có liên tưởng rằng chính rác thải mới là nguyên nhân gây hại cho sức khỏe con ngườ','00:00:42.800','00:00:47.800','4000-essential-english-words-25'),
	('One day Joe walked through a park','Vào một ngày nọ, Joe đang đi bộ trong công viên','00:00:47.800','00:00:50.800','4000-essential-english-words-25'),
	('He recognized some of the problems from the video','Cậu nhận ra được một số vấn đề trong đoạn phim là có thật','00:00:50.800','00:00:54.500','4000-essential-english-words-25'),
	('One instance of these problems was the trash in the pond','Một trong số đó là việc có rác ở trong ao','00:00:54.500','00:00:58.200','4000-essential-english-words-25'),
	('It was full of plastic cups','Cốc nhựa ở khắp nơi','00:01:58.200','00:01:00.200','4000-essential-english-words-25'),
	('There was too much trash','Thật quá là nhiều rác','00:01:00.200','00:01:01.900','4000-essential-english-words-25'),
	('Joe didn\'t want it to hurt anyone','Joe không muốn ai gặp nguy hiểm cả','00:01:01.900','00:01:04.900','4000-essential-english-words-25'),
	('He told his grandfather about the park','Cậu đã nói với ông nội mình về cái công viên đầy rác đó','00:01:04.900','00:01:07.900','4000-essential-english-words-25'),
	('His grandfather said, "You know, it\'s a tradition in our family to help people"','Ông của cậu đã nói với cậu rằng, "Con biết không, truyền thống của gia đình chúng ta là giúp đỡ người khác"','00:01:07.900','00:01:13.400','4000-essential-english-words-25'),
	('"That\'s why we give food to poor people"','"Đó là lý do tại sao chúng ta lấy thức ăn để chia cho người nghèo"','00:01:13.400','00:01:16.400','4000-essential-english-words-25'),
	('"Maybe you can help people by cleaning the park"','"Có lẽ con có thể giúp đỡ mọi người bằng cách làm vệ sinh công viên đó"','00:01:16.400','00:01:19.800','4000-essential-english-words-25'),
	('Cleaning the park would involve hard work','Vệ sinh công viên là một công việc đòi hỏi sự lao động cực nhọc','00:01:19.800','00:01:22.800','4000-essential-english-words-25'),
	('Joe decided to organize a group to help him','Joe quyết định thành lập một nhóm để cùng chung tay hành động với cậu','00:01:22.800','00:01:26.400','4000-essential-english-words-25'),
	('He chose a wide area of the park','Cậu chọn ra một khu vực rộng rãi trong công viên','00:01:26.400','00:01:28.800','4000-essential-english-words-25'),
	('It had the most trash','Đó cũng là nơi chứa nhiều rác nhất','00:01:28.800','00:01:31.200','4000-essential-english-words-25'),
	('He asked his family and friends to come','Cậu cũng nhờ gia đình và bạn bè đến hỗ trợ','00:01:31.200','00:01:33.800','4000-essential-english-words-25'),
	('On Saturday, he gave everyone a sharp stick','Hôm thứ Bảy, cậu phát cho mỗi người một cây gậy có đầu nhọn','00:01:33.800','00:01:37.700','4000-essential-english-words-25'),
	('They wondered why','Mọi người thắc mắc tại sao','00:01:37.700','00:01:39.100','4000-essential-english-words-25'),
	('He said, "You use the stick\'s tip to pick up trash"','Joe giải thích rằng, "Mọi người sẽ cần cái đầu gậy này để khều rác đấy"','00:01:39.100','00:01:42.900','4000-essential-english-words-25'),
	('"This makes it easier"','"Dùng cái gậy này sẽ dễ làm hơn đấy"','00:01:42.900','00:01:44.900','4000-essential-english-words-25'),
	('They worked for six weeks','Họ đã làm việc đó liên tục trong sáu tuần lễ','00:01:44.900','00:01:46.800','4000-essential-english-words-25'),
	('Different people helped each time, but Joe was always there','Luôn có những người khác thay phiên nhau đến giúp sức mỗi lần như vậy nhưng Joe lúc nào cũng có mặt tại đó','00:01:46.800','00:01:51.300','4000-essential-english-words-25'),
	('In that period of time, Joe saw a range of results','Trong suốt khoảng thời gian đó, Joe đã thấy được một chuỗi các kết quả','00:01:51.300','00:01:55.800','4000-essential-english-words-25'),
	('There was no trash in the water','Rác thải dần dần không còn nữa','00:01:55.800','00:01:57.800','4000-essential-english-words-25'),
	('People could swim in it','Giờ đây mọi người có thể đi bơi trong hồ được rồi','00:01:57.800','00:01:59.800','4000-essential-english-words-25'),
	('Joe knew that was a good sign','Joe biết rằng đó là một tín hiệu tốt','00:01:59.800','00:02:02.100','4000-essential-english-words-25'),
	('He was happy because he helped his environment','Cậu cảm thấy hạnh phúc vì đã cải thiện được môi trường sống quanh mình','00:02:02.100','00:02:05.900','4000-essential-english-words-25');

