INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-26','Archie and his donkey','Archie và con lừa','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_026.mp3',NULL,'00:00:00.000','00:02:00.700','4000-essential-english-words','NO',26) */
	('Old Archie needed some money','Ông già Archie cần ít tiền','00:00:03.000','00:00:05.400','4000-essential-english-words-26'),
	('He decided to sell his donkey','Ông quyết định bán con lừa của mình đi','00:00:05.400','00:00:07.800','4000-essential-english-words-26'),
	('So he and his son Tom went to town','Ông và con trai là Tom đi tới thị trấn','00:00:07.800','00:00:10.500','4000-essential-english-words-26'),
	('It was situated many miles away','Nơi đó nằm cách xa nhiều dặm','00:00:10.500','00:00:13.400','4000-essential-english-words-26'),
	('Soon, they met a woman','Chẳng bao lâu, họ gặp một người phụ nữ','00:00:13.400','00:00:15.800','4000-essential-english-words-26'),
	('"Where are you going?" she asked','"Hai người đi đâu vậy?" bà ta hỏi','00:00:15.800','00:00:18.800','4000-essential-english-words-26'),
	('"To town," said Archie','"Đến thị trấn," Archie trả lời','00:00:18.800','00:00:20.800','4000-essential-english-words-26'),
	('"Any smart person would ride the donkey," she said','"Ai thông minh cũng sẽ cưỡi lên con lừa," bà ta nói','00:00:20.800','00:00:24.800','4000-essential-english-words-26'),
	('"What are you implying?" Archie asked','"Bà đang ám chỉ điều gì vậy?" Archie hỏi','00:00:24.800','00:00:27.800','4000-essential-english-words-26'),
	('"I\'m very smart"','"Tôi là người thông minh"','00:00:27.800','00:00:29.800','4000-essential-english-words-26'),
	('Archie wanted to look smart','Archie muốn mình trông thật thông minh','00:00:29.800','00:00:31.800','4000-essential-english-words-26'),
	('So he climbed onto the donkey','Nên ông ta đã trèo lên lưng con lừa','00:00:31.800','00:00:33.800','4000-essential-english-words-26'),
	('Then they continued in the direction of the town',' Sau đó họ tiếp tục thẳng tiến đến thị trấn','00:00:33.800','00:00:36.800','4000-essential-english-words-26'),
	('Further along the road, they met a farmer','Đi được quãng đường xa hơn, họ gặp một người nông dân','00:00:36.800','00:00:40.300','4000-essential-english-words-26'),
	('"Hello," said Archie','"Xin chào," Archie nói','00:00:40.300','00:00:41.800','4000-essential-english-words-26'),
	('"We want to sell this donkey"','"Chúng tôi muốn bán con lừa này"','00:00:41.800','00:00:44.400','4000-essential-english-words-26'),
	('"Do you want to buy it?"','"Ông có muốn mua không?"','00:00:44.400','00:00:45.800','4000-essential-english-words-26'),
	('"I don\'t need a donkey," said the farmer','"Tôi không muốn mua lừa," người nông dân nói','00:00:45.800','00:00:49.000','4000-essential-english-words-26'),
	('"But if you want my advice, don\'t ride it"','"Nhưng nếu ông muốn một lời khuyên của tôi, thì đừng cưỡi nó"','00:00:49.000','00:00:52.300','4000-essential-english-words-26'),
	('"The donkey needs to be in good physical condition"','"Con lừa cần có một thể trạng tốt"','00:00:52.300','00:00:55.400','4000-essential-english-words-26'),
	('"Good idea," said Archie','"Ý kiến hay," Archie nói','00:00:55.400','00:00:57.800','4000-essential-english-words-26'),
	('"Tom, I want you to ride it"','"Tom, bố muốn con cưỡi nó"','00:00:57.800','00:00:59.800','4000-essential-english-words-26'),
	('"You\'re lighter"','Con nhẹ hơn bố','00:00:59.800','00:01:01.000','4000-essential-english-words-26'),
	('"Neither you nor your son should ride it"','"Ông và con trai đều không nên cưỡi nó"','00:01:01.000','00:01:04.300','4000-essential-english-words-26'),
	('"It looks very tired"','"Nó trông có vẻ rất mệt"','00:01:04.300','00:01:06.000','4000-essential-english-words-26'),
	('"You should carry the donkey" suggested the farmer','"Ông nên ôm con lừa đi." người nông dân gợi ý','00:01:06.000','00:01:09.900','4000-essential-english-words-26'),
	('"You\'re right," said Archie','"Ông nói đúng," Archie nói','00:01:09.900','00:01:11.900','4000-essential-english-words-26'),
	('"Come on, Tom"','"Lại đây nào, Tom"','00:01:11.900','00:01:13.300','4000-essential-english-words-26'),
	('"We\'ll carry it for the final few miles"','"Chúng ta sẽ ôm nó cho đến những dặm cuối cùng"','00:01:13.300','00:01:15.800','4000-essential-english-words-26'),
	('"The donkey was very heavy, and they couldn\'t maintain a good speed"','"Con lừa rất nặng, và họ không thể duy trì tốc độ nhanh được"','00:01:15.800','00:01:20.200','4000-essential-english-words-26'),
	('They didn\'t arrive until late in the evening','Họ không thể đến được thị trấn cho đến khi trời đã khuya','00:01:20.200','00:01:22.800','4000-essential-english-words-26'),
	('At last, they walked into the town','Cuối cùng, họ đã đi tới được thị trấn','00:01:22.800','00:01:25.800','4000-essential-english-words-26'),
	('But there they attracted the attention of some teenage boys','Nhưng ở đó họ lại bị thu hút bởi những thiếu niên','00:01:25.800','00:01:29.700','4000-essential-english-words-26'),
	('They laughed at Tom and Archie','Chúng cười nhạo Tom và Archie','00:01:29.700','00:01:31.700','4000-essential-english-words-26'),
	('They started to throw stones at them','Chúng bắt đầu ném đá vào họ','00:01:31.700','00:01:33.800','4000-essential-english-words-26'),
	('The donkey reacted by kicking','Con lừa phản ứng bằng việc đá loạn xạ','00:01:33.800','00:01:36.200','4000-essential-english-words-26'),
	('Tom and Archie dropped the donkey','Tom và Archie thả con lừa ra','00:01:36.200','00:01:39.100','4000-essential-english-words-26'),
	('It fell on the ground and then ran away','Nó ngã trên đất và bỏ chạy','00:01:39.100','00:01:41.900','4000-essential-english-words-26'),
	('Archie lost his donkey','Archie mất con lừa','00:01:41.900','00:01:43.900','4000-essential-english-words-26'),
	('He went home with no money','Ông quay về nhà nhưng trong tay không có đồng nào cả','00:01:43.900','00:01:46.700','4000-essential-english-words-26'),
	('What does this story teach us?','Câu chuyện này dạy chúng ta điều gì?','00:01:46.700','00:01:48.800','4000-essential-english-words-26'),
	('We cannot please everyone in our society','Chúng ta không thể làm hài lòng mọi người trong xã hội','00:01:48.800','00:01:51.900','4000-essential-english-words-26'),
	('Don\'t take everyone\'s advice, but set your own standards','Đừng nghe tất cả lời khuyên của mọi người, nhưng cần đặt cho riêng mình những tiêu chuẩn','00:01:51.900','00:01:56.900','4000-essential-english-words-26'),
	('Prove to everyone that you can make decisions by yoursel','Chứng minh cho mọi người rằng bạn có thể đưa ra quyết định của chính mình','00:01:56.900','00:02:00.700','4000-essential-english-words-26'),
	('Otherwise, you may end up with nothing at all','Nếu không bạn có thể kết thúc cuộc đời mình với việc chẳng còn gì cả','00:02:00.700','00:02:04.200','4000-essential-english-words-26'),

	/* (UUID(),'4000-essential-english-words-27','The spider and the bird','Con nhện và con chim','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_027.mp3',NULL,'00:00:00.000','00:02:02.000','4000-essential-english-words','NO',27) */
	('There was once a very big spider','Thuở xưa có một chú nhện rất lớn','00:00:03.400','00:00:06.300','4000-essential-english-words-27'),
	('If a bug got into his web, he would examine it','Nếu một con bọ bị rơi vào mạng nhện của chú, chú sẽ cân nhắc','00:00:06.300','00:00:10.100','4000-essential-english-words-27'),
	('However, he didn\'t eat the bug right away','Nhưng chú không ăn con bọ ngay','00:00:10.100','00:00:13.800','4000-essential-english-words-27'),
	('He asked the bug a question first','Trước hết, chú sẽ hỏi con bọ đó một câu hỏi','00:00:13.800','00:00:16.800','4000-essential-english-words-27'),
	('It was always quite a difficult puzzle','Đó luôn là một câu đố khá khó','00:00:16.800','00:00:19.700','4000-essential-english-words-27'),
	('If the bug\'s answer was correct, he let it go','Nếu câu trả lời của con bọ đúng thì chú sẽ thả nó đi','00:00:19.700','00:00:23.600','4000-essential-english-words-27'),
	('If not, he ate it','Còn nếu không thì chú sẽ ăn nó','00:00:23.600','00:00:24.800','4000-essential-english-words-27'),
	('One day, a small bird on a journey flew into the spider\'s web','Một ngày nọ, một cô chim nhỏ đang trên hành trình của mình thì bị sa vào mạng nhện','00:00:24.800','00:00:30.500','4000-essential-english-words-27'),
	('The spider couldn\'t imagine eating a bird','Chú nhện không thể tưởng tượng đến việc ăn một con chim','00:00:30.500','00:00:33.600','4000-essential-english-words-27'),
	('It was so big','Nó thật là lớn','00:00:33.600','00:00:34.800','4000-essential-english-words-27'),
	('But his hunger was too great','Nhưng chú đang trong cơn đói','00:00:34.800','00:00:37.600','4000-essential-english-words-27'),
	('He said to the bird, "If you cannot give me a specific answer, I will eat you"','Chú nói với cô chim rằng "Nếu ngươi không cho ta câu trả lời chính xác, ta sẽ ăn ngươi"','00:00:37.600','00:00:42.800','4000-essential-english-words-27'),
	('The bird laughed','Cô chim liền cười lớn','00:00:42.800','00:00:44.300','4000-essential-english-words-27'),
	('"I could eat you"','"Ta cũng có thể thể ăn ngươi đấy"','00:00:44.300','00:00:45.800','4000-essential-english-words-27'),
	('But the bird was actually scared','Nhưng thực ra cô chim rất sợ hãi','00:00:45.800','00:00:48.800','4000-essential-english-words-27'),
	('She had used all her energy trying to get out of the web','Cô dùng hết sức mình để cố gắng thoát ra khỏi mạng nhện','00:00:48.800','00:00:52.500','4000-essential-english-words-27'),
	('And a spider\'s bite can be very effective in killing animals','Và một vết cắn của con nhện có thể giết chết một con vật','00:00:52.500','00:00:57.200','4000-essential-english-words-27'),
	('"Please don\'t eat me," the bird said','"Làm ơn đừng ăn tôi," cô chim nói','00:00:57.200','00:00:59.800','4000-essential-english-words-27'),
	('"I would rather make a deal with you"','"Tôi muốn thỏa thuận với anh"','00:00:59.800','00:01:01.800','4000-essential-english-words-27'),
	('"OK," the spider said','"Được thôi," chú nhện nói','00:01:01.800','00:01:04.200','4000-essential-english-words-27'),
	('"If your answer is right, I will let you go"','"Nếu câu trả lời của ngươi đúng, ta sẽ để ngươi đi"','00:01:04.200','00:01:07.500','4000-essential-english-words-27'),
	('"If not, you must give me a gift"','"Nếu không, ngươi phải đưa ta một món quà"','00:01:07.500','00:01:09.800','4000-essential-english-words-27'),
	('"It must be something of great value"','"Nó phải là thứ có giá trị"','00:01:09.800','00:01:12.800','4000-essential-english-words-27'),
	('The bird said, "You can pick anything you want to eat"','Cô chim nói, "Anh có thể đề nghị bất cứ thứ gì anh muốn ăn"','00:01:12.800','00:01:16.300','4000-essential-english-words-27'),
	('"I will find it for you"','"Tôi sẽ đi kiếm cho anh"','00:01:16.300','00:01:18.300','4000-essential-english-words-27'),
	('The spider agreed','Chú nhện đồng ý','00:01:18.300','00:01:20.000','4000-essential-english-words-27'),
	('"Where can you take a trip to the coast, the desert, and the mountains at the same time?" the spider asked','"Nơi nào mà ngươi có thể thực hiện chuyến đi đến cả bờ biển, sa mạc, và núi cùng một lúc?" chú nhện hỏi','00:01:20.000','00:01:26.800','4000-essential-english-words-27'),
	('The bird asked, "Does this place have earthquakes?"','Cô chim hỏi lại: "Đấy chẳng phải nơi có động đất hay sao?"','00:01:26.800','00:01:30.300','4000-essential-english-words-27'),
	('But the spider did not say anything','Nhưng chú nhện không nói nói gì cả','00:01:30.300','00:01:32.800','4000-essential-english-words-27'),
	('"I can see those places when I fly"','"Tôi có thể nhìn thấy những nơi này khi tôi bay"','00:01:32.800','00:01:35.800','4000-essential-english-words-27'),
	('"Is the \'sky\' the right answer?"','"\'Bầu trời\' có phải đáp án đúng không?"','00:01:35.800','00:01:37.800','4000-essential-english-words-27'),
	('"False" said the spider','"Sai" chú nhện nói','00:01:37.800','00:01:40.200','4000-essential-english-words-27'),
	('"The answer is Hawaii"','"Đáp án là Hawaii"','00:01:40.200','00:01:41.900','4000-essential-english-words-27'),
	('"Now you must find some bugs for me"','"Giờ ngươi phải đi tìm cho ta mấy con bọ"','00:01:41.900','00:01:44.900','4000-essential-english-words-27'),
	('The spider climbed on the bird\'s back','Chú nhện leo lên lưng con chim','00:01:44.900','00:01:47.800','4000-essential-english-words-27'),
	('They flew and ate bugs together','Họ bay và cùng nhau ăn những con bọ','00:01:47.800','00:01:50.200','4000-essential-english-words-27'),
	('They took a tour of the forest','Họ đi một vòng quanh khu rừng','00:01:50.200','00:01:52.800','4000-essential-english-words-27'),
	('Then the bird took the spider home','Rồi chim đưa nhện về nhà','00:01:52.800','00:01:55.800','4000-essential-english-words-27'),
	('From that day on, they were friends','Từ hôm đó trở đi họ là bạn','00:01:55.800','00:01:58.800','4000-essential-english-words-27'),
	('And they never tried to eat each other again','Và họ không bao giờ cố gắng ăn thịt nhau lần nữa','00:01:58.800','00:02:02.000','4000-essential-english-words-27'),

	/* (UUID(),'4000-essential-english-words-28','The party','Bữa tiệc sinh nhật','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_028.mp3',NULL,'00:00:00.000','00:02:11.000','4000-essential-english-words','NO',28) */
	('Cody\'s family moved to a new house','Gia đình của Cody vừa mới chuyển tới ở một ngôi nhà mới','00:00:03.000','00:00:05.000','4000-essential-english-words-28'),
	('His dad got a new job as a professor','Cha cậu cũng đã bắt đầu một công việc mới là một giáo sư','00:00:05.000','00:00:07.800','4000-essential-english-words-28'),
	('Cody liked his new town, but he missed his grandparents','Cody thích thị trấn mới này thế nhưng cậu bé lại rất nhớ ông bà','00:00:07.800','00:00:11.800','4000-essential-english-words-28'),
	('For his birthday, Cody wanted to have a party','Cody muốn có một bữa tiệc trong ngày sinh nhật của mình','00:00:11.800','00:00:15.000','4000-essential-english-words-28'),
	('His dad said, "Yes, we could even have a band play"','Cha cậu bé nói rằng: "Được thôi, chúng ta thậm chí mời cả ban nhạc đến biểu diễn nữa cơ"','00:00:15.000','00:00:19.500','4000-essential-english-words-28'),
	('On the day of the party, Cody woke up and rushed to get ready','Vào ngày sinh nhật, Cody thức dậy rồi vội vã chuẩn bị mọi thứ','00:00:19.500','00:00:23.600','4000-essential-english-words-28'),
	('He started to check his list of things to do','Cậu bé bắt đầu liệt kê danh sách những việc cần làm','00:00:23.600','00:00:26.600','4000-essential-english-words-28'),
	('He was so excited','Cậu bé vô cùng hào hứng','00:00:26.600','00:00:28.600','4000-essential-english-words-28'),
	('But then he noticed something terrible','Nhưng sau đó Cody nhận thấy có điều gì đó rất tệ','00:00:28.600','00:00:30.800','4000-essential-english-words-28'),
	('There was snow on the ground and lots of it','Ở ngoài sân có rất nhiều tuyết','00:00:30.800','00:00:34.700','4000-essential-english-words-28'),
	('"Dad" he yelled','"Cha ơi", cậu hét toáng lên','00:00:34.700','00:00:36.800','4000-essential-english-words-28'),
	('"How can the band play their instruments outside?"','"Làm sao mà ban nhạc có thể biểu diễn nhạc cụ ở bên ngoài đây"','00:00:36.800','00:00:40.200','4000-essential-english-words-28'),
	('Dad said, "We\'ll move the stage inside"','Cha cậu đáp: "Chúng ta sẽ chuyển sân khấu vào trong"','00:00:40.200','00:00:43.800','4000-essential-english-words-28'),
	('It barely fit within the garage because there were some boxes and garbage there','Rất khó để chuyển vào trong gara vì có một vài cái hộp và túi rác ở đó','00:00:43.800','00:00:48.800','4000-essential-english-words-28'),
	('But when they finished, they got a call from the band','Nhưng khi hai ba con Cody thu xếp xong xuôi thì họ nhận được cuộc gọi từ ban nhạc','00:00:48.800','00:00:52.100','4000-essential-english-words-28'),
	('They did not want to come in the snow storm','Họ nói rằng họ không thể đến vì đang có bão tuyết','00:00:52.100','00:00:54.800','4000-essential-english-words-28'),
	('Dad said, "Let\'s get someone to perform magic"','Cha cậu nói, "Vậy chúng ta sẽ tìm ai đó trình diễn ảo thuật nhé"','00:00:54.800','00:00:58.800','4000-essential-english-words-28'),
	('But no one would come because of the snow','Nhưng không ai có thể đến được vì tuyết rơi rất dày','00:00:58.800','00:01:01.900','4000-essential-english-words-28'),
	('Finally, Dad said, "Cody, there\'s too much snow"','Cuối cùng cha cậu nói, "Cody à, tuyết rơi nhiều quá"','00:01:01.900','00:01:05.900','4000-essential-english-words-28'),
	('"We need to cancel the party"','"Chúng ta cần phải hủy bữa tiệc thôi"','00:01:05.900','00:01:08.000','4000-essential-english-words-28'),
	('"Yes, sir," Cody said sadly','"Dạ vâng, thưa cha," Cody nói một cách buồn bã','00:01:08.000','00:01:11.000','4000-essential-english-words-28'),
	('"It\'s going to be a boring birthday," he predicted','"Chắc hôm nay sẽ là môt ngày sinh nhật buồn chán lắm đây," cậu nghĩ','00:01:11.000','00:01:15.000','4000-essential-english-words-28'),
	('Cody wanted to share his birthday with someone','Cody muốn cùng chia sẻ ngày sinh nhật của mình với ai đó','00:01:15.000','00:01:17.900','4000-essential-english-words-28'),
	('He wanted to be at his old home','Cậu muốn ở ngôi nhà cũ trước đây','00:01:17.900','00:01:20.400','4000-essential-english-words-28'),
	('He wanted to see his grandparents','Cậu muốn được gặp ông bà yêu quý của mình','00:01:20.400','00:01:22.800','4000-essential-english-words-28'),
	('But then something got his attention','Thế rồi có thứ gì đó đã thu hút sự chú ý của cậu bé','00:01:22.800','00:01:24.800','4000-essential-english-words-28'),
	('He noticed a car in the driveway','Cody thấy có một chiếc xe ô tô đậu ở lối vào','00:01:24.800','00:01:27.800','4000-essential-english-words-28'),
	('His grandparents owned a car like that','Chiếc xe này giống y như chiếc xe của ông bà vậy','00:01:27.800','00:01:30.800','4000-essential-english-words-28'),
	('Cody was right','Cody đã đúng','00:01:30.800','00:01:32.500','4000-essential-english-words-28'),
	('His grandparents came for his birthday','Ông bà đến dự tiệc sinh nhật của cậu','00:01:32.500','00:01:35.200','4000-essential-english-words-28'),
	('"Happy birthday, Cody"','"Sinh nhật vui vẻ nhé Cody"','00:01:35.200','00:01:36.800','4000-essential-english-words-28'),
	('"We\'re sorry we are late"','"Chúng ta xin lỗi vì đã đến muộn"','00:01:36.800','00:01:38.800','4000-essential-english-words-28'),
	('"But there was so much snow"','"Tuyết rơi dày quá mà"','00:01:38.800','00:01:40.800','4000-essential-english-words-28'),
	('"It made us go off schedule"','"Tuyết khiến ông bà đến trễ vào bữa tiệc sinh nhật của cháu"','00:01:40.800','00:01:42.800','4000-essential-english-words-28'),
	('"We tried to leave a message to tell you"','"Chúng ta đã cố gắng để lại một tin nhắn cho cháu"','00:01:42.800','00:01:45.800','4000-essential-english-words-28'),
	('Cody told them what happened','Cody kể cho ông bà những chuyện đã xảy ra','00:01:45.800','00:01:47.800','4000-essential-english-words-28'),
	('"I\'m sorry," said Grandpa','"Ông thấy rất tiếc," ông cậu bé nói','00:01:47.800','00:01:50.400','4000-essential-english-words-28'),
	('"I was sad," Cody said','"Con rất buồn ông à," Cody nois','00:01:50.400','00:01:52.800','4000-essential-english-words-28'),
	('"But I\'m not anymore"','Nhưng giờ thì hết rồi','00:01:52.800','00:01:54.800','4000-essential-english-words-28'),
	('"I\'m so happy to see you"','"Con rất vui vì được gặp mọi người"','00:01:54.800','00:01:57.000','4000-essential-english-words-28'),
	('Dad brought out Cody\'s birthday treat','Bố mang bánh sinh nhật của Cody ra','00:01:57.000','00:01:59.800','4000-essential-english-words-28'),
	('It was his favorite type, a sundae with whipped cream on top','Chiếc bánh đúng khẩu vị yêu thích của cậu bé, một chiếc bánh vị hoa quả với lớp kem xốp béo ngậy ở bên trên','00:01:59.800','00:02:04.500','4000-essential-english-words-28'),
	('Then Cody told his grandparents about the new town','Rồi Cody ngồi kể cho ông bà nghe về thị trấn mới','00:02:04.500','00:02:07.800','4000-essential-english-words-28'),
	('It was his best birthday ever','Đó thật sự là một ngày sinh nhật tuyệt vời nhất của cậu bé','00:02:07.800','00:02:11.000','4000-essential-english-words-28'),

	/* (UUID(),'4000-essential-english-words-29','How the World got light','Thế giới đã có ánh sáng như thế nào','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_029.mp3',NULL,'00:00:00.000','00:02:03.800','4000-essential-english-words','NO',29) */
	('The president of Darkland was a pig - a very bad pig','Lãnh chúa của Vùng đất bóng tối là một con lợn - một con lợn cực kỳ xấu tính','00:00:03.800','00:00:08.500','4000-essential-english-words-29'),
	('He was a pig of major importance','Hắn là một con lợn quan trọng chủ chốt','00:00:08.500','00:00:11.500','4000-essential-english-words-29'),
	('He was rich, and he had a lot of strength','Hắn rất giàu, và có nhiều sức khỏe','00:00:11.500','00:00:14.800','4000-essential-english-words-29'),
	('But he was mean to all the animals in Darkland','Nhưng hắn hèn mọn với muôn thú ở Vùng đất bóng tối','00:00:14.800','00:00:18.800','4000-essential-english-words-29'),
	('He kept all of the world\'s light in a bag','Hắn giữ ánh sáng của cả thế giới trong một cái túi','00:00:18.800','00:00:22.300','4000-essential-english-words-29'),
	('He preferred to keep the world cool and dark','Hắn thích giữ thế giới mát mẻ và tăm tối','00:00:22.300','00:00:25.500','4000-essential-english-words-29'),
	('He wanted to stop the progress of the city','Hắn muốn dừng tiến trình của thành phố lại','00:00:25.500','00:00:28.700','4000-essential-english-words-29'),
	('The animals couldn\'t work in the dark','Muông thú không thể làm việc trong bóng tối','00:00:28.700','00:00:31.000','4000-essential-english-words-29'),
	('He didn\'t have any respect for them','Hắn không có bất cứ tôn trọng nào dành cho họ cả','00:00:31.000','00:00:33.700','4000-essential-english-words-29'),
	('"Light is too good for them," he said','"Anh sáng quá tốt cho họ," hắn nói','00:00:33.700','00:00:36.400','4000-essential-english-words-29'),
	('"Only I should have light"','"Chỉ mình tôi nên có ánh sáng thôi"','00:00:36.400','00:00:38.800','4000-essential-english-words-29'),
	('But the animals needed light','Nhưng muông thú cần ánh sáng','00:00:38.800','00:00:40.800','4000-essential-english-words-29'),
	('So they decided to hold a competition','Vì vậy họ quyết định tổ chức một cuộc thi','00:00:40.800','00:00:43.800','4000-essential-english-words-29'),
	('They wanted to find the smartest animal in Darkland','Họ muốn tìm ra con vật thông minh nhất ở Vùng đất bóng tối','00:00:43.800','00:00:47.300','4000-essential-english-words-29'),
	('That animal had to steal light from the president','Con vật đó sẽ phải ăn trộm ánh sáng từ chủ tịch','00:00:47.300','00:00:51.100','4000-essential-english-words-29'),
	('They advertised the competition everywhere','Chúng quảng bá cuộc thi khắp mọi nơi','00:00:51.100','00:00:54.300','4000-essential-english-words-29'),
	('All the animals came','Muông thú đều đến','00:00:54.300','00:00:56.900','4000-essential-english-words-29'),
	('The animals all showed off their skills','Các con vật đều thể hiện hết kỹ năng của mình','00:00:56.900','00:01:00.000','4000-essential-english-words-29'),
	('The audience watched and then voted for the animal with the most knowledge',' Khán giả xem và bình chọn cho con vật có trí thông minh nhất','00:01:00.000','00:01:05.000','4000-essential-english-words-29'),
	('The winner was a tall bird named Raven','Con vật chiến thắng là một chú chim cao lớn tên Raven','00:01:05.000','00:01:08.700','4000-essential-english-words-29'),
	('They assigned him the job of getting light','Chúng phân công cho anh công việc lấy lại ánh sáng','00:01:08.700','00:01:11.800','4000-essential-english-words-29'),
	('The next morning, Raven ate breakfast and then left his home','Sáng hôm sau, Raven ăn bữa sáng và rời nhà mình','00:01:11.800','00:01:15.800','4000-essential-english-words-29'),
	('"How will I gain light from the president?" thought Raven','"Làm sao để mình có thể đạt được ánh sáng từ chủ tịch?" Raven nghĩ','00:01:15.800','00:01:20.000','4000-essential-english-words-29'),
	('He needed to trick the president somehow','Anh ấy cần phải lừa lãnh chúa bằng cách nào đó','00:01:20.000','00:01:23.000','4000-essential-english-words-29'),
	('Then, Raven had an idea','Rồi, Raven nghĩ ra một ý tưởng','00:01:23.000','00:01:26.000','4000-essential-english-words-29'),
	('Raven could make his voice sound like anything','Raven có thể khiến giọng của bản thân giống bất cứ thứ gì','00:01:26.000','00:01:29.000','4000-essential-english-words-29'),
	('Raven walked up to the president\'s door','Raven đi bộ lên cửa của lãnh chúa','00:01:29.000','00:01:31.800','4000-essential-english-words-29'),
	('He made the sound of a crying baby','Anh tạo nên âm thanh của một đứa bé đang khóc','00:01:31.800','00:01:34.800','4000-essential-english-words-29'),
	('He cried very loudly','Anh ấy khóc rất to','00:01:34.800','00:01:36.800','4000-essential-english-words-29'),
	('Soon, the president opened the door','Không lâu sau, lãnh chúa ra mở cửa','00:01:36.800','00:01:40.300','4000-essential-english-words-29'),
	('"Be quiet" the president yelled','"Im lặng đi" lãnh chúa quát','00:01:40.300','00:01:43.100','4000-essential-english-words-29'),
	('Right then, Raven quickly made his move','Ngay lúc đó, Raven nhanh chóng hành động','00:01:43.100','00:01:46.000','4000-essential-english-words-29'),
	('He flew by the pig and found the soft bag','Anh ấy bay qua con lợn và tìm thấy chiếc túi mềm','00:01:46.000','00:01:49.500','4000-essential-english-words-29'),
	('He took it outside','Anh ấy lấy nó ra','00:01:49.500','00:01:50.800','4000-essential-english-words-29'),
	('The sun was inside the bag','Mặt trời đang ở trong chiếc túi đó','00:01:50.800','00:01:53.000','4000-essential-english-words-29'),
	('Raven flew high and put the sun in the sky','Raven bay cao và đặt chiếc túi trên bầu trời','00:01:53.000','00:01:56.900','4000-essential-english-words-29'),
	('The president was very mad','Lãnh chúa rất tức giận','00:01:56.900','00:01:59.000','4000-essential-english-words-29'),
	('Raven tricked him','Raven đã lừa hắn','00:01:59.000','00:02:01.800','4000-essential-english-words-29'),
	('But the other animals were very happy','Nhưng những động vật khác thì lại rất hạnh phúc','00:02:01.800','00:02:03.800','4000-essential-english-words-29'),
	('At last, they had light - all because of Raven\'s smart thinking','Cuối cùng, họ có ánh sáng - tất cả là nhờ suy nghĩ thông minh của Raven','00:02:03.800','00:02:09.300','4000-essential-english-words-29'),

	/* (UUID(),'4000-essential-english-words-30','Cats and secrets','Con mèo và những bí mật','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_030.mp3',NULL,'00:00:00.000','00:01:57.000','4000-essential-english-words','NO',30) */
	('In English, there is a common idiom "let the cat out of the bag"','Trong tiếng Anh, có một câu thành ngữ phổ biến "Hãy để con mèo ra khỏi cái túi"','00:00:03.400','00:00:08.800','4000-essential-english-words-30'),
	('It means to tell a secret','Nó có nghĩa là nói ra điều bí mật','00:00:08.800','00:00:10.700','4000-essential-english-words-30'),
	('But where did this idiom start?','Nhưng câu thành ngữ này bắt đầu từ đâu?','00:00:10.700','00:00:12.900','4000-essential-english-words-30'),
	('It came from a section of England','Nó xuất phát từ một tầng lớp nhân dân ở Anh','00:00:12.900','00:00:15.400','4000-essential-english-words-30'),
	('Long ago, people there went from town to town to sell things like vegetables, clothes, and pigs','Rất lâu về trước, người dân nơi đó đi từ thị trấn này sang thị trấn khác để buôn những thứ như rau củ, quần áo và heo','00:00:15.400','00:00:22.400','4000-essential-english-words-30'),
	('They had strong beliefs about honesty','Họ có niềm tin mạnh mẽ về sự thành thực','00:00:22.400','00:00:24.900','4000-essential-english-words-30'),
	('They didn\'t like lying','Họ không thích nói dối','00:00:24.900','00:00:26.900','4000-essential-english-words-30'),
	('One day, a man went to the section\'s center to sell things','Một ngày nọ, một người đàn ông ghé đến một trung tâm của vùng để bán buôn','00:00:26.900','00:00:30.900','4000-essential-english-words-30'),
	('"I have a baby pig for sale"','"Tôi muốn bán một con heo con"','00:00:30.900','00:00:33.100','4000-essential-english-words-30'),
	('"It won\'t cost much," he said','"Tôi sẽ không lấy giá đắt quá đâu" anh ta nói','00:00:33.100','00:00:35.900','4000-essential-english-words-30'),
	('He held the animal above his head','Anh ấy giữ con vật ở trên đầu mình','00:00:35.900','00:00:38.000','4000-essential-english-words-30'),
	('His style was different from honest people\'s style','Phong cách của anh khác với phong cách của những người thành thực khác','00:00:38.000','00:00:41.600','4000-essential-english-words-30'),
	('He was a master of tricking people and lying','Anh ta là một bậc thầy về lừa người và nói dối','00:00:41.600','00:00:43.900','4000-essential-english-words-30'),
	('A woman named Beth scanned his pig','Một người phụ nữ tên Beth nhìn vào con heo của anh','00:00:43.900','00:00:48.000','4000-essential-english-words-30'),
	('He offered her the pig for one gold coin','Anh ấy đề nghị bán cho cô con lợn giá 1 đồng tiền vàng','00:00:48.000','00:00:51.000','4000-essential-english-words-30'),
	('That was a very small amount','Đó chỉ là một khoảng rất nhỏ','00:00:51.000','00:00:53.000','4000-essential-english-words-30'),
	('Beth gave him the coin','Beth đưa đồng tiền cho anh ấy','00:00:53.000','00:00:55.000','4000-essential-english-words-30'),
	('He put it in his pocket','Anh ta để nó trong túi mình','00:00:55.000','00:00:57.200','4000-essential-english-words-30'),
	('He walked ahead of Beth to get the pig','Người đàn ông đi về phía trước để Beth lấy con lợn','00:00:57.200','00:01:00.000','4000-essential-english-words-30'),
	('He gave her a closed bag and said, "Here\'s your pig"','Anh ta đưa cô một cái túi kín và nói, "Đây là con heo của cô"','00:01:00.000','00:01:04.000','4000-essential-english-words-30'),
	('He then left very quickly','Rồi anh ta rời đi rất nhanh','00:01:04.000','00:01:06.000','4000-essential-english-words-30'),
	('Beth looked at the bag\'s surface','Beth nhìn vào bề mặt của chiếc túi','00:01:06.000','00:01:08.900','4000-essential-english-words-30'),
	('It was moving','Nó đang cử động','00:01:08.900','00:01:10.800','4000-essential-english-words-30'),
	('She opened it to let the pig out','Cô ấy mở túi để con heo ra người','00:01:10.800','00:01:12.900','4000-essential-english-words-30'),
	('A cat was inside','Một con mèo ở trong','00:01:12.900','00:01:15.100','4000-essential-english-words-30'),
	('"He tricked me"','"Anh ta đã lừa tôi"','00:01:15.100','00:01:17.000','4000-essential-english-words-30'),
	('"That isn\'t proper," she said','"Điều này không đúng," cô ấy nói','00:01:17.000','00:01:19.800','4000-essential-english-words-30'),
	('Later, the man returned to trick more people','Sau đó, người đàn ông quay lại để lừa nhiều người hơn','00:01:19.800','00:01:22.900','4000-essential-english-words-30'),
	('Beth saw him and the memory of the cat came back','Beth nhìn thấy hắn và ký ức về con mèo quay về','00:01:22.900','00:01:26.700','4000-essential-english-words-30'),
	('She told her friends','Cô ấy nói với những người bạn của mình','00:01:26.700','00:01:28.400','4000-essential-english-words-30'),
	('They stopped him','Họ ngăn anh ta lại','00:01:28.400','00:01:29.800','4000-essential-english-words-30'),
	('But no one knew what to do next','Nhưng không một ai biết phải làm gì tiếp theo','00:01:29.800','00:01:32.100','4000-essential-english-words-30'),
	('Someone said, "We need an independent and fair person to decide that"','Một người nói "Chúng ta cần một người tự lập và công bằng để quyết định điều đó"','00:01:32.100','00:01:37.100','4000-essential-english-words-30'),
	('They went to the judge','Họ tới gặp quan tòa','00:01:37.100','00:01:38.800','4000-essential-english-words-30'),
	('Beth told him about the cat in the bag','Beth kể quan tòa nghe về con mèo trong cái túi','00:01:38.800','00:01:41.800','4000-essential-english-words-30'),
	('The judge asked, "Is there evidence?"','Quan tòa hỏi "Có bằng chứng không?"','00:01:41.800','00:01:44.800','4000-essential-english-words-30'),
	('"Can you demonstrate how he did it?"','"Cô có thể trình bày cách anh ta thực hiện nó không?"','00:01:44.800','00:01:47.600','4000-essential-english-words-30'),
	('"Look in his bag," said Beth','"Nhìn vào chiếc túi của anh ta kìa" Beth nói','00:01:47.600','00:01:50.000','4000-essential-english-words-30'),
	('She opened it and let a cat out of the bag','Cô ấy mở nó ra và để con mèo ra khỏi cái túi','00:01:50.000','00:01:53.500','4000-essential-english-words-30'),
	('They learned the man\'s secret, and he went to jail','Mọi người đã biết được bí mật của người đàn ông, và anh ta bị tống vào tù','00:01:53.500','00:01:57.000','4000-essential-english-words-30'),
	('That\'s how the idiom "let the cat out of the bag" came to mean to tell a secret','Đó là cách mà thành ngữ "hãy để cho con mèo ra khỏi chiếc túi" có nghĩa nói ra một bí mật','00:01:57.000','00:02:03.000','4000-essential-english-words-30');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-31','The twelve months','Mười hai tháng','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_031.mp3',NULL,'00:00:00.000','00:01:52.200','4000-essential-english-words','NO',31) */
	('An awful woman lived with her daughter and stepdaughter in her household','Một người phụ nữ đáng sợ sống cùng con gái ruột và đứa con riêng trong một căn nhà','00:00:03.200','00:00:08.600','4000-essential-english-words-31'),
	('She possessed feelings of hate for her stepdaughter, Anna','Bà có ác cảm với đứa con riêng, Anna','00:00:08.600','00:00:12.900','4000-essential-english-words-31'),
	('Anna worked while her stepsister did nothing','Anna làm việc trong khi người em không làm gì','00:00:12.900','00:00:16.900','4000-essential-english-words-31'),
	('On a cold January night, Anna\'s stepmother remarked, "Your stepsister desires flowers"','Vào đêm tháng Giêng lạnh lẽo, người mẹ kế dặn dò Anna: "Em con ao ước có những bông hoa"','00:00:16.900','00:00:24.000','4000-essential-english-words-31'),
	('"Go and find some"','"Vậy con hãy đi và tìm chúng về đây"','00:00:24.000','00:00:25.700','4000-essential-english-words-31'),
	('Anna wasn\'t anxious to walk through the chilled landscape','Anna không lo lắng mấy khi đi trong khoảng trời rét buốt','00:00:25.700','00:00:29.900','4000-essential-english-words-31'),
	('The cold air made her lungs burn','Khí trời lạnh giá đã khiến cô bé bị viêm phổi','00:00:29.900','00:00:32.900','4000-essential-english-words-31'),
	('She walked at a slow pace because of the snow','Cô bước chậm vì tuyết rơi','00:00:32.900','00:00:36.900','4000-essential-english-words-31'),
	('Soon she saw a group of people','Chẳng bao lâu cô thấy một nhóm người','00:00:36.900','00:00:39.700','4000-essential-english-words-31'),
	('It consisted of twelve men','Có mười hai người đàn ông','00:00:39.700','00:00:41.900','4000-essential-english-words-31'),
	('Anna told them about the flowers','Anna nói cho họ nghe về chuyện những bông hoa','00:00:41.900','00:00:44.900','4000-essential-english-words-31'),
	('One of the man said they were the twelve months and that they would help Anna','Một trong những người đàn ông này nói rằng họ là mười hai tháng và họ sẽ giúp Anna','00:00:44.900','00:00:50.000','4000-essential-english-words-31'),
	('January walked to her and made a motion with his hand','Tháng Một bước đến chỗ cô và tạo ra một phép chuyển trong bàn tay','00:00:50.000','00:00:54.000','4000-essential-english-words-31'),
	('The days of the month passed rapidly until it was February\'s turn','Các ngày trong tháng trôi qua nhanh cho đến lượt Tháng Hai','00:00:54.000','00:00:59.000','4000-essential-english-words-31'),
	('February also made the month speed up','Tháng Hai cũng làm phép cho trôi qua nhanh','00:00:59.000','00:01:02.800','4000-essential-english-words-31'),
	('Then March made the sun shine and flowers grew in the field',' Đến Tháng Ba tạo ra ánh nắng mặt trời cùng những bông hoa tơi tốt trên cánh đồng','00:01:02.800','00:01:07.800','4000-essential-english-words-31'),
	('Anna loaded her basket with so many flowers that she could hardly lift it','Anna đặt những bông hoa vào rổ nhiều đến nổi cô phải rất khó khăn để nhấc nó lên','00:01:07.800','00:01:13.800','4000-essential-english-words-31'),
	('Then she gave a quick but polite "thank you" to the twelve men and returned home','Sau đó cô cảm ơn nhanh một cách lịch sự "Cảm ơn" với mười hai người đàn ông và trở về nhà','00:01:13.800','00:01:19.800','4000-essential-english-words-31'),
	('She was very eager to show her stepmother all the flowers','Cô bé vô cùng háo hức để khoe với mẹ kế những bông hoa','00:01:19.800','00:01:24.800','4000-essential-english-words-31'),
	('Back at the house, she spilled the flowers onto the table','Trở về nhà, cô trải những bông hoa lên bàn','00:01:24.800','00:01:29.300','4000-essential-english-words-31'),
	('Then she told her stepmother about the twelve men','Rồi cô kể cho mẹ kế nghe về chuyện mười hai người đàn ông','00:01:29.300','00:01:33.300','4000-essential-english-words-31'),
	('Anna\'s stepmother and stepsister went to seek the twelve months','Mẹ kế của Anna và cô em gái đã cùng đi tìm mười hai người đàn ông','00:01:33.300','00:01:38.500','4000-essential-english-words-31'),
	('Their intent was to ask for gifts','Ý định của họ là để xin những món quà','00:01:38.500','00:01:41.800','4000-essential-english-words-31'),
	('They looked and looked','Họ tìm mãi, tìm mãi','00:01:41.800','00:01:44.000','4000-essential-english-words-31'),
	('They became very lost and never found their way home','Nhưng họ đã bị lạc và không bao giờ tìm thấy đường về nhà','00:01:44.000','00:01:48.800','4000-essential-english-words-31'),
	('Anna lived happily by herself','Anna sống hạnh phúc một mình','00:01:48.800','00:01:52.200','4000-essential-english-words-31'),

	/* (UUID(),'4000-essential-english-words-32','The dragon','Con rồng','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_032.mp3',NULL,'00:00:00.000','00:01:40.000','4000-essential-english-words','NO',32) */
	('An evil dragon lived in a castle in the remote southern mountains','Có một con rồng hung ác sống trong một tòa lâu đài trên những ngọn núi phía Nam hẻo lánh','00:00:03.000','00:00:07.900','4000-essential-english-words-32'),
	('One day the monster landed in a town','Một ngày nọ, con quái vật đã hạ cánh xuống một ngôi làng','00:00:07.900','00:00:10.900','4000-essential-english-words-32'),
	('The dragon commanded the people, "Give me food now, or I will eat you"','Con rồng đã ra lệnh cho người dân "Hãy mau đưa thức ăn đến đây cho ta, nếu không ta sẽ ăn thịt các ngươi"','00:00:10.900','00:00:16.900','4000-essential-english-words-32'),
	('The dragon lifted its wings so that its lungs could be completely filled with hot steam, and breathed it upon the people','Con rồng nâng đôi cánh của nó lên để phổi nó có thể chứa đầy hơi nóng và thổi hơi nóng đó vào người dân','00:00:16.900','00:00:25.900','4000-essential-english-words-32'),
	('A man turned into a stone statue','Và rồi một người đàn ông bị biến thành tượng đá','00:00:25.900','00:00:29.800','4000-essential-english-words-32'),
	('The people submitted and brought food','Người dân đã nộp và mang tới thức ăn','00:00:29.800','00:00:32.800','4000-essential-english-words-32'),
	('The dragon ate all of it and left','Con rồng ngấu nghiến hết số đồ ăn và và rời đi','00:00:32.800','00:00:35.800','4000-essential-english-words-32'),
	('The people sent a boy to ask for help from a wise old man','Người dân đã cử một chàng trai đi cầu xin sự giúp đỡ của một ông lão thông thái','00:00:35.800','00:00:39.800','4000-essential-english-words-32'),
	('He resided in a temple','Ông lão cư ngụ trong một ngôi chùa','00:00:39.800','00:00:42.800','4000-essential-english-words-32'),
	('The boy told the old man about the dragon','Chàng trai nói với ông lão về chuyện con rồng','00:00:42.800','00:00:45.800','4000-essential-english-words-32'),
	('Then, the old man counseled the boy','Sau đó, ông lão đã mách chàng trai rằng','00:00:45.800','00:00:48.800','4000-essential-english-words-32'),
	('"A meteor will fall in the northern sky"','"Một ngôi sao băng sẽ rơi trên bầu trời phía Bắc"','00:00:48.800','00:00:52.600','4000-essential-english-words-32'),
	('"It will make a huge explosion"','"Nó sẽ tạo ra một vụ nổ lớn"','00:00:52.600','00:00:55.000','4000-essential-english-words-32'),
	('"Find the meteor and bring it to me"','"Hãy tìm ngôi sao băng đó và mang về đây cho ta"','00:00:55.000','00:00:58.000','4000-essential-english-words-32'),
	('"I will use it to make a sword for you"','"Nó sẽ tạo nên một vụ nổ lớn"','00:00:58.000','00:01:01.000','4000-essential-english-words-32'),
	('The boy did as the old man said','Cậu bé làm theo lời ông già nói','00:01:01.000','00:01:04.200','4000-essential-english-words-32'),
	('Soon, the sword was ready','Chẳng bao lâu sau, một thanh kiếm','00:01:04.200','00:01:07.000','4000-essential-english-words-32'),
	('"Use this to kill the dragon"','"Hãy dùng thanh kiếm này để giết chết con rồng"','00:01:07.000','00:01:10.000','4000-essential-english-words-32'),
	('"But be careful"','"Nhưng con phải cẩn thận"','00:01:10.000','00:01:12.000','4000-essential-english-words-32'),
	('"You must cover yourself with weeds that smell bad"','"Con phải khoác lên mình một lớp cỏ dại để tạo mùi hương lạ"','00:01:12.000','00:01:15.600','4000-essential-english-words-32'),
	('"That will ensure that he does not smell you," the man said','"Điều đó sẽ đảm bảo rằng con rồng không ngửi thấy con," ông lão nói','00:01:15.600','00:01:20.000','4000-essential-english-words-32'),
	('The boy traveled for many days to find the castle','Chàng trai đi nhiều ngày trời để tìm kiếm tòa lâu đài','00:01:20.000','00:01:24.000','4000-essential-english-words-32'),
	('He went to the upper level and opened a door','Cậu trèo lên tầng cao và mở một cánh cửa ra','00:01:24.000','00:01:27.000','4000-essential-english-words-32'),
	('He could see the dragon\'s tail','Tại đây cậu có thể nhìn thấy đuôi của con rồng','00:01:27.000','00:01:29.200','4000-essential-english-words-32'),
	('It was sleeping, so the boy killed it','Con rồng đang ngủ nên cậu đã giết được nó','00:01:29.200','00:01:33.000','4000-essential-english-words-32'),
	('Then, he took the dragon\'s gold and jewelry and returned to his town','Tiếp đó, cậu lấy vàng và đồ trang sức của con rồng rồi quay trở về ngôi làng của mình','00:01:33.000','00:01:37.300','4000-essential-english-words-32'),
	('The people were happy','Từ đó mọi người trong làng sống hạnh phúc, bình yên bên nhau','00:01:37.300','00:01:40.000','4000-essential-english-words-32'),

	/* (UUID(),'4000-essential-english-words-33','The battle of Thermopylae','Trận chiến Thermopylae','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_033.mp3',NULL,'00:00:00.000','00:01:41.000','4000-essential-english-words','NO',33) */
	('This is a true story','Đây là một câu chuyện có thật','00:00:03.000','00:00:05.800','4000-essential-english-words-33'),
	('It happened long ago in Greece','Nó xảy ra cách đây rất lâu ở Hy Lạp','00:00:05.800','00:00:08.800','4000-essential-english-words-33'),
	('"We must fight," the Spartan chief told his small army of brave men','"Chúng ta phải chiến đấu" chỉ huy người Sparta nói với đạo quân nhỏ bé nhưng dũng cảm của ông','00:00:08.800','00:00:14.800','4000-essential-english-words-33'),
	('They were at a great disadvantage','Họ đang gặp phải một trở ngại rất lớn','00:00:14.800','00:00:17.400','4000-essential-english-words-33'),
	('There were only three hundred of them','Họ chỉ còn lại ba trăm người','00:00:17.400','00:00:20.000','4000-essential-english-words-33'),
	('The Persian military had hundreds of thousands of men','Trong khi quân đội Ba Tư lại có hàng trăm ngàn binh lính','00:00:20.000','00:00:24.100','4000-essential-english-words-33'),
	('They were going to lose unless they could secure a small entrance','Họ sẽ thua nếu họ không giữ được lối đi nhỏ duy nhất này','00:00:24.100','00:00:29.100','4000-essential-english-words-33'),
	('The enemy couldn\'t move through it easily','Lối đi nhỏ đến mức kẻ địch không thể tiến vào một cách dễ dàng','00:00:29.100','00:00:32.100','4000-essential-english-words-33'),
	('They intended to stop the enemy here','Họ có ý định ngăn chặn kẻ địch tại đây','00:00:32.100','00:00:35.600','4000-essential-english-words-33'),
	('The chief and his men got ready for the battle','Chỉ huy và quân lính của ông đã sẵn sàng cho trận chiến','00:00:35.600','00:00:38.800','4000-essential-english-words-33'),
	('Soon, long lines of the enemy\'s army twisted around the hills','Chẳng bao lâu, hàng ngàn quân lính bao vây xung quanh các ngọn đồi','00:00:38.800','00:00:44.100','4000-essential-english-words-33'),
	('The chief met the enemy with laughter','Chỉ huy nhìn đám quân địch với giọng cười mỉa mai','00:00:44.100','00:00:47.100','4000-essential-english-words-33'),
	('He knew that his men\'s weapons and skills were better','Ông biết rằng vũ khí và kỹ năng đánh trận của đội quân ông tốt hơn','00:00:47.100','00:00:51.100','4000-essential-english-words-33'),
	('The Spartans trusted their leader and obeyed him','Quân lính Sparta tin tưởng vào tài lãnh đạo và tuân theo lời của ông','00:00:51.100','00:00:54.800','4000-essential-english-words-33'),
	('First, the enemy soldiers shot arrows from their bows','Đầu tiên, quân địch bắn cung','00:00:54.800','00:00:59.400','4000-essential-english-words-33'),
	('The chief told his men to lift their shields','Chỉ huy ra lệnh cho đội quân của mình dùng khiên chắn','00:00:59.400','00:01:03.000','4000-essential-english-words-33'),
	('The arrows stuck into the shields but did not hurt any of the men','Nhờ vậy mà những mũi tên khi va vào khiên không làm bị thương bất kỳ ai','00:01:03.000','00:01:07.800','4000-essential-english-words-33'),
	('Then the enemy\'s soldiers attacked the Spartans with long spears','Tiếp đó quân địch tấn công quân lính Sparta bằng những cây giáo dài','00:01:07.800','00:01:13.200','4000-essential-english-words-33'),
	('The chief surprised them','Chỉ huy bất ngờ phản công','00:01:13.200','00:01:15.400','4000-essential-english-words-33'),
	('His troops rolled logs down on the enemy','Đó là ông cho đội quân lăn hàng loạt những khúc gỗ xuống quân địc','00:01:15.400','00:01:18.800','4000-essential-english-words-33'),
	('They fought for three days','Họ đã chiến đấu ròng rã trong ba ngày trời','00:01:18.800','00:01:21.300','4000-essential-english-words-33'),
	('Though they hardly slept at all, the chief and his men remained steady','Mặc dù họ không thể chợp mắt chút nào, nhưng chỉ huy và đoàn quân của ông vẫn giữ được tinh thần vững vàng','00:01:21.300','00:01:26.900','4000-essential-english-words-33'),
	('But the enemy found a way to beat the Spartans','Nhưng cuối cùng quân địch đã tìm ra được cách để đánh bại đội quân Sparta','00:01:26.900','00:01:30.900','4000-essential-english-words-33'),
	('The chief and all of his men were killed','Chỉ huy và tất cả đoàn quân của ông đã bị giết chết','00:01:30.900','00:01:33.900','4000-essential-english-words-33'),
	('Even though they lost, the Battle ofThermopylae is one of the most famous battles in history','Mặc dù họ đã thất bại, nhưng trận đánh Thermopylae đã trở thành một trong những trận đánh nổi tiếng nhất trong lịch sử','00:01:33.900','00:01:41.000','4000-essential-english-words-33'),

	/* (UUID(),'4000-essential-english-words-34','The deer and his image','Con huơu và hình tượng của nó','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_034.mp3',NULL,'00:00:00.000','00:01:34.100','4000-essential-english-words','NO',34) */
	('A deer told himself every day, "I am the most handsome deer in the forest"','Có một con hươu ngày ngày ca ngợi với bản thân rằng, "Mình là con hươu đẹp trai nhất trong khu rừng này"','00:00:03.500','00:00:09.900','4000-essential-english-words-34'),
	('"My large chest is a symbol of my power"','"Bộ ngực lớn là biểu tượng cho sức mạnh"','00:00:09.900','00:00:13.400','4000-essential-english-words-34'),
	('"And my beautiful horns impress other animals"','"Và cặp sừng tuyệt đẹp này luôn gây ấn tượng với những loài vật khác"','00:00:13.400','00:00:16.900','4000-essential-english-words-34'),
	('But he did not like his legs and hooves','Nhưng nó lại chẳng thích đôi chân với bộ móng','00:00:16.900','00:00:20.100','4000-essential-english-words-34'),
	('"My legs are narrow, and my hooves are ugly"','"Ôi cái chân của mình thật là hẹp còn bộ móng trông lại thật xấu xí"','00:00:20.100','00:00:24.100','4000-essential-english-words-34'),
	('"They do not satisfy me"','"Mình không hài lòng về chúng tý nào cả"','00:00:24.100','00:00:26.200','4000-essential-english-words-34'),
	('One day, the deer saw a big dog','Một ngày nọ, con hươu trông thấy một con chó to','00:00:26.200','00:00:29.900','4000-essential-english-words-34'),
	('The deer made some noise and disturbed the dog','Nó đã gây ra tiếng động và quấy rầy đến con chó','00:00:29.900','00:00:33.000','4000-essential-english-words-34'),
	('The dog woke up and chased him','Con chó tỉnh dậy và đuổi theo con hươu','00:00:33.000','00:00:36.000','4000-essential-english-words-34'),
	('The deer felt terror','Con hươu cảm thấy khiếp sợ','00:00:36.000','00:00:38.000','4000-essential-english-words-34'),
	('He screamed','Nó hét lên','00:00:38.000','00:00:39.400','4000-essential-english-words-34'),
	('He did not want to be a victim, so he ran into the forest','Nó chạy thẳng vào rừng vì không muốn trở thành nạn nhân của con chó','00:00:39.400','00:00:44.000','4000-essential-english-words-34'),
	('His strong legs helped him run fast','Đôi chân khỏe mạnh đã giúp nó chạy thật nhanh','00:00:44.000','00:00:46.900','4000-essential-english-words-34'),
	('His pale brown hooves were hard, so they were not sensitive to rough rocks','Bộ móng màu nâu nhạt cứng cáp, nên chúng không dễ bị thương bởi mấy cái cục đá lởm chởm kia','00:00:46.900','00:00:51.900','4000-essential-english-words-34'),
	('However, his horns got caught in branches, slowing him down','Tuy nhiên, cặp sừng của nó lại bị kẹt trong các nhánh cây, làm nó chậm lại','00:00:51.900','00:00:57.100','4000-essential-english-words-34'),
	('His large chest could not fit between thick trees','Còn bộ ngực rộng lại chẳng vừa vặn giữa những hàng cây dày rậm','00:00:57.100','00:01:01.000','4000-essential-english-words-34'),
	('The deer estimated that he ran for an hour','Con hươu ước tính nó đã chạy được khoảng chừng một giờ đồng hồ','00:01:01.000','00:01:04.100','4000-essential-english-words-34'),
	('He felt like he was running a marathon','Nó cảm thấy như đang chạy marathon','00:01:04.100','00:01:07.000','4000-essential-english-words-34'),
	('In the end, the deer escaped the threat of the dog','Cuối cùng, con hươu đã thoát khỏi sự đe dọa của con chó','00:01:07.000','00:01:11.000','4000-essential-english-words-34'),
	('He sat in the shade of a tree','Nó ngồi phịch dưới bóng cây','00:01:11.000','00:01:13.200','4000-essential-english-words-34'),
	('"That was almost a disaster"','"Thật đúng là một thảm họa"','00:01:13.200','00:01:16.000','4000-essential-english-words-34'),
	('"I almost did not escape because of my chest and horns"','"Mình gần như không thể trốn thoát được bởi bộ ngực và cặp sừng này"','00:01:16.000','00:01:20.000','4000-essential-english-words-34'),
	('"My legs and hooves saved me"','"May sao đôi chân và bộ móng này đã cứu mình"','00:01:20.000','00:01:23.000','4000-essential-english-words-34'),
	('As a consequence, the deer learned to honor his fast legs and have confidence in his strong hooves','Kết quả là, con hươu đã học được cách tôn trọng đôi chân nhanh nhạy và cảm thấy tự tin với bộ móng chắc khỏe của mình','00:01:23.000','00:01:29.900','4000-essential-english-words-34'),
	('"Pretty things only supplement important things," he thought','"Những thứ đẹp đẽ chỉ bổ sung cho những điều quan trọng mà thôi," nó nghĩ','00:01:29.900','00:01:34.100','4000-essential-english-words-34'),

	/* (UUID(),'4000-essential-english-words-35','May 29,1953','Ngày 29 tháng 5 năm 1953','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_035.mp3',NULL,'00:00:00.000','00:01:35.200','4000-essential-english-words','NO',35) */
	('Today is the most important day of my life','Hôm nay là ngày vô cùng đặc biệt đối với tôi','00:00:04.800','00:00:08.000','4000-essential-english-words-35'),
	('I finally climbed Mt.Everest, the tallest mountain in the world','Cuối cùng thì tôi cũng đã leo lên được Đỉnh Everest, đỉnh núi cao nhất thế giới','00:00:08.000','00:00:13.000','4000-essential-english-words-35'),
	('The top of the mountain was amazing','Đứng trên đỉnh núi cảm giác thật tuyệ','00:00:13.000','00:00:15.700','4000-essential-english-words-35'),
	('It felt like we were close to heaven','Cái cảm giác như chúng tôi đang đứng rất gần với thiên đường','00:00:15.700','00:00:18.800','4000-essential-english-words-35'),
	('The snow was so thick that my boots sank','Tuyết quá dày đến nỗi đôi ủng của tôi bị ngập toàn tuyết với tuyết','00:00:18.800','00:00:22.800','4000-essential-english-words-35'),
	('The air was silent','Không khí thật tĩnh lặng','00:00:22.800','00:00:24.800','4000-essential-english-words-35'),
	('I looked at the beauty that surrounded me','Quang cảnh xung quanh tôi đẹp lạ kỳ','00:00:24.800','00:00:27.400','4000-essential-english-words-35'),
	('Maybe my story will be a legend someday','Có thể một ngày nào đó câu chuyện của tôi sẽ trở thành huyền thoại','00:00:27.400','00:00:30.800','4000-essential-english-words-35'),
	('I want people to remember this forever','Tôi muốn mọi người nhớ về nó mãi mãi','00:00:30.800','00:00:34.000','4000-essential-english-words-35'),
	('I was the senior explorer in my group, and I knew we needed proof of our climb','Là một nhà thám hiểm lâu năm trong nhóm, tôi biết chúng tôi cần phải có bằng chứng về chuyến leo núi của mình','00:00:34.000','00:00:40.800','4000-essential-english-words-35'),
	('I took many pictures with my camera','Tôi đã chụp rất nhiều bức ảnh','00:00:40.800','00:00:43.800','4000-essential-english-words-35'),
	('I\'ll put them in a frame and hang them','Tôi bỏ chúng vào khung và treo lên tường','00:00:43.800','00:00:46.000','4000-essential-english-words-35'),
	('On the mountain, the air was very cold','Ở trên núi, không khí rất lạnh','00:00:46.000','00:00:49.800','4000-essential-english-words-35'),
	('I wrapped my coat around my body','Tôi phải phủ thêm nhiều lớp áo trên người','00:00:49.800','00:00:52.800','4000-essential-english-words-35'),
	('I looked over the side of the mountaintop','Tôi nhìn qua sườn núi','00:00:52.800','00:00:55.800','4000-essential-english-words-35'),
	('From that angle, I saw the border of the clouds touch the rocks below','Từ góc này có thể nhìn thấy những áng mây chạm vào tảng đá bên dưới','00:00:55.800','00:01:01.800','4000-essential-english-words-35'),
	('The snow was thick','Tuyết rất dày','00:01:01.800','00:01:03.300','4000-essential-english-words-35'),
	('It looked pure','Gần như trong suốt','00:01:03.300','00:01:04.900','4000-essential-english-words-35'),
	('There was no sign of modern life','Không có dấu hiệu của sự sống hiện đại','00:01:04.900','00:01:08.000','4000-essential-english-words-35'),
	('Thousands of years ago, my ancestors saw the world this way','Cách đây hàng nghìn năm, tổ tiên của chúng ta đã nhìn thế giới theo cách này','00:01:08.000','00:01:12.000','4000-essential-english-words-35'),
	('After fifteen minutes, I knew it was time to proceed down the mountain','Mười lăm phút sau, tôi biết rằng đã đến lúc phải xuống núi','00:01:12.000','00:01:17.500','4000-essential-english-words-35'),
	('The whole team congratulated us','Cả đội đã vỗ tay chúc mừng chúng tôi','00:01:17.500','00:01:20.100','4000-essential-english-words-35'),
	('My superior, John Hunt, praised us all','Đàn anh của tôi, John Hunt, đã tán dương tất cả chúng tôi','00:01:20.100','00:01:23.400','4000-essential-english-words-35'),
	('I sent messages to my relatives to tell them that I was safe','Tôi gửi tin nhắn đến cho người thân của mình để thông báo rằng tôi đã an toàn','00:01:23.400','00:01:28.100','4000-essential-english-words-35'),
	('But it was hard to leave the mountain so quickly','Nhưng thật khó để rời khỏi ngọn núi này một cách nhanh chóng','00:01:28.100','00:01:31.200','4000-essential-english-words-35'),
	('I wanted to enjoy the incredible sight even longer','Thật sự tôi vẫn muốn được chiêm ngưỡng cảnh sắc tuyệt diệu này lâu hơn','00:01:31.200','00:01:35.200','4000-essential-english-words-35');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-36','The frog prince','Hoàng tử ếch','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_036.mp3',NULL,'00:00:00.000','00:01:34.000','4000-essential-english-words','NO',36) */
	('A lovely princess sat by the pool and played with a sculpture of a bear','Một công chúa đáng yêu ngồi bên bể bơi và chơi với bức tượng điêu khắc một con gấu','00:00:03.000','00:00:08.100','4000-essential-english-words-36'),
	('Suddenly, she dropped it, and it rolled away','Đột nhiên, cô đánh rơi nó, và nó lăn đi','00:00:08.100','00:00:12.100','4000-essential-english-words-36'),
	('She chased it, but it fell into the water','Cô ấy đã đuổi theo nó, nhưng nó đã rơi xuống nước','00:00:12.100','00:00:15.900','4000-essential-english-words-36'),
	('She began to cry','Cô bắt đầu khóc','00:00:15.900','00:00:17.900','4000-essential-english-words-36'),
	('A large, ugly frog asked, "Why are you crying?"','Một chú ếch to, xấu xí hỏi, "Tại sao bạn khóc?"','00:00:17.900','00:00:22.100','4000-essential-english-words-36'),
	('After the princess told him, the frog said, "I can get the sculpture"','Sau khi nàng công chúa kể với chú ếch, chú nói, "Tôi có thể lấy bức tượng điêu khắc"','00:00:22.100','00:00:27.300','4000-essential-english-words-36'),
	('"What will you give me in exchange for the favor?"','"Vậy bạn sẽ đưa tôi cái gì thay cho sự trả ơn đây?"','00:00:27.300','00:00:30.900','4000-essential-english-words-36'),
	('"I can pay you a fee in gold," she said','"Tôi có thể trả cho bạn phí bằng vàng," cô nói','00:00:30.900','00:00:34.100','4000-essential-english-words-36'),
	('But the frog protested','Nhưng chú ếch từ chối','00:00:34.100','00:00:36.100','4000-essential-english-words-36'),
	('"I want to sleep in your bed, and you must kiss me in the morning"','"Tôi muốn ngủ trong chiếc giường của bạn, và bạn phải hôn tôi vào buổi sáng"','00:00:36.100','00:00:41.000','4000-essential-english-words-36'),
	('"He\'d die without water"','"Chú sẽ chết nếu không có nước"','00:00:41.000','00:00:43.000','4000-essential-english-words-36'),
	('"So, I don\'t have to keep my promise," she thought','"Vì vậy, tôi không phải giữ lời hứa," cô nghĩ vậy','00:00:43.000','00:00:47.000','4000-essential-english-words-36'),
	('The frog dove for a brief moment and got the sculpture','Chú ếch lặn xuống một khoảnh khắc ngắn và lấy được tượng điêu khắc','00:00:47.000','00:00:51.000','4000-essential-english-words-36'),
	('Then the princess ran away with it','Sau đó nàng công chúa chạy đi với nó','00:00:51.000','00:00:53.000','4000-essential-english-words-36'),
	('Later, the frog went to the palace','Sau đó, chú ếch đã đi tới cung điện','00:00:53.000','00:00:56.800','4000-essential-english-words-36'),
	('The king told her to keep her promise','Nhà vua dặn cô phải giữ lời hứa','00:00:56.800','00:01:00.000','4000-essential-english-words-36'),
	('This put the princess in a bad mood','Điều này đặt nàng công chúa trong tâm trạng xấu','00:01:00.000','00:01:02.800','4000-essential-english-words-36'),
	('She permitted the frog to sleep on her pillow','Cô cho phép chú ếch ngủ trên chiếc gối của cô','00:01:02.800','00:01:06.000','4000-essential-english-words-36'),
	('In the morning, she gave him a kiss','Buổi sáng, cô ấy đã trao nó một nụ hôn','00:01:06.000','00:01:09.000','4000-essential-english-words-36'),
	('Suddenly, he turned into a guy','Đột nhiên, nó biến thành một chàng trai','00:01:09.000','00:01:12.000','4000-essential-english-words-36'),
	('He said, "I\'m from a kingdom abroad"','Chàng trai nói, "Tôi đến từ một vương quốc xa xôi"','00:01:12.000','00:01:16.000','4000-essential-english-words-36'),
	('"In my youth, I angered a tribe of cruel witches, who turned me into a frog"','"Hồi còn trẻ, tôi đã chọc giận một nhóm bộ tộc phù thủy, đã biến tôi thành một chú ếch"','00:01:16.000','00:01:21.900','4000-essential-english-words-36'),
	('The princess asked him, "Can I be your bride and stay with you forever?"','Cô công chúa hỏi anh, "Em có thể trở thành cô dâu của anh và ở bên cạnh anh mãi mãi chứ?"','00:01:21.900','00:01:27.500','4000-essential-english-words-36'),
	('But the prince said, "No"','Nhưng chàng hoàng tử nói, "Không"','00:01:27.500','00:01:30.000','4000-essential-english-words-36'),
	('"You disappointed me"','"Nàng làm ta thất vọng"','00:01:30.000','00:01:31.800','4000-essential-english-words-36'),
	('"You didn\'t keep your promise"','"Nàng đã không giữ lời hứa của mình','00:01:31.800','00:01:34.000','4000-essential-english-words-36'),

	/* (UUID(),'4000-essential-english-words-37','A beautiful bird','Chú chim xinh đẹp','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_037.mp3',NULL,'00:00:00.000','00:01:44.000','4000-essential-english-words','NO',37) */
	('Dr.Norton\'s occupation was a scholar of biology','Nghề nghiệp của Tiến sĩ Norton là một học giả về sinh học','00:00:03.500','00:00:07.200','4000-essential-english-words-37'),
	('He learned about all animals on a daily basis','Hàng ngày, ông nghiên cứu về tất cả các loài động vật','00:00:07.200','00:00:11.000','4000-essential-english-words-37'),
	('One day he met a sailor from a colony overseas','Một ngày nọ, ông đã gặp một thủy thủ từ một thuộc địa nước ngoài','00:00:11.000','00:00:15.000','4000-essential-english-words-37'),
	('The man told Dr.Norton about a talking bird','Người đàn ông nói với tiến sĩ về một con chim biết nói','00:00:15.000','00:00:18.300','4000-essential-english-words-37'),
	('The bird fascinated Dr.Norton, so he told his colleagues about it','Con chim đã thu hút Tiến sĩ, nên ông đã nói với đồng nghiệp của mình về nó','00:00:18.300','00:00:23.900','4000-essential-english-words-37'),
	('They debated with him: no one thought a bird could talk','Họ tranh luận với ông: chẳng ai lại nghĩ chim có thể nói được cả','00:00:23.900','00:00:28.100','4000-essential-english-words-37'),
	('He tried to persuade them, but they laughed at him','Ông cố gắng thuyết phục họ, tuy nhiên họ lại chỉ cười nhạo ông','00:00:28.100','00:00:31.900','4000-essential-english-words-37'),
	('Nevertheless, Dr.Norton believed the bird was real','Tuy nhiên, Tiến sĩ Norton lại tin rằng con chim đấy có thực','00:00:31.900','00:00:35.900','4000-essential-english-words-37'),
	('His new mission was to find it','Sứ mệnh mới của ông là phải tìm ra được nó','00:00:35.900','00:00:38.200','4000-essential-english-words-37'),
	('He wanted factual proof','Ông muốn có được chứng cớ xác thực','00:00:38.200','00:00:40.800','4000-essential-english-words-37'),
	('The next day he departed for the colony','Ngày hôm sau, ông khởi hành đến thuộc địa','00:00:40.800','00:00:43.800','4000-essential-english-words-37'),
	('The sailor he had met told him to look for a man named Jai, who would be able to help him in his search','Người thủy thủ mà ông từng gặp bảo ông tìm một người đàn ông tên là Jai, là người có thể sẽ giúp ông trong việc tìm kiếm','00:00:43.800','00:00:51.000','4000-essential-english-words-37'),
	('After a month of sailing, Dr.Norton finally reached the colony where he met Jai','Sau một tháng trên biển, cuối cùng Tiến sĩ Norton đã đến thuộc địa nơi ông có thể gặp Jai','00:00:51.000','00:00:57.400','4000-essential-english-words-37'),
	('"I can take you to where it lives"','"Tôi có thể đưa ông đến nơi nó sống"','00:00:57.400','00:00:59.700','4000-essential-english-words-37'),
	('"It lives by the volcano," Jai said','"Nó sống gần núi lửa," Jai nói','00:00:59.700','00:01:03.000','4000-essential-english-words-37'),
	('They left the next day','Ngay ngày sau, họ đã rời đi','00:01:03.000','00:01:04.800','4000-essential-english-words-37'),
	('A week later, they arrived at the volcano','Và một tuần sau, họ đã đến khu vực núi lửa','00:01:04.800','00:01:08.100','4000-essential-english-words-37'),
	('Every day they walked around and looked for the bird, but they couldn\'t find it','Hàng ngày họ đều dạo quanh đó và tìm kiếm con chim, nhưng họ không thể tìm ra nó','00:01:08.100','00:01:14.000','4000-essential-english-words-37'),
	('After one month, Dr.Norton could not find the bird, and this depressed him','Sau một tháng, tiến sĩ Norton không thể tìm thấy chú chim, và điều đó làm ông chán nản','00:01:14.000','00:01:19.900','4000-essential-english-words-37'),
	('He decided to go home','Ông quyết định về nhà','00:01:19.900','00:01:22.000','4000-essential-english-words-37'),
	('On the route back, he walked past some old ruins','Trên đường trở về, ông đi qua những nơi đổ nát cũ','00:01:22.000','00:01:26.200','4000-essential-english-words-37'),
	('He heard someone say, "Hello"','Ông nghe thấy ai đó nói, "Xin chào"','00:01:26.200','00:01:29.000','4000-essential-english-words-37'),
	('"Who are you?" he asked','"Ai đó?" ông hỏi','00:01:29.000','00:01:31.300','4000-essential-english-words-37'),
	('Dr.Norton looked up and saw a bird','Tiến sĩ Norton dõi mắt tìm kiếm và ông đã trông thấy một con chim','00:01:31.300','00:01:34.900','4000-essential-english-words-37'),
	('Dr.Norton put the talking bird into a cage','Tiến sĩ Norton bỏ con chim biết nói vào trong một cái lồng','00:01:34.900','00:01:38.900','4000-essential-english-words-37'),
	('Then he returned home','Sau đó ông quay trở về nhà','00:01:38.900','00:01:40.900','4000-essential-english-words-37'),
	('He had made a significant discovery','Ông đã có một phát hiện quan trọng','00:01:40.900','00:01:44.000','4000-essential-english-words-37'),

	/* (UUID(),'4000-essential-english-words-38','Tricky turtle','Chú rùa khôn lanh','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_038.mp3',NULL,'00:00:00.000','00:01:44.000','4000-essential-english-words','NO',38) */
	('Ricky the rabbit and Tera the turtle met by the edge of the river','Thỏ Ricky và rùa Tera gặp nhau ở bờ sông','00:00:03.000','00:00:08.000','4000-essential-english-words-38'),
	('"No one is capable of beating me in a race" Ricky said','"Không ai có khả năng đánh bại tôi trong cuộc đua" Ricky nói','00:00:08.000','00:00:12.900','4000-essential-english-words-38'),
	('He was confident, his smile conveyed that','Anh ấy rất tự tin, nụ cười của anh ấy thể hiện điều đó','00:00:12.900','00:00:16.800','4000-essential-english-words-38'),
	('"I can beat you," Tera said','"Tôi có thể đánh bại cậu", Tera nói','00:00:16.800','00:00:19.800','4000-essential-english-words-38'),
	('Ricky laughed with delight','Ricky bật cười sảng khoái','00:00:19.800','00:00:22.000','4000-essential-english-words-38'),
	('Tera said, "We will race tomorrow"','Tera nói, "Ngày mai chúng ta cùng đua"','00:00:22.000','00:00:25.800','4000-essential-english-words-38'),
	('"The destination is the hill"','"Đích đến là ngọn đồi"','00:00:25.800','00:00:27.800','4000-essential-english-words-38'),
	('Ricky agreed','Ricky đồng ý','00:00:27.800','00:00:29.800','4000-essential-english-words-38'),
	('Tera concentrated on winning the race','Tera tập trung để dành chiến thắng trong cuộc đua','00:00:29.800','00:00:32.800','4000-essential-english-words-38'),
	('She was not faster than Ricky','Cô rùa không nhanh hơn Ricky','00:00:32.800','00:00:35.000','4000-essential-english-words-38'),
	('She needed a definite way to succeed','Nên nó cần một cách thức rõ ràng để thành công','00:00:35.000','00:00:38.600','4000-essential-english-words-38'),
	('She told her family about the race, "I have concluded that I have to resort to something bad"','Cô đã nói với gia đình về cuộc đua, "Con đã kết luận rằng con buộc phải dùng một vài thứ xấu xa"','00:00:38.600','00:00:44.800','4000-essential-english-words-38'),
	('"I will cheat"','"Con sẽ ăn gian"','00:00:44.800','00:00:46.400','4000-essential-english-words-38'),
	('She dictated her instructions to them','Cô nói ra ý định của mình cho họ biết','00:00:46.400','00:00:48.900','4000-essential-english-words-38'),
	('At the race, they all wore white feathers','Ở đường đua, tất cả đều khoác lên bộ lông màu trắng','00:00:48.900','00:00:53.000','4000-essential-english-words-38'),
	('They looked exactly the same','Nhìn họ hoàn toàn giống nhau','00:00:53.000','00:00:55.000','4000-essential-english-words-38'),
	('Then, her family members hid in shadows on the path','Sau đó các thành viên trong gia đình của Tera ẩn trong các bóng râm trên đường đua','00:00:55.000','00:00:59.000','4000-essential-english-words-38'),
	('The race began','Cuộc đua bắt đầu','00:00:59.000','00:01:00.900','4000-essential-english-words-38'),
	('Tera was soon far behind','Tera nhanh chóng bị bỏ lại đằng sau','00:01:00.900','00:01:03.400','4000-essential-english-words-38'),
	('However, Tera\'s brother hid behind a bush in the valley below','Tuy nhiên, em trai Tera đã ẩn nấp đằng sau một bụi cây trong thung lũng bên dưới','00:01:03.400','00:01:08.000','4000-essential-english-words-38'),
	('When Ricky got close, Tera\'s brother began to run','Khi Ricky đến gần, em trai Tera bắt đầu chạy','00:01:08.000','00:01:12.000','4000-essential-english-words-38'),
	('He looked just like Tera','Cậu ta trông rất giống với Tera','00:01:12.000','00:01:15.000','4000-essential-english-words-38'),
	('Ricky ran as fast as he could along the path','Ricky chạy nhanh nhất có thể dọc theo con đường','00:01:15.000','00:01:18.000','4000-essential-english-words-38'),
	('But, to him, it seemed like Tera was always ahead','Nhưng, với Ricky, cậu ta luôn cho rằng Tera luôn dẫn đầu','00:01:18.000','00:01:22.000','4000-essential-english-words-38'),
	('Ricky had used a considerable amount of energy','Ricky đã tiêu tốn một lượng năng lượng đáng kể','00:01:22.000','00:01:25.800','4000-essential-english-words-38'),
	('He reached the top, but Tera\'s sister was already there','Ricky chạy tới đích nhưng chị của Tera đã ở đấy rồi','00:01:25.800','00:01:30.000','4000-essential-english-words-38'),
	('"Well, you win," Ricky said','"Ồ, bạn đã thắng," Ricky nói','00:01:30.000','00:01:33.800','4000-essential-english-words-38'),
	('Later, Tera had a broad smile on her face','Sau đó, Tera đã cười vang','00:01:33.800','00:01:37.800','4000-essential-english-words-38'),
	('Ricky never suspected','Ricky không nghi ngờ điều gì','00:01:37.800','00:01:40.000','4000-essential-english-words-38'),
	('He had been tricked by a family of slow turtles','Cậu đã bị lừa bởi một gia đình rùa chậm chạp','00:01:40.000','00:01:44.000','4000-essential-english-words-38'),

	/* (UUID(),'4000-essential-english-words-39','The tale of Bartelby O\'Boyle','Câu chuyện về Bartelby O\'Boyle','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_039.mp3',NULL,'00:00:00.000','00:01:44.000','4000-essential-english-words','NO',39) */
	('Long ago, there was a clever man by the name of Bartelby O\'Boyle','Thuở xưa, có một chàng trai rất thông minh tên là Bartelby O’Boyle','00:00:04.000','00:00:09.000','4000-essential-english-words-39'),
	('As a boy, he was kept as a slave by the royal family','Khi còn nhỏ, anh làm nô lệ cho một gia đình hoàng gia','00:00:09.000','00:00:13.800','4000-essential-english-words-39'),
	('He saw other children play, but he always had to work','Anh thường nhìn những đứa trẻ khác chơi đùa nhưng còn mình thì luôn phải làm việc','00:00:13.800','00:00:18.700','4000-essential-english-words-39'),
	('This frustrated him very much','Điều này khiến anh cảm thấy rất chán nản','00:00:18.700','00:00:21.000','4000-essential-english-words-39'),
	('But he was not stupid, and he wanted to change things','Nhưng anh không phải là một đứa trẻ ngu ngốc, và anh muốn thay đổi mọi thứ','00:00:21.000','00:00:26.000','4000-essential-english-words-39'),
	('Then one day there was a struggle for authority in the kingdom','Một ngày nọ, trong vương quốc nổ ra một cuộc tranh giành quyền lực','00:00:26.000','00:00:30.800','4000-essential-english-words-39'),
	('There was a division of the people, and one group fought against another group to see which would govern the kingdom','Đã có sự phân chia trong dân chúng, một nhóm người này chống lại một nhóm người kia để xem bên nào sẽ cai trị được vương quốc','00:00:30.800','00:00:38.200','4000-essential-english-words-39'),
	('There was disorder in the kingdom','Vương quốc trở nên hỗn loạn','00:00:38.200','00:00:40.800','4000-essential-english-words-39'),
	('Bartelby ran away','Bartelby đã bỏ chạy','00:00:40.800','00:00:42.800','4000-essential-english-words-39'),
	('He saw much fighting and destruction','Anh đã chứng kiến rất nhiều cuộc chiến và sự tàn phá','00:00:42.800','00:00:46.400','4000-essential-english-words-39'),
	('Many people had nothing to eat','Nhiều người đã chẳng còn gì để ăn','00:00:46.400','00:00:49.000','4000-essential-english-words-39'),
	('Bartelby decided to aid them','Bartelby quyết định trợ giúp họ','00:00:49.000','00:00:52.000','4000-essential-english-words-39'),
	('He would help them get food','Anh quyết định mang thức ăn đến cho họ','00:00:52.000','00:00:53.900','4000-essential-english-words-39'),
	('But how?','Nhưng bằng cách nào?','00:00:53.900','00:00:55.800','4000-essential-english-words-39'),
	('Bartelby went to the capital to find an answer','Bartelby bèn đi đến thủ đô để tìm kiếm câu trả lời','00:00:55.800','00:00:59.100','4000-essential-english-words-39'),
	('There, he met a man named Gilliam','Tại đây, anh đã gặp một người đàn ông tên là Gilliam','00:00:59.100','00:01:02.800','4000-essential-english-words-39'),
	('A group of men attempted to hurt Gilliam','Và một nhóm người đang ra sức làm Gilliam bị thương','00:01:02.800','00:01:06.200','4000-essential-english-words-39'),
	('Bartelby defended him','Bartelby đã bảo vệ anh ta','00:01:06.200','00:01:08.500','4000-essential-english-words-39'),
	('Then, he gave Gilliam some food to relieve his hunger','Sau đó, anh đưa cho Gilliam một ít thức ăn để làm dịu đi cơn đói của ông','00:01:08.500','00:01:12.400','4000-essential-english-words-39'),
	('After that, the two became friends','Và sau đó, hai người trở thành bạn bè','00:01:12.400','00:01:15.600','4000-essential-english-words-39'),
	('They took food from the rich and gave it to the poor','Họ lấy thức ăn của người giàu chia cho người nghèo','00:01:15.600','00:01:19.700','4000-essential-english-words-39'),
	('Soon, other people cooperated with them','Không lâu sau đó, đã có nhiều người cùng tham gia','00:01:19.700','00:01:22.900','4000-essential-english-words-39'),
	('Working together enabled them to take more food','Cùng nhau làm việc giúp họ lấy thêm được nhiều thức ăn hơn','00:01:22.900','00:01:26.900','4000-essential-english-words-39'),
	('But they only took food from people who had plenty, and they always gave it to those who had none','Nhưng họ chỉ lấy thức ăn từ những người có rất nhiều thức ăn rồi chuyển nó cho những người không có','00:01:26.900','00:01:34.000','4000-essential-english-words-39'),
	('Because of this, Bartleby gained a reputation across the kingdom','Vì những điều này, danh tiếng của Bartelby vang khắp vương quốc','00:01:34.000','00:01:38.800','4000-essential-english-words-39'),
	('Even today, many people admire him for helping the poor','Thậm chí đến bây giờ, nhiều người vẫn ngưỡng mộ anh về câu chuyện giúp đỡ những người nghèo khổ','00:01:38.800','00:01:44.000','4000-essential-english-words-39'),

	/* (UUID(),'4000-essential-english-words-40','Blackbeard','Râu đen','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_040.mp3',NULL,'00:00:00.000','00:01:36.700','4000-essential-english-words','NO',40) */
	('A longtime ago, I had my first job','Cách đây rất lâu rồi, tôi đã tìm được công việc đầu tiên của mình','00:00:03.000','00:00:06.900','4000-essential-english-words-40'),
	('It didn\'t give me much of an income','Nó không mang lại cho tôi nhiều thu nhập','00:00:06.900','00:00:09.000','4000-essential-english-words-40'),
	('It was on a giant pirate ship','Đó là công việc trên một con tàu cướp biển khổng lồ','00:00:09.000','00:00:12.000','4000-essential-english-words-40'),
	('On my first night, there was a thick fog over the water','Vào đêm đầu tiên, màn sương mù dày đặc bao phủ trên mặt nước biển','00:00:12.000','00:00:16.000','4000-essential-english-words-40'),
	('A lamp on the ship revealed an enormous man','Ngọn đèn trên tàu đã làm lộ ra một người đàn ông to lớn','00:00:16.000','00:00:19.800','4000-essential-english-words-40'),
	('He had a sword in his belt','Ông ta có một thanh gươm ở thắt lưng','00:00:19.800','00:00:22.400','4000-essential-english-words-40'),
	('His name was Blackbeard, and he was one of the most violent pirates ever','Tên ông ta là Râu Đen, và là một trong những tên cướp biển tàn bạo nhất từ trước tới giờ','00:00:22.400','00:00:28.400','4000-essential-english-words-40'),
	('One day, Blackbeard did an extraordinary thing','Rồi một ngày, Râu Đen đã làm một điều thật phi thường','00:00:28.400','00:00:32.800','4000-essential-english-words-40'),
	('He attacked several ships near a town','Ông ta tấn công một số con thuyền ở gần một thị trấn','00:00:32.800','00:00:35.200','4000-essential-english-words-40'),
	('He took some of the town\'s citizens','Ông đã bắt một vài người dân của thị trấn','00:00:35.200','00:00:38.200','4000-essential-english-words-40'),
	('Then he declared, "You give me medicine"','Sau đó ông ta tuyên bố, "Các ngươi hãy đưa thuốc cho ta"','00:00:38.200','00:00:42.000','4000-essential-english-words-40'),
	('Blackbeard wanted the medicine for some of the sick pirates on his ship','Râu Đen muốn lấy thuốc để chữa bệnh cho một số tên cướp biển đang bị ốm trên con tàu của ông ta','00:00:42.000','00:00:47.000','4000-essential-english-words-40'),
	('The people had a bad impression of him','Mọi người đều có ấn tượng xấu về ông','00:00:47.000','00:00:50.000','4000-essential-english-words-40'),
	('They were mad, and they resisted','Họ đã nổi giận và họ kháng cự lại','00:00:50.000','00:00:53.000','4000-essential-english-words-40'),
	('But they were trapped','Nhưng rồi họ đều bị bắt giữ lại','00:00:53.000','00:00:55.200','4000-essential-english-words-40'),
	('They wanted to get rid of him','Họ muốn tống khứ ông ta','00:00:55.200','00:00:57.800','4000-essential-english-words-40'),
	('So the town\'s council decided to give him the medicine','Thế là hội đồng thị trấn đã quyết định đưa thuốc cho ông ta','00:00:57.800','00:01:01.000','4000-essential-english-words-40'),
	('After this, there was a reward for catching Blackbeard','Sau đó, người ta đã treo thưởng cho ai bắt được Râu Đen','00:01:01.000','00:01:05.200','4000-essential-english-words-40'),
	('If Blackbeard was caught, he would have a trial','Nếu Râu Đen bị bắt, ông ta sẽ bị xét xử','00:01:05.200','00:01:08.900','4000-essential-english-words-40'),
	('He didn\'t want to go to jail, so he quit being a pirate','Vì không muốn ngồi tù, nên Râu Đen đã từ bỏ làm cướp biển','00:01:08.900','00:01:13.200','4000-essential-english-words-40'),
	('Blackbeard became a fisherman','Râu Đen trở thành một người đánh cá','00:01:13.200','00:01:15.700','4000-essential-english-words-40'),
	('But he ought to have stayed on land','Nhưng lẽ ra ông ta nên ở lại trên đất liền','00:01:15.700','00:01:18.200','4000-essential-english-words-40'),
	('The Royal Navy was still looking for him','Hải quân Hoàng gia vẫn đang truy tìm ông ta','00:01:18.200','00:01:21.000','4000-essential-english-words-40'),
	('They attacked him while he was fishing on his boat','Họ tấn công ông khi ông đang đánh cá trên thuyền','00:01:21.000','00:01:24.600','4000-essential-english-words-40'),
	('Blackbeard fought against many men','Râu Đen đã đánh lại rất nhiều người khác','00:01:24.600','00:01:27.700','4000-essential-english-words-40'),
	('Finally, he was killed','Nhưng cuối cùng thì ông đã bị giết','00:01:27.700','00:01:30.000','4000-essential-english-words-40'),
	('He didn\'t even get a funeral','Ông ta thậm chí còn không được tổ chức đám tang','00:01:30.000','00:01:32.600','4000-essential-english-words-40'),
	('But people still tell tales about him many years later','Nhưng nhiều người vẫn kể chuyện về ông trong rất nhiều năm sau đó','00:01:32.600','00:01:36.700','4000-essential-english-words-40');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-41','Dinosaur drawings','Bức hình khủng long','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_041.mp3',NULL,'00:00:00.000','00:01:39.200','4000-essential-english-words','NO',41) */
	('It was the worst morning ever','Đó là một buổi sáng tồi tệ nhất từ trước tới giờ','00:00:03.000','00:00:05.800','4000-essential-english-words-41'),
	('When Carl woke up, he realized that he didn\'t do his astronomy and chemistry homework','Khi tỉnh dậy, Carl nhận ra anh ấy đã không làm bài tập về nhà môn thiên văn học và hóa học','00:00:05.800','00:00:12.200','4000-essential-english-words-41'),
	('Also, the forecast called for rain and that would affect baseball practice','Hơn thế nữa, dự báo nói rằng trời hôm nay sẽ mưa và điều đó sẽ ảnh hưởng đến giờ thực hành bóng chày','00:00:12.200','00:00:18.200','4000-essential-english-words-41'),
	('Suddenly, his mother yelled, "Take out the garbage right now"','Bỗng nhiên, mẹ anh ấy gọi toáng lên, "Đi đổ rác ngay lập tức"','00:00:18.200','00:00:23.000','4000-essential-english-words-41'),
	('When Carl returned from taking the garbage outside, he was all wet','Khi Carl quay về từ điểm đổ rác, anh ấy bị ướt cả người','00:00:23.000','00:00:28.100','4000-essential-english-words-41'),
	('"What a terrible day," he said','"Thật là một ngày tồi tệ" anh ấy nói ','00:00:28.100','00:00:31.100','4000-essential-english-words-41'),
	('He walked to class','Anh ấy đi bộ đến lớp','00:00:31.100','00:00:33.000','4000-essential-english-words-41'),
	('He put his umbrella on the shelf and sat in the third row','Anh đặt ô lên kệ và ngồi xuống dãy bàn thứ ba','00:00:33.000','00:00:37.600','4000-essential-english-words-41'),
	('But the teacher asked why Carl\'s umbrella was on the floor','Nhưng cô giáo hỏi tại sao ô của Carl lại nằm trên sàn nhà','00:00:37.600','00:00:41.400','4000-essential-english-words-41'),
	('He told her not to blame him','Anh ấy nói với cô giáo đó không phải do anh ấy làm','00:00:41.400','00:00:43.600','4000-essential-english-words-41'),
	('But she sent him to the principal out of spite','Nhưng cô giáo đã cho anh đến gặp thầy hiệu trưởng','00:00:43.600','00:00:47.200','4000-essential-english-words-41'),
	('Next, he took a geography test','Tiếp đó, anh ấy phải làm bài kiểm tra môn địa','00:00:47.200','00:00:50.200','4000-essential-english-words-41'),
	('Despite studying, Carl didn\'t know the answers','Mặc dù đã học bài, nhưng Carl không thể biết câu trả lời','00:00:50.200','00:00:54.000','4000-essential-english-words-41'),
	('He started drawing lightly on his paper','Anh ta bắt đầu vẽ bừa lên tờ giấy','00:00:54.000','00:00:57.000','4000-essential-english-words-41'),
	('Carl drew a huge dinosaur','Anh ấy vẽ một con khủng long khổng lồ','00:00:57.000','00:01:00.000','4000-essential-english-words-41'),
	('What if it were real?','Liệu nó có thật thì sao nhỉ?','00:01:00.000','00:01:01.800','4000-essential-english-words-41'),
	('He saw it in his mind','Anh ấy nghĩ thầm','00:01:01.800','00:01:04.000','4000-essential-english-words-41'),
	('Carl\'s class said he was a genius for having a dinosaur','Các bạn cùng lớp nói rằng Anh ta là một thiên tài vì có một con khủng long to như thế','00:01:04.000','00:01:08.200','4000-essential-english-words-41'),
	('It could interfere with math class, too','Điều này có thể ảnh hưởng đến cả giờ toán nữa','00:01:08.200','00:01:11.800','4000-essential-english-words-41'),
	('Soon, Carl\'s fame spread through school','Không lâu sau, danh tiếng của Carl lan rộng khắp trường','00:01:11.800','00:01:15.600','4000-essential-english-words-41'),
	('He taught his dinosaur to be very gentle and put it on exhibit','Anh ấy thuần hóa con khủng long của mình trở nên hiền lành và đưa ra triển lãm','00:01:15.600','00:01:20.900','4000-essential-english-words-41'),
	('But admission would only be given to those classmates who paid him a fee','Nhưng vá vào cửa sẽ chỉ dành cho những người bạn cùng lớp, những người có trả phí cho anh ấy','00:01:20.900','00:01:26.000','4000-essential-english-words-41'),
	('His idea was super','Ý tưởng của anh ấy thật tuyệt vời','00:01:26.000','00:01:28.100','4000-essential-english-words-41'),
	('"It\'s time to turn in your tests," the teacher said','"Đã đến giờ nộp bài" giáo viên nói','00:01:28.100','00:01:32.300','4000-essential-english-words-41'),
	('Carl looked at his paper','Carl nhìn vào bài thi của anh ấy','00:01:32.300','00:01:34.300','4000-essential-english-words-41'),
	('As he was dreaming in class, he hadn\'t finished the test','Khi mà anh ấy đang mơ trong lớp thì bài kiểm tra đã không được hoàn thành','00:01:34.300','00:01:39.200','4000-essential-english-words-41'),

	/* (UUID(),'4000-essential-english-words-42','The mean chef','Đầu bếp xấu tính','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_042.mp3',NULL,'00:00:00.000','00:01:29.500','4000-essential-english-words','NO',42) */
	('Once there was a chef, who was mean to his cooks','Ngày xưa có một người bếp trưởng, ông luôn đối xử tệ với các đầu bếp của mình','00:00:03.400','00:00:07.400','4000-essential-english-words-42'),
	('He was mean to the people who came in to eat','Ông rất khó tính đối với những người tới đây ăn uống','00:00:07.400','00:00:10.800','4000-essential-english-words-42'),
	('He charged too much for meals','Ông thu phí các món ăn rất cao','00:00:10.800','00:00:13.000','4000-essential-english-words-42'),
	('Many people were not able to afford the cheapest bean dish','Nhiều người không có khả năng mua món đậu rẻ nhất','00:00:13.000','00:00:16.800','4000-essential-english-words-42'),
	('When his metal oven broke, he did not have it fixed','Khi lò vi sóng bằng kim loại bị hỏng, ông không sửa lại nó','00:00:16.800','00:00:21.000','4000-essential-english-words-42'),
	('So everything baked in it burned','Nên mọi thứ nướng trong đó đều bị cháy đen','00:00:21.000','00:00:23.800','4000-essential-english-words-42'),
	('The only light was from candles, and the whole place was a mess','Ánh sáng duy nhất là từ ngọn nến, và toàn bộ không gian trở thành một mớ hỗn độn','00:00:23.800','00:00:28.400','4000-essential-english-words-42'),
	('Sometimes, he didn\'t pay his waiters','Thỉnh thoảng, ông không trả tiền cho phục vụ','00:00:28.400','00:00:31.100','4000-essential-english-words-42'),
	('Since they had no funds, they had many debts','Từ đó họ không có thu nhập, họ đã mắc nợ quá nhiều','00:00:31.100','00:00:34.900','4000-essential-english-words-42'),
	('The chef behaved this way all the time','Người bếp trưởng lúc nào cũng đối xử với mọi người theo cách này','00:00:34.900','00:00:37.900','4000-essential-english-words-42'),
	('He monitored the cooks and yelled if they did not do things his way','Ông quản lý các đầu bếp và la mắng họ nếu họ không làm theo ý ông','00:00:37.900','00:00:42.000','4000-essential-english-words-42'),
	('One day, the cooks decided that they were tired of the abuse and that they would not be passive anymore','Một ngày, họ quyết định rằng họ mệt mỏi với sự lạm quyền này và họ không còn muốn bị động nữa','00:00:42.000','00:00:49.200','4000-essential-english-words-42'),
	('Everyone opposed the chef','Mọi người đều đứng lên chống lại người bếp trưởng','00:00:49.200','00:00:52.000','4000-essential-english-words-42'),
	('At first, they thought about suing him','Lúc đầu, họ nghĩ sẽ kiện ông ta','00:00:52.000','00:00:55.000','4000-essential-english-words-42'),
	('Instead, they tied up the chef with rope','Nhưng thay vào đó, họ trói ông ta bằng sợi dây thừng','00:00:55.000','00:00:58.400','4000-essential-english-words-42'),
	('Now, they controlled the restaurant','Bây giờ họ đã có thể kiểm soát nhà hàng','00:00:58.400','00:01:01.000','4000-essential-english-words-42'),
	('They decreased the price of food','Họ giảm giá thức ăn','00:01:01.000','00:01:04.000','4000-essential-english-words-42'),
	('They used the best ingredients and made large quantities of food','Họ sử dụng những nguyên liệu tốt nhất và làm ra một số lượng lớn thức ăn','00:01:04.000','00:01:08.000','4000-essential-english-words-42'),
	('They turned on the lights','Họ bật hết đèn lên','00:01:08.000','00:01:10.000','4000-essential-english-words-42'),
	('The restaurant was converted into a happy place','Nhà hàng thay đổi thành một nơi hạnh phúc, ấm áp','00:01:10.000','00:01:13.400','4000-essential-english-words-42'),
	('For the first time, many people came to eat','Vì thế, lần đầu tiên có rất nhiều người đến đây ăn uống','00:01:13.400','00:01:17.000','4000-essential-english-words-42'),
	('The chef realized that the restaurant\'s problems were his fault','Người bếp trưởng đã nhận ra vấn đề của nhà hàng là do lỗi của mình','00:01:17.000','00:01:21.000','4000-essential-english-words-42'),
	('The chef learned an important lesson','Ông đã học được một bài học quan trọng','00:01:21.000','00:01:24.000','4000-essential-english-words-42'),
	('The new, generous chef insisted on giving the customers a free meal','Người bếp trưởng mới kiên quyết cho khách một bữa ăn miễn phí','00:01:24.000','00:01:29.500','4000-essential-english-words-42'),

	/* (UUID(),'4000-essential-english-words-43','The Cat and the Fox','Mèo và Cáo','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_043.mp3',NULL,'00:00:00.000','00:01:37.000','4000-essential-english-words','NO',43) */
	('One day, a cat hiked on a mountain','Một ngày nọ, một con mèo leo lên một ngọn núi','00:00:03.800','00:00:06.700','4000-essential-english-words-43'),
	('When he reached the peak, he met a fox','Khi nó tới đỉnh núi, nó đã gặp một con cáo','00:00:06.700','00:00:09.800','4000-essential-english-words-43'),
	('They began talking about how they get away from their enemies','Chúng bắt đầu nói cho nhau nghe về cách để tránh được kẻ thù của mình','00:00:09.800','00:00:13.800','4000-essential-english-words-43'),
	('"I am very smart"','"Tôi rất thông minh"','00:00:13.800','00:00:16.000','4000-essential-english-words-43'),
	('"I have billions of ideas"','"Tôi có vô vàn ý tưởng"','00:00:16.000','00:00:18.800','4000-essential-english-words-43'),
	('"I can carve a tiny hole in a tree, and then climb in," the fox said','" Tôi có thể khoét được một lỗ rất nhỏ trên thân cây và chui vào trong đó," cáo nói','00:00:18.800','00:00:25.000','4000-essential-english-words-43'),
	('He added, "I have a lot of friends"','Cáo nói thêm, "Tôi có rất nhiều bạn bè"','00:00:25.000','00:00:28.300','4000-essential-english-words-43'),
	('"If I am in trouble, I can call them to lend their help"','"Nếu tôi gặp rắc rối, tôi có thể nhờ sự trợ giúp từ họ"','00:00:28.300','00:00:32.400','4000-essential-english-words-43'),
	('"I can escape an entire army if I have to"','"Tôi có thể thoát khỏi kẻ thù nếu gặp phải chúng"','00:00:32.400','00:00:36.000','4000-essential-english-words-43'),
	('Then, the fox asked, "What are your potential plans?"','Sau đó, Cáo hỏi, "Kế hoạch tiềm năng của cậu là gì?"','00:00:36.000','00:00:40.500','4000-essential-english-words-43'),
	('The cat said, "I have only one plan"','Mèo trả lời, "Tôi chỉ có một kế hoạch"','00:00:40.500','00:00:44.200','4000-essential-english-words-43'),
	('The fox said, "I hope you have good fortune, then"','Cáo nói, "Tôi hi vọng bạn gặp may mắn"','00:00:44.200','00:00:48.700','4000-essential-english-words-43'),
	('"Do you want me to be your tutor?"','"Bạn có muốn tôi làm người hướng dẫn cho bạn không?"','00:00:48.700','00:00:51.000','4000-essential-english-words-43'),
	('"I can teach you many things"','"Tôi có thể dạy bạn mọi thứ"','00:00:51.000','00:00:54.000','4000-essential-english-words-43'),
	('The cat said, "I guarantee that my plan works every time"','Mèo nói, "Tôi đảm bảo rằng kế hoạch của tôi có thể hoạt động bất kỳ lúc nào"','00:00:54.000','00:00:59.000','4000-essential-english-words-43'),
	('"We can quit talking about it"','"Chúng ta có thể dừng cuộc nói chuyện về vấn đề này ở đây rồi"','00:00:59.000','00:01:01.800','4000-essential-english-words-43'),
	('Soon, they saw a group of wolves','Chẳng bao lâu, họ nhìn thấy một đàn sói','00:01:01.800','00:01:04.800','4000-essential-english-words-43'),
	('It was an emergency','Đó là một tình huống khẩn cấp','00:01:04.800','00:01:06.800','4000-essential-english-words-43'),
	('The cat quickly used her plan','Mèo nhanh chóng thực hiện kế hoạch của mình','00:01:06.800','00:01:09.300','4000-essential-english-words-43'),
	('She ran up a tree','Nó trèo lên một cái cây','00:01:09.300','00:01:11.300','4000-essential-english-words-43'),
	('The fox could not decide which plan to use','Cáo thì không thể quyết định nên sử dụng kế hoạch nào','00:01:11.300','00:01:15.000','4000-essential-english-words-43'),
	('"What should my initial move be?"','"Kế hoạch ban đầu của mình nên là gì nhỉ?"','00:01:15.000','00:01:17.300','4000-essential-english-words-43'),
	('"Should I consult my friends?"','"Mình có nên tham khảo ý kiến của các bạn không?"','00:01:17.300','00:01:19.500','4000-essential-english-words-43'),
	('The fox felt intense anxiety','Cáo cảm thấy vô cùng lo lắng','00:01:19.500','00:01:22.700','4000-essential-english-words-43'),
	('All he could do was spin in a circle','Mọi điều nó có thể làm là xoay thành một vòng tròn','00:01:22.700','00:01:25.600','4000-essential-english-words-43'),
	('The wolves caught the fox','Những con sói đã bắt được cáo','00:01:25.600','00:01:28.100','4000-essential-english-words-43'),
	('The cat was full of pride','Mèo thì đầy tự hào','00:01:28.100','00:01:30.400','4000-essential-english-words-43'),
	('This is proof that having a good plan is better than having many bad plans','Đây là bằng chứng cho thấy có một kế hoạch hay thì tốt hơn là có nhiều kế hoạch không ra gì','00:01:30.400','00:01:37.000','4000-essential-english-words-43'),

	/* (UUID(),'4000-essential-english-words-44','The Good Student','Học sinh giỏi','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_044.mp3',NULL,'00:00:00.000','00:01:38.000','4000-essential-english-words','NO',44) */
	('Sue left her dormitory early that morning','Sue rời kí túc xá từ sáng sớm','00:00:03.000','00:00:06.000','4000-essential-english-words-44'),
	('She had even washed her uniform the night before','Cô thậm chí đã giặt đồng phục của mình từ đêm hôm trước','00:00:06.000','00:00:09.800','4000-essential-english-words-44'),
	('She wanted to look nice for the day','Cô muốn trông mình thật xinh đẹp trong ngày hôm nay','00:00:09.800','00:00:12.100','4000-essential-english-words-44'),
	('Sue was committed to learning, and she had a talent for getting good grades','Sue đã cam kết là sẽ học tập, và cô đã có một tài năng trong việc giành được điểm cao','00:00:12.100','00:00:18.000','4000-essential-english-words-44'),
	('In fact, Sue didn\'t sleep much','Thực tế, Sue đã không được ngủ nhiều','00:00:18.000','00:00:21.000','4000-essential-english-words-44'),
	('She composed a paper and found the perfect thesis about the importance of greenhouses','Cô đã soạn bài ra một tờ giấy và tìm ra luận điểm hoàn hảo về tầm quan trọng của nhà kính','00:00:21.000','00:00:26.800','4000-essential-english-words-44'),
	('She also studied for her physics test','Cô cũng ôn tập cho bài kiểm tra môn vật lý','00:00:26.800','00:00:29.700','4000-essential-english-words-44'),
	('Sue was already tired','Sue thực sự đã rất mệt','00:00:29.700','00:00:32.000','4000-essential-english-words-44'),
	('During the test, she calculated her answers','Trong quá trình kiểm tra, cô đã tính toán các câu trả lời của mình','00:00:32.000','00:00:35.800','4000-essential-english-words-44'),
	('Soon, she felt sick','Tuy nhiên, cô bị ốm','00:00:35.800','00:00:38.600','4000-essential-english-words-44'),
	('Her face got hot, and her vision began to blur','Mặt cô trở nên nóng bừng và tầm nhìn thì bắt đầu mờ dần','00:00:38.600','00:00:43.000','4000-essential-english-words-44'),
	('She was blind for a moment','Cô bắt đầu không nhìn thấy gì trong giây lát','00:00:43.000','00:00:45.200','4000-essential-english-words-44'),
	('The teacher saw Sue\'s apparent sickness','Thầy giáo đã nhìn thấy được bệnh tình rõ rệt của Sue','00:00:45.200','00:00:48.200','4000-essential-english-words-44'),
	('He wanted to send her to the nurse','Ông muốn đưa cô đến gặp y tá','00:00:48.200','00:00:51.000','4000-essential-english-words-44'),
	('But she wouldn\'t go','Thế nhưng Sue lại không muốn đi','00:00:51.000','00:00:52.800','4000-essential-english-words-44'),
	('Sue still had a portion of the test to finish','Sue vẫn còn một phần của bài kiểm tra phải hoàn thành','00:00:52.800','00:00:56.000','4000-essential-english-words-44'),
	('After that, Sue went to the nurse','Sau đó, Sue đã đi gặp y tá','00:00:56.000','00:00:59.000','4000-essential-english-words-44'),
	('After seeing the secretary, she waited','Sau khi nhìn thấy người trợ lý, cô đã ngồi đợi','00:00:59.000','00:01:02.100','4000-essential-english-words-44'),
	('A few minutes later, the nurse came in with a glass of juice and told Sue they needed to chat','Một vài phút sau đó, y tá mang đến một cốc nước hoa quả trong tay và bảo Sue rằng họ cần nói chuyện một chút','00:01:02.100','00:01:08.800','4000-essential-english-words-44'),
	('"It is obvious that you have exhausted yourself," the nurse said','"Rõ ràng là bản thân cháu đã bị kiệt sức", y tá nói','00:01:08.800','00:01:13.800','4000-essential-english-words-44'),
	('"If you keep working so hard, it could have severe results"','"Nếu cháu cứ tiếp tục học tập quá độ thế này, sẽ gây ra hậu quả nghiêm trọng"','00:01:13.800','00:01:18.100','4000-essential-english-words-44'),
	('"My parents tell me that all the time"','"Cha mẹ cháu luôn nói với cháu như vậy"','00:01:18.100','00:01:21.000','4000-essential-english-words-44'),
	('"I guess I shouldn\'t ignore them," Sue said','"Có lẽ là cháu không nên phớt lờ đi lời khuyên của họ", Sue nói','00:01:21.000','00:01:24.000','4000-essential-english-words-44'),
	('"You have to remind yourself it is OK to rest," the nurse said','"Cháu cần phải luôn nhắc nhở bản thân rằng nghỉ ngơi là điều tốt," y tá nói','00:01:24.000','00:01:29.600','4000-essential-english-words-44'),
	('When Sue got back to her room, she went right to bed','Khi Sue trở về phòng mình, cô đã đi ngủ ngay','00:01:29.600','00:01:33.600','4000-essential-english-words-44'),
	('She made sure she got enough rest every night after that','Cô chắc chắn mình sau này sẽ phải luôn nghỉ ngơi đầy đủ vào mọi buổi tối','00:01:33.600','00:01:38.000','4000-essential-english-words-44'),

	/* (UUID(),'4000-essential-english-words-45','The Lucky Knife','Con dao may mắn','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_045.mp3',NULL,'00:00:00.000','00:01:33.000','4000-essential-english-words','NO',45) */
	('I\'ve devoted my life to studying past generations','Tôi đã dành cả cuộc đời tôi để nghiên cứu về các thế hệ trước đây','00:00:03.000','00:00:07.200','4000-essential-english-words-45'),
	('Last year, I had a unique chance to work with my uncle','Năm ngoái, tôi có một cơ hội đặc biệt làm việc cùng với chú tôi','00:00:07.200','00:00:11.500','4000-essential-english-words-45'),
	('Our job was to find old treasures for a school\'s history foundation','Công việc của chúng tôi là tìm kiếm các kho báu cho một tổ chức nghiên cứu về lịch sử tại một trường học','00:00:11.500','00:00:16.700','4000-essential-english-words-45'),
	('He also hired a crew of students','Ông cũng thuê một nhóm sinh viên làm việc cùng nữa','00:00:16.700','00:00:19.700','4000-essential-english-words-45'),
	('They signed a contract to work with him','Họ ký hợp đồng làm việc với ông','00:00:19.700','00:00:22.100','4000-essential-english-words-45'),
	('He was the boss','Chú tôi là hiệu trưởng','00:00:22.100','00:00:24.000','4000-essential-english-words-45'),
	('The place was strange, though','Nơi này cũng thật là lạ','00:00:24.000','00:00:26.000','4000-essential-english-words-45'),
	('I dined on many things that I had never tasted before','Tôi đã ăn rất nhiều thứ mà tôi chưa bao giờ thử trước đây','00:00:26.000','00:00:30.200','4000-essential-english-words-45'),
	('They had an unusual flavor','Chúng có hương vị thật kỳ lạ','00:00:30.200','00:00:32.800','4000-essential-english-words-45'),
	('We had been there about a month and hadn\'t found anything','Chúng tôi đã ở đó trong khoảng một tháng và rốt cục chả tìm thấy gì cả','00:00:32.800','00:00:36.800','4000-essential-english-words-45'),
	('One day, I began to dig in the soil','Một ngày, tôi bắt đầu đào đất','00:00:36.800','00:00:40.700','4000-essential-english-words-45'),
	('The ground\'s layers got wetter','Những lớp đất nền trở nên ẩm ướt hơn','00:00:40.700','00:00:43.000','4000-essential-english-words-45'),
	('Soon I was digging in the mud','Một lúc sau tôi đào thấy bùn','00:00:43.000','00:00:45.300','4000-essential-english-words-45'),
	('My shovel began to get very heavy','Xẻng của tôi đã bắt đầu nặng hơn','00:00:45.300','00:00:48.500','4000-essential-english-words-45'),
	('It felt like it had doubled in weight because the ground had absorbed a lot of water','Tôi có cảm giác như trọng lượng của nó đã tăng lên gấp đôi bởi mặt đất đã hấp thụ rất nhiều nước','00:00:48.500','00:00:54.000','4000-essential-english-words-45'),
	('Finally, I saw something in the mud','Cuối cùng, tôi tìm thấy thứ gì đó trong đống bùn','00:00:54.000','00:00:56.800','4000-essential-english-words-45'),
	('It was an old knife','Nó là một con dao cũ','00:00:56.800','00:00:59.000','4000-essential-english-words-45'),
	('The handle felt smooth in my hand','Cán dao nhẵn mịn ở trong tay','00:00:59.000','00:01:02.000','4000-essential-english-words-45'),
	('I elevated it so I could see it better','Tôi đã giơ nó lên để có thể quan sát kỹ hơn','00:01:02.000','00:01:05.000','4000-essential-english-words-45'),
	('There was writing on it','Có dòng chữ gì đó viết trên dao','00:01:05.000','00:01:06.800','4000-essential-english-words-45'),
	('"It says it will bring good luck," my uncle said with a smile','"Nó sẽ mang lại may mắn cho chủ nhân," chú tôi cười và nói với tôi','00:01:06.800','00:01:11.000','4000-essential-english-words-45'),
	('"Why don\'t you keep it?"','"Sao con không giữ nó luôn nhỉ?"','00:01:11.000','00:01:12.800','4000-essential-english-words-45'),
	('I put it in my tent','"Tôi bỏ con dao lại vào trong lều"','00:01:12.800','00:01:14.800','4000-essential-english-words-45'),
	('The next day, we found many more things','Hôm sau, chúng tôi lại tiếp tục tìm thấy nhiều thứ hơn','00:01:14.800','00:01:18.500','4000-essential-english-words-45'),
	('There were pots, jewelry and weapons','Trong số đồ vật đó có nồi niêu, trang sức và vũ khí','00:01:18.500','00:01:22.000','4000-essential-english-words-45'),
	('My uncle donated all of the things to a special committee','Chú tôi đã quyên góp tất cả mọi thứ cho một ủy ban đặc biệt','00:01:22.000','00:01:26.000','4000-essential-english-words-45'),
	('Many newspapers wrote stories about it','Rất nhiều tờ báo đã viết những câu chuyện về thành tích của chúng tôi','00:01:26.000','00:01:29.000','4000-essential-english-words-45'),
	('It seemed the knife really did bring good luck','Dường như con dao đó thực sự đã mang lại may mắn cho chúng tôi','00:01:29.000','00:01:33.000','4000-essential-english-words-45');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-46','Prince Sam','Hoàng tử Sam','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_046.mp3',NULL,'00:00:00.000','00:01:50.200','4000-essential-english-words','NO',46) */
	('Sam\'s mother cooked at the royal palace','Mẹ của Sam nấu ăn trong một cung điện hoàng gia','00:00:03.000','00:00:06.000','4000-essential-english-words-46'),
	('One day, he went to work with her','Một ngày nọ, cậu bé đi làm cùng mẹ','00:00:06.000','00:00:08.800','4000-essential-english-words-46'),
	('She emphasized that he should stay in the kitchen','Bà đã nhấn mạnh rằng cậu chỉ nên ở yên trong bếp','00:00:08.800','00:00:12.000','4000-essential-english-words-46'),
	('But Sam was bored','Nhưng Sam cảm thấy chán ngắt','00:00:12.000','00:00:14.000','4000-essential-english-words-46'),
	('Thus, he decided to look around','Thế là, cậu quyết định nhìn ngó xung quanh','00:00:14.000','00:00:17.000','4000-essential-english-words-46'),
	('He went around a corner','Cậu bé đi vòng quanh góc tường','00:00:17.000','00:00:19.200','4000-essential-english-words-46'),
	('It shocked him to see a boy who had a strong likeness to him','Cậu đã bị sốc khi nhìn thấy một cậu bé khác có bề ngoài giống mình như tạc','00:00:19.200','00:00:23.200','4000-essential-english-words-46'),
	('Sam soon recovered','Sam nhanh chóng bình tĩnh lại','00:00:23.200','00:00:25.000','4000-essential-english-words-46'),
	('The other boy stared at him','Cậu bé kia nhìn chằm chằm vào Sam','00:00:25.000','00:00:27.400','4000-essential-english-words-46'),
	('Then he spoke "Come with me"','Sau đó cậu cất lời "Đi theo mình"','00:00:27.400','00:00:31.000','4000-essential-english-words-46'),
	('He needed to be rational','Sam cần phải lý trí','00:00:31.000','00:00:32.800','4000-essential-english-words-46'),
	('But he couldn\'t deny that he wanted to go','Nhưng cậu không thể phủ nhận rằng mình cũng muốn đi cùng','00:00:32.800','00:00:35.800','4000-essential-english-words-46'),
	('So he followed the boy to a chamber','Vậy là cậu bé đi theo người bạn mới tiến đến một phòng ngủ','00:00:35.800','00:00:38.600','4000-essential-english-words-46'),
	('"I am Prince Bertram," the boy said','"Mình là hoàng tử Bertram," cậu bạn nói','00:00:38.600','00:00:42.000','4000-essential-english-words-46'),
	('Sam felt shy talking to a prince','Sam cảm thấy xấu hổ khi nói chuyện cùng hoàng tử','00:00:42.000','00:00:45.300','4000-essential-english-words-46'),
	('"I\'m Sam"','"Mình là Sam"','00:00:45.300','00:00:47.300','4000-essential-english-words-46'),
	('"Trade places with me" The prince said','"Hãy trao đổi thân phận với mình đi," Hoàng tử nói','00:00:47.300','00:00:51.000','4000-essential-english-words-46'),
	('"We can\'t"','"Không được"','00:00:51.000','00:00:52.100','4000-essential-english-words-46'),
	('"My mother will kill me"','"Mẹ mình sẽ giết mình mất"','00:00:52.100','00:00:53.900','4000-essential-english-words-46'),
	('"Moreover, I don\'t know anything about being a prince"','"Hơn nữa, mình chẳng biết bất cứ điều gì khi trở thành hoàng tử"','00:00:53.900','00:00:58.000','4000-essential-english-words-46'),
	('"No one will find out," the prince interrupted','"Sẽ không có ai phát hiện ra đâu," Hoàng tử ngắt lời','00:00:58.000','00:01:02.000','4000-essential-english-words-46'),
	('"We look the same, and even our gestures are the same"','"Chúng ta nhìn giống nhau như một, và thậm chí cả những cử chỉ của chúng ta cũng tương đồn"','00:01:02.000','00:01:06.000','4000-essential-english-words-46'),
	('"It will only last for a week"','"Mọi việc sẽ chỉ kéo dài trong một tuần thôi"','00:01:06.000','00:01:09.000','4000-essential-english-words-46'),
	('Sam said OK','Sam đồng ý','00:01:09.000','00:01:11.000','4000-essential-english-words-46'),
	('Soon, Sam\'s perspective on being a prince changed','Ngay tức khắc, ý nghĩ của Sam về việc trở thành hoàng tử đã thay đổi','00:01:11.000','00:01:15.200','4000-essential-english-words-46'),
	('He spent most of his day signing royal documents','Cậu dành phần lớn thời gian trong ngày để ký những tài liệu hoàng gia','00:01:15.200','00:01:19.000','4000-essential-english-words-46'),
	('At night, the prince\'s chamber was cold','Khi đêm xuống, phòng ngủ của hoàng tử trở nên lạnh lẽo','00:01:19.000','00:01:22.000','4000-essential-english-words-46'),
	('He thought he was going to freeze or get sick with a fever or the flu','Cậu nghĩ cậu sắp bị đóng băng hoặc ốm sốt hoặc là cảm cúm','00:01:22.000','00:01:26.700','4000-essential-english-words-46'),
	('He was happy when the week ended','Khi một tuần trôi qua cậu thấy hạnh phúc vô ngần','00:01:26.700','00:01:28.800','4000-essential-english-words-46'),
	('So was the prince','Và hoàng tử cũng vậy','00:01:28.800','00:01:31.000','4000-essential-english-words-46'),
	('"I didn\'t know how to do anything," the prince said','"Mình chẳng biết làm gì cả," Hoàng tử nói','00:01:31.000','00:01:34.400','4000-essential-english-words-46'),
	('"I\'ve always relied on my servants to do everything for me"','"Mình luôn luôn phải dựa vào những người phò tá để họ làm hết mọi việc cho mình"','00:01:34.400','00:01:38.100','4000-essential-english-words-46'),
	('"I think I like being a regular person," Sam said','"Mình nghĩ mình thích hợp làm người bình thường," Sam nói','00:01:38.100','00:01:42.100','4000-essential-english-words-46'),
	('"Being a prince isn\'t fun"','"Làm hoàng tử không vui một chút nào"','00:01:42.100','00:01:44.500','4000-essential-english-words-46'),
	('So, they both returned to their normal positions and enjoyed their lives more than before','Thế là họ đều quay trở về thân phận ban đầu của mình và yêu thích cuộc sống này hơn bao giờ hết','00:01:44.500','00:01:50.200','4000-essential-english-words-46'),

	/* (UUID(),'4000-essential-english-words-47','Henry Ford\'s Famous Car','Chiếc xe hơi nổi tiếng của Henry Ford','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_047.mp3',NULL,'00:00:00.000','00:01:31.800','4000-essential-english-words','NO',47) */
	('My name is Henry Ford, and I invented a car called the Model T','Tên tôi là Henry Ford, và tôi đã chế tạo ra một chiếc xe hơi có tên gọi là mô hình T','00:00:03.800','00:00:08.300','4000-essential-english-words-47'),
	('I used to watch carriages on the streets','Tôi từng quan sát những chiếc xe ngựa trên đường phố','00:00:08.300','00:00:11.300','4000-essential-english-words-47'),
	('They fascinated me','Chúng đã mê hoặc tôi','00:00:11.300','00:00:12.900','4000-essential-english-words-47'),
	('Then I got a job as a junior mechanic','Rồi tôi kiếm được việc làm với tư cách là một thợ cơ khí tập sự','00:00:12.900','00:00:15.900','4000-essential-english-words-47'),
	('My father criticized me','Cha tôi chỉ trích tôi','00:00:15.900','00:00:17.900','4000-essential-english-words-47'),
	('He wanted me to run the farm','Ông muốn tôi điều hành hoạt động của trang trại','00:00:17.900','00:00:19.900','4000-essential-english-words-47'),
	('But I did not shift my plans','Nhưng tôi đã không thay đổi kế hoạch của mình','00:00:19.900','00:00:22.100','4000-essential-english-words-47'),
	('Then I worked for the Detroit Auto Company','Sau đó tôi đã làm việc cho công ty ô tô Detroit','00:00:22.100','00:00:25.200','4000-essential-english-words-47'),
	('But I wanted to make cars using less labor','Nhưng tôi muốn chế tạo ra những chiếc xe hơi sử dụng ít nhân công hơn','00:00:25.100','00:00:28.800','4000-essential-english-words-47'),
	('That way, there would be fewer expenses','Bằng cách đó sẽ tiêu tốn ít chi phí hơn','00:00:28.800','00:00:31.800','4000-essential-english-words-47'),
	('I started the Ford Motor Company in 1903','Tôi bắt đầu gây dựng công ty Ford Motor vào năm 1903','00:00:31.800','00:00:35.100','4000-essential-english-words-47'),
	('At first, the company did not do well','Những ngày đầu tiên, công ty hoạt động không hiệu quả','00:00:35.100','00:00:38.500','4000-essential-english-words-47'),
	('But many people were betting on my success','Nhưng có rất nhiều người đã đánh cược vào thành công của tôi','00:00:38.500','00:00:41.800','4000-essential-english-words-47'),
	('I also had a sincere aim to make a car that anybody could buy','Tôi cũng có một mục đích chân thành đó là tạo ra một chiếc ô tô mà bất kì ai đều có thể mua','00:00:41.800','00:00:46.400','4000-essential-english-words-47'),
	('Then, in 1908,1 introduced the Model-T in a formal ceremony','Sau đó, vào năm 1908, tôi đã giới thiệu chiếc Mô hình-T trong một buổi lễ','00:00:46.400','00:00:51.500','4000-essential-english-words-47'),
	('It confirmed that I was right: it was possible to build a car my way','Việc làm này chứng thực rằng tôi đã đúng đắn: Hoàn toàn có thể tạo lên một chiếc xe theo cách của riêng mình','00:00:51.500','00:00:57.000','4000-essential-english-words-47'),
	('The Model T differed from other vehicles','Chiếc mô hình T khác biệt so với những loại phương tiện khác','00:00:57.000','00:01:00.000','4000-essential-english-words-47'),
	('Workers could attach different parts for cars or trucks','Người lao động có thể gắn những bộ phận khác nhau cho xe hơi hoặc xe tải','00:01:00.000','00:01:04.000','4000-essential-english-words-47'),
	('This saved time','Điều này tiết kiệm thời gian','00:01:04.000','00:01:06.000','4000-essential-english-words-47'),
	('One Model T could be put together in 93 minutes','Một chiếc mô hình T có thể đươc lắp ráp các bộ phận khác nhau trong vòng 93 phút','00:01:06.000','00:01:10.000','4000-essential-english-words-47'),
	('All of them had the same classic design','Tất cả các bộ phận đó đều có chung thiết kế cổ điển','00:01:10.000','00:01:13.000','4000-essential-english-words-47'),
	('They were all the same size and height','Chúng cũng có cùng kích cỡ và chiều cao','00:01:13.000','00:01:15.600','4000-essential-english-words-47'),
	('The prime reason for doing this was to save money','Nguyên nhân căn bản để làm điều này là tiết kiệm tiền','00:01:15.600','00:01:19.000','4000-essential-english-words-47'),
	('Over 19 years, I sold over 15 million Model Ts','Hơn 19 năm qua, tôi đã bán trên 15 triệu chiếc mô hình T','00:01:19.000','00:01:24.000','4000-essential-english-words-47'),
	('This sent a signal to other companies','Con số này đã gửi một tín hiệu đến các công ty khác','00:01:24.000','00:01:27.000','4000-essential-english-words-47'),
	('People would buy cars to commute to work if the price was low enough','Người dân sẽ mua xe để đi làm đều đặn mỗi ngày nếu giá cả thấp và vừa đủ','00:01:27.000','00:01:31.800','4000-essential-english-words-47'),

	/* (UUID(),'4000-essential-english-words-48','The Priest','Vị linh mục','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_048.mp3',NULL,'00:00:00.000','00:01:25.200','4000-essential-english-words','NO',48) */
	('A young priest was always sad','Một vị linh mục trẻ luôn thấy buồn','00:00:03.000','00:00:06.000','4000-essential-english-words-48'),
	('He was good at his profession, but he still had no joy','Ông giỏi về chuyên môn của mình, nhưng ông vẫn không chút vui vẻ gì','00:00:06.000','00:00:10.200','4000-essential-english-words-48'),
	('He visited a group of wise monks','Ông đã tới thăm một nhóm các thầy tu thông thái','00:00:10.200','00:00:13.000','4000-essential-english-words-48'),
	('When he got to the monks\' house, they greeted him and let him in','Khi ông tới ngôi nhà của các thầy tu, họ chào đón ông và để ông ở đó','00:00:13.000','00:00:17.000','4000-essential-english-words-48'),
	('The monks asked the priest, "What is the matter?"','Các thầy tu đã hỏi vị linh mục "Có vấn đề gì vậy?"','00:00:17.000','00:00:20.800','4000-essential-english-words-48'),
	('The priest said, "I should be happy, but I am not"','Vị linh mục nói "Tôi nên vui vẻ, nhưng tôi không hề gì"','00:00:20.800','00:00:25.400','4000-essential-english-words-48'),
	('"I don\'t know what to do"','"Tôi không biết phải làm gì"','00:00:25.400','00:00:27.500','4000-essential-english-words-48'),
	('The wise monks paused for a minute','Các thầy tu thông thái đã dừng lại một phút','00:00:27.500','00:00:30.200','4000-essential-english-words-48'),
	('Then one said, "We are convinced of your faith"','Rồi một người đã nói, "Chúng tôi được thuyết phục về sự nổi tiếng của ông"','00:00:30.200','00:00:34.000','4000-essential-english-words-48'),
	('"You are a very good priest"','"Ông là một vị linh mục rất tốt"','00:00:34.000','00:00:36.000','4000-essential-english-words-48'),
	('"But to find joy, you have to do more"','"Nhưng để tìm được niềm vui, ông phải làm hơn nữa"','00:00:36.000','00:00:39.000','4000-essential-english-words-48'),
	('"Above all, investigate the elements of your life that you love"','"Hơn hết là, hãy đi điều tra các yếu tố của cuộc sống mà ông yêu quý ấy"','00:00:39.000','00:00:43.800','4000-essential-english-words-48'),
	('The priest thought that this answer was odd, but he was curious','Vị linh mục đã nghĩ câu trả lời này thật kỳ quặc, nhưng ông đã tò mò','00:00:43.800','00:00:48.300','4000-essential-english-words-48'),
	('The next day, the priest thought about his abilities','Ngày tiếp theo, vị linh mục đã nghĩ về các khả năng của mình','00:00:48.300','00:00:51.700','4000-essential-english-words-48'),
	('He got a few ideas, and he did not want to delay any longer','Ông đã có một vài ý tưởng, và ông không muốn trì hoãn thêm nữa','00:00:51.700','00:00:55.800','4000-essential-english-words-48'),
	('He liked to draw, so he made some cartoons','Ông thích vẽ, vì vậy ông đã làm một vài hoạt hình','00:00:55.800','00:00:59.200','4000-essential-english-words-48'),
	('He also liked to write, so he started a diary','Ông cũng thích viết, vì vậy ông bắt đầu viết nhật ký','00:00:59.200','00:01:03.000','4000-essential-english-words-48'),
	('He was interested in agriculture, so he planted some grains','Ông có hứng thú với nông nghiệp, nên ông bắt đầu trồng cây','00:01:03.000','00:01:07.800','4000-essential-english-words-48'),
	('He made jam from berries','Ông làm mứt từ dâu','00:01:07.800','00:01:09.900','4000-essential-english-words-48'),
	('He made his own labels to put on the jars of jam','Ông đã tạo nhãn hiệu cho riêng mình để đặt lên các lọ mứt','00:01:09.900','00:01:13.400','4000-essential-english-words-48'),
	('He painted his ceiling','Ông đã vẽ trần nhà','00:01:13.400','00:01:15.200','4000-essential-english-words-48'),
	('The priest learned something','Vị linh mục đã học được điều gì đó','00:01:15.200','00:01:17.400','4000-essential-english-words-48'),
	('It is not too hard to be happy after all','Cũng không quá khó để vui vẻ sau tất cả','00:01:17.400','00:01:20.600','4000-essential-english-words-48'),
	('All one has to do is find things they like doing, and do them','Mọi thứ bạn phải làm là tìm những thứ họ thích làm và làm chúng','00:01:20.600','00:01:25.200','4000-essential-english-words-48'),

	/* (UUID(),'4000-essential-english-words-49','Mrs.May and the Green Girl','Bà May và cô bé màu xanh','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_049.mp3',NULL,'00:00:00.000','00:01:34.200','4000-essential-english-words','NO',49) */
	('One morning, people from a small town found a little girl by a stream','Một buổi sáng nọ, người dân trong một thị trấn tìm thấy một cô gái nhỏ bên cạnh dòng suối','00:00:03.800','00:00:09.000','4000-essential-english-words-49'),
	('She seemed to be wearing a green costume','Cô bé dường như đang mặc một bộ đồ có kiểu dáng rất lạ màu xanh lá cây','00:00:09.00','00:00:12.400','4000-essential-english-words-49'),
	('As the people got closer, they saw that the girl\'s skin was green','Khi mọi người tiến lại gần cô, họ mới biết rằng da của cô cũng có màu xanh lá cây','00:00:12.400','00:00:17.600','4000-essential-english-words-49'),
	('"Oh my," the people exclaimed','"Ôi trời ơi," một ai đó la lên','00:00:17.600','00:00:20.400','4000-essential-english-words-49'),
	('"What if her motive for coming to our town is bad?"','"Chuyện gì sẽ xảy ra với thị trấn của chúng ta nếu cô bé này mang chỉ mang đến toàn điều xấu mà thôi?"','00:00:20.400','00:00:24.000','4000-essential-english-words-49'),
	('"What if she has a strange origin?"','"Nhỡ đâu nó có năng lực gì đó là lạ thì sao?"','00:00:24.000','00:00:27.000','4000-essential-english-words-49'),
	('An old woman kindly went to her','Một người phụ nữ lớn tuổi ân cần đến bên cô bé','00:00:27.000','00:00:29.800','4000-essential-english-words-49'),
	('"Look how scared she is"','"Nó sợ các người lắm đấy"','00:00:29.800','00:00:31.900','4000-essential-english-words-49'),
	('"Please," she begged','"Làm ơn", bà cầu xin','00:00:31.900','00:00:33.900','4000-essential-english-words-49'),
	('"Do not reject her"','"Đừng hắt hủi nó"','00:00:33.900','00:00:35.500','4000-essential-english-words-49'),
	('"I will adopt her"','"Tôi sẽ nuôi nó"','00:00:35.500','00:00:37.000','4000-essential-english-words-49'),
	('There was silence until the judge spoke','Không khí im lặng cho đến khi vị thẩm phán cất tiếng','00:00:37.000','00:00:40.000','4000-essential-english-words-49'),
	('"I don\'t know," he said in a worried tone','"Tôi không biết," ông nói cùng sự lo lắng','00:00:40.000','00:00:43.300','4000-essential-english-words-49'),
	('"But we cannot forbid you"','"Nhưng chúng tôi không thể ngăn cấm được bà làm việc đó"','00:00:43.300','00:00:45.400','4000-essential-english-words-49'),
	('"I indeed hope you\'re not being a fool"','"Tôi thực lòng hy vọng rằng bà không bị mất trí đấy"','00:00:45.400','00:00:48.700','4000-essential-english-words-49'),
	('Mrs.May extended her hand to the girl','Bà May dang rộng vòng tay đón cô né về phía mình','00:00:48.700','00:00:51.800','4000-essential-english-words-49'),
	('"Come with me"','"Đến đây với ta nào"','00:00:51.800','00:00:53.000','4000-essential-english-words-49'),
	('"I won\'t hurt you"','"Ta sẽ không làm hại gì con đâu"','00:00:53.000','00:00:54.400','4000-essential-english-words-49'),
	('The girl spoke a language Mrs.May didn\'t know','Cô bé nói một thứ tiếng gì đó mà bà May không thể hiểu được','00:00:54.400','00:00:57.900','4000-essential-english-words-49'),
	('But she was able to interpret what the girl was trying to say','Nhưng bà vẫn cố gắng tìm cách hiểu được những gì mà cô bé đang cố gắng nhắc đến','00:00:57.900','00:01:02.000','4000-essential-english-words-49'),
	('Sometimes the girl drew pictures to illustrate what she meant','Đôi khi, cô bé vẽ những bức tranh để thể hiện cho ý định của cô','00:01:02.000','00:01:06.800','4000-essential-english-words-49'),
	('The green girl was from a place far beyond the sun','Cô bé da xanh đến từ một một nơi bên ngoài hệ mặt trời','00:01:06.800','00:01:10.700','4000-essential-english-words-49'),
	('There, people lived in nests built in trees','Tại đó, mọi người sống trong những chiếc tổ được xây dựng trên cây','00:01:10.700','00:01:14.600','4000-essential-english-words-49'),
	('They only ate green leaves, which made their skin green','Những người dân vùng này chỉ ăn lá cây,và điều này sẽ khiến da họ có màu xanh nhiều hơn','00:01:14.600','00:01:18.800','4000-essential-english-words-49'),
	('"Well, you can\'t just eat leaves," Mrs.May said','"Chà, cháu không cần ăn lá cây nữa nhé," Bà May nói','00:01:18.800','00:01:23.100','4000-essential-english-words-49'),
	('She fed the green girl home-cooked meals, and soon the girl wasn\'t green anymore','Bà ấy nấu những món ăn mà bà thường nấu trong những bữa ăn hàng ngày, và cô gái không còn màu xanh nữa','00:01:23.100','00:01:29.100','4000-essential-english-words-49'),
	('The people had a huge reception to welcome her as a citizen of the town','Người dân đã có một sự đón nhận to lớn để chào mừng cô bé như một công dân của thị trấn','00:01:29.100','00:01:34.200','4000-essential-english-words-49'),

	/* (UUID(),'4000-essential-english-words-50','Albert Einstein','Albert Einstein','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_050.mp3',NULL,'00:00:00.000','00:01:36.500','4000-essential-english-words','NO',50) */
	('My name is Albert Einstein','Tên tôi là Albert Einstein','00:00:03.000','00:00:05.800','4000-essential-english-words-50'),
	('Many people know about the great things I\'ve accomplished','Nhiều người biết về những thứ vĩ đại mà tôi đã đạt được','00:00:05.800','00:00:09.800','4000-essential-english-words-50'),
	('But I had many barriers before I became famous','Nhưng không biết tôi đã phải đối mặt với nhiều khó khăn trước khi trở nên nổi tiếng','00:00:09.800','00:00:13.300','4000-essential-english-words-50'),
	('I was born in Germany','Tôi được sinh ra ở Đức','00:00:13.300','00:00:15.300','4000-essential-english-words-50'),
	('When I was in elementary school, I already knew about math and statistics','Khi tôi đang học tiểu học, tôi đã bắt đầu hiểu biết về Toán và số liệu','00:00:15.300','00:00:20.800','4000-essential-english-words-50'),
	('When I was a boy, I pretended to be a great scientist','Khi tôi còn là một cậu nhóc, tôi giả vờ là một nhà khoa học vĩ đại','00:00:20.800','00:00:25.000','4000-essential-english-words-50'),
	('I loved school, but my life at home was hard','Tôi yêu trường, nhưng đời sống ở nhà thì lại khó khăn','00:00:25.000','00:00:28.800','4000-essential-english-words-50'),
	('My father lost his job, so my family lived in poverty','Cha tôi mất việc, nên gia đình tôi đã phải sống trong nghèo đói','00:00:28.800','00:00:33.200','4000-essential-english-words-50'),
	('We could not pay the rent in Germany','Chúng tôi không thể chi trả tiền thuê nhà ở Đức','00:00:33.200','00:00:36.000','4000-essential-english-words-50'),
	('We became immigrants and went to Italy','Sau đó, chúng tôi trở thành dân nhập cư và chuyển đến Ý','00:00:36.000','00:00:39.200','4000-essential-english-words-50'),
	('I finished high school and went to college in Switzerland','Tôi hoàn thành cấp 3 và bước vào đại học ở Thụy Sĩ','00:00:39.200','00:00:43.000','4000-essential-english-words-50'),
	('After college, I began writing about science','Sau đại học, tôi bắt đầu viết về khoa học','00:00:43.000','00:00:47.200','4000-essential-english-words-50'),
	('I did not reach success in an instant, though','Mặc dù thế, tôi đã không đạt được thành công ngay lập tức','00:00:47.200','00:00:50.200','4000-essential-english-words-50'),
	('At first, other scientists did not approve of my work','Lúc đầu, các nhà khoa học khác không chấp thuận công trình của tôi','00:00:50.200','00:00:54.800','4000-essential-english-words-50'),
	('They thought I was a failure','Họ nghĩ rằng tôi là một kẻ thất bại','00:00:54.800','00:00:57.000','4000-essential-english-words-50'),
	('Rising to the rank of an admired scientist was a gradual process','Vươn lên đến vị trí của một nhà khoa học được mọi người ngưỡng mộ là một quá trình lâu dài','00:00:57.000','00:01:01.800','4000-essential-english-words-50'),
	('Soon, people started to notice that I was right','Không lâu sau, mọi người bắt đầu nhận ra rằng tôi đã đúng','00:01:01.800','00:01:05.500','4000-essential-english-words-50'),
	('At last, I began to get some recognition','Cuối cùng, tôi đã bắt đầu có được một vài sự công nhận','00:01:05.500','00:01:09.000','4000-essential-english-words-50'),
	('I showed how to find the approximate size of very big things, like stars','Tôi đã chỉ ra cách để tìm ra kích thước xấp xỉ của những thứ rất lớn như các vì sao','00:01:09.000','00:01:14.300','4000-essential-english-words-50'),
	('I also detected and explained the movement of very small things, like atoms','Tôi cũng đã phát hiện và giải thích chuyển động của những thứ rất nhỏ như các nguyên tử','00:01:14.300','00:01:20.100','4000-essential-english-words-50'),
	('And for fun, I made a machine that could refrigerate food by inserting heat','Và để cho vui, tôi đã làm một chiếc máy có thể giữ lạnh thức ăn bằng cách chèn thêm nhiệt','00:01:20.100','00:01:26.100','4000-essential-english-words-50'),
	('I never retired','Tôi chưa bao giờ nghỉ hưu','00:01:26.100','00:01:28.100','4000-essential-english-words-50'),
	('It was my duty to keep working','Nghĩa vụ của tôi là tiếp tục làm việc','00:01:28.100','00:01:30.300','4000-essential-english-words-50'),
	('I overcame many hard times, and I will be remembered for my important works','Tôi đã vượt qua nhiều lần khó khăn, và tôi tin rằng tôi sẽ được nhớ đến vì những công trình khoa học quan trọng của mình','00:01:30.300','00:01:36.500','4000-essential-english-words-50');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-51','From the Earth to the Stars','Từ trái đất đến những vì sao','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_051.mp3',NULL,'00:00:00.000','00:01:41.000','4000-essential-english-words','NO',51) */
	('Jeremy was from a family of miners','Jeremy đến từ một gia đình có truyền thống làm thợ mỏ','00:00:03.800','00:00:06.700','4000-essential-english-words-51'),
	('Like them, he worked underground during the day','Giống như những người thợ mỏ khác, anh làm việc dưới lòng đất suốt ngày','00:00:06.700','00:00:10.200','4000-essential-english-words-51'),
	('His job was to gather raw minerals and jewels','Công việc của anh là thu thập khoáng sản thô và đá quý','00:00:10.200','00:00:13.800','4000-essential-english-words-51'),
	('Each night after work, he lay awake in an open field','Hằng đêm sau khi làm xong công việc, anh ấy nằm thao thức trên một cánh đồng mênh mông','00:00:13.800','00:00:18.100','4000-essential-english-words-51'),
	('With his telescope, he looked at the stars','Anh dùng chiếc kính viễn vọng của mình ngắm nhìn những vì sao','00:00:18.100','00:00:21.300','4000-essential-english-words-51'),
	('He was amazed by the scale of space','Anh bị choáng ngợp bởi sự bao la của vũ trụ','00:00:21.300','00:00:24.500','4000-essential-english-words-51'),
	('He wished someday he might travel there','Anh ước rằng ngày nào đó mình có thể bay vào không gian','00:00:24.500','00:00:28.000','4000-essential-english-words-51'),
	('One day there was an accident in the mine','Một ngày nọ, trong mỏ xảy ra một vụ tai nạn','00:00:28.000','00:00:30.800','4000-essential-english-words-51'),
	('Water poured into the mine','Nước tràn vào trong mỏ','00:00:30.800','00:00:32.800','4000-essential-english-words-51'),
	('Everything was dark','Mọi thứ trở nên tối đen','00:00:32.800','00:00:35.000','4000-essential-english-words-51'),
	('Jeremy stretched out and grabbed a piece of wood','Jeremy cố gắng với tới và tóm lấp một mảnh gỗ','00:00:35.000','00:00:38.400','4000-essential-english-words-51'),
	('It kept him from sinking','Mảnh gỗ đã giúp anh không bị chìm xuống','00:00:38.400','00:00:40.500','4000-essential-english-words-51'),
	('Jeremy felt a presence nearby','Jeremy cảm nhận được có một sự hiện diện nào đó cạnh bên','00:00:40.500','00:00:43.400','4000-essential-english-words-51'),
	('"I am an angel," said a voice','"Tôi là thiên thần đây" một giọng nói vang lên','00:00:43.400','00:00:46.000','4000-essential-english-words-51'),
	('"What?" Jeremy exclaimed','"Cái gì cơ?" Jeremy kêu lên','00:00:46.000','00:00:48.800','4000-essential-english-words-51'),
	('"You must never come underground again"','"Bạn sẽ không bao giờ phải làm việc dưới lòng đất một lần nào nữa"','00:00:48.800','00:00:51.200','4000-essential-english-words-51'),
	('"Have the courage to make your wishes come true"','"Hãy can đảm lên để biến những ước mơ của bạn trở thành hiện thực"','00:00:51.200','00:00:55.000','4000-essential-english-words-51'),
	('For a long time he floated in silence','Suốt một thời gian dài trôi nổi trong sự yên lặng','00:00:55.000','00:00:58.300','4000-essential-english-words-51'),
	('Then he heard other voices','Rồi anh nghe thấy có tiếng nói','00:00:58.300','00:01:01.000','4000-essential-english-words-51'),
	('The other miners were coming to rescue him','Thì ra những người thợ mỏ khác đang trên đường đến giải cứu anh','00:01:01.000','00:01:04.000','4000-essential-english-words-51'),
	('The next day Jeremy skipped work','Ngày tiếp theo, Jeremy nghỉ làm','00:01:04.000','00:01:07.000','4000-essential-english-words-51'),
	('He decided to become an astronaut','Anh quyết định trở thành một phi hành gia','00:01:07.000','00:01:09.300','4000-essential-english-words-51'),
	('For the next two years, he studied hard','Trong hai năm sau đó, anh ấy đã học tập chăm chỉ','00:01:09.300','00:01:12.800','4000-essential-english-words-51'),
	('One day, he was given permission to participate in a mission to space','Một ngày nọ, anh được phép tham gia vào một nhiệm vụ trong vũ trụ','00:01:12.800','00:01:17.800','4000-essential-english-words-51'),
	('His wish had been granted','Điều ước của anh đã thành hiện thực','00:01:17.800','00:01:19.800','4000-essential-english-words-51'),
	('His spaceship left the ground','Tàu không gian của anh ấy rời mặt đất','00:01:19.800','00:01:22.100','4000-essential-english-words-51'),
	('It went higher until there was no more gravity','Nó bay lên cao cho đến khi không còn bất cứ trọng lực nào nữa','00:01:22.100','00:01:25.400','4000-essential-english-words-51'),
	('He saw satellites floating next to the ship','Anh nhìn thấy những vệ tinh trôi nổi bên cạnh con tàu của mình','00:01:25.400','00:01:28.700','4000-essential-english-words-51'),
	('Then Jeremy saw a beautiful angel outside his spaceship','Rồi Jeremy nhìn thấy một thiên thần xinh đẹp bên ngoài tàu không gian của anh ấy','00:01:28.700','00:01:32.800','4000-essential-english-words-51'),
	('It smiled at Jeremy','Và thiên thần đã mỉm cười với Jeremy','00:01:32.800','00:01:35.200','4000-essential-english-words-51'),
	('For some minutes, Jeremy could not speak','Trong vài phút, Jeremy không thể nói nên lời','00:01:35.200','00:01:38.000','4000-essential-english-words-51'),
	('Finally, he said, "Thankyou"','Cuối cùng, anh nói, "Cảm ơn"','00:01:38.000','00:01:41.000','4000-essential-english-words-51'),

	/* (UUID(),'4000-essential-english-words-52','The Farm Festival','Lễ hội nông trại','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_052.mp3',NULL,'00:00:00.000','00:01:35.800','4000-essential-english-words','NO',52) */
	('Once there was a farm','Ngày xưa, ở một nông trại nọ','00:00:03.000','00:00:05.200','4000-essential-english-words-52'),
	('Many animals lived there','Có nhiều con vật cùng nhau sinh sống','00:00:05.200','00:00:07.300','4000-essential-english-words-52'),
	('One day, they had a contest in the yard','Một ngày nọ, trong sân tổ chức một cuộc thi','00:00:07.300','00:00:10.800','4000-essential-english-words-52'),
	('They were going to race from the barn to the farmer\'s garage','Các con vật sẽ chạy từ chuồng nuôi đến nhà để xe của ông chủ','00:00:10.800','00:00:14.100','4000-essential-english-words-52'),
	('The barn and the garage were far apart','Chuồng nuôi và nhà để xe cách xa nhau. Đây sẽ là một cuộc đua đường dài','00:00:14.100','00:00:17.000','4000-essential-english-words-52'),
	('It would be a long race','Đây sẽ là một cuộc đua đường dài','00:00:17.000','00:00:19.700','4000-essential-english-words-52'),
	('The winner qualified to win a bag full of apples as an award','Người chiến thắng sẽ nhận được một phần thưởng đó là một chiếc túi đầy táo','00:00:19.700','00:00:24.300','4000-essential-english-words-52'),
	('But the race did not start well','Nhưng cuộc đua không được thuận lợi','00:00:24.300','00:00:27.300','4000-essential-english-words-52'),
	('The cart with all the apples was not stable, and the animals had to repair it','Cái xe đẩy những quả táo không kiên cố nên những con vật phải sửa lại nó','00:00:27.300','00:00:33.000','4000-essential-english-words-52'),
	('Then the pup knocked over the apples','Rồi cô cún con làm rơi những quả táo ra ngoài','00:00:33.000','00:00:35.800','4000-essential-english-words-52'),
	('The pig yelled, "We are going to slip"','Chú heo hét lên, "Chúng ta sẽ trượt té mất"','00:00:35.800','00:00:38.800','4000-essential-english-words-52'),
	('"We must clean up this mess"','"Ta phải dọn dẹp mớ hỗn độn này"','00:00:38.800','00:00:41.000','4000-essential-english-words-52'),
	('The pup felt bad, and she began to cry','Cô cún cảm thấy có lỗi, và cô bắt đầu khóc','00:00:41.000','00:00:45.000','4000-essential-english-words-52'),
	('The dog gave her a tissue to wipe her tears','Chú chó đưa cô khăn giấy để lau nước mắt','00:00:45.000','00:00:48.300','4000-essential-english-words-52'),
	('Then the race resumed','Sau đó cuộc đua được tiếp tục','00:00:48.300','00:00:50.800','4000-essential-english-words-52'),
	('But the duck tried to rob them and take all the apples','Nhưng con vịt lại cố gắng cướp và lấy hết tất cả quả táo','00:00:50.800','00:00:54.800','4000-essential-english-words-52'),
	('The cat said, "I will have you arrested"','Con mèo nói, "Tôi sẽ bắt bạn"','00:00:54.800','00:00:58.100','4000-essential-english-words-52'),
	('The duck said, "You can\'t convict me"','Con vịt nói, "Bạn không thể kết tội tôi"','00:00:58.100','00:01:01.100','4000-essential-english-words-52'),
	('"You can\'t prove I took it"','"Bạn không thể chứng minh được tôi lấy nó"','00:01:01.100','00:01:03.100','4000-essential-english-words-52'),
	('The race stopped yet again','Cuộc đua dừng lại một lần nữa','00:01:03.100','00:01:05.500','4000-essential-english-words-52'),
	('The animals tried to race one more time','Những con vật cố chạy đua một lần nữa','00:01:05.500','00:01:08.400','4000-essential-english-words-52'),
	('Then they heard an alarm coming from the barn','Rồi chúng nghe được một tiếng báo đến từ chuồng nuôi','00:01:08.400','00:01:11.200','4000-essential-english-words-52'),
	('There was a fire','Có một đám cháy lớn','00:01:11.200','00:01:13.400','4000-essential-english-words-52'),
	('They got buckets of water to put out the fire','Tất cả con vật liền lấy xô nước dập tắt ngọn lửa','00:01:13.400','00:01:17.000','4000-essential-english-words-52'),
	('A journalist came to write a story about the festival and the race','Một nhà báo đến để viết một câu chuyện về lễ hội và cuộc đua','00:01:17.000','00:01:21.300','4000-essential-english-words-52'),
	('The horse told her, "I am a special breed of horse"','Con ngựa nói với cô ấy, "Tôi là một giống ngựa đặc biệt"','00:01:21.300','00:01:25.100','4000-essential-english-words-52'),
	('"I would have won the race easily"','"Tôi có lẽ đã thắng cuộc đua dễ dàng"','00:01:25.100','00:01:27.800','4000-essential-english-words-52'),
	('The pig said, "It was somewhat hard to have the race"','Chú heo nói, "Cuộc đua có chút khó khăn"','00:01:27.800','00:01:31.800','4000-essential-english-words-52'),
	('"But we had fun"','" Nhưng chúng tôi đã rất vui"','00:01:31.800','00:01:33.000','4000-essential-english-words-52'),
	('"That is what\'s important"','"Đó mới là điều quan trọng"','00:01:33.000','00:01:35.800','4000-essential-english-words-52'),

	/* (UUID(),'4000-essential-english-words-53','The Clever Thief','Tên trộm thông minh','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_053.mp3',NULL,'00:00:00.000','00:01:33.200','4000-essential-english-words','NO',53) */
	('A new king inherited a lot of gold','Một vị vua mới lên ngôi và được thừa kế rất nhiều vàng','00:00:03.000','00:00:06.200','4000-essential-english-words-53'),
	('He loved his gold very much','Ông ta rất quý trọng số vàng của mình','00:00:06.200','00:00:08.700','4000-essential-english-words-53'),
	('He even wanted to keep it after he died','Đến nỗi mà ông còn muốn đem theo số vàng đó xuống mồ','00:00:08.700','00:00:11.700','4000-essential-english-words-53'),
	('Therefore, he had a large tomb built for himself and his riches','Do đó, ông đã xây một cái hầm mộ lớn cho riêng mình và những của cải châu báu của mình','00:00:11.700','00:00:16.600','4000-essential-english-words-53'),
	('However, the tomb\'s builder had a plan','Tuy nhiên, người thợ xây hầm mộ đã có một kế hoạch riêng','00:00:16.600','00:00:20.000','4000-essential-english-words-53'),
	('Most of the stones were solid, but he put one special stone on the roof','Hầu hết những tảng đá thì nặng nhưng anh ta đã bí mật thay một tảng đá đặc biệt vào trần của hầm','00:00:20.000','00:00:25.700','4000-essential-english-words-53'),
	('It was made of a lighter substance','Tảng đá đó được làm bằng chất liệu nhẹ hơn','00:00:25.700','00:00:28.700','4000-essential-english-words-53'),
	('When the tomb was done, the king moved in his stock of gold','Khi hầm mộ được hoàn thiện, vị vua đã di chuyển đống vàng đó vào trong này','00:00:28.700','00:00:33.100','4000-essential-english-words-53'),
	('One night, the builder went to the tomb','Một đêm nọ, người thợ xây đến hầm mộ','00:00:33.100','00:00:36.800','4000-essential-english-words-53'),
	('His excitement mounted','Sự hào hứng của anh ta ngày càng tăng','00:00:36.800','00:00:38.900','4000-essential-english-words-53'),
	('Because all the stones looked alike, he had left a distinct mark on the artificial block','Bởi vì tất cả những viên đá dùng để xây mộ đều có hình dáng giống nhau nên anh ta đã để lại một cái dấu trên tảng đá nhân tạo của mình','00:00:38.900','00:00:45.000','4000-essential-english-words-53'),
	('The mark helped him distinguish the difference in the architecture','Cái dấu này giúp anh ta phân biệt được sự khác biệt trong kiến trúc','00:00:45.000','00:00:49.000','4000-essential-english-words-53'),
	('The builder lifted the stone','Người thợ xây nhấc tảng đá lên','00:00:49.000','00:00:51.800','4000-essential-english-words-53'),
	('Using a chain, he climbed into the tomb','Rồi anh dùng dây xích để trèo vào bên trong hầm mộ','00:00:51.800','00:00:55.200','4000-essential-english-words-53'),
	('He filled his pockets with gold','Ông đã nhét đấy vàng vào trong túi áo và túi quần của mình','00:00:55.200','00:00:57.900','4000-essential-english-words-53'),
	('The builder followed this manner night after night','Người thợ xây cứ thế làm theo cách như trên đêm này qua đêm khác','00:00:57.900','00:01:01.700','4000-essential-english-words-53'),
	('Soon, the king noticed a shortage in his gold','Chẳng mấy chốc mà vị vua đã để ý và thấy rằng số lượng vàng mà mình giữ đang hụt dần','00:01:01.700','00:01:05.600','4000-essential-english-words-53'),
	('This annoyed the king','Điều này đã khiến ông nổi giận','00:01:05.600','00:01:07.800','4000-essential-english-words-53'),
	('At last he hired a guard to hide inside the tomb','Cuối cùng, ông quyết định sử dụng lính canh rình bằng cách ẩn nấp trong hầm mộ','00:01:07.800','00:01:11.800','4000-essential-english-words-53'),
	('When the builder entered the tomb, the guard wounded him','Khi anh chàng thợ xây kia bước vào, lính gác đã tấn công và làm anh ta bị thương','00:01:11.800','00:01:15.800','4000-essential-english-words-53'),
	('He climbed a pole to the roof','Anh trèo lên đỉnh của hầm mộ','00:01:15.800','00:01:18.200','4000-essential-english-words-53'),
	('The builder left drops of blood in the dust','Anh ta thoát ra ngoài nhưng lại để lại những giọt máu rải dọc đường trong những đống cát','00:01:18.200','00:01:21.700','4000-essential-english-words-53'),
	('The guard followed them and caught him','Tên lính canh kia đuổi theo dấu máu và bắt được anh ta','00:01:21.700','00:01:24.200','4000-essential-english-words-53'),
	('When the builder healed, he explained to the king that he didn\'t keep any of the gold','Khi anh chàng thợ xây bình phục trở lại, anh giải thích với vị vua giàu có kia rằng anh đã không hề giữ bất cứ miếng vàng nào cả','00:01:24.200','00:01:29.800','4000-essential-english-words-53'),
	('He had given it all away to the poor','Thay vào đó, anh đã chia số vàng mà mình lấy được cho những người nghèo khó hơn','00:01:29.800','00:01:33.200','4000-essential-english-words-53'),

	/* (UUID(),'4000-essential-english-words-54','The Doctor\'s Cure','Việc chữa bệnh của bác sĩ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_054.mp3',NULL,'00:00:00.000','00:01:38.600','4000-essential-english-words','NO',54) */
	('James Fry was a fantastic doctor','James Fry là một bác sĩ tuyệt vời','00:00:03.000','00:00:06.400','4000-essential-english-words-54'),
	('His surgeries helped many disabled people overcome their injuries','Những ca phẫu thuật của ông đã giúp đỡ cho nhiều người khuyết tật vượt qua những chấn thương','00:00:06.400','00:00:10.700','4000-essential-english-words-54'),
	('He also wrote for a popular medical journal','Ông cũng viết cho một tạp chí y khoa nổi tiếng','00:00:10.700','00:00:13.800','4000-essential-english-words-54'),
	('James was very busy','James luôn bận rộn','00:00:13.800','00:00:16.000','4000-essential-english-words-54'),
	('His son, Steve, rarely saw him','Con trai ông, Steve, rất hiếm khi nhìn thấy ông','00:00:16.000','00:00:19.000','4000-essential-english-words-54'),
	('One day, James was walking and inspecting a patient\'s file','Một ngày nọ, ông đang đi bộ và kiểm tra hồ sơ bệnh nhân','00:00:19.000','00:00:23.800','4000-essential-english-words-54'),
	('There was water all over the floor','Có nước chảy trên sàn nhà','00:00:23.800','00:00:26.000','4000-essential-english-words-54'),
	('James slipped on the liquid and fell','James trượt chân và té','00:00:26.000','00:00:29.000','4000-essential-english-words-54'),
	('He fell on a broken glass tube','Ông ngã vào một ống thủy tinh đã vỡ','00:00:29.000','00:00:31.800','4000-essential-english-words-54'),
	('He was hurt','Ông bị thương','00:00:31.800','00:00:33.000','4000-essential-english-words-54'),
	('Steve came to visit him in the hospital','Steve đến bệnh viện thăm ông','00:00:33.000','00:00:35.900','4000-essential-english-words-54'),
	('James said, "It will be tough for me to stay in bed"','James nói, "Thật khó để cho bố có thể nằm trên giường"','00:00:35.900','00:00:40.200','4000-essential-english-words-54'),
	('"But I can hardly bend my legs"','"Và bố vẫn không thể gập được chân"','00:00:40.200','00:00:43.000','4000-essential-english-words-54'),
	('"Then let\'s watch a movie" Steve said','"Vậy giờ bố con mình xem phim nhé" Steve nói','00:00:43.000','00:00:46.000','4000-essential-english-words-54'),
	('It made them laugh together','Họ cười với nhau','00:00:46.000','00:00:48.000','4000-essential-english-words-54'),
	('Steve said, "I have to leave, but here\'s some fiction to read"','Steve nói, "Con phải về đây, con có để vài cuốn tiểu thuyết cho bố đọc"','00:00:48.000','00:00:52.800','4000-essential-english-words-54'),
	('James started to recall fun parts of life','James bắt đầu nhớ lại quãng thời gian hạnh phúc của mình','00:00:52.800','00:00:55.800','4000-essential-english-words-54'),
	('He marveled at small things, like food','Ông ngạc nhiên trước những điều tưởng chừng rất nhỏ nhặt, như thức ăn chẳng hạn','00:00:55.800','00:00:59.400','4000-essential-english-words-54'),
	('He was too busy to notice them before','Ông bận tới nỗi không có thời gian để ý đến chúng','00:00:59.400','00:01:02.000','4000-essential-english-words-54'),
	('"Steve," he said, "you get more nutrients when you chew slowly"','"Steve," Ông nói, "Khi con nhai kỹ, con sẽ hấp thụ được nhiều chất dinh dưỡng hơn đấy"','00:01:02.000','00:01:07.000','4000-essential-english-words-54'),
	('"But I think it makes food taste better, too"','"Và bố nghĩ nó cũng khiến thức ăn có mùi vị ngon hơn"','00:01:07.000','00:01:10.000','4000-essential-english-words-54'),
	('Weeks later, James said, "Steve, I haven\'t spent enough time with you"','Vài tuần sau, James nói: "Steve, bố đã không dành nhiều thời gian cho con"','00:01:10.000','00:01:15.400','4000-essential-english-words-54'),
	('"I regret this"','"Bố hối tiếc về điều này"','00:01:15.400','00:01:17.000','4000-essential-english-words-54'),
	('"Even my soul feels better when you visit"','"Thậm chí tâm hồn bố giờ đây cũng cảm thấy tốt hơn khi con đến thăm"','00:01:17.000','00:01:20.000','4000-essential-english-words-54'),
	('"But I have spent sufficient time here"','"Nhưng bố ở đây đủ rồi"','00:01:20.000','00:01:22.300','4000-essential-english-words-54'),
	('"We should go home"','"Giờ thì chúng ta về nhà thôi"','00:01:22.300','00:01:24.000','4000-essential-english-words-54'),
	('Outside, there was a warm breeze','Bên ngoài, một làn gió ấm áp thổi qua','00:01:24.000','00:01:26.700','4000-essential-english-words-54'),
	('James watched a flag blow','James nhìn lá cờ đang tung bay','00:01:26.700','00:01:29.200','4000-essential-english-words-54'),
	('Finally, James said, "I\'m not ready to work"','Cuối cùng, James nói, "Bố chưa sẵn sàng để bắt tay vào việc"','00:01:29.200','00:01:33.400','4000-essential-english-words-54'),
	('"I\'m going to take a long bath"','"Bố sẽ tắm rửa một chút"','00:01:33.400','00:01:35.600','4000-essential-english-words-54'),
	('"And then we\'ll watch a movie together"','"Và sau đó chúng ta sẽ cùng xem phim"','00:01:35.600','00:01:38.600','4000-essential-english-words-54'),

	/* (UUID(),'4000-essential-english-words-55','The Criminal','Tên tội phạm','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_055.mp3',NULL,'00:00:00.000','00:01:25.700','4000-essential-english-words','NO',55) */
	('A man had been in jail because he stole things','Có một người đàn ông vào tù vì tội ăn cắp','00:00:02.600','00:00:05.800','4000-essential-english-words-55'),
	('The criminal never felt bad','Tên tội phạm không bao giờ cảm thấy tồi tệ','00:00:05.800','00:00:08.200','4000-essential-english-words-55'),
	('One day, he escaped and ran into the woods','Một ngày nọ, hắn trốn thoát và chạy vào rừng','00:00:08.200','00:00:11.500','4000-essential-english-words-55'),
	('He found a cabin with a fence','Ông tìm thấy một cái chòi với một cái hàng rào','00:00:11.500','00:00:14.000','4000-essential-english-words-55'),
	('The cabin was very neat','Cái chòi thì rất gọn gàng','00:00:14.000','00:00:15.800','4000-essential-english-words-55'),
	('Inside, the criminal found a bowl of fruit, a bottle of milk, and a dozen eggs','Vào bên trong, tên tội phạm tìm thấy một bát hoa quả, một hộp sữa và một tá trứng','00:00:15.800','00:00:22.000','4000-essential-english-words-55'),
	('He ate the fruit and drank the milk','Hắn ăn trái cây và uống sữa','00:00:22.000','00:00:24.300','4000-essential-english-words-55'),
	('But the eggs smelled funny, so he put them in the trash bin','Thế nhưng trứng có mùi rất buồn cười, vì vậy ông vất chúng vào thùng rác','00:00:24.300','00:00:28.400','4000-essential-english-words-55'),
	('Soon, he heard the sound of a vehicle\'s motor','Ngay sau đó, ông nghe thấy tiếng của động cơ xe hơi','00:00:28.600','00:00:32.000','4000-essential-english-words-55'),
	('An old man came in and saw the criminal','Một ông lão bước vào và nhìn thấy tất cả mọi việc','00:00:32.000','00:00:35.000','4000-essential-english-words-55'),
	('The old man yelled, "Why are you in my house?"','Ông hét lên, "Sao anh lại ở trong nhà tôi?"','00:00:35.000','00:00:38.400','4000-essential-english-words-55'),
	('The criminal lied, "I am a policeman"','Tên tội phạm nói dối, "Tôi là cảnh sát đây"','00:00:38.400','00:00:41.700','4000-essential-english-words-55'),
	('The old man replied, "I am your elder"','Ông lão đáp, "Tôi là người nhiều tuổi hơn anh"','00:00:41.700','00:00:44.800','4000-essential-english-words-55'),
	('"You cannot fool me"','"Anh không lừa được tôi đâu"','00:00:44.800','00:00:46.000','4000-essential-english-words-55'),
	('"You are the criminal"','"Anh là một tên trộm"','00:00:46.000','00:00:48.000','4000-essential-english-words-55'),
	('The criminal\'s facial expression became very sad','Vẻ mặt tên tội phạm biến thành rất buồn','00:00:48.000','00:00:51.800','4000-essential-english-words-55'),
	('He admitted that he was a criminal','Hắn thừa nhận hắn là tội phạm','00:00:51.800','00:00:54.300','4000-essential-english-words-55'),
	('He said, "I\'m sorry"','Hắn nói, "Tôi xin lỗi"','00:00:54.300','00:00:56.900','4000-essential-english-words-55'),
	('"It was rude for me to come into your home"','"Tôi thật bất lịch sự vì đã đột nhập vào nhà ông"','00:00:56.900','00:00:59.400','4000-essential-english-words-55'),
	('"Please take the cash from my wallet"','"Hãy cầm lấy tiền mặt trong ví tiền của tôi"','00:00:59.400','00:01:02.000','4000-essential-english-words-55'),
	('"It is a mere amount, but it will settle our problem"','"Đó chỉ là một ít tiền, nhưng nó sẽ giải quyết vấn đề của chúng ta"','00:01:02.000','00:01:05.800','4000-essential-english-words-55'),
	('The old man said, "I do not want your money"','Ông lão nói, "Tôi không cần tiền của anh"','00:01:05.800','00:01:09.200','4000-essential-english-words-55'),
	('"I just want to inspire you to be good"','"Tôi chỉ muốn truyền cảm hứng để anh sống tốt hơn"','00:01:09.200','00:01:12.300','4000-essential-english-words-55'),
	('"There will be no penalty for taking my food"','"Tôi sẽ không phạt anh vì đã lấy đồ ăn của tôi"','00:01:12.300','00:01:15.900','4000-essential-english-words-55'),
	('On this occasion, the criminal realized that he had been bad','Nhân dịp này, tên tội phạm nhận ra trước kia hắn xấu xa thế nào','00:01:15.900','00:01:20.200','4000-essential-english-words-55'),
	('He listened to the old man and never stole from anyone ever again','Hắn nghe lời ông lão và không bao giờ ăn cắp của bất cứ ai nữa','00:01:20.200','00:01:25.700','4000-essential-english-words-55');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-56','The Two Captains','Hai ông thuyền trưởng','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_056.mp3',NULL,'00:00:00.000','00:01:29.800','4000-essential-english-words','NO',56) */
	('Once there were two ships','Vào một lần nọ, có hai con tàu','00:00:03.300','00:00:05.400','4000-essential-english-words-56'),
	('Both ships carried cotton','Trên cả hai con tàu đó đều chở bông','00:00:05.400','00:00:07.600','4000-essential-english-words-56'),
	('The captains were very different','Hai ông thuyền trưởng này có tính cách trái ngược nhau','00:00:07.600','00:00:09.800','4000-essential-english-words-56'),
	('Thomas was strict','Thomas rất nghiêm khắc','00:00:09.800','00:00:11.500','4000-essential-english-words-56'),
	('He made his crew engage in difficult tasks','Ông đã đưa phi hành đoàn của ông tham gia vào nhiều nhiệm vụ khó khăn','00:00:11.500','00:00:14.600','4000-essential-english-words-56'),
	('"Make sure the ship\'s deck is firm and that nothing falls"','"“Hãy đảm bảo rằng boong tàu chắc chắn và không có cái gì rơi ra"','00:00:14.600','00:00:18.600','4000-essential-english-words-56'),
	('"Put more fuel in the tank" he said','"Và cho thêm nhiên liệu vào thùng" ông nói','00:00:18.600','00:00:21.800','4000-essential-english-words-56'),
	('His ship was very plain, but he never had a problem with it','Con tàu của ông nhìn rất thô sơ nhưng ông chưa bao giờ phàn nàn về nó cả','00:00:21.800','00:00:25.900','4000-essential-english-words-56'),
	('The second captain, William, was not serious','William, thuyền trưởng thứ hai, là người không nghiêm túc','00:00:25.900','00:00:29.800','4000-essential-english-words-56'),
	('He had a grand ship, and he loved having fun','Ông có một con tàu hoành tráng, và ông ta thích vui vẻ','00:00:29.800','00:00:33.100','4000-essential-english-words-56'),
	('His crew amused him by singing and dancing','Phi hàng đoàn của ông giúp ông giải trí bằng mấy cái trò ca hát, nhảy múa','00:00:33.100','00:00:36.700','4000-essential-english-words-56'),
	('But his crew never fixed anything on the ship','Nhưng họ không bao giờ cố định bất cứ thứ gì trên tàu','00:00:36.700','00:00:39.700','4000-essential-english-words-56'),
	('They just wanted to surf','Họ chỉ muốn lướt sóng','00:00:39.700','00:00:41.700','4000-essential-english-words-56'),
	('One day, Thomas saw a hurricane ahead','Một ngày nọ, Thomas nhìn thấy một cơn bão ở phía trước','00:00:41.700','00:00:44.900','4000-essential-english-words-56'),
	('He knew that his ship needed to turn around','Ông biết tàu của ông cần phải quay lại','00:00:44.900','00:00:47.800','4000-essential-english-words-56'),
	('But he was sure William did not see the storm','Nhưng ông chắc chắn William không nhìn thấy cơn bão','00:00:47.800','00:00:50.800','4000-essential-english-words-56'),
	('He adjusted the dials on the radio and called his friend','Ông đánh điện trên radio cho bạn mình','00:00:50.800','00:00:54.300','4000-essential-english-words-56'),
	('Thomas said, "You\'ll hit the reef"','Thomas nói, "Ông anh sẽ đâm vào đá ngầm đấy"','00:00:54.300','00:00:57.000','4000-essential-english-words-56'),
	('"It\'s made completely of coral"','"Chúng hoàn toàn là san hô"','00:00:57.000','00:00:59.000','4000-essential-english-words-56'),
	('"Turn around to ensure that you do not crash"','"Mau quay lại và đảm bảo anh không đâm sầm vào nó"','00:00:59.000','00:01:02.000','4000-essential-english-words-56'),
	('William said, "We will go under the deck and shut the door"','William nói, "Chúng tôi sẽ đi dưới boong tàu và đóng cửa lại"','00:01:02.000','00:01:06.700','4000-essential-english-words-56'),
	('"We will dance and sing until we are past the danger zone"','"Chúng tôi sẽ nhảy múa và ca hát cho đến khi qua vùng nguy hiểm"','00:01:06.700','00:01:10.200','4000-essential-english-words-56'),
	('When William\'s ship got to the hurricane, the wind blew it into the reef','Khi tàu của William gặp cơn bão, gió thổi con tàu va vào các đá ngầm','00:01:10.200','00:01:14.900','4000-essential-english-words-56'),
	('The ship crashed, and water flowed below the deck','Con tàu gặp nạn, và nước chảy xuống vào boong tàu','00:01:14.900','00:01:18.900','4000-essential-english-words-56'),
	('William\'s crew accused him of being a bad captain','Phi hành đoàn William đổ lỗi cho ông là một thuyền trưởng dở tệ','00:01:18.900','00:01:21.800','4000-essential-english-words-56'),
	('The loss of the ship taught William a lesson','Mất con tàu đã dạy cho William một bài học','00:01:21.800','00:01:24.800','4000-essential-english-words-56'),
	('There are times to have fun, but there are also times to be serious','Vui vẻ đúng lúc, nghiêm túc đúng nơi','00:01:24.800','00:01:29.800','4000-essential-english-words-56'),

	/* (UUID(),'4000-essential-english-words-57','The Duke and the Minister','Công tước và bộ trưởng','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_057.mp3',NULL,'00:00:03.800','00:01:35.800','4000-essential-english-words','NO',57) */
	('A mean duke grew tobacco, and his cardinal rule was to always keep the plants healthy','Có một công tước trồng cây thuốc lá, và một nguyên tắc cốt lõi của ông là luôn giữ cho cây khỏe mạnh','00:00:03.800','00:00:10.800','4000-essential-english-words-57'),
	('The duke\'s top minister was his twin brother','Ngài bộ trưởng chính là người em trai song sinh của ông','00:00:10.800','00:00:14.000','4000-essential-english-words-57'),
	('They closely resembled each other','Họ rất giống nhau','00:00:14.000','00:00:16.200','4000-essential-english-words-57'),
	('One day, the tobacco plants started to die','Một ngày, những cây thuốc lá bắt đầu chết','00:00:16.200','00:00:19.800','4000-essential-english-words-57'),
	('He hired men to watch the fields','Vị công tước nọ thuê người để xem xét cánh đồng của mình','00:00:19.800','00:00:22.800','4000-essential-english-words-57'),
	('Soon, the men brought a woman to him and said, "We captured a witch"','Ngay sau đó, toán lính canh đưa một người phụ nữ đến trước mặt ông ta và nói rằng: "Chúng tôi đã bắt được một mụ phù thủy, thưa Ngài"','00:00:22.800','00:00:27.800','4000-essential-english-words-57'),
	('The Duke asked, "How do you know?"','Công tước hỏi, "Làm thế nào mà anh biết được điểu đó?"','00:00:27.800','00:00:30.800','4000-essential-english-words-57'),
	('"She sang magic words"','"Cô ta hát những lời ma thuật"','00:00:30.800','00:00:32.800','4000-essential-english-words-57'),
	('"I can\'t pronounce them"','Tôi không thể hiểu được','00:00:32.800','00:00:34.800','4000-essential-english-words-57'),
	('"She has cursed us"','"Cô ta nguyền rủa chúng tôi"','00:00:34.800','00:00:36.800','4000-essential-english-words-57'),
	('"The death of the plants is a symptom of her curse," the men said','"Cây cối chết là dấu hiệu của lời nguyền của ả", những người đàn ông nói','00:00:36.800','00:00:41.000','4000-essential-english-words-57'),
	('"I am just an ordinary woman"','','00:00:41.000','00:00:43.800','4000-essential-english-words-57'),
	('"I was singing a song in a different language," the woman protested','"Tôi chỉ đơn giản là ca những bài hát bằng những thứ tiếng khác nhau,", người phụ nữ cam đoan','00:00:43.800','00:00:48.800','4000-essential-english-words-57'),
	('The duke didn\'t listen','Vị công tước không hề lắng nghe','00:00:48.900','00:00:50.800','4000-essential-english-words-57'),
	('"You are guilty"','"Ngươi có tội"','00:00:50.800','00:00:51.800','4000-essential-english-words-57'),
	('"You will go to jail"','"Ngươi sẽ phải vào nhà lao"','00:00:51.800','00:00:53.800','4000-essential-english-words-57'),
	('The minister thoughfrthat she was innocent','Ông bộ trưởng lại nghĩ rằng người phụ nữ kia vô tội','00:00:53.800','00:00:56.800','4000-essential-english-words-57'),
	('He needed to expose the truth','Ông cần phải vạch trần sự thật này','00:00:56.800','00:00:59.000','4000-essential-english-words-57'),
	('He asked the duke to loan him one of his plants','Ông yêu cầu công tước cho ông mượn một cây thuốc lá','00:00:59.000','00:01:02.800','4000-essential-english-words-57'),
	('He looked at it closely','Ông nhìn nó say sưa','00:01:02.800','00:01:04.500','4000-essential-english-words-57'),
	('He saw hundreds of small bugs eating it','Ông quan sát thấy có hàng trăm con bọ nhỏ đang ăn thân cây','00:01:04.500','00:01:07.800','4000-essential-english-words-57'),
	('Then the ministerwent to the jail and did something bold','Sau đó, ngài Bộ trưởng đến thẳng nhà lao và thực hiện một điều táo bạo','00:01:07.800','00:01:12.800','4000-essential-english-words-57'),
	('"Let this woman go," he said','"Hãy thả người phụ nữ này ra ngay,", ông ra lệnh','00:01:12.800','00:01:14.800','4000-essential-english-words-57'),
	('The guards thought he was the duke','Lính canh nghĩ rằng ông là ngài Công tước','00:01:14.800','00:01:17.000','4000-essential-english-words-57'),
	('They let her go','Họ thả người phụ nữ ra','00:01:17.000','00:01:18.800','4000-essential-english-words-57'),
	('The minister said, "I owe you an apology"','"Tôi nợ cô một lời xin lỗi từ tận đáy lòng", Ngài Bộ trưởng nói','00:01:18.800','00:01:22.000','4000-essential-english-words-57'),
	('"Thank you"','Cảm ơn ngài','00:01:22.000','00:01:23.000','4000-essential-english-words-57'),
	('"I thought my stay in jail was permanent," the woman answered','Tôi cứ ngỡ rằng mình sẽ phải ở trong phòng giam này đến rũ xương trong này cả đời mất", người phụ nữ đáp lại','00:01:23.000','00:01:27.800','4000-essential-english-words-57'),
	('The minister thought the duke would punish him','Ngài Bộ trưởng lo ngại rằng vị Công tước sẽ trừng phạt ông','00:01:27.800','00:01:30.400','4000-essential-english-words-57'),
	('But he didn\'t','Nhưng ông ta đã không làm vậy','00:01:30.400','00:01:31.800','4000-essential-english-words-57'),
	('The duke was too busy trying to preserve his plants','Công tước đang bận rộn cố gắng cứu lấy những cái cây của mình','00:01:31.800','00:01:35.800','4000-essential-english-words-57'),

	/* (UUID(),'4000-essential-english-words-58','The Fisherman','Người ngư dân','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_058.mp3',NULL,'00:00:00.000','00:01:26.900','4000-essential-english-words','NO',58) */
	('Every day, a fisherman sat on a bridge','Ngày nào cũng có một người ngư dân ngồi trên cây cầu','00:00:03.000','00:00:06.800','4000-essential-english-words-58'),
	('He ate apples and spit the seeds into the water','Ông ăn táo và nhổ hạt xuống nước','00:00:06.800','00:00:10.800','4000-essential-english-words-58'),
	('He had a simple way to catch fish','Ông có một cách đơn giản để bắt cá','00:00:10.800','00:00:13.100','4000-essential-english-words-58'),
	('He cut a branch off of a tree and tied a line to it','Ông bẻ một cành cây và buộc một sợi dây vào nó','00:00:13.100','00:00:17.300','4000-essential-english-words-58'),
	('He put a sharp hook on it and made a tight knot','Ông buộc một cái móc nhọn vào đầu còn lại và buộc chặt nó lại','00:00:17.300','00:00:20.800','4000-essential-english-words-58'),
	('Then he whispered, "Come here fish"','Sau đó, ông nói nhỏ, "Hãy đến đây, cá ơi"','00:00:20.800','00:00:23.800','4000-essential-english-words-58'),
	('Like magic, the fish bit the hook','Cứ như là có ma thuật vậy, cá cắn vào lưỡi câu','00:00:23.800','00:00:27.000','4000-essential-english-words-58'),
	('He put them in a big net and took them home to make big pots of fish soup from them','Ông nhốt chúng vào một cái lưới lớn và đem về nhà nấu súp cá','00:00:27.000','00:00:32.600','4000-essential-english-words-58'),
	('One day, another man walked up to him','Một ngày nọ, có một người đến chỗ ông ta','00:00:32.600','00:00:35.800','4000-essential-english-words-58'),
	('He said, "My name is George"','Anh ta nói: "Tôi là George"','00:00:35.800','00:00:38.700','4000-essential-english-words-58'),
	('"I am staying at the inn"','"Tôi đang ở một nhà trọ"','00:00:38.700','00:00:40.700','4000-essential-english-words-58'),
	('"I bet that I am a better fisherman than you"','"Tôi cá rằng tôi là một ngư dân giỏi hơn ông"','00:00:40.700','00:00:43.800','4000-essential-english-words-58'),
	('"I will accompany you today"','"Hôm nay tôi sẽ đi cùng ông"','00:00:43.800','00:00:45.800','4000-essential-english-words-58'),
	('"I dare you to prove your skill"','"Tôi thách ông chứng minh được khả năng của mình"','00:00:45.800','00:00:48.800','4000-essential-english-words-58'),
	('The fisherman cast his line','Người đánh cá thả dây câu','00:00:48.800','00:00:51.000','4000-essential-english-words-58'),
	('George had a lot of electronic tools','Geoge có rất nhiều công cụ bằng điện','00:00:51.000','00:00:54.000','4000-essential-english-words-58'),
	('One machine gave him the virtual locations offish','Một chiếc máy khiến anh ta tìm thấy gần như chính xác vị trí của cá','00:00:54.000','00:00:58.000','4000-essential-english-words-58'),
	('His rod weighed fish','Cần câu của anh cân được cá','00:00:58.000','00:01:00.000','4000-essential-english-words-58'),
	('At the end of the day, George subtracted his fish from the fisherman\'s','Vào cuối ngày, George trừ đi số cá của mình từ người ngư dân','00:01:00.000','00:01:05.600','4000-essential-english-words-58'),
	('The fisherman had beaten him by forty-seven','Người ngư dân đã đánh bại anh ta với tỉ lệ 40-7','00:01:05.600','00:01:08.800','4000-essential-english-words-58'),
	('George asked, "How do you catch fish with only a branch and a bare line?"','George hỏi, "Tại sao ông có thể bắt cá chỉ với một cành cây và một sợi dây?"','00:01:08.800','00:01:14.100','4000-essential-english-words-58'),
	('"I have many different sorts of tools"','Tôi có rất nhiều loại công cụ khác nhau','00:01:14.100','00:01:16.900','4000-essential-english-words-58'),
	('The fisherman told George, "My philosophy is simple"','Người đánh cá nói với George "Triết lý của tôi rất đơn giản"','00:01:16.900','00:01:20.900','4000-essential-english-words-58'),
	('"I am patient, and I believe in myself"','"Tôi là người kiên nhẫn và tôi tin vào bản thân mình"','00:01:20.900','00:01:23.900','4000-essential-english-words-58'),
	('"Take a breath, and try it my way"','"Hãy hít thở và làm theo cách của tôi"','00:01:23.900','00:01:26.900','4000-essential-english-words-58'),

	/* (UUID(),'4000-essential-english-words-59','Osiris and the Nile','Thần Osiris và dòng sông Nile','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_059.mp3',NULL,'00:00:00.000','00:01:38.200','4000-essential-english-words','NO',59) */
	('Long ago, Osiris was the king of Egypt, and Isis was the queen','Ngày xưa, Osiris là vua của Ai Cập, còn Isis là nữ hoàng','00:00:03.500','00:00:08.400','4000-essential-english-words-59'),
	('They ruled the fertile land by the Nile River','Họ cai trị vùng sông Nile màu mỡ','00:00:08.400','00:00:12.100','4000-essential-english-words-59'),
	('They had great intelligence, and they shared their abstract ideas with everyone','Họ cực kì thông minh và họ chia sẻ những ý tưởng trừu tượng của mình với người dân','00:00:12.100','00:00:17.300','4000-essential-english-words-59'),
	('Osiris taught the Egyptians how to make wheels and furniture','Osiris dạy người Ai Cập cách làm bánh xe và đồ nội thất','00:00:17.300','00:00:22.100','4000-essential-english-words-59'),
	('Isis taught them how to make things from clay and cloth','Isis dạy họ cách làm từ đất sét và vải','00:00:22.100','00:00:25.900','4000-essential-english-words-59'),
	('The people thought they deserved a gift','Người dân nghĩ rằng họ xứng đáng nhận được một món quà','00:00:25.900','00:00:28.200','4000-essential-english-words-59'),
	('So they built Osiris and Isis a pyramid','Vì vậy họ xây dựng một kim tự tháp cho Osiris và Isis','00:00:28.200','00:00:31.400','4000-essential-english-words-59'),
	('Everyone loved Osiris except his brother, Set','Mọi người đều yêu mến Osiris trừ anh trai của ông, Set','00:00:31.400','00:00:35.300','4000-essential-english-words-59'),
	('Set wanted to be king','Set muốn làm vua','00:00:35.300','00:00:37.300','4000-essential-english-words-59'),
	('Osiris made his annual trip around Egypt and led religious events','Osiris thực hiện chuyến đi hàng năm của mình vòng quanh Ai Cập và tổ chức các sự kiện về tôn giáo','00:00:37.300','00:00:42.900','4000-essential-english-words-59'),
	('The villages gave him beautiful shells and colorful feathers as gifts','Dân làng lấy vỏ sò và lông vũ đầy màu sắc để làm quà tặng ông','00:00:42.900','00:00:47.400','4000-essential-english-words-59'),
	('When Osiris returned, Set brought a beautiful wooden box from behind a curtain','Khi Osiris trở về, Set mang một hộp bằng gỗ tuyệt đẹp từ phía sau tấm rèm','00:00:47.400','00:00:53.100','4000-essential-english-words-59'),
	('"If someone fits inside this box, I will give it to him or her," Set said','"Ai chui vào vừa chiếc hộp này, tôi sẽ tặng cho người đó," Set nói','00:00:53.100','00:00:59.100','4000-essential-english-words-59'),
	('Osiris got in it','Osiris chui vào','00:00:59.100','00:01:00.900','4000-essential-english-words-59'),
	('It was an ideal fit','Quả là vừa khít','00:01:00.900','00:01:02.900','4000-essential-english-words-59'),
	('Suddenly, Set closed the box and threw it into the river','Đột nhiên Set đóng chiếc hộp lại và quăng nó xuống sông','00:01:02.900','00:01:07.400','4000-essential-english-words-59'),
	('"Now I will be king," Set said','"Từ giờ ta sẽ chính là vua," Set nói','00:01:07.400','00:01:11.000','4000-essential-english-words-59'),
	('The box washed up on a foreign shore after a flood','Chiếc hộp trôi dạt vào một bờ biển của nước khác sau trận lũ','00:01:11.000','00:01:15.000','4000-essential-english-words-59'),
	('Isis brought his body home and obtained a grave for him in Egypt','Isis mang cơ thể chồng mình về nhà và xây cho ông ngôi mộ ở Ai Cập','00:01:15.000','00:01:19.800','4000-essential-english-words-59'),
	('The Egyptian gods thought Isis had done something very romantic','Các vị thần Ai Cập nghĩ hành động của Isis thật cảm động','00:01:19.800','00:01:24.800','4000-essential-english-words-59'),
	('Because of her love, the gods made him the god of the underworld','Vì tình yêu của bà, thần linh đã để ông trở thành vị thần của thế giới ngầm','00:01:24.800','00:01:29.200','4000-essential-english-words-59'),
	('Osiris returned every spring to help the farmers','Osiris trở lại vào mỗi mùa xuân để giúp đỡ người nông dân','00:01:29.200','00:01:33.200','4000-essential-english-words-59'),
	('Even nowadays, people say Osiris keeps their crops alive','Thậm chí ngày nay, người ta vẫn tin rằng thần Osiris giúp cho cây trồng của họ luôn tươi tốt','00:01:33.200','00:01:38.200','4000-essential-english-words-59'),

	/* (UUID(),'4000-essential-english-words-60','The Taxi Driver','Tài xế taxi','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_060.mp3',NULL,'00:00:00.000','00:01:32.800','4000-essential-english-words','NO',60) */
	('Peter\'s job was driving a taxi downtown','Công việc của Peter là một tài xế taxi ở trung tâm thành phố','00:00:03.500','00:00:06.800','4000-essential-english-words-60'),
	('He made a small salary','Anh ấy kiếm được một khoản lương nhỏ','00:00:06.800','00:00:08.800','4000-essential-english-words-60'),
	('But he liked his job because it wasn\'t dull','Tuy nhiên anh thích công việc này vì nó không hề buồn tẻ','00:00:08.800','00:00:12.200','4000-essential-english-words-60'),
	('Every day, he saw new things that appealed to him','Ngày nào, anh ấy cũng thấy những điều mới mẻ hấp dẫn mình','00:00:12.200','00:00:15.200','4000-essential-english-words-60'),
	('Peter was practical about the future','Peter rất thực tế về tương lai','00:00:15.200','00:00:17.900','4000-essential-english-words-60'),
	('"Maybe I can get a scholarship to college," he thought','"Tôi có thể nhận được một học bổng để đi học đại học," anh ấy đã nghĩ','00:00:17.900','00:00:21.100','4000-essential-english-words-60'),
	('"I could learn mathematical formulas and get a job at a bank"','"Tôi có thể học về các công thức toán học và kiếm một công việc trong ngân hàng"','00:00:21.100','00:00:25.300','4000-essential-english-words-60'),
	('"I could help clients invest their money"','"Tôi có thể giúp khách hàng đầu tư tiền của họ"','00:00:25.300','00:00:28.200','4000-essential-english-words-60'),
	('Peter stopped to pick up a passenger','Peter dừng lại đón một hành khách','00:00:28.200','00:00:30.800','4000-essential-english-words-60'),
	('"Where to?" he asked','"Anh đi đâu?", anh ấy hỏi','00:00:30.800','00:00:33.800','4000-essential-english-words-60'),
	('"Go to the Fourth Street Bank"','"Hãy tới ngân hàng Fourth Street"','00:00:33.800','00:00:35.200','4000-essential-english-words-60'),
	('"And don\'t talk to me"','Và đừng nói chuyện gì với tôi hết','00:00:35.200','00:00:36.800','4000-essential-english-words-60'),
	('"I\'ve had a rough day," the man said','"Tôi đã có một ngày căng thẳng," người đàn ông nói','00:00:36.800','00:00:39.800','4000-essential-english-words-60'),
	('Peter was angry, but he had a peaceful philosophy','Peter hơi tức giận, nhưng anh ấy có một triết lý sống ôn hòa','00:00:39.800','00:00:43.800','4000-essential-english-words-60'),
	('When they stopped, the man\'s fare came to $10.25','Khi họ dừng lại, cước phí của người khách đó lên đến 10,25 đô la','00:00:43.800','00:00:48.000','4000-essential-english-words-60'),
	('He put his hands in his pockets','Ông ta thò tay vào các túi quần của mình','00:00:48.000','00:00:50.800','4000-essential-english-words-60'),
	('"I can\'t find my wallet" he said','"Tôi không thể tìm thấy ví của mình", ông ấy nói','00:00:50.800','00:00:53.800','4000-essential-english-words-60'),
	('"I can\'t pay the fare"','"Tôi không thể trả tiền phí"','00:00:53.800','00:00:55.800','4000-essential-english-words-60'),
	('Peter said, "Maybe I\'ll give you a temporary loan"','Peter nói, "Tôi sẽ cho anh vay một một khoản tạm thời"','00:00:55.800','00:00:59.800','4000-essential-english-words-60'),
	('"You can borrow ten dollars and a quarter from me"','Anh có thể mượn tôi 10,25 đô la','00:00:59.800','00:01:02.800','4000-essential-english-words-60'),
	('The man was embarrassed, saying, "I was mean to you, but now I want to help you"','Người đàn ông rất xấu hổ, ông ấy nói, "Tôi đã tỏ ra thật ích kỷ, nhưng bây giờ tôi muốn giúp anh"','00:01:02.800','00:01:08.300','4000-essential-english-words-60'),
	('"I founded this bank"','"Chính tôi đã thành lập ngân hàng này"','00:01:08.300','00:01:10.000','4000-essential-english-words-60'),
	('"I want to give you one thousand dollars"','"Tôi muốn tặng cho anh một nghìn đô la"','00:01:10.000','00:01:12.800','4000-essential-english-words-60'),
	('That much money was like a treasure to Peter','Số tiền đó nhiều như một kho báu đối với Peter','00:01:12.800','00:01:15.800','4000-essential-english-words-60'),
	('The man urged him to take the money, but he didn\'t','Người đàn ông cứ hối thúc Peter nhận số tiền đó nhưng anh ấy đã không làm vậy','00:01:15.800','00:01:19.100','4000-essential-english-words-60'),
	('"You\'re an honest person," the man said','"Anh là một người thật thà," người đàn ông nói','00:01:19.100','00:01:22.000','4000-essential-english-words-60'),
	('"I assumed you would take it"','"Tôi đã cho rằng anh sẽ nhận nó"','00:01:22.000','00:01:23.800','4000-essential-english-words-60'),
	('"I want you to work for me"','Tôi muốn anh làm việc cho tôi','00:01:23.800','00:01:25.800','4000-essential-english-words-60'),
	('The next day, Peter started his job at the bank','Ngày hôm sau, Peter bắt đầu công việc tại ngân hàng','00:01:25.800','00:01:29.800','4000-essential-english-words-60'),
	('He was happy to be done with his former job','Anh ấy rất hạnh phúc vì đã làm tốt với công việc cũ của mình','00:01:29.800','00:01:32.800','4000-essential-english-words-60');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-61','The Real St. Nick','Thánh Nick thật sự','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_061.mp3',NULL,'00:00:00.000','00:01:40.700','4000-essential-english-words','NO',61) */
	('At Christmas, children wait for Saint Nicholas to bring gifts down the chimney','Vào lễ Giáng sinh, trẻ em chờ đợi Thánh Nicholas mang quà xuống ống khói','00:00:03.000','00:00:08.000','4000-essential-english-words-61'),
	('But it\'s not just a story','Nhưng nó không chỉ là một câu chuyện','00:00:08.000','00:00:09.300','4000-essential-english-words-61'),
	('Saint Nicholas was a real person','Thánh Nicholas là một người có thật','00:00:09.300','00:00:11.300','4000-essential-english-words-61'),
	('A long time ago, a man named Marcus occupied a house with his family','Cách đây rất lâu, một người đàn ông tên Marcus đã chiếm một ngôi nhà với gia đình anh ta','00:00:11.300','00:00:16.100','4000-essential-english-words-61'),
	('He was not modest','Anh ta không hề khiêm tốn','00:00:16.100','00:00:17.800','4000-essential-english-words-61'),
	('He always told everybody he was the strongest man in the province','Anh ta luôn nói rằng mình là người mạnh nhất vùng','00:00:17.800','00:00:21.800','4000-essential-english-words-61'),
	('He worked hard, but he could barely sustain his family','Anh ta làm việc chăm chỉ nhưng vẫn không thể nuôi sống gia đình','00:00:21.800','00:00:25.100','4000-essential-english-words-61'),
	('He wanted to save money and prosper','Anh ta muốn tiết kiệm tiền và trở nên giàu có','00:00:25.100','00:00:27.400','4000-essential-english-words-61'),
	('Still, he could never earn a penny more than he needed','Tuy nhiên, anh ta không bao giờ kiếm đủ số tiền anh ta cần','00:00:27.400','00:00:30.800','4000-essential-english-words-61'),
	('One day, Marcus made an agreement with a blacksmith','Một ngày nọ, Marcus đã thỏa thuận với một thợ rèn','00:00:30.800','00:00:33.800','4000-essential-english-words-61'),
	('The blacksmith had a lot of work to do','Người thợ rèn có rất nhiều việc phải làm nhưng anh ấy không thể tự mình làm hết được','00:00:33.800','00:00:36.000','4000-essential-english-words-61'),
	('But he couldn\'t do it all by himself','Nhưng anh ấy cũng tin rằng mình nên khiêm tốn và bác ái','00:00:36.000','00:00:39.000','4000-essential-english-words-61'),
	('Marcus wanted to help him forge iron','Marcus muốn giúp anh ta rèn sắt','00:00:39.000','00:00:41.800','4000-essential-english-words-61'),
	('The blacksmith agreed to compensate him with a lot of money','Người thợ rèn đồng ý bồi thường cho anh ta rất nhiều tiền','00:00:41.800','00:00:45.000','4000-essential-english-words-61'),
	('In the same town, there was a man named Nicholas','Trong cùng một thị trấn, có một người đàn ông tên Nicholas','00:00:45.000','00:00:48.00','4000-essential-english-words-61'),
	('At an early age, Nicholas started preaching','Và khi còn nhỏ, Nicholas bắt đầu thuyết giảng','00:00:48.000','00:00:51.000','4000-essential-english-words-61'),
	('But he also believed that he should be humble and charitable','Nhưng anh ấy cũng tin rằng mình nên khiêm tốn và bác ái','00:00:51.000','00:00:55.000','4000-essential-english-words-61'),
	('He learned that helping people gave him even more satisfaction than preaching','Anh học được rằng giúp đỡ mọi người mang lại cho anh nhiều niềm vui hơn là giảng đạo','00:00:55.000','00:00:59.500','4000-essential-english-words-61'),
	('One day, Nicholas encountered Marcus','Một ngày, Nicholas gặp Marcus','00:00:59.500','00:01:02.000','4000-essential-english-words-61'),
	('Marcus told Nicholas about his agreement with the blacksmith','Marcus kể cho Nicholas về thỏa thuận của anh ta với người thợ rèn','00:01:02.000','00:01:05.800','4000-essential-english-words-61'),
	('"I worked hard for him," Marcus said, "but a problem arose"','"Tôi đã làm việc chăm chỉ cho anh ấy" Marcus nói, "nhưng một vấn đề phát sinh"','00:01:05.800','00:01:08.000','4000-essential-english-words-61'),
	('"Even though I worked for him, he didn\'t pay me"','"Mặc dù tôi làm việc cho anh ta, anh ấy vẫn không trả lương cho tôi"','00:01:08.000','00:01:12.800','4000-essential-english-words-61'),
	('Nicholas wanted to help Marcus','Nicholas muốn giúp Marcus','00:01:12.800','00:01:15.000','4000-essential-english-words-61'),
	('That night, he went back to Marcus\'s house','Đêm đó anh ta trở về nhà của Marcus','00:01:15.000','00:01:17.800','4000-essential-english-words-61'),
	('He brought a bag of gold','Anh ta đem theo một bịch vàng','00:01:17.800','00:01:19.300','4000-essential-english-words-61'),
	('It exceeded the amount that Marcus needed','Nó vượt xa số lượng mà Marcus cần','00:01:19.300','00:01:22.000','4000-essential-english-words-61'),
	('Nicholas climbed up a ladder and dropped the bag of gold down the chimney','Nicholas leo lên một cái thang và thả bịch vàng xuống ống khói','00:01:22.000','00:01:26.800','4000-essential-english-words-61'),
	('Marcus thanked his benefactor','Marcus cảm ơn ân nhân của mình','00:01:26.800','00:01:28.900','4000-essential-english-words-61'),
	('Soon, people found out about Nicholas\'s gift','Ngay sau đó, mọi người đã phát hiện ra món quà của Nicholas','00:01:28.900','00:01:32.000','4000-essential-english-words-61'),
	('He became well known and loved','Anh ấy trở nên nổi tiếng và được yêu mến','00:01:32.000','00:01:34.300','4000-essential-english-words-61'),
	('Even today, people still give secret gifts to children','Thậm chí ngày nay người ta vẫn tặng quà bí mật cho trẻ em','00:01:34.300','00:01:38.000','4000-essential-english-words-61'),
	('And we say they are from St.Nicholas','Và chúng ta nói rằng món quà đến từ Thánh Nicholas','00:01:38.000','00:01:40.700','4000-essential-english-words-61'),

	/* (UUID(),'4000-essential-english-words-62','The shepherd and the wild sheep','Người chăn cừu và bầy cừu hoang','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_062.mp3',NULL,'00:00:00.000','00:01:36.500','4000-essential-english-words','NO',62) */
	('Once there was a shepherd','Ngày xưa có một người chăn cừu','00:00:03.900','00:00:05.500','4000-essential-english-words-62'),
	('Every night he counted and gathered his sheep','Hằng đêm ông ta đếm và tập hợp bầy cừu của mình lại','00:00:05.500','00:00:08.400','4000-essential-english-words-62'),
	('He was sure never to overlook any of them','Ông ta chắc chắn không bao giờ bỏ qua bất kỳ con nào trong số chúng','00:00:08.400','00:00:11.200','4000-essential-english-words-62'),
	('One night, he saw some wild sheep had joined his herd','Một đêm nọ, ông nhìn thấy một vài con cừu hoang gia nhập đàn cừu của mình','00:00:11.200','00:00:15.000','4000-essential-english-words-62'),
	('He hoped to acquire the newcomers','Ông hy vọng rằng có được những kẻ mới đến','00:00:15.000','00:00:17.300','4000-essential-english-words-62'),
	('It snowed that night','Tuyết rơi vào đêm hôm đó','00:00:17.300','00:00:19.000','4000-essential-english-words-62'),
	('In the morning, the shepherd couldn\'t take his sheep out of his lodge','Buổi sáng hôm sau, người chăn cừu không thể lôi những con cừu của ông ra khỏi túp lều','00:00:19.000','00:00:22.800','4000-essential-english-words-62'),
	('Instead, he had to feed them inside','Thay vào đó, ông phải cho chúng ăn ở bên trong','00:00:22.800','00:00:25.400','4000-essential-english-words-62'),
	('He gave a small amount of wheat to his own sheep','Ông cho bầy cừu của mình ăn một ít lúa mạch','00:00:25.400','00:00:28.100','4000-essential-english-words-62'),
	('But he gave more of the food to the wild sheep','Nhưng ông cho những con cừu hoang nhiều thức ăn hơn','00:00:28.100','00:00:31.000','4000-essential-english-words-62'),
	('He thought the extra wheat would discourage them from leaving','Ông nghĩ rằng lượng lúa mì được cho thêm sẽ ngăn chúng rời đi','00:00:31.000','00:00:34.400','4000-essential-english-words-62'),
	('It snowed for several days','Tuyết rơi khoảng vài ngày','00:00:34.400','00:00:36.600','4000-essential-english-words-62'),
	('During that time, the shepherd\'s sheep ate very little','Trong suốt thời gian đó, bầy cừu của người ăn cừu ăn rất ít','00:00:36.600','00:00:40.000','4000-essential-english-words-62'),
	('The wild sheep, however, ate very well','Những con cừu hoang trái lại ăn rất khỏe','00:00:40.000','00:00:42.600','4000-essential-english-words-62'),
	('At last, the snow melted, and they ventured outdoors','Cuối cùng, khi tuyết tan, chúng mạo hiểm ra bên ngoài','00:00:42.600','00:00:46.400','4000-essential-english-words-62'),
	('As soon as he opened the door of his hut, the wild sheep started to run away','Ngay sau khi người chăn cừu mở cửa túp lều của mình, những con cừu hoang bắt đầu chạy trốn','00:00:46.400','00:00:51.100','4000-essential-english-words-62'),
	('"Wait! This is how you repay me?"','"Đợi đã! Đây là cách chúng mày trả ơn tao sao?"','00:00:51.100','00:00:53.300','4000-essential-english-words-62'),
	('"After I treated you so kindly, why do you run away?" the shepherd asked','"Sau khi tao đã đối xử với chúng mày rất tốt, tại sao chúng mày lại chạy trốn?" người chăn cừu hỏi','00:00:53.300','00:00:58.100','4000-essential-english-words-62'),
	('His voice was full of hatred','Giọng nói của ông ta chứa đầy sự hận thù','00:00:58.100','00:01:00.000','4000-essential-english-words-62'),
	('The wild sheep stopped and turned toward the shepherd','Lũ cừu hoang dã dừng lại và quay về phía người chăn cừu','00:01:00.000','00:01:03.800','4000-essential-english-words-62'),
	('"We\'re leaving because you fed us betterthan your own sheep," one of the wild sheep replied','"Chúng tôi rời đi vì ông cho chúng tôi ăn ngon hơn cừu của ông," một con cừu hoang trả lời','00:01:03.800','00:01:09.000','4000-essential-english-words-62'),
	('"You tried to deceive us with your ridiculous plan"','"Ông cố gắng lừa dối chúng tôi với kế hoạch ngớ ngẩn của ông"','00:01:09.000','00:01:12.000','4000-essential-english-words-62'),
	('"Yesterday you treated us kindly, but tomorrow you might be different"','"Ngày hôm qua ông đối xử với chúng tôi rất tốt, nhưng ngày mai có thể ông đã khác rồi"','00:01:12.000','00:01:16.000','4000-essential-english-words-62'),
	('"If more wild sheep joined your herd, you would treat us as inferior sheep"','"Nếu có nhiều cừu hoang gia nhập bầy cừu của ông, ông sẽ đối xử với chúng tôi như những con cừu thấp kém kia"','00:01:16.000','00:01:20.800','4000-essential-english-words-62'),
	('As the wild sheep ran away, the shepherd understood his offense','Khi lũ cừu hoang bỏ đi, người chăn cừu hiểu được tội lỗi của ông ta','00:01:20.800','00:01:25.100','4000-essential-english-words-62'),
	('He knew this awkward situation was his own fault','Ông ta biết tình huống khó xử này là lỗi của ông ta','00:01:25.100','00:01:28.100','4000-essential-english-words-62'),
	('He had not been a satisfactory caretaker','Ông ta không phải là một người chăm cừu đạt yêu cầu','00:01:28.100','00:01:31.000','4000-essential-english-words-62'),
	('He was a fake friend to the wild sheep','Ông ta là một người bạn giả dối với lũ cừu hoang','00:01:31.000','00:01:33.500','4000-essential-english-words-62'),
	('Because of this, he had neglected his own herd','Bởi vì điều này, ông đã lơ là với bầy cừu của mình','00:01:33.500','00:01:36.500','4000-essential-english-words-62'),

	/* (UUID(),'4000-essential-english-words-63','The Boy and his Sled','Cậu bé và chiếc xe trượt tuyết','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_063.mp3',NULL,'00:00:00.000','00:01:27.400','4000-essential-english-words','NO',63) */
	('Mike was the smallest child in school','Mike là cậu bé có dáng người nhỏ bé nhất ở trường học','00:00:03.300','00:00:06.300','4000-essential-english-words-63'),
	('Another boy, Joe, always teased Mike','Joe, một cậu bé khác, luôn trêu chọc Mike','00:00:06.300','00:00:08.800','4000-essential-english-words-63'),
	('Joe had a large scar on his face from fighting other children','Một ngày, Joe đã làm tổn thương Mike khi đem thư tình của cậu viết cho Jane ra làm trò đùa','00:00:08.800','00:00:12.900','4000-essential-english-words-63'),
	('One day, Joe offended Mike when he made fun of Mike\'s valentine, Jane','Một ngày, Joe đã làm tổn thương Mike khi đem thư tình của cậu viết cho Jane ra làm trò đùa','00:00:12.900','00:00:17.300','4000-essential-english-words-63'),
	('Mike felt disgrace, but he didn\'t know how to make Joe stop','Mike cảm thấy xấu hổ, nhưng cậu không biết làm thế nào để cho Joe dừng lại','00:00:17.300','00:00:21.700','4000-essential-english-words-63'),
	('That day, Mike walked home down an alley','Ngày hôm đó, Mike đi bộ qua con hẻm để về nhà','00:00:21.700','00:00:24.800','4000-essential-english-words-63'),
	('He found a bunch of wood boards next to a pine tree','Cậu phát hiện một chồng tấm bảng gỗ đặt gần một cây thông','00:00:24.800','00:00:28.100','4000-essential-english-words-63'),
	('He thought to himself, "I could build a decent sled from this"','Cậu bé nghĩ thầm, "Mình có thể làm một chiếc xe trượt tuyết ngon nghẻ từ cái này"','00:00:28.100','00:00:31.700','4000-essential-english-words-63'),
	('"If I let Joe use it, he will be nicerto me and Jane"','"Nếu để Joe dùng nó, cậu ta sẽ đối xử với mình và Jane tốt hơn"','00:00:31.700','00:00:35.200','4000-essential-english-words-63'),
	('He took the wood home','Cậu bé mang tấm gỗ về nhà','00:00:35.200','00:00:36.900','4000-essential-english-words-63'),
	('Mike got an ax and cut the wood','Mike lấy một cái rìu lớn và chặt tấm gỗ ra','00:00:36.900','00:00:39.200','4000-essential-english-words-63'),
	('He used nails to make sure that the pieces were not loose','Cậu bé đóng đinh vào những miếng gỗ để đảm bảo chúng không bị lỏng lẻo','00:00:39.200','00:00:42.800','4000-essential-english-words-63'),
	('As he worked, he bumped his elbow on the boards','Khi làm việc, khuỷu tay của cậu va vào tấm bảng','00:00:42.800','00:00:45.600','4000-essential-english-words-63'),
	('The painful sensation made him want to cry','Cảm giác đau đớn làm cho cậu muốn khóc','00:00:45.600','00:00:48.400','4000-essential-english-words-63'),
	('It was a hard chore, but he persisted','Đây là một việc khó khăn, nhưng cậu vẫn kiên trì','00:00:48.400','00:00:50.800','4000-essential-english-words-63'),
	('He worked overnight','Cậu bé làm việc xuyên đêm','00:00:50.800','00:00:52.400','4000-essential-english-words-63'),
	('By morning, the sled was finished','Sáng hôm sau, chiếc xe trượt tuyết đã hoàn thành','00:00:52.400','00:00:54.300','4000-essential-english-words-63'),
	('Mike called Joe on the telephone','Mike gọi điện cho Joe','00:00:54.300','00:00:56.700','4000-essential-english-words-63'),
	('He said, "Hi Joe, come over to my house right away"','Cậu bé nói, "Chào Joe, đến nhà tớ ngay nhé"','00:00:56.700','00:01:00.300','4000-essential-english-words-63'),
	('Joe didn\'t know why Mike wanted him to come over','Joe không biết tại sao Mike lại muốn mình ghé qua nhà','00:01:00.300','00:01:03.400','4000-essential-english-words-63'),
	('When Joe arrived, Mike told him, "Joe, it irritated me the other day when you said mean things about my card to Jane"','Khi Joe tới, Mike nói: "Joe, khi cậu nói những điều nhỏ nhen về tấm thiệp của tớ dành cho Jane, tớ đã rất tức giận"','00:01:03.400','00:01:10.800','4000-essential-english-words-63'),
	('"You weren\'t kidding when you said those mean things"','"Cậu không có ý đùa giỡn tớ khi cậu nói những thứ nhỏ nhen đó"','00:01:10.800','00:01:13.400','4000-essential-english-words-63'),
	('"But I\'m not like you"','"Nhưng tớ không giống như cậu"','00:01:13.400','00:01:14.900','4000-essential-english-words-63'),
	('"I just built this sled, and I\'ll let you ride it with me if you are nice"','"Tớ vừa làm xong cái xe trượt tuyết này, và cậu sẽ lái nó cùng với tớ nếu như cậu tử tế hơn"','00:01:14.900','00:01:19.000','4000-essential-english-words-63'),
	('They became friends, and Joe was grateful that Mike was so nice to him','Họ đã trở thành bạn, và Joe rất biết ơn vì Mike đối đãi rất tốt với cậu','00:01:19.000','00:01:23.800','4000-essential-english-words-63'),
	('He learned that it is more fun to be nice than to be mean','Cậu bé học được rằng trở nên tử tế, tốt đẹp thì vui hơn nhiều so với việc nhỏ nhen, xấu tính','00:01:23.800','00:01:27.400','4000-essential-english-words-63'),

	/* (UUID(),'4000-essential-english-words-64','Tiny Tina','Tina tí hon','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_064.mp3',NULL,'00:00:00.000','00:01:43.000','4000-essential-english-words','NO',64) */
	('In a distant land, there was a kingdom where fairies lived','Ở một vùng đất xa xôi nọ, có một vương quốc là nơi sinh sống của các nàng tiên','00:00:02.800','00:00:06.600','4000-essential-english-words-64'),
	('Tina was a fairy','Tina là một nàng tiên','00:00:06.600','00:00:07.800','4000-essential-english-words-64'),
	('She had yellow curls and wore a dress made of wool','Cô ấy có mái tóc vàng xoăn và mặc một chiếc váy len','00:00:07.800','00:00:10.800','4000-essential-english-words-64'),
	('She always moved with grace','Cô luôn di chuyển với vẻ duyên dáng','00:00:10.800','00:00:12.800','4000-essential-english-words-64'),
	('However, because of her compact size, she was scared of mankind','Dù vậy, vì thân hình nhỏ bé của mình nên cô lo sợ loài người','00:00:12.800','00:00:17.700','4000-essential-english-words-64'),
	('One day, there was an eclipse of the sun','Một ngày nọ, hiện tượng nhật thực xuất hiện','00:00:17.700','00:00:20.400','4000-essential-english-words-64'),
	('The fairies didn\'t know what was happening','Các nàng tiên không biết chuyện gì đang xảy ra','00:00:20.400','00:00:22.600','4000-essential-english-words-64'),
	('They were scared, so they ran away','Họ hoảng loạn và bỏ chạy khắp nơi','00:00:22.600','00:00:25.200','4000-essential-english-words-64'),
	('Tina looked for a place to hide','Tina tìm kiếm một nơi để nấp','00:00:25.200','00:00:27.200','4000-essential-english-words-64'),
	('She found a garden with flowers blooming','Cô ấy tìm thấy một khu vườn với những bông hoa đang nở','00:00:27.200','00:00:29.700','4000-essential-english-words-64'),
	('Tina had a passion for flowers','Tina có một niềm đam mê với những bông hoa','00:00:29.700','00:00:32.100','4000-essential-english-words-64'),
	('She decided to hide there','Cô quyết định trốn ở đó','00:00:32.100','00:00:33.800','4000-essential-english-words-64'),
	('She became sleepy and made a pillow with some leaves','Cô bắt đầu cảm thấy buồn ngủ và đã làm một chiếc gối từ những chiếc lá','00:00:33.800','00:00:37.200','4000-essential-english-words-64'),
	('She whistled happily as she worked, and she fell asleep','Cô vừa làm vừa huýt sáo một cách vui vẻ và sau đó ngủ thiếp đi','00:00:37.200','00:00:41.100','4000-essential-english-words-64'),
	('Suddenly, somebody sneezed','Đột nhiên, có ai đó hắt xì','00:00:41.100','00:00:43.300','4000-essential-english-words-64'),
	('The sound woke Tina up','Tiếng động đánh thức Tina','00:00:43.300','00:00:45.000','4000-essential-english-words-64'),
	('She saw a very big face looking at her','Cô nhìn thấy một khuôn mặt rất lớn đang nhìn mình','00:00:45.000','00:00:47.800','4000-essential-english-words-64'),
	('Tina was so scared that she couldn\'t move','Tina hoảng sợ đến mức cô không thế nào di chuyển được','00:00:47.800','00:00:50.100','4000-essential-english-words-64'),
	('She could feel her pulse going very fast','Cô có thể cảm thấy mạch của mình đang đập rất nhanh','00:00:47.800','00:00:53.100','4000-essential-english-words-64'),
	('The big woman went into her house','Người đàn bà to lớn đi vào nhà của bà','00:00:53.100','00:00:55.200','4000-essential-english-words-64'),
	('When she came back, she gave Tina a cup','Khi bà trở lại, bà ta đưa cho Tina một chiếc cốc','00:00:55.200','00:00:58.700','4000-essential-english-words-64'),
	('The woman sat on the ground among some decaying leaves','Người phụ nữ to lớn ngồi xuống đất giữa những chiếc lá mục nát','00:00:58.700','00:01:02.100','4000-essential-english-words-64'),
	('Tina dipped a finger in the cup and tasted it','Tina nhúng một ngón tay vào chiếc cốc và nếm thử','00:01:02.100','00:01:05.300','4000-essential-english-words-64'),
	('It was tea with all kinds of delicious spices in it','Đó là một tách trà với tất cả các vị tuyệt vời trong đó','00:01:05.300','00:01:08.700','4000-essential-english-words-64'),
	('Tina felt refreshed after drinking the tea','Tina cảm thấy sảng khoái sau khi uống tách trà ấy','00:01:08.700','00:01:11.500','4000-essential-english-words-64'),
	('"I\'m Wilma," the lady said','"Ta là Wilma", người phụ nữ nói','00:01:11.500','00:01:13.500','4000-essential-english-words-64'),
	('"I spend all my leisure time in my garden cutting flowers"','"Ta dành tất cả thời gian rảnh của mình để cắt tỉa những bông hoa này"','00:01:13.500','00:01:17.200','4000-essential-english-words-64'),
	('"Would you like some dessert?"','"Cháu có muốn ăn một chút món tráng miệng không?"','00:01:17.200','00:01:19.000','4000-essential-english-words-64'),
	('Tina said yes','Tina đồng ý','00:01:19.000','00:01:20.300','4000-essential-english-words-64'),
	('She was hungry, and she wasn\'t frightened anymore','Nàng tiên đói và cô chẳng còn lo sợ gì nữa','00:01:20.300','00:01:23.200','4000-essential-english-words-64'),
	('She took a bite of cake and relaxed','Cô cắn một miếng bánh và cảm thấy rất thoải mái','00:01:23.200','00:01:25.700','4000-essential-english-words-64'),
	('"How did you get to my garden?"','"Làm sao cháu tới được khu vườn của ta?"','00:01:25.700','00:01:27.800','4000-essential-english-words-64'),
	('Tina told Wilma how she got lost','Tina kể cho Wilma chuyện cô bị lạc như thế nào','00:01:27.800','00:01:29.900','4000-essential-english-words-64'),
	('"That\'s terrible"','"Điều đó thật là tệ"','00:01:29.900','00:01:31.300','4000-essential-english-words-64'),
	('"Let us take you home"','"Chúng ta hãy đưa cháu về nhà nào"','00:01:31.300','00:01:33.000','4000-essential-english-words-64'),
	('"Actually, I think that I want to stay with you," Tina said','"Thật ra cháu nghĩ cháu muốn ở đây với cô," Tina nói','00:01:33.000','00:01:36.800','4000-essential-english-words-64'),
	('She wasn\'t scared of big people anymore','Tina không còn sợ những người khổng lồ nữa','00:01:36.800','00:01:39.600','4000-essential-english-words-64'),
	('Wilma and Tina lived happily ever after','Wilma và Tina sống hạnh phúc mãi mãi về sau','00:01:39.600','00:01:43.000','4000-essential-english-words-64'),

	/* (UUID(),'4000-essential-english-words-65','Trick or treat','Xin kẹo hay bị ghẹo','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_065.mp3',NULL,'00:00:00.000','00:01:40.000','4000-essential-english-words','NO',65) */
	('Many different cultures have had traditions about the dead','Nhiều nền văn hóa khác nhau có những tín ngưỡng khác nhau về cái chết','00:00:02.800','00:00:06.300','4000-essential-english-words-65'),
	('People in places like Ireland, China, Egypt and Mexico believed that souls needed food','Chẳng hạn như người Ai-len, Trung Quốc, Ai cập, Mê-xi-cô tin rằng những linh hồn cũng cần đồ ăn','00:00:06.300','00:00:12.500','4000-essential-english-words-65'),
	('They thought the food nourished them on their journey from cemeteries to heaven','Họ nghĩ rằng thức ăn sẽ nuôi dưỡng những linh hồn trong chuyến đi từ nghĩa địa tới thiên đàng','00:00:12.500','00:00:16.900','4000-essential-english-words-65'),
	('People had to put out good things for souls to eat','Người ta phải cho linh hồn những thứ thật ngon để ăn','00:00:16.900','00:00:20.100','4000-essential-english-words-65'),
	('However, if the food rotted or spoiled, the soul got mad','Mặc dù vậy, nếu như thức ăn thối rữa hay bị hỏng, thì linh hồn sẽ tức giận','00:00:20.100','00:00:24.000','4000-essential-english-words-65'),
	('The wicked soul might curse the family and make them starve during the winter','Linh hồn độc ác có thể sẽ nguyền rủa những gia đình đó và khiến họ bị đói trong suốt mùa đông','00:00:24.000','00:00:28.200','4000-essential-english-words-65'),
	('In other places, people begged for food on a holiday that remembers the souls of dead saints','Ở những nơi khác, người dân đi xin đồ ăn trong một ngày lễ để tưởng nhớ linh hồn của các vị thánh','00:00:28.200','00:00:33.900','4000-essential-english-words-65'),
	('People wore disguises with hoods that covered their faces','Người ta sẽ mặc đồ hóa trang với mũ trùm đầu để che mặt mình','00:00:33.900','00:00:37.700','4000-essential-english-words-65'),
	('If they did not get food, they played a trick on the home','Nếu họ không lấy được đồ ăn họ sẽ trêu ghẹo gia đình đó','00:00:37.700','00:00:41.100','4000-essential-english-words-65'),
	('For this reason, the activity is known as "trick-or-treating"','Chính bởi lí do này mà hoạt động đó được biết đến với cái tên là "Xin kẹo hay bị ghẹo"','00:00:41.100','00:00:44.900','4000-essential-english-words-65'),
	('Shortly after people first began trick-or-treating, parents started sending their children to beg on that day','It lâu sau hoạt động này nhận được sự hưởng ứng của nhiều người, bố mẹ thường đưa những đứa trẻ của họ đi xin đồ ăn vào ngày đó','00:00:44.900','00:00:51.900','4000-essential-english-words-65'),
	('Housewives gave the children food if they performed a song or a dance','Những bà mẹ sẽ thưởng cho bọn trẻ đồ ăn sau khi chúng biểu diễn ca hát hay nhảy múa','00:00:51.900','00:00:56.000','4000-essential-english-words-65'),
	('When people moved to America from all over the world, they brought this tradition with them','Khi người dân di cư đến Mĩ từ khắp nơi trên thế giới, họ đã mang theo tập tục này','00:00:56.000','00:01:01.200','4000-essential-english-words-65'),
	('Inhabitants of villages started trick-or-treating in the early 1900s','Người dân ở các ngôi làng bắt đầu với câu nói Xin kẹo hay bị ghẹo vào đầu những năm 1900','00:01:01.200','00:01:05.400','4000-essential-english-words-65'),
	('In 1939 a children\'s publication acquainted the whole country with the tradition','Vào năm 1939,trẻ em trên toàn quốc bắt đầu được làm quen với tập tục đó','00:01:05.400','00:01:10.900','4000-essential-english-words-65'),
	('It became very popular','Kể từ đó , tập tục này trở nên rất phổ biến','00:01:10.900','00:01:13.000','4000-essential-english-words-65'),
	('Today, trick-or-treaters are not begging for food, and they are not scared of souls','Ngày nay, những người chơi "Xin kẹo hay bị ghẹo" không còn đi xin đồ ăn, và họ cũng không sợ những linh hồn nữa','00:01:13.000','00:01:17.300','4000-essential-english-words-65'),
	('They just enjoy the thrill of dressing up like creatures and getting candy','Họ chỉ tận hưởng sự vui sướng khi được hóa trang thành các sinh vật và đi xin kẹo','00:01:17.300','00:01:22.000','4000-essential-english-words-65'),
	('Ghosts and skeletons are favorite costumes','Hồn ma và bộ xương là những trang phục được yêu thích','00:01:22.000','00:01:25.000','4000-essential-english-words-65'),
	('But some children wear fancy disguises, like pirates','Một số trả em lại mặc đồ hóa trang trong đặc biệt, như là cướp biển','00:01:25.000','00:01:28.800','4000-essential-english-words-65'),
	('They carry flashlights instead of fires','Chúng mang theo đèn pin thay vì mang đuốc','00:01:28.800','00:01:31.400','4000-essential-english-words-65'),
	('In some places, children still perform songs or riddles to get candy','Ở một vài nơi, trẻ em vẫn biểu diễn các bài hát hoặc câu đố để được nhận kẹo','00:01:31.400','00:01:35.900','4000-essential-english-words-65'),
	('But most of the time, they just say "Trick or Treat"','Nhưng phần lớn ngày nay, họ chỉ thường nói "Xin kẹo hay bị ghẹo"','00:01:35.900','00:01:40.000','4000-essential-english-words-65');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-66','The Senator and the Worm','Ngài thượng nghị sĩ và con sâu','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_066.mp3',NULL,'00:00:00.000','00:01:34.000','4000-essential-english-words','NO',66) */
	('A rich senator lived in a big house','Có một vị thượng nghị sĩ giàu có nọ sống trong một ngôi nhà rất lớn','00:00:03.500','00:00:05.900','4000-essential-english-words-66'),
	('He had more money than anyone in his district','Ông ta có nhiều tiền hơn bất cứ ai trong quận của mình','00:00:05.900','00:00:08.900','4000-essential-english-words-66'),
	('One day, he was sitting on a chair listening to a radio broadcast','Một ngày nọ, ông ta ngồi trên ghế và nghe đài phát thanh','00:00:08.900','00:00:13.000','4000-essential-english-words-66'),
	('As he listened to the news bulletin, a worm crawled from underneath the chair and onto his head','Khi ông ta đang ngồi nghe thông báo thì bỗng có một con sâu bò từ bên dưới chiếc ghế lên đầu ông ta','00:00:13.000','00:00:18.900','4000-essential-english-words-66'),
	('His cook was in the kitchen stirring some spaghetti sauce','Đầu bếp của ông đang ở trong bếp khuấy món mì spaghetti','00:00:18.900','00:00:22.100','4000-essential-english-words-66'),
	('Suddenly, a cry from the senator alerted him','Bỗng nhiên tiếng khóc của ngài nghị sĩ khiến cho anh ta chú ý','00:00:22.100','00:00:25.100','4000-essential-english-words-66'),
	('He ran to the rear of the house where the senator was sitting','Anh ta liền chạy tới phía rìa sau của ngôi nhà nơi mà ngài nghị sĩ đang ngồi','00:00:25.100','00:00:28.300','4000-essential-english-words-66'),
	('The cook looked and saw the worm','Anh đầu bếp nhìn và thấy con sâu','00:00:28.300','00:00:30.400','4000-essential-english-words-66'),
	('He tried to console the senator','Anh ta cố gắng giải vây cho ngài nghị sĩ','00:00:30.400','00:00:32.900','4000-essential-english-words-66'),
	('"I\'ll take it off right away," he said','"Tôi sẽ lấy nó ra ngay đây," anh nói','00:00:32.900','00:00:34.900','4000-essential-english-words-66'),
	('"No" shouted the senator','"Không" ngài nghị sĩ hét lên','00:00:34.900','00:00:36.900','4000-essential-english-words-66'),
	('"I want you to kill it"','Tôi muốn anh hãy giết nó đi','00:00:36.900','00:00:38.200','4000-essential-english-words-66'),
	('"But it\'s only a worm," the cook said','"Nhưng nó chỉ là một con sâu thôi mà," người đầu bếp nói','00:00:38.200','00:00:41.000','4000-essential-english-words-66'),
	('"Why should we execute it?"','"Tại sao chúng ta phải giết nó?"','00:00:41.000','00:00:42.500','4000-essential-english-words-66'),
	('"It hasn\'t committed a crime"','Nó chẳng gây nên tội tình gì cả','00:00:42.500','00:00:44.100','4000-essential-english-words-66'),
	('The senator could not endure the worm on his head','Ngài nghị sĩ không thể chịu đựng được con sâu ở trên đầu nữa','00:00:44.100','00:00:47.300','4000-essential-english-words-66'),
	('"Hurry" he shouted','"Nhanh lên" ông ta quát','00:00:47.300','00:00:49.400','4000-essential-english-words-66'),
	('The cook looked through several drawers, but found nothing','Người đầu bếp nhìn vào cái ngăn kéo nhưng không thấy gì hết','00:00:49.400','00:00:52.900','4000-essential-english-words-66'),
	('Then he ran to the closet and took out a pipe','Anh ta chạy đến nhà vệ sinh và lấy một cái ống','00:00:52.900','00:00:55.300','4000-essential-english-words-66'),
	('He returned to the senator and lifted the pipe over his head','Anh trở lại chỗ ngài nghị sĩ và đưa chiếc ống lên đầu ngài','00:00:55.300','00:00:59.000','4000-essential-english-words-66'),
	('He knew he couldn\'t just tap the worm','Anh biết là anh không thể chỉ đập nhẹ vào con sâu','00:00:59.000','00:01:01.100','4000-essential-english-words-66'),
	('He was going to hit it hard','Anh ta sẽ đập nó thật mạnh','00:01:01.100','00:01:03.100','4000-essential-english-words-66'),
	('He grasped the pipe tightly','Anh cầm chiếc ống thật chặt','00:01:03.100','00:01:05.700','4000-essential-english-words-66'),
	('"What are you waiting for?" said the senator','"Anh còn chờ đợi gì nữa?" ngài nghị sĩ nói','00:01:05.700','00:01:07.700','4000-essential-english-words-66'),
	('"Kill it"','"Giết nó đi"','00:01:07.700','00:01:08.700','4000-essential-english-words-66'),
	('The cook swung the pipe at the senator\'s head','Anh đầu bếp vung chiếc ống vào đầu ngài nghị sĩ','00:01:08.700','00:01:11.000','4000-essential-english-words-66'),
	('"Oh, no," the worm said','"Ôi, không," con sâu nói','00:01:11.000','00:01:13.000','4000-essential-english-words-66'),
	('"He\'s going to chop me in half"','"Anh ta sẽ chặt mình làm đôi mất"','00:01:13.000','00:01:14.800','4000-essential-english-words-66'),
	('It jumped off the senator\'s head','Và rồi nó nhảy khỏi đầu của ngài nghị sĩ','00:01:14.800','00:01:17.000','4000-essential-english-words-66'),
	('There was a tremendous noise','Một tiếng động lớn vang lên','00:01:17.000','00:01:19.000','4000-essential-english-words-66'),
	('"Owww" cried the senator','"Owww" ngài nghị sĩ bật khóc','00:01:19.000','00:01:21.300','4000-essential-english-words-66'),
	('A bump rose upon his skull','Một cục u mọc trên đầu của ông ta','00:01:21.300','00:01:23.700','4000-essential-english-words-66'),
	('Meanwhile, the worm crawled outside','Trong khi đó, con sâu đang bò ở bên ngoài','00:01:23.700','00:01:26.500','4000-essential-english-words-66'),
	('"That was close," said the worm','"Suýt nữa thì chết," con sâu nói','00:01:26.500','00:01:28.100','4000-essential-english-words-66'),
	('"Instead of being nice, he wanted to hurt me"','"Thay vì tỏ ra ngoan ngoãn thì hắn ta lại muốn làm hại mình"','00:01:28.100','00:01:30.900','4000-essential-english-words-66'),
	('"Now, that man has a big bump on his head"','"Giờ thì hắn có một cái u rất lớn trên đầu rồi nhé"','00:01:30.900','00:01:34.000','4000-essential-english-words-66'),

	/* (UUID(),'4000-essential-english-words-67','Patsy Ann','Patsy Ann','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_067.mp3',NULL,'00:00:00.000','00:01:37.200','4000-essential-english-words','NO',67) */
	('A long time ago in Alaska, a dog named Patsy Ann watched the horizon','Cách đây rất lâu, ở Alaska, có một chú chó tên là Pasty Ann luôn nhìn về phía chân trời','00:00:03.000','00:00:08.100','4000-essential-english-words-67'),
	('Every day, she waited by the bay for ships returning from an expedition','Hằng ngày, cô đợi những con tàu trở về từ chuyến đi thám hiểm ở vịnh','00:00:08.100','00:00:13.000','4000-essential-english-words-67'),
	('Patsy Ann was a brilliant dog, and she was very unique','Pasty Ann là một nàng cún rất thông minh, và cô ấy rất đặc biệt','00:00:13.000','00:00:16.300','4000-essential-english-words-67'),
	('She was deaf','Cô ấy bị điếc','00:00:16.300','00:00:17.600','4000-essential-english-words-67'),
	('She couldn\'t bark, either','Cô ấy cũng không thể sủa được','00:00:17.600','00:00:19.700','4000-essential-english-words-67'),
	('But she used all of her other senses to know when a ship was near','Nhưng cô dùng tất cả các giác quan của mình để biết được khi nào có con tàu đến gần','00:00:19.700','00:00:24.000','4000-essential-english-words-67'),
	('Patsy Ann lived on the streets','Pasty Ann sống ở trên những con phố','00:00:24.000','00:00:26.100','4000-essential-english-words-67'),
	('Her owners did not want her because she could not hear','Người chủ của cô không muốn nhận nuôi cô vì cô không thể nghe được gì','00:00:26.100','00:00:29.400','4000-essential-english-words-67'),
	('So they abandoned her','Vì vậy mà họ đã bỏ rơi cô','00:00:29.400','00:00:31.000','4000-essential-english-words-67'),
	('She found refuge in a fancy hotel','Sau đó, cô đã tìm được nơi ẩn náu ở một khách sạn tuyệt đẹp','00:00:31.000','00:00:33.800','4000-essential-english-words-67'),
	('Guests rubbed her back and scratched her chin','Những vị khách ở đó thường xoa lưng và gãi cằm cô','00:00:33.800','00:00:36.800','4000-essential-english-words-67'),
	('Many people gave her food','Và rất nhiều người cho cô thức ăn','00:00:36.800','00:00:38.800','4000-essential-english-words-67'),
	('She became quite overweight','Cô trở nên hơi thừa cân','00:00:38.800','00:00:40.800','4000-essential-english-words-67'),
	('She became very famous','Cô trở nên rất nổi tiếng','00:00:40.800','00:00:42.400','4000-essential-english-words-67'),
	('Visitors to Alaska were enthusiastic about meeting her','Khách du lịch ở Alaska rất háo hức với việc gặp cô','00:00:42.400','00:00:46.000','4000-essential-english-words-67'),
	('They brought presents for her','Họ mang những món quà tới cho cô','00:00:46.000','00:00:48.000','4000-essential-english-words-67'),
	('They liked seeing her and the feeling was mutual','Họ thích được gặp cô và cô cũng cảm thấy như vậy','00:00:48.000','00:00:50.800','4000-essential-english-words-67'),
	('The mayor said Patsy Ann should be called the town\'s greeter','Ngài thị trưởng nghĩ rằng Pasty Ann nên được gọi là người chào mừng của thành phố','00:00:50.800','00:00:54.700','4000-essential-english-words-67'),
	('The people in town loved Patsy Ann, too, even though she lived on the streets','Mọi người trong thị trấn đều yêu mến Pasty Ann mặc dù cô sống trên những con phố','00:00:54.700','00:00:59.400','4000-essential-english-words-67'),
	('They were willing to fight to keep her','Họ sẵn sàng chiến đấu để có thể giữ cô lại','00:00:59.400','00:01:01.700','4000-essential-english-words-67'),
	('A new law made all dogs wear a collar and get shots','Một luật mới bắt buộc tất cả chó phải đeo vòng cổ và tiêm phòng','00:01:01.700','00:01:05.800','4000-essential-english-words-67'),
	('The mayor received many complaints','Ngài thị trưởng nhận được rất nhiều lời phàn nàn','00:01:05.800','00:01:08.100','4000-essential-english-words-67'),
	('People wanted Patsy Ann to be able to stay','Mọi người đều muốn Pasty Ann có thể ở lại','00:01:08.100','00:01:11.400','4000-essential-english-words-67'),
	('One ambitious sailor got people to help','Một anh thủy thủ đầy tham vọng đã kêu gọi sự giúp đỡ của mọi người','00:01:11.400','00:01:14.200','4000-essential-english-words-67'),
	('Together, they paid for Patsy Ann to go to the veterinarian','Đó là mọi người cùng nhau góp tiền để đưa Pasty Ann tới bác sĩ thú y','00:01:14.200','00:01:18.600','4000-essential-english-words-67'),
	('She got her shots and collar','Cuối cùng, cô ấy đã được tiêm phòng và đeo vòng','00:01:18.600','00:01:20.600','4000-essential-english-words-67'),
	('She could stay','Cô đã có thể ở lại','00:01:20.600','00:01:22.000','4000-essential-english-words-67'),
	('When Patsy Ann died, everyone missed the town\'s loyal greeter','Khi Pasty Ann mất, mọi người đều nhớ thương người chào mừng trung thành của thị trấn','00:01:22.000','00:01:26.300','4000-essential-english-words-67'),
	('So the mayor hired someone to make a statue of Patsy Ann','Vậy nên ngài thị trưởng đã cho người tạc một bức tượng Pasty Ann','00:01:26.300','00:01:30.400','4000-essential-english-words-67'),
	('He restored the town\'s greeter','Ông đã mang người chào mừng của thị trấn trở lại với mọi người','00:01:30.400','00:01:32.600','4000-essential-english-words-67'),
	('Now, she sits at the dock forever, waiting for ships to come home','Giờ đây, cô mãi mãi có thể được ngồi ở bến tàu chờ đợi những con tàu trở về nhà','00:01:32.600','00:01:37.200','4000-essential-english-words-67'),

	/* (UUID(),'4000-essential-english-words-68','The Anniversary Gift','Món quà kỷ niệm','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_068.mp3',NULL,'','','4000-essential-english-words','NO',68) */
	('Joe was a carpenter','Joe là một thợ mộc','','','4000-essential-english-words-68'),
	('He built houses in the highlands','Anh xây những ngôi nhà trên thảo nguyên','','','4000-essential-english-words-68'),
	('Joe\'s wife Stella used a needle and thread to sew elegant clothing','Vợ của Joe là Stella thường dùng kim và chỉ để may những bộ quần áo tao nhã','','','4000-essential-english-words-68'),
	('She only used beautiful fabric to make clothes','Cô ấy chỉ sử dụng những tấm vải thật đẹp để may trang phục','','','4000-essential-english-words-68'),
	('Since they didn\'t have a lot of money, they lived in an old shed','Bởi vì họ không có nhiều tiền nên sống trong một căn nhà cũ','','','4000-essential-english-words-68'),
	('Water dripped in when it rained','Nước mưa nhỏ giọt xuống căn nhà khi trời mưa','','','4000-essential-english-words-68'),
	('They had broken chairs instead of a couch','Họ dùng những chiếc ghế gãy thay vì ghế sofa','','','4000-essential-english-words-68'),
	('But they had coal for heat, and flour from the mill for bread','Nhưng họ có than để sưởi ấm và bột từ cối xay gió để làm bánh mì','','','4000-essential-english-words-68'),
	('Together, they trimmed the bushes to make their house look nice','Họ cùng nhau cắt tỉa những bụi cây để ngôi nhà trông thật đẹp','','','4000-essential-english-words-68'),
	('Joe and Stella were poor, but not ashamed','Joe và Stella đều nghèo nhưng họ không xấu hổ','','','4000-essential-english-words-68'),
	('They were happy','Họ sống rất hạnh phúc','','','4000-essential-english-words-68'),
	('Sometimes in the evening, they walked downtown','Thi thoảng vào buổi tối, họ đi bộ xuống thị trấn','','','4000-essential-english-words-68'),
	('They looked in store windows and dreamed','Họ nhìn qua cửa kính của các cửa hàng và mơ ước','','','4000-essential-english-words-68'),
	('Stella wanted a hairbrush with an ivory handle','Stella muốn có một chiếc lược với tay cầm làm từ ngà','','','4000-essential-english-words-68'),
	('She pulled her hair upwards every day because she didn\'t have a brush to make it nice','Cô ấy chỉ vén tóc lên trên mỗi ngày vì cô không có một chiếc lược nào để khiến mái tóc trông đẹp hơn','','','4000-essential-english-words-68'),
	('Joe wanted to fix his grandfather\'s watch','Joe lại muốn sửa chiếc đồng hồ đeo tay của ông nội anh','','','4000-essential-english-words-68'),
	('For their anniversary, Stella wanted to get Joe what he wanted','Ngày kỷ niệm của họ, Stella muốn làm điều Joe muốn','','','4000-essential-english-words-68'),
	('But then she did the arithmetic','Nhưng lúc đó cô thử tính toán','','','4000-essential-english-words-68'),
	('It would take at least six months to save enough money','Để sửa được chiếc đồng hồ, cô sẽ mất ít nhất 6 tháng để tiết kiệm tiền','','','4000-essential-english-words-68'),
	('Then she had an idea','Sau đó cô nghĩ ra một ý tưởng','','','4000-essential-english-words-68'),
	('She cut off all of her hair and sold it','Đó là cô ấy đã cắt mái tóc của mình và bán nó','','','4000-essential-english-words-68'),
	('Meanwhile, Joe knew that he could never fix his watch','Trong khi đó, Joe biết rằng anh ấy có thể không bao giờ sửa được chiếc đồng hồ của mình','','','4000-essential-english-words-68'),
	('So he polished it and sold it','Nên anh ấy đã làm bóng và bán nó đi','','','4000-essential-english-words-68'),
	('He made enough to buy the brush','Anh ấy đã có đủ tiền để mua chiếc lược','','','4000-essential-english-words-68'),
	('On their anniversary, the door burst open','Vào ngày kỉ niệm của họ, cánh cửa mở tung ra','','','4000-essential-english-words-68'),
	('Joe was excited to give Stella his gift','Joe thích thú tặng cho Stella món quà của mình','','','4000-essential-english-words-68'),
	('But first, Stella gave him the money to fix the watch','Nhưng trước tiên, Stella đã đưa số tiền sửa đồng hồ cho Joe','','','4000-essential-english-words-68'),
	('When he saw his wife without any hair, he smiled','Khi nhìn thấy vợ mình không còn chút tóc nào, anh mỉm cười','','','4000-essential-english-words-68'),
	('"I sold my watch to buy you something," Joe said','"Anh đã bán chiếc đồng hồ của mình để mua cho em món quà này," Joe nói','','','4000-essential-english-words-68'),
	('He gave her the brush, and she laughed','Anh ấy đưa cô chiếc lược và cô cười','','','4000-essential-english-words-68'),
	('They were both willing to give up something very special to make each other happy','Cả hai bọn họ sẵn sàng từ bỏ những thứ quan trọng với mình để khiến người kia hạnh phúc','','','4000-essential-english-words-68'),

	/* (UUID(),'4000-essential-english-words-69','Dalton vs the Bully','Dalton và kẻ thất bại','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_069.mp3',NULL,'','','4000-essential-english-words','NO',69) */
	('Dalton was a nice boy, but sometimes the other boys made fun of him because he was so tall and skinny','Dalton từng là một cậu bé ngoan, nhưng đôi khi những cậu bé khác chế giễu cậu vì cậu rất cao và gầy','','','4000-essential-english-words-69'),
	('Dalton\'s biggest problem was Mitch','Vấn đề lớn nhất của Dalton là Mitch','','','4000-essential-english-words-69'),
	('He was a bully who boasted about his strength','Cậu ấy là một kẻ bắt nạt người khoác lác về sức mạnh của mình','','','4000-essential-english-words-69'),
	('He quarreled with the other boys','Cậu ấy đã cãi nhau với những cậu bé khác','','','4000-essential-english-words-69'),
	('Sometimes, if boys gave Mitch their lunch money, he would have mercy and leave them alone','Đôi khi, nếu những cậu bé khác đưa cho Mitch tiền ăn trưa của chúng, cậu ấy sẽ có lòng từ bi và để chúng yên','','','4000-essential-english-words-69'),
	('One day, the boys learned about a special Middle School Olympics','Một ngày, đám bọn con trai học về Thế vận hội trung học','','','4000-essential-english-words-69'),
	('Their gym class was going to be in it','Lớp thể hình định ở trong đó','','','4000-essential-english-words-69'),
	('Many kids were excited','Rất nhiều đứa trẻ đã hào hứng','','','4000-essential-english-words-69'),
	('But Dalton thought it sounded like torture','Nhưng Dalton đã nghĩ nó nghe như là tra tấn vậy','','','4000-essential-english-words-69'),
	('That morning, Dalton ate plenty of carbohydrates for breakfast','Buổi sáng đó, Dalton đã ăn vô vàn hydrat cacbon cho bữa sáng','','','4000-essential-english-words-69'),
	('He entered the gym and looked at the dial on the clock','Cậu đi vào phòng gym và nhìn vào bề mặt chiếc đồng hồ','','','4000-essential-english-words-69'),
	('It was time to begin','Đã tới giờ tập','','','4000-essential-english-words-69'),
	('The teacher asked if they were ready','Thầy giáo yêu cầu chúng chuẩn bị','','','4000-essential-english-words-69'),
	('Everyone nodded, except Dalton','Mọi người gật đầu, trừ Dalton','','','4000-essential-english-words-69'),
	('"I got stung by a bee"','"Em bị ong đốt"','','','4000-essential-english-words-69'),
	('"I need to see the nurse" said Dalton','"Em cần tới gặp y tá" Dalton nói','','','4000-essential-english-words-69'),
	('He made it up so he wouldn\'t have to play','Cậu bịa chuyện này để không phải chơi','','','4000-essential-english-words-69'),
	('"I don\'t believe you"','"Tôi không tin cậu"','','','4000-essential-english-words-69'),
	('"Get ready to play," responded the coach','"Chuẩn bị chơi đi," thầy giáo trả lời','','','4000-essential-english-words-69'),
	('First, they wrestled','Đầu tiên, chúng vật nhau','','','4000-essential-english-words-69'),
	('Then they jumped, crawled and played other games','Sau đó chúng nhảy lên, bò và chơi games','','','4000-essential-english-words-69'),
	('But Mitch was dominant in every event','Nhưng Mitch thắng thế ở mọi sự kiện','','','4000-essential-english-words-69'),
	('They strained all morning to defeat him','Chúng căng sức cả buổi sáng để đánh bại cậu','','','4000-essential-english-words-69'),
	('By lunch, they were sore','Tới bữa trưa, chúng thấy buồn phiền','','','4000-essential-english-words-69'),
	('Their entire bodies ailed them','Cả cơ thể chúng đau mỏi','','','4000-essential-english-words-69'),
	('They thought about how to win','Chúng nghĩ cách chiến thắng','','','4000-essential-english-words-69'),
	('They knew the last game of the day was volleyball','Chúng biết trò chơi cuối cùng của ngày là bóng chuyền','','','4000-essential-english-words-69'),
	('Kids who used to be Dalton\'s rivals became his allies','Những đứa trẻ thông thường là đối thủ của Dalton trở thành đồng minh của cậu','','','4000-essential-english-words-69'),
	('They wanted him to help them beat Mitch','Chúng muốn cậu ta giúp chúng đánh bại Mitch','','','4000-essential-english-words-69'),
	('Dalton was going to be Mitch\'s opponent','Dalton đã định trở thành đối thủ của Mitch','','','4000-essential-english-words-69'),
	('The game started','Trò chơi bắt đầu','','','4000-essential-english-words-69'),
	('Every time Mitch tried to hit the ball over the net, Dalton stopped it','Mỗi lần Mitch cố gắng đánh quả bóng qua cái lưới, Dalton đã chặn nó','','','4000-essential-english-words-69'),
	('Finally, Mitch used all of his strength','Cuối cùng, Mitch đã sử dụng tất cả sức mạnh của mình','','','4000-essential-english-words-69'),
	('But the ball bounced off Dalton\'s hands and back into Mitch\'s face','Nhưng quả bóng đã nảy khỏi tay của Dalton và đập trở lại mặt của Mitch','','','4000-essential-english-words-69'),
	('Finally Mitch was defeated','Cuối cùng Mitch đã bị đánh bại','','','4000-essential-english-words-69'),

	/* (UUID(),'4000-essential-english-words-70','Anna the Babysitter','Cô trông trẻ Anna','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_070.mp3',NULL,'','','4000-essential-english-words','NO',70) */
	('Since her parents got a divorce, Anna has had to help her mother','Từ khi ba mẹ ly hôn, Anna đã phải phụ giúp mẹ của mình','','','4000-essential-english-words-70'),
	('In her mother\'s absence, Anna takes care of Grace, the baby','Trong khi mẹ đi vắng, Anna chăm sóc cho em gái tên là Grace','','','4000-essential-english-words-70'),
	('At first, Anna thought it was an easy job','Lúc đầu, Anna nghĩ rằng đó là một công việc dễ dàng','','','4000-essential-english-words-70'),
	('One afternoon, Anna played with Grace','Vào một buổi chiều, Anna chơi cùng Grace','','','4000-essential-english-words-70'),
	('She meowed like a cat and Grace imitated her','Anna kêu meo meo như một con mèo và Grace bắt chước','','','4000-essential-english-words-70'),
	('In fact, Grace reproduced every sound that Anna made','Sự thật là Grace nhái lại từng âm thanh mà Anna tạo ra','','','4000-essential-english-words-70'),
	('She took her sister outside','Cô đưa em gái của mình ra ngoài','','','4000-essential-english-words-70'),
	('She put Grace in the wagon, but there was nowhere for them to go','Anna đặt Grace vào một chiếc xe đẩy cho trẻ em, nhưng họ không biết đi đâu','','','4000-essential-english-words-70'),
	('So they went back inside','Vậy nên họ lại trở về nhà','','','4000-essential-english-words-70'),
	('Anna put the infant on the floor and went into her room','Anna đặt đứa trẻ sơ sinh trên sàn nhà và đi vào phòng mình','','','4000-essential-english-words-70'),
	('But when she came back, Grace had vanished','Nhưng khi cô quay lại, Grace đã biến mất','','','4000-essential-english-words-70'),
	('Anna looked everywhere, but she could not find her sister','Anna tìm kiếm khắp mọi nơi, nhưng không thể nào tìm thấy em gái mình','','','4000-essential-english-words-70'),
	('Maybe the baby had been kidnapped','Có lẽ Grace đã bị bắt cóc','','','4000-essential-english-words-70'),
	('"Where are you?", Anna called aloud','"Em ở đâu?", Anna gọi lớn','','','4000-essential-english-words-70'),
	('The situation was becoming urgent','Tình hình trở nên cấp bách','','','4000-essential-english-words-70'),
	('She wanted to call her mom, but she didn\'t want her to think Anna couldn\'t do the job','Cô muốn gọi mẹ nhưng lại không muốn bà nghĩ là mình không thể làm được việc','','','4000-essential-english-words-70'),
	('Anna sat down','Anna ngồi xuống','','','4000-essential-english-words-70'),
	('What was she going to do?','Cô sẽ phải làm gì đây?','','','4000-essential-english-words-70'),
	('But then, Anna heard something','Nhưng ngay lúc đó, Anna nghe thấy tiếng gì đó','','','4000-essential-english-words-70'),
	('It was coming from her room','Nó phát ra từ phòng của mình','','','4000-essential-english-words-70'),
	('"Grace?"','"Grace?"','','','4000-essential-english-words-70'),
	('She got down on her knees and looked under the bed','Cô quỳ xuống và nhìn xuống gầm giường','','','4000-essential-english-words-70'),
	('She could see Grace\'s bald head','Cô có thế nhìn thấy cái đầu trọc của Grace','','','4000-essential-english-words-70'),
	('Grace had followed Anna into her room and crept under the bed','Grace đã theo Anna vào phòng và bò dưới gầm giường','','','4000-essential-english-words-70'),
	('"What a relief" Anna cried','"Thật là nhẹ nhõm!", Anna bật khóc','','','4000-essential-english-words-70'),
	('She picked up her sister and patted her on the head','Cô bế đứa em gái lên và vỗ về','','','4000-essential-english-words-70'),
	('Her head was soft and had no wrinkles','Đầu Grace thật là mềm mượt và không có vết nhăn','','','4000-essential-english-words-70'),
	('Grace was sucking on her thumb and looked tired','Grace mút ngón tay và trông có vẻ mệt mỏi','','','4000-essential-english-words-70'),
	('So, Anna wrapped her in a blanket and sang rhymes for her','Vì thế Anna quấn Grace vào một chiếc khăn và hát ru','','','4000-essential-english-words-70'),
	('Then she put Grace in bed for a nap','Sau đó cô đặt Grace lên giường cho bé nghỉ ngơi','','','4000-essential-english-words-70'),
	('After that afternoon, Anna knew that taking care of Grace was notan easy job','Sau buổi chiều hôm đó, Anna biết rằng việc trông Grace không phải là một công việc dễ dàng','','','4000-essential-english-words-70'),
	('It takes a lot of work to take care of a baby','Trông một đứa trẻ sẽ mất rất nhiều công sức','','','4000-essential-english-words-70');

