INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-76','Matthew Learns a Lesson','Matthew học được một bài học','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_076.mp3',NULL,'','','4000-essential-english-words','NO',76) */
	('Matthew was a sensible boy','Matthew là một cậu bé nhạy cảm','','','4000-essential-english-words-76'),
	('He always kept his room tidy and had a natural literary aptitude','Cậu ấy luôn giữ cho căn phòng của mình gọn gàng và có khuynh hướng văn học tự nhiên','','','4000-essential-english-words-76'),
	('One day, he hoped to have a career in journalism','Một ngày, cậu ấy đã hy vọng sẽ có một sự nghiệp trong ngành báo chí','','','4000-essential-english-words-76'),
	('The adolescent spent much of his time reading and liked having privacy','Người thiếu niên đã dành phần lớn thời gian của cậu vào việc đọc và thích có không gian riêng tư','','','4000-essential-english-words-76'),
	('But his quiet personality hindered his ability to make friends','Nhưng tính cách im lặng của cậu đã cản trở khả năng kết bạn','','','4000-essential-english-words-76'),
	('One day, Matthew went to the pharmacy to pick up some pills for his grandmother','Một ngày, Matthew đã tới hiệu thuốc mua vài viên thuốc cho bà','','','4000-essential-english-words-76'),
	('He saw some boys leaning against a pole outside','Cậu nhìn thấy vài cậu bé đang đứng dựa cột học bên ngoài','','','4000-essential-english-words-76'),
	('One of the boys complimented Matthew','Một trong số cậu bé đó khen Matthew','','','4000-essential-english-words-76'),
	('"I like your jacket"','"Tớ thích cái áo khoác của cậu"','','','4000-essential-english-words-76'),
	('"Another boy asked," Do you want to go to Nate\'s Restaurant?"','Một cậu bé khác hỏi "Bạn có muốn đi tới nhà hàng của Nate không?"','','','4000-essential-english-words-76'),
	('"Sure" Matthew said','"Chắc chắn rồi" Matthew nói','','','4000-essential-english-words-76'),
	('The boys walked to the restaurant','Bọn trẻ đi bộ tới nhà hàng','','','4000-essential-english-words-76'),
	('They were going to have slices of pizza','Chúng sẽ ăn vài lát pizza','','','4000-essential-english-words-76'),
	('They ordered their food and drank soda with straws','Chúng gọi đồ ăn và uống soda với ống hút','','','4000-essential-english-words-76'),
	('They ate until their bellies swelled up','Chúng ăn tới khi cái bụng căng phồng lên','','','4000-essential-english-words-76'),
	('Matthew was having so much fun','Matthew đã rất vui vẻ','','','4000-essential-english-words-76'),
	('One of the boys said, "Let\'s leave without paying"','Một trong số đám bọn con trai nói, "Hãy rời đi mà không phải trả tiền"','','','4000-essential-english-words-76'),
	('Matthew didn\'t want to','Matthew không muốn như vậy','','','4000-essential-english-words-76'),
	('But he presumed his new friends wouldn\'t like him if he didn\'t','Nhưng anh ấy cho rằng những người bạn mới của mình cũng không thích anh ấy nếu anh ấy không muốn thế','','','4000-essential-english-words-76'),
	('Suddenly, the waiter yelled, "Stop"','Đột nhiên, người hầu bàn hét lên : "Dừng lại"','','','4000-essential-english-words-76'),
	('The two other boys ran, leaving Matthew there alone','Hai đứa con trai chạy lẹ, để Matthew ở đó một mình','','','4000-essential-english-words-76'),
	('Soon, the police arrived','Sớm sau đó, cảnh sát tới','','','4000-essential-english-words-76'),
	('"Leaving without paying for your meal is the same as stealing," said the police officer','"Rời đi mà không trả tiền thì không khác nào ăn cắp cả," ngài cảnh sát viên chức nói','','','4000-essential-english-words-76'),
	('"The restaurant wants justice"','"Nhà hàng muốn có sự công bằng"','','','4000-essential-english-words-76'),
	('"So next week you have to go to court and let a jury decide your punishment"','"Vì vậy tuần sau bạn phải tới tòa án và để ban hội thẩm quyết định mức án phạt của mình"','','','4000-essential-english-words-76'),
	('When he went to court, the judge asked, "Do you have anything to say, Matthew?"','Khi anh ấy đi tới tòa án, ngài bồi thẩm phán hỏi "Bạn có điều gì để nói không, Matthew?"','','','4000-essential-english-words-76'),
	('He said, "I feel sorrow for what I\'ve done"','"Anh ấy nói, "Tôi cảm thấy buồn vì những gì tôi đã làm"','','','4000-essential-english-words-76'),
	('"Now I know that real friends won\'t ask you to do something illegal"','"Bây giờ tôi biết rằng những người bạn thực sự sẽ không yêu cầu tôi làm những việc phạm tội"','','','4000-essential-english-words-76'),
	('The jury then let him have his liberty','Ngài bồi thẩm sau đó để anh ấy có sự tự do','','','4000-essential-english-words-76'),
	('But they made Matthew pick up trash as punishment','Nhưng họ ép Matthew đi nhặt rác như một hình phạt','','','4000-essential-english-words-76'),
	('Much to Matthew\'s surprise, he ended up meeting some new friends','Matthew thật sự rất ngạc nhiên, anh ấy cuối cùng đã gặp được những người bạn mới','','','4000-essential-english-words-76'),

	/* (UUID(),'4000-essential-english-words-77','The Magic Cup','Chiếc cốc thần kỳ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_077.mp3',NULL,'','','4000-essential-english-words','NO',77) */
	('Paul and John were brothers','Paul và John là hai anh em','','','4000-essential-english-words-77'),
	('They fought all the time because they both wanted to be leaders of the agency they both worked at','Cả hai đấu đá nhau suốt ngày vì hai người đều muốn trở thành lãnh đạo của cơ quan mà họ đang cùng làm','','','4000-essential-english-words-77'),
	('There was a superstition in their town about a magic cup','Có một điều mê tín về một chiếc cốc thần kì ở nơi mà họ sống','','','4000-essential-english-words-77'),
	('People said the cup was in a volcano located far away','Người ta nói chiếc cốc nằm trong một ngọn núi lửa ở vị trí rất xa','','','4000-essential-english-words-77'),
	('Anyone who retrieved the cup would have their wish come true','Bất cứ ai tìm và lấy được chiếc cốc thì điều ước của họ sẽ trở thành hiện thực','','','4000-essential-english-words-77'),
	('John and Paul both wanted to find it','Cả John và Paul đều muốn tìm thấy chiếc cốc đó','','','4000-essential-english-words-77'),
	('Then they could become the leader','Để sau đó họ có thể trở thành lãnh đạo','','','4000-essential-english-words-77'),
	('They both left to find the cup','Cả hai cùng rời đi để tìm chiếc cốc','','','4000-essential-english-words-77'),
	('Before their trip, their mother said they should work together','Trước chuyến đi, mẹ của họ khuyên rằng họ nên hợp tác với nhau','','','4000-essential-english-words-77'),
	('They dismissed that idea','Nhưng họ đã bác bỏ ý kiến đó','','','4000-essential-english-words-77'),
	('Even though their trips originated from the same house, each wanted to travel alone','Mặc dù chuyến đi của họ cùng xuất phát từ một ngôi nhà nhưng mỗi người lại muốn đi riêng','','','4000-essential-english-words-77'),
	('They were both miserable during the trip','Cả hai đều gặp khó khăn trong suốt chuyến đi','','','4000-essential-english-words-77'),
	('They had to navigate small boats across shallow rivers and climb difficult slopes','Họ phải lái chiếc thuyền nhỏ đi qua nhiều con sông cạn và họ còn phải leo lên những con dốc gian nan','','','4000-essential-english-words-77'),
	('Their journey spanned many days','Chuyến đi của hai anh em kéo dài rất nhiều ngày','','','4000-essential-english-words-77'),
	('When they finally got close to the volcano, the ground began to vibrate and the volcano erupted','Khi họ đến gần ngọn núi lửa, mặt đất bắt đầu rung chuyển và núi lửa thì phun trào','','','4000-essential-english-words-77'),
	('Ash filled the sky and lava covered everything','Tro bụi đầy trời và dung nham thì che phủ mọi thứ','','','4000-essential-english-words-77'),
	('John climbed to the top of a hill to keep from getting burned','John trèo lên đỉnh đồi để tránh bị bỏng','','','4000-essential-english-words-77'),
	('A few moments later, his brother went up the same hill','Một lúc sau, anh trai cậu cũng leo lên ngọn đồi đó','','','4000-essential-english-words-77'),
	('They were confined to the hill until the lava cooled down','Cả hai buộc phải ở lại trên đồi cho tới khi dung nham nguội đi','','','4000-essential-english-words-77'),
	('They talked about the things they had seen while wandering around the country','Trong khoảng thời gian đó, họ nói với nhau về những thứ mình đã nhìn thấy khi đi lang thang quanh vùng đất','','','4000-essential-english-words-77'),
	('They felt more sympathy and affection for each other than ever before','Họ cảm thấy đồng cảm và quý mến nhau hơn bao giờ hết','','','4000-essential-english-words-77'),
	('They decided that fate had brought them together','Họ quyết định rằng số phận đã đưa họ đến với nhau','','','4000-essential-english-words-77'),
	('The next day they left to finish the remainder of the trip together','Ngày hôm sau, cả hai rời đi và cùng nhau hoàn thành phần còn lại của chuyến đi','','','4000-essential-english-words-77'),
	('Everything seemed much easier','Dường như mọi thứ trở nên dễ dàng hơn rất nhiều','','','4000-essential-english-words-77'),
	('When they finally found the cup, they learned that it didn\'t make wishes come true','Khi mà họ cuối cùng cũng tìm thấy được chiếc cốc, họ mới biết rằng nó không thể biến điều ước thành hiện thực','','','4000-essential-english-words-77'),
	('It was only an ordinary cup','Nó chỉ là một chiếc cốc bình thường','','','4000-essential-english-words-77'),
	('But the trip to reach the cup taught them to work together and love each other','Nhưng chuyến đi tìm chiếc cốc đã dạy cho họ một bài học về cách làm việc cùng nhau và yêu thương lẫn nhau','','','4000-essential-english-words-77'),

	/* (UUID(),'4000-essential-english-words-78','The Knight\'s Plan','Kế hoạch của hiệp sĩ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_078.mp3',NULL,'','','4000-essential-english-words','NO',78) */
	('A town was fighting for their independence from another country','Một thị trấn đang diễn ra chiến tranh để giành lại độc lập từ một quốc gia khác','','','4000-essential-english-words-78'),
	('Several rebels started a revolution','Một số người nổi loạn bắt đầu thực hiện những cuộc nổi loạn chống đối','','','4000-essential-english-words-78'),
	('However, they were afraid of an invasion from a lot of troops','Tuy nhiên, họ sợ một cuộc xâm lược đến từ nhiều quân đội','','','4000-essential-english-words-78'),
	('They didn\'t have enough warriors to stop them, so they asked a knight for help','Họ đã không đủ chiến binh để ngăn cản họ, vì thế họ cầu cứu sự giúp từ một người kỵ sĩ','','','4000-essential-english-words-78'),
	('The knight made a plan','Người kỵ sĩ đã tạo ra một kế hoạch','','','4000-essential-english-words-78'),
	('A tall mountain was outside the town','Có một ngọn núi cao bên ngoài thị trấn','','','4000-essential-english-words-78'),
	('The road near the top was very narrow','Con đường gần đến đỉnh rất hẹp','','','4000-essential-english-words-78'),
	('Cliffs rose on both sides of it','Có những vách đá dựng đứng ở cả hai bên đường','','','4000-essential-english-words-78'),
	('"We must trick the enemy"','"Chúng ta phải lừa được kẻ địch"','','','4000-essential-english-words-78'),
	('"They have to follow us up the mountain," the knight explained','"Để chúng đi theo ta lên núi" chàng kỵ sĩ giải thích','','','4000-essential-english-words-78'),
	('"On the narrow path, only a few can attack us at one time"','"Trong con đường hẹp đó, chỉ có vài tên địch có thể tấn công ta lúc đó"','','','4000-essential-english-words-78'),
	('The people agreed with the knight\'s plan','Mọi người đều đồng ý với kế hoạch của người kỵ sĩ','','','4000-essential-english-words-78'),
	('The knight put on his armor, and the warriors got their spears','Chàng kỵ sĩ mặc áo giáp, và những chiến binh cầm binh khí của họ lên','','','4000-essential-english-words-78'),
	('When the enemy attacked, the knight and warriors acted as if they were afraid','Khi quân địch bị tấn công, người kỵ sĩ và các chiến binh đã hành động như thể họ rất gan dạ','','','4000-essential-english-words-78'),
	('They quickly withdrew toward the mountain','Họ nhanh chóng rút về ngọn núi','','','4000-essential-english-words-78'),
	('The enemy troops followed them up the steep path','Quân giặc đuổi theo họ lên con đường dốc','','','4000-essential-english-words-78'),
	('Soon, the enemy became tired','Ngay lập tức, quân giặc trở nên đuối sức','','','4000-essential-english-words-78'),
	('At the summit, the knight and his troops stopped','Ở trên đỉnh núi, kỵ sĩ và binh lính của anh ấy đã bị cản lại','','','4000-essential-english-words-78'),
	('The enemy was close behind them','Quân địch đã đến gần phía sau họ','','','4000-essential-english-words-78'),
	('But now they were tired','Nhưng hiện tại chúng đang rất mệt','','','4000-essential-english-words-78'),
	('Also, only a few could attack because the path was narrow','Vì thế, chỉ có vài người có thể chiến đấu bởi vì con đường đó rất hẹp','','','4000-essential-english-words-78'),
	('The knight and the warriors fought the enemy','Chàng kỵ sĩ mặc áo giáp, và những chiến binh cầm binh khí của họ lên','','','4000-essential-english-words-78'),
	('But there were too many troops','Nhưng hiện tại chúng đang rất mệt','','','4000-essential-english-words-78'),
	('The knight was afraid','Chàng kỵ sĩ khá lo lắng','','','4000-essential-english-words-78'),
	('If the warriors yielded the path to the enemy, the town would be lost','Nếu những binh lính đầu hàng với quân địch, thị trấn của họ sẽ bị chiếm','','','4000-essential-english-words-78'),
	('A storm suddenly came over the mountain','Một cơn bão lớn bất ngờ xuất hiện trên ngọn núi','','','4000-essential-english-words-78'),
	('There was strong wind and rain','Có một trận gió mạnh và mưa','','','4000-essential-english-words-78'),
	('Thunder boomed','Sấm sét rất lớn','','','4000-essential-english-words-78'),
	('Lightning struck some trees near the enemy','Sét đánh vào một vài cành cây gần quân địch','','','4000-essential-english-words-78'),
	('The trees blazed','Những cái cây đó cháy sáng','','','4000-essential-english-words-78'),
	('The flames scared the enemy and they retreated','Những ngọn lửa khiến quân địch sợ hãi và họ đã rút lui','','','4000-essential-english-words-78'),
	('They ran down the mountain, out of the town, and never returned','Họ chạy về chân núi, rút ra khỏi thị trấn, và không bao giờ quay trở lại nữa','','','4000-essential-english-words-78'),
	('The knight explained, "With a little luck, a good plan beats even a big army"','Chàng kỵ sĩ đã giải thích thêm rằng, "Nhờ vào một chút may mắn, kế hoạch của chúng ta đã đánh bại một quân đội lớn"','','','4000-essential-english-words-78'),

	/* (UUID(),'4000-essential-english-words-79','The Magic Pear Tree','Cây lê ma thuật','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_079.mp3',NULL,'','','4000-essential-english-words','NO',79) */
	('It was a cool morning, and the grass was covered in mist','Đó là một buổi sáng mát mẻ, và cỏ được bọc trong sương mù','','','4000-essential-english-words-79'),
	('The market was full of people','Khu chợ đông kín người','','','4000-essential-english-words-79'),
	('A mean farmer named Jack yelled, "Pears for sale"','Một người nông dân tên Jack đã hét lên, "Bán lê đây"','','','4000-essential-english-words-79'),
	('He sat on a bench, plotting how he could trick people','Ông ấy ngồi trên một chiếc ghế bành, vẽ sơ đồ ông ấy có thể lừa người khác như thế nào','','','4000-essential-english-words-79'),
	('Then an orphan came to his cart','Sau đó một đứa trẻ mồ côi tới quầy hàng của ông','','','4000-essential-english-words-79'),
	('"Can you spare a pear?" she asked','"Ông có thể chia cho cháu một quả lê được chứ?" Cô bé hỏi','','','4000-essential-english-words-79'),
	('Jack felt rage','Jack cảm thấy phẫn nộ','','','4000-essential-english-words-79'),
	('He replied, "You don\'t have any money"','Ông ấy đáp, "Cháu không có một xu dính túi"','','','4000-essential-english-words-79'),
	('"Please, I haven\'t had supper in days"','"Làm ơn, tôi đã không ăn tối trong nhiều ngày rồi"','','','4000-essential-english-words-79'),
	('"No" shouted the farmer','"Không" người nông dân quát lên','','','4000-essential-english-words-79'),
	('The orphan sighed','Đứa bé mồ côi thở dài','','','4000-essential-english-words-79'),
	('However, a pregnant lady heard the dispute and confronted Jack','Tuy nhiên, một người phụ nữ bụng chửa đã nghe thấy cuộc tranh luận và đã đương đầu với Jack','','','4000-essential-english-words-79'),
	('"Just give her a pear," she said','"Cứ đưa cho cô ấy 1 quả lê," bà nói','','','4000-essential-english-words-79'),
	('Jack had no shame and said no','Jack không hề có tí xấu hổ nào và đã nói không','','','4000-essential-english-words-79'),
	('Finally, a man bought a pear for the girl','Cuối cùng, một người đàn ông đã mua một quả lê cho cô gái','','','4000-essential-english-words-79'),
	('The girl quickly ate it, but she saved the seed','Một cô gái ăn nó nhanh chóng, nhưng cô ấy đã giữ lại hạt giống','','','4000-essential-english-words-79'),
	('She wanted to get revenge','Cô ấy đã muốn trả thù','','','4000-essential-english-words-79'),
	('She told Jack, "I know a way to get hundreds of pears in one day"','Cô ấy bảo với Jack, "Tôi biết một cách để có hàng trăm quả lê trong một ngày"','','','4000-essential-english-words-79'),
	('"I\'ll show you how"','"Tôi sẽ cho bạn thấy như thế nào"','','','4000-essential-english-words-79'),
	('He watched the girl dig a hole','Ông ấy đã xem cô bé đào một cái hố','','','4000-essential-english-words-79'),
	('She dropped the seed into the ground','Cô ấy đã thả những hạt giống vào đất','','','4000-essential-english-words-79'),
	('Then she spread the dirt over it','Rồi cô rải đất lên nó','','','4000-essential-english-words-79'),
	('"Watch closely," she said','"Nhìn gần đi," cô ấy nói','','','4000-essential-english-words-79'),
	('"In a few minutes, a stem will grow"','"Trong một vài phút, một thân cây mọc lên"','','','4000-essential-english-words-79'),
	('"It\'ll turn into a tree that\'s full of pears"','"Nó trở thành một cái cây đầy quả lê"','','','4000-essential-english-words-79'),
	('Jack stared at the dirt, but nothing happened','Jack đã nhìn chằm chằm vào vết bẩn, nhưng không chuyện gì xảy ra cả','','','4000-essential-english-words-79'),
	('The only objects there were a few daisies','Những thứ duy nhất là một vài cây hoa cúc','','','4000-essential-english-words-79'),
	('He looked for the girl, but she had snuck away','Anh ấy đã tìm cô gái, nhưng cô đã lẻn đi mất','','','4000-essential-english-words-79'),
	('Then he looked at his cart in horror','Sau đó anh ấy nhìn vào cái giỏ hàng của mình trong sự kinh hoàng','','','4000-essential-english-words-79'),
	('It was empty','Nó trống rỗng','','','4000-essential-english-words-79'),
	('He suddenly realized that the orphan had tricked him','Ông đột nhiên nhận ra rằng đứa trẻ mồ côi đã lừa mình','','','4000-essential-english-words-79'),
	('While Jack was waiting for the tree to grow, the people had taken the pears from his cart','Trong khi Jack đang đợi cái cây lớn, mọi người đã lấy những quả lê khỏi cái giỏ hàng của ông ta','','','4000-essential-english-words-79'),
	('They all laughed while they were eating the tender fruit','Họ đều cười trong khi họ đang ăn những trái cây còn non','','','4000-essential-english-words-79'),
	('The farmer felt ashamed','Người nông dân đã cảm thấy xấu hổ','','','4000-essential-english-words-79'),
	('The incident taught him to be kinder','Tình tiết đã dạy cho ông trở nên tử tế hơn','','','4000-essential-english-words-79'),

	/* (UUID(),'4000-essential-english-words-80','Little Wolf and Mother Wolf','Sói con và sói mẹ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_080.mp3',NULL,'','','4000-essential-english-words','NO',80) */
	('Mother Wolf was a magnificent animal','Sói Mẹ là một con thú đẹp lộng lẫy','','','4000-essential-english-words-80'),
	('She had all the traits of a terrific hunter','Cô ấy có mọi tính cách của một con thú săn mồi đáng sợ','','','4000-essential-english-words-80'),
	('She was very strong and fast','Cô ấy rất mạnh mẽ và nhanh','','','4000-essential-english-words-80'),
	('She knew how to hide and how to seize prey','Cô biết cách để trốn và bắt con mồi','','','4000-essential-english-words-80'),
	('Mother Wolf was the forest\'s supreme creature','Mẹ Sói là sinh vật tối cao của rừng già','','','4000-essential-english-words-80'),
	('Her skills were evident to all the other animals','Những kĩ năng của cô được làm chứng tới mọi động vật khác','','','4000-essential-english-words-80'),
	('Mother Wolf lived in a den beneath a tree with her cub, Little Wolf','Mẹ Sói sống trong hang thú dữ dưới một cái cây với thú con, Sói Con','','','4000-essential-english-words-80'),
	('At dawn, Little Wolf and Mother Wolf were eating breakfast','Lúc bình minh, Sói Con và Mẹ Sói ăn bữa sáng','','','4000-essential-english-words-80'),
	('Little Wolf looked sad','Sói Con trông có vẻ buồn','','','4000-essential-english-words-80'),
	('Mother Wolf said, "What is wrong, my cub?"','Mẹ Sói nói, "Chuyện gì sai sót, thú con của ta?"','','','4000-essential-english-words-80'),
	('Little Wolf said, "I want to be big like you"','Sói Con đáp, "Con muốn lớn như mẹ"','','','4000-essential-english-words-80'),
	('"You can run and leap better than anyone"','"Con có thể chạy và nhảy tốt hơn bất kì ai"','','','4000-essential-english-words-80'),
	('"You can howl so loudly"','"Mẹ có thể gào rú thật to"','','','4000-essential-english-words-80'),
	('"Being big is a necessity, and I am so small"','"Là một quân to là điều cần thiết, và con thì rất nhỏ"','','','4000-essential-english-words-80'),
	('Mother Wolf said, "Don\'t be dissatisfied with your size"','Mẹ Sói nói, "Đừng trở nên không hài lòng với kích cỡ của mình"','','','4000-essential-english-words-80'),
	('"Being small can be very helpful sometimes"','"Là một con nhỏ đôi khi còn có thể hữu dụng đấy"','','','4000-essential-english-words-80'),
	('Just then, rain and hail began to fall','Đúng lúc đó, mưa và mưa đá bắt đầu rơi','','','4000-essential-english-words-80'),
	('The tree was hit by lightning','Cành cây bị đánh trúng bởi sét','','','4000-essential-english-words-80'),
	('It fell on the wolves\' den','Nó rơi xuống sào huyệt của những chú chó sói','','','4000-essential-english-words-80'),
	('Little Wolf was scared','Sói Con thấy sợ','','','4000-essential-english-words-80'),
	('The wolves knew that escaping the den was vital','Nó biết trốn chạy khỏi hang thú dữ là điều quan trọng cho sự tồn tại','','','4000-essential-english-words-80'),
	('Mother Wolf said, "Little Wolf, I cannot move the heavy pile of branches"','Mẹ Sói đã nói, "Sói Con, mẹ không thể di chuyển cọc nặng của các nhánh"','','','4000-essential-english-words-80'),
	('"But you can escape with ease"','"Nhưng con có thể trốn chạy dễ dàng"','','','4000-essential-english-words-80'),
	('"You can get out and find help"','"Con hãy đi ra khỏi và tìm sự giúp đỡ"','','','4000-essential-english-words-80'),
	('Little Wolf crawled out of the den and called all the large animals for help','Sói Con bò ra khỏi hang thú dữ và gọi tất cả các con thú lớn tới giúp','','','4000-essential-english-words-80'),
	('They went to the den and pulled away the branches','Họ đến hang thú và kéo những nhánh cây đi','','','4000-essential-english-words-80'),
	('Mother Wolf came out and said, "Thankyou Little Wolf"','Mẹ Sói bước ra và nói, "Cảm ơn, Sói Con"','','','4000-essential-english-words-80'),
	('"You saved my life"','"Con đã cứu sống cuộc đời mẹ"','','','4000-essential-english-words-80'),
	('She softly squeezed Little Wolf and kissed her',' Cô siết nhẹ Sói Con và hôn nó','','','4000-essential-english-words-80'),
	('Little Wolf smiled','Sói Con mỉm cười','','','4000-essential-english-words-80'),
	('She said, "Mother, this outcome has taught me a profound lesson"','Cô nói, "Mẹ, hậu quả này đã dạy con một bài học sâu sắc"','','','4000-essential-english-words-80'),
	('"Even though I\'m small, I\'m still important"','"Mặc dù con còn nhỏ, con vẫn quan trọng"','','','4000-essential-english-words-80');

