INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-81','The Old Man with a Bump','Ông già với một cái bướu','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_081.mp3',NULL,'','','4000-essential-english-words','NO',81) */
	('An old man had a large bump on his face','Một ông già có một cái bướu lớn trên mặt','','','4000-essential-english-words-81'),
	('He went to the best physician in town','Ông đi tới gặp một thầy thuốc giỏi nhất trong thị trấn','','','4000-essential-english-words-81'),
	('He gave the old man tragic news: "I can\'t do anything"','Người thầy thuốc đưa ông một tin buồn: "Tôi không thể làm bất cứ điều gì cả"','','','4000-essential-english-words-81'),
	('"You\'ll have to get accustomed to it"','"Ông sẽ phải làm quen với nó"','','','4000-essential-english-words-81'),
	('One day, the old man went into the forest','Một ngày, ông già đi vào rừng','','','4000-essential-english-words-81'),
	('Suddenly, the light became dim','Bỗng nhiên, ánh sáng trở nên lờ mờ','','','4000-essential-english-words-81'),
	('It was going to rain','Trời sắp mưa','','','4000-essential-english-words-81'),
	('So he found a hollow tree to sit under','Ông ta tìm thấy một cái cây rỗng để ngồi trú bên trong','','','4000-essential-english-words-81'),
	('It leaked a little, but there was no other place he could wait','Nó bị dột nước một chút, nhưng không còn nơi nào khác để trú','','','4000-essential-english-words-81'),
	('When the rain stopped, his joints felt stiff from sitting','Khi mưa tạnh, các khớp xương của ông ta cảm thấy cứng đơ vì ngồi lâu','','','4000-essential-english-words-81'),
	('Suddenly, he heard a tune coming from far away','Đột nhiên, ông nghe thấy một giai điệu từ xa vọng lại','','','4000-essential-english-words-81'),
	('Many fables said monsters lived in the forest','Rất nhiều truyền thuyết nói về những con quái vật sống ở trong rừng','','','4000-essential-english-words-81'),
	('No one could affirm that the stories were true, though','Tuy nhiên, chưa một ai có thể xác nhận rằng câu chuyện đó là đúng','','','4000-essential-english-words-81'),
	('Still, his instincts told him that there was something out there','Bản năng ông ta mách bảo rằng có gì đó đang ở ngoài kia','','','4000-essential-english-words-81'),
	('He walked farther into the forest','Ông ta đi sâu hơn vào trong rừng','','','4000-essential-english-words-81'),
	('Then he saw a fire glowing','Sau đó ông nhìn thấy một đống lửa đang cháy rực','','','4000-essential-english-words-81'),
	('He was astonished to see a clan of monsters','Ông ta ngạc nhiên khi nhìn thấy một đám quái vật','','','4000-essential-english-words-81'),
	('They were having a great feast and banging on drums','Chúng đang có một bữa tiệc lớn và đang đánh trống','','','4000-essential-english-words-81'),
	('He stood behind a tree, spying on them','Ông nấp sau cái cây theo dõi họ','','','4000-essential-english-words-81'),
	('Then the leader asked, "Who\'s the best dancer here?"','Rồi tên đầu đàn hỏi, "Ở đây đứa nào nhảy giỏi nhất?"','','','4000-essential-english-words-81'),
	('"Me" the man yelled, coming from behind the tree','"Tôi" người đàn ông hét lên rồi bước ra từ sau cái cây','','','4000-essential-english-words-81'),
	('He started to dance','Ông ta bắt đầu nhảy múa','','','4000-essential-english-words-81'),
	('When he was finished, the leader said, "I want you to dance every night"','Khi ông kết thúc, tên đầu đàn nói “ ta muốn ngươi nhảy múa hàng đêm','','','4000-essential-english-words-81'),
	('"In order to make sure you return, I\'m going to keep something you love"','" Để chắc chắn rằng người quay trở lại, ta sẽ giữ lấy thứ ngươi quý"','','','4000-essential-english-words-81'),
	('"Please don\'t take my bump," he begged','"Xin đừng lấy đi cái bướu của tôi," ông ta cầu xin','','','4000-essential-english-words-81'),
	('"I can\'t sacrifice it"','"Tôi không thể hi sinh nó"','','','4000-essential-english-words-81'),
	('"It\'s good luck"','"Nó là vật may mắn của tô"','','','4000-essential-english-words-81'),
	('He exclaimed, pointing at it for emphasis','Ông ta kêu lên, chỉ tay vào cái bướu để nhấn mạnh','','','4000-essential-english-words-81'),
	('The monsters agreed that they had to take his bump','Những con quỷ đồng ý rằng chúng sẽ giữ cái bướu của ông già','','','4000-essential-english-words-81'),
	('After they did, the man stroked his face to make sure it was gone','Sau khi chúng làm vậy, ông già đánh lên mặt mình để chắc chắn rằng cái bướu đã biến mất','','','4000-essential-english-words-81'),
	('He had tricked them','Ông ta đã lừa lũ quái vật','','','4000-essential-english-words-81'),
	('He never went back, and he never had to worry about his bump again','Ông sẽ không bao giờ quay lại và ông cũng sẽ không bao giờ phải lo lắng về cái bướu nữa','','','4000-essential-english-words-81'),

	/* (UUID(),'4000-essential-english-words-82','The Circus','Rạp xiếc','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_082.mp3',NULL,'','','4000-essential-english-words','NO',82) */
	('Ben was unhappy','Ben cảm thấy phiền muộn','','','4000-essential-english-words-82'),
	('He lived on a ranch near a small town, and he didn\'t have many friends','Anh ta đã sống ở một nông trại gần một thị trấn nhỏ, và anh không có nhiều người bạn','','','4000-essential-english-words-82'),
	('Then one day a messenger came to the ranch','Sau đó một ngày nọ một tin nhắn tới trang trại','','','4000-essential-english-words-82'),
	('He showed the headline in the town newspaper','Anh ấy chỉ ra trang đầu trong tờ báo địa phương','','','4000-essential-english-words-82'),
	('The circus was coming to the town','Đám xiếc dự định sẽ tới thị trấn','','','4000-essential-english-words-82'),
	('It even coincided with Ben\'s birthday','Ngày đó trùng với sinh nhật của Ben','','','4000-essential-english-words-82'),
	('Ben was very excited as his father steered the car through the town','Ben đã rất hào hứng vì bố anh đã lái chiếc ô tô vào thị trấn','','','4000-essential-english-words-82'),
	('The circus couldn\'t accommodate all the people who wanted to see the show, but Ben had a ticket','Đám xiếc đã không thể chứa hết tất cả mọi người muốn tới xem buổi biểu diễn, nhưng Ben đã có vé','','','4000-essential-english-words-82'),
	('Ben peered at the activity around him','Ben nhìn chăm chú hoạt động xung quanh anh','','','4000-essential-english-words-82'),
	('He watched people of both genders dance all around','Anh đã xem mọi người cả 2 giới tính nhảy múa xung quanh','','','4000-essential-english-words-82'),
	('They wore funny costumes, and their hair was dyed many different colors','Họ mặc những bộ trang phục buồn cười, và mái tóc của họ được nhuộm rất nhiều màu khác nhau','','','4000-essential-english-words-82'),
	('Also, tame tigers with stripes on their fur did tricks','Cũng vậy, những con hổ được thuần hóa với những chiếc vằn trên bộ lông của chúng đã diễn trò','','','4000-essential-english-words-82'),
	('Outside, M people could commission an informal portrait','Bên ngoài, mọi người có thể đặt mua một bức chân dung tùy sở thích cá nhân','','','4000-essential-english-words-82'),
	('They posed in front of a funny picture while an artist quickly drew them','Họ sắp đặt ở tư thế đứng trước bức tranh vui nhộn trong khi một họa sĩ đã nhanh chóng vẽ lại họ','','','4000-essential-english-words-82'),
	('Ben couldn\'t believe it','Ben đã không thể tin nổi','','','4000-essential-english-words-82'),
	('He was happier than he had ever been before','Anh ấy đã vui mừng hơn anh ấy từng có trước đây','','','4000-essential-english-words-82'),
	('That day, Ben knew what he wanted to do','Hôm đó, Ben đã biết anh ấy muốn điều gì','','','4000-essential-english-words-82'),
	('He loved the circus to such an extent that he wanted to have his own circus when he grew older','Anh yêu gánh xiếc tới mức độ rằng anh đã muốn có một gánh xiếc cho riêng mình khi anh lớn hơn','','','4000-essential-english-words-82'),
	('Seeing the circus was like a dose of medicine for him','Xem xiếc như là một liều thuốc cho anh ấy','','','4000-essential-english-words-82'),
	('He wasn\'t unhappy anymore','Anh ấy không còn buồn rầu nữa','','','4000-essential-english-words-82'),
	('He felt special','Anh đã cảm thấy đặc biệt','','','4000-essential-english-words-82'),
	('He inquired about what he needed to do to have his own circus','Anh ấy yêu cầu về điều anh cần có cho gánh xiếc của riêng mình','','','4000-essential-english-words-82'),
	('He studied hard and learned about business','Anh đã chăm chỉ học hành và học về kinh doanh','','','4000-essential-english-words-82'),
	('Ben worked very hard, and one day, he had his own circus','Ben đã làm việc rất chăm và một ngày kia, anh ta đã có được rạp xiếc của riêng mình','','','4000-essential-english-words-82'),
	('It was a great circus','Đó là một gánh xiếc tuyệt vời','','','4000-essential-english-words-82'),
	('People told him that he could be very rich','Mọi người đã bảo với anh là anh có thể rất giàu có','','','4000-essential-english-words-82'),
	('But he wasn\'t tempted by money','Nhưng anh đã không bị cám dỗ bởi đồng tiền','','','4000-essential-english-words-82'),
	('He just wanted to make children happy','Anh chỉ muốn khiến bọn trẻ được vui vẻ thôi','','','4000-essential-english-words-82'),
	('He knew the circus had changed his life, and he wanted to do the same thing for others','Anh biết rằng gánh xiếc đã thay đổi cuộc đời của mình và anh muốn làm điều tương tự cho những người khác','','','4000-essential-english-words-82'),

	/* (UUID(),'4000-essential-english-words-83','Lazy Hans','Hans lười biếng','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_083.mp3',NULL,'','','4000-essential-english-words','NO',83) */
	('Hans was lazy','Hans rất lười biếng','','','4000-essential-english-words-83'),
	('He seldom helped his mother with anything','Anh ta hiếm khi giúp mẹ bất cứ việc gì','','','4000-essential-english-words-83'),
	('He didn\'t cook and he never mowed the lawn','Anh ta không nấu ăn và cũng chẳng bao giờ cắt cỏ','','','4000-essential-english-words-83'),
	('He didn\'t even shave','Thậm chí anh ta còn không cả cạo râu','','','4000-essential-english-words-83'),
	('He spent the daytime gambling with his mother\'s money','Từ sáng tới tối, anh ta chỉ biết dùng tiền của mẹ mình để chơi bài bạc','','','4000-essential-english-words-83'),
	('One day, his mother realized that her money was gone from her purse','Một ngày nọ, mẹ của anh ta phát hiện ra tiền trong ví của bà bị mất','','','4000-essential-english-words-83'),
	('"You\'re banned from my house" she shouted','"Mày bị cấm vào nhà" bà quát lên','','','4000-essential-english-words-83'),
	('"Don\'t come back until you\'ve learned your lesson"','"Đừng quay về cho đến khi mày học được một bài học"','','','4000-essential-english-words-83'),
	('Hans went to live in the forest like an outlaw','Hans lang thang trong rừng và sống như một kẻ phạm tội','','','4000-essential-english-words-83'),
	('But it was cold, and Hans couldn\'t find food','Thế nhưng, ở trong rừng quá lạnh và anh không thể tìm thấy thức ăn','','','4000-essential-english-words-83'),
	('He went to a cottage to ask for a meal','Anh ta đi tới một ngôi nhà tranh để hỏi xin một bữa ăn','','','4000-essential-english-words-83'),
	('An Aborigine answered the door','Một thổ dân đã mở cửa','','','4000-essential-english-words-83'),
	('"Can I stay here please?" Hans asked','"Tôi có thể xin ở lại đây được không?" Hans hỏi','','','4000-essential-english-words-83'),
	('"You can stay ifyou work," the man replied','"Cậu có thể ở đây nếu cậu làm việc," người đàn ông trả lời','','','4000-essential-english-words-83'),
	('Hans liked the prospect of food and warmth, so he agreed','Hans thích cảnh tượng có thức ăn ngon và nơi ở ấm áp, nên anh ta đồng ý','','','4000-essential-english-words-83'),
	('The man pointed to a field','Người đàn ông chỉ tay ra cái cánh đồng','','','4000-essential-english-words-83'),
	('"Take this rod and plant it over there"','"Lấy cái gậy này và cắm nó ở đằng kia"','','','4000-essential-english-words-83'),
	('"I am a wizard, and this magic rod will bring us food"','"Ta là một phù thủy, và cái gậy thần kỳ này sẽ mang đồ ăn tới cho chúng ta"','','','4000-essential-english-words-83'),
	('The field was far away','Cánh đồng ở rất xa','','','4000-essential-english-words-83'),
	('Hans knew it would be hard to walk there','Hans biết rằng để đi bộ đến đó thì rất vất vả','','','4000-essential-english-words-83'),
	('So he just threw the rod behind the cottage and sat by the river','Vì vậy, anh ta ném chiếc gậy đằng sau ngôi nhà và ngồi bên bờ sông','','','4000-essential-english-words-83'),
	('When daylight faded, he returned to the cottage and went to sleep','Khi một ngày sắp tàn, anh ta trở lại ngôi nhà và đi ngủ','','','4000-essential-english-words-83'),
	('The next morning, the old man looked very fierce','Buổi sáng hôm sau, ông già trông rất dữ tợn','','','4000-essential-english-words-83'),
	('"You didn\'t take the rod to the field" he shouted','"Ngươi đã không mang cái gậy tới cánh đồng," ông ta quát lớn','','','4000-essential-english-words-83'),
	('"No," confessed Hans, "it was too far"','"Không," Hans thú nhận, "Chỗ đó quá xa"','','','4000-essential-english-words-83'),
	('"Because of you we have nothing to eat" replied the man','"Bởi vì ngươi mà giờ không ai có gì ăn cả" người đàn ông đáp lờ','','','4000-essential-english-words-83'),
	('Hans was terrified that the man would punish him','Hans sợ rằng người đàn ông sẽ trừng phạt anh ta','','','4000-essential-english-words-83'),
	('So he ran home','Nên Hans chạy về nhà','','','4000-essential-english-words-83'),
	('"Mama" he cried, "I\'m desperate to come back"','"Mẹ ơi" anh ta oà khóc, "Con tuyệt vọng khi quay trở về đây"','','','4000-essential-english-words-83'),
	('His mother was cautious','Mẹ của Hans thận trọng','','','4000-essential-english-words-83'),
	('"Do you promise to work?" she asked','"Con có hứa sẽ làm việc không?" bà hỏi','','','4000-essential-english-words-83'),
	('"Yes" said Hans, "I\'ll never be lazy again"','"Vâng" Hans nói, "Con sẽ không bao giờ lười nhác nữa"','','','4000-essential-english-words-83'),

	/* (UUID(),'4000-essential-english-words-84','The Bremen Town Musicians','Những nhạc sĩ của thị trấn Bremen','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_084.mp3',NULL,'','','4000-essential-english-words','NO',84) */
	('Larry the cow, Harry the rooster and Lester the duck lived on a widow\'s farm','Chú bò Larry, gà trống Harry và chú vịt Lester sống ở trang trại của một góa phụ','','','4000-essential-english-words-84'),
	('They dreamed of playing music in a parade','Cả ba mơ ước được chơi nhạc trong một cuộc diễu hành','','','4000-essential-english-words-84'),
	('One day, the widow went to the lawn where her herd of cattle was grazing','Một ngày, người góa phụ xuống đồng cỏ nơi đang chăn thả đàn gia súc','','','4000-essential-english-words-84'),
	('"I\'ll eat him tomorrow," she said, pointing to Larry','"Mình sẽ ăn nó vào ngày mai," bà nói, chỉ tay vào Larry','','','4000-essential-english-words-84'),
	('Larry wanted to flee, but he didn\'t have the nerve to go by himself','Larry muốn chạy trốn nhưng cậu không có dũng khí đi một mình','','','4000-essential-english-words-84'),
	('Then his friends Lester and Harry showed him a poster','Và sau đó thì bạn của cậu, Lester và Harry cho cậu xem một áp phích quảng cáo','','','4000-essential-english-words-84'),
	('"It\'s for a parade in Bremen"','"Đó là một buổi diễu hành ở Bremen"','','','4000-essential-english-words-84'),
	('"We\'ll go with you, and we can perform our symphony there," Lester said','"Chúng tớ sẽ đi với cậu, và chúng ta có thể biểu diễn bản giao hưởng ở đó," Lester nói','','','4000-essential-english-words-84'),
	('The animals put together a small bundle that held a drum, a flute and a portable microphone','Cả ba gom đồ đạc thành một bó nhỏ bao gồm một cái trống, một cái sáo và một cái micro di động','','','4000-essential-english-words-84'),
	('Then they took their baggage and initiated their long journey','Sau đó chúng lấy hành lý và bắt đầu một chuyến đi dài','','','4000-essential-english-words-84'),
	('They walked down a paved lane all day','Cả ba đi bộ trên một con đường lát gạch cả ngày','','','4000-essential-english-words-84'),
	('That night, they looked in the window of a house','Đêm hôm đó chúng nhìn vào cửa sổ của một ngôi nhà','','','4000-essential-english-words-84'),
	('They saw a group of thieves','Chúng nhìn thấy một toán cướp','','','4000-essential-english-words-84'),
	('They were eating a large dinner and telling stories about their greed and the people they stole from','Bọn trộm đang ăn một bữa tối thịnh soạn và kể những câu chuyện về sự tham lam của bản thân và những người mà họ đã lấy trộm','','','4000-essential-english-words-84'),
	('Lester was an optimist','Lester là một chú vịt lạc quan','','','4000-essential-english-words-84'),
	('He said, "I think we can scare them away"','Cậu nói, "Tớ nghĩ chúng ta có thể dọa bọn chúng chạy mất dép đấy"','','','4000-essential-english-words-84'),
	('Soon, the animals came up with a plan','Cả ba nhanh chóng nghĩ ra một kế hoạch','','','4000-essential-english-words-84'),
	('Harry flew inside and knocked over the lamp','Harry bay vào trong nhà và đập vào cái đèn','','','4000-essential-english-words-84'),
	('"What was that?" screamed a thief as the bulb broke','"Cái gì vậy?" một tên trộm hét lên khi mà bóng đèn vỡ','','','4000-essential-english-words-84'),
	('They could barely see now','Bọn họ không thể thấy gì hết','','','4000-essential-english-words-84'),
	('Then Larry stood on two feet, and Lester flew to the top of his head','Sau đó Larry đứng bằng hai chân, và Lester bay lên đỉnh đầu của Larry','','','4000-essential-english-words-84'),
	('They looked very big','Cả hai trông thật là to lớn','','','4000-essential-english-words-84'),
	('All three of the animals made scary noises','Cả ba con vật tạo ra những âm thanh đáng sợ','','','4000-essential-english-words-84'),
	('The thieves tried to hit the animals','Những tên trộm cố gắng đánh vào những con vật ấy','','','4000-essential-english-words-84'),
	('But Harry flew over them and scratched them','Nhưng Harry đã bay qua đầu những tên trộm và cào bọn họ','','','4000-essential-english-words-84'),
	('"It\'s a phantom" yelled one thief','"Đó là một bóng ma" một tên trộm hét lên','','','4000-essential-english-words-84'),
	('The thieves ran away','Và rồi những tên trộm bỏ chạy','','','4000-essential-english-words-84'),
	('The animals ate and rested','Còn ba con vật thì ăn uống và nghỉ ngơi','','','4000-essential-english-words-84'),
	('The next morning, Larry said, "Why go to Bremen?','Sáng hôm sau, Larry nói, "Tại sao chúng ta phải tới Bremen?"','','','4000-essential-english-words-84'),
	('We can stay here and make music"','"Chúng ta có thể ở đây và tạo ra âm nhạc mà"','','','4000-essential-english-words-84'),
	('And so they remained there and were quite happy','Và thế là họ ở luôn lại đó và sống khá hạnh phúc','','','4000-essential-english-words-84'),

	/* (UUID(),'4000-essential-english-words-85','How Did Greenland Get Its Name?','Greenland đã có tên gọi như thế nào?','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_085.mp3',NULL,'','','4000-essential-english-words','NO',85) */
	('The nation of Greenland isn\'t very green','Quốc gia của Vùng đất màu xanh thực ra không quá xanh','','','4000-essential-english-words-85'),
	('The sun\'s rays don\'t shine there for three whole months','Những tia nắng mặt trời không chiếu ở đó trong 3 tháng ròng','','','4000-essential-english-words-85'),
	('As a result, it\'s covered with snow, ice and frost','Kết quả là nơi đó bị bao phủ bởi tuyết, băng và sương giá','','','4000-essential-english-words-85'),
	('Then how was the name derived?','Vậy thì cái tên đó đã có nguồn gốc như thế nào?','','','4000-essential-english-words-85'),
	('It started with a Viking named Erik the Red','Nó bắt nguồn từ một người Viking có tên là Erik the Red','','','4000-essential-english-words-85'),
	('Erik had many merits','Erik có rất nhiều tài cán','','','4000-essential-english-words-85'),
	('However, there was an underlying problem...he got angry easily','Tuy nhiên, có một vấn đề cơ bản anh ấy rất dễ nổi cáu','','','4000-essential-english-words-85'),
	('People were scared of him','Mọi người đều sợ anh ta','','','4000-essential-english-words-85'),
	('However, he was married to the niece of a very powerful man','Tuy nhiên, anh ấy đã kết hôn với cháu gái của một người đàn ông rất quyền lực','','','4000-essential-english-words-85'),
	('So everybody tried to be nice to him','Vì vậy, mọi người đều cố gắng đối xử tốt với anh ấy','','','4000-essential-english-words-85'),
	('One day, Erik fought with his neighbor and killed him','Một ngày nọ, Erik đánh nhau với người hàng xóm và đã giết chết anh ấy','','','4000-essential-english-words-85'),
	('His consequent punishment was to leave Iceland','Hình phạt hậu quả của anh ấy là phải rời khỏi vùng đất Iceland','','','4000-essential-english-words-85'),
	('Many stories circulated about a land west of Iceland','Có nhiều câu chuyện lan truyền về vùng đất phía Tây của Iceland','','','4000-essential-english-words-85'),
	('But only a fraction of the people in Iceland believed them','Tuy nhiên chỉ có một phần nhỏ người dân của Iceland tin vào điều đó','','','4000-essential-english-words-85'),
	('Still, Erik wanted to find it','Dù vậy, Erik vẫn muốn tìm nơi đó','','','4000-essential-english-words-85'),
	('Erik sailed toward the land via the Atlantic Ocean','Erik đi thuyền về phía đất liền qua Đại Tây Dương','','','4000-essential-english-words-85'),
	('His marine knowledge was good, but the trip was hard','Kiến thức về biển của anh ấy rất tốt, nhưng chuyến đi vẫn gặp nhiều khó khăn','','','4000-essential-english-words-85'),
	('Some of his men drowned','Một số người đi cùng với anh đã chết đuối','','','4000-essential-english-words-85'),
	('Erik\'s lieutenant wanted to resign from his position','Trung úy Erik muốn từ chức','','','4000-essential-english-words-85'),
	('Others thought about committing suicide','Những người khác thậm chí còn nghĩ đến việc tự tử','','','4000-essential-english-words-85'),
	('Suddenly, Erik thought he saw something','Đột nhiên, Erik nghĩ rằng mình đã nhìn thấy gì đó','','','4000-essential-english-words-85'),
	('"I don\'t believe it," said Erik','"Không thể tin được," Erik nói','','','4000-essential-english-words-85'),
	('"It must be an illusion"','"Đó chắc chắn chỉ là sự ảo giác"','','','4000-essential-english-words-85'),
	('But it was no trick - it was the new land','Nhưng chẳng có màn lừa lọc gì ở đây cả - đó thật sự là vùng đất mới','','','4000-essential-english-words-85'),
	('Erik trembled in the cold polar air','Erik run rẩy trong không khí lạnh giá vùng cực địa','','','4000-essential-english-words-85'),
	('He saw that there was ice everywhere','Anh ấy nhìn thấy băng ở khắp mọi nơi','','','4000-essential-english-words-85'),
	('He realized that the ice could keep enemies out','Anh nhận ra rằng băng có thể ngăn chặn kẻ thù','','','4000-essential-english-words-85'),
	('Not even the best navy could invade the new land','Ngay cả hải quân tốt nhất cũng không thể xâm lược vùng đất mới','','','4000-essential-english-words-85'),
	('He could start a new dynasty in his name','Anh ta có thể bắt đầu một vương triều  mới dưới tên của mình','','','4000-essential-english-words-85'),
	('But how could he convince people to live here?','Nhưng làm thế nào anh ta có thể thuyết phục mọi người sống ở đây?','','','4000-essential-english-words-85'),
	('"I\'ll call it ‘Greenland,\'" he said','"Tôi sẽ đặt tên cho nó là \'Greenlan\'," anh ấy nói','','','4000-essential-english-words-85'),
	('Erik\'s plan worked','Kế hoạch của Erik đã thành công','','','4000-essential-english-words-85'),
	('Within two years, over a thousand people moved to Greenland','Trong vòng hai năm, hơn một nghìn người đã chuyển đến Greenland','','','4000-essential-english-words-85'),
	('In the end, Greenland got its name all because of a trick','Cuối cùng, Greenland có tên gọi đó bởi vì một trò đùa','','','4000-essential-english-words-85');

