INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-86','Everyone is Special','Mọi người đều đặc biệt','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_086.mp3',NULL,'','','4000-essential-english-words','NO',86) */
	('When I was young, everything that went wrong in my house seemed to be my fault','Khi tôi còn nhỏ, mọi chuyện xảy ra trong nhà dường như là lỗi của tôi','','','4000-essential-english-words-86'),
	('Once, my brothers tried to make cookies','Một lần,anh em tôi đã thử làm bánh','','','4000-essential-english-words-86'),
	('They blended flour and ginger and made a disgusting paste','Họ trộn bột và gừng và tạo nên một thứ bột nhão đáng kinh tởm','','','4000-essential-english-words-86'),
	('Then they tried to wash it down the drain, but it got all over the floor','Sau đó, họ cố gắng rửa sạch nó xuống cống, nhưng nó đã tràn hết ra sàn','','','4000-essential-english-words-86'),
	('Later, my brothers said that I did it and I had to wipe it up','Thế rồi, các anh tôi nói rằng tôi đã làm việc đó và tôi phải lau nó','','','4000-essential-english-words-86'),
	('I worried that my parents liked them more than me','Tôi lo rằng bố mẹ yêu quý họ hơn tôi','','','4000-essential-english-words-86'),
	('One autumn day, I was sure I would make my parents proud','Vào một ngày thu, tôi đã chắc nịch rằng mình sẽ khiến cho ba mẹ tôi tự hào','','','4000-essential-english-words-86'),
	('I bought a model rocket','Tôi đã mua một mô hình tên lửa','','','4000-essential-english-words-86'),
	('After I put it together, I invited everybody to watch it','Sau khi tôi đã lắp ráp nó, tôi đã mời mọi người đến để xem nó','','','4000-essential-english-words-86'),
	('I wanted my brothers to envy my technical knowledge','Tôi muốn cho những người anh trai của mình ghen tị với kiến thức kỹ thuật của tô','','','4000-essential-english-words-86'),
	('I lit the fuse, but nothing happened','Tôi châm ngòi nổ, nhưng không có chuyện gì xảy ra','','','4000-essential-english-words-86'),
	('"Looks like your fireworks don\'t work"','"Có vẻ như pháo hoa của em không hoạt động rồi"','','','4000-essential-english-words-86'),
	('"I hope you kept the receipt so you can return them," my brother said','Anh mong rằng em vẫn còn giữ hóa đơn để có thể trả lại nó,” anh tôi nói','','','4000-essential-english-words-86'),
	('"It\'s not fireworks" I screamed','"Đó không phải pháo hoa" Tôi hét lên','','','4000-essential-english-words-86'),
	('They were making fun of me again','Họ lại chế giễu tôi','','','4000-essential-english-words-86'),
	('I didn\'t know what went wrong','Tôi không biết chuyện gì đã xảy ra','','','4000-essential-english-words-86'),
	('I hadn\'t altered anything','Tôi không có thay đổi bất cứ thứ gì cả','','','4000-essential-english-words-86'),
	('I quickly moved the wires on the bottom, hoping that would help','Tôi nhanh chóng di chuyển các dây nối ở phía dưới, hy vọng điều đó sẽ hữu ích','','','4000-essential-english-words-86'),
	('Suddenly, the rocket flew up','Đột nhiên, chiếc tên lửa bay lên','','','4000-essential-english-words-86'),
	('We stood aside as it curved through the lawn and ran straight into the mailbox','Chúng tôi đứng sang một bên khi nó uốn cong qua bãi cỏ và chạy thẳng vào hộp thư','','','4000-essential-english-words-86'),
	('Then the mailbox collapsed','Sau đó hộp thư đổ sập xuốn','','','4000-essential-english-words-86'),
	('The rocket was crushed','Chiếc tên lửa tan tành','','','4000-essential-english-words-86'),
	('Embarrassed, I ran inside and hid','Xấu hổ, tôi chạy vào trong trốn','','','4000-essential-english-words-86'),
	('A few minutes later, my mom asked, "Are you OK?"','Vài phút sau, mẹ tôi hỏi, "Con ổn chứ?"','','','4000-essential-english-words-86'),
	('"I just wanted them to be jealous of me for once"','"Con chỉ muốn các anh ghen tị với con chỉ một lần thô"','','','4000-essential-english-words-86'),
	('"Now I see why you and Dad don\'t love me as much as them," I said','"Giờ con đã hiểu tại sao mẹ và ba không yêu thương con như các anh ấy," tôi nói','','','4000-essential-english-words-86'),
	('"That\'s not true" said my mom','Điều đó không đúng" mẹ tôi nói','','','4000-essential-english-words-86'),
	('"See my fingers...each one is different"','"Nhìn tay mẹ này….mỗi ngón đều khác nhau"','','','4000-essential-english-words-86'),
	('"You kids are like my fingers: all are different, but I love them all the same"','"Các con cũng giống như những ngón tay này vậy: tất cả đều khác nhau, nhưng mẹ yêu các con như nhau"','','','4000-essential-english-words-86'),
	('I embraced her','Tôi ôm chặt mẹ','','','4000-essential-english-words-86'),
	('Now I know that my parents love me just as much as my brothers','Giờ thì tôi biết rằng ba mẹ mình yêu tôi cũng nhiều như các anh trai của mình vậy','','','4000-essential-english-words-86'),

	/* (UUID(),'4000-essential-english-words-87','Pizarro and the Inca Gold','Pizarro và vàng ở Inca','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_087.mp3',NULL,'','','4000-essential-english-words','NO',87) */
	('According to rumors, there\'s lots of precious gold hidden in the jungles of Peru','Theo những lời đồn đại, có rất nhiều vàng quý giá được giấu ở trong rừng tại Peru','','','4000-essential-english-words-87'),
	('It got there when the Spanish conquered parts of South America','Vàng được chôn ở đây khi Tây Ban Nha chinh phạt nhiều lãnh thổ ở Bắc Mỹ','','','4000-essential-english-words-87'),
	('The Spanish noble, Francisco Pizarro, arrived in Peru in the 1500s','Một quý tộc Tây Ban Nha, Francisco Pizarro, đã đến Peru vào những năm 1500','','','4000-essential-english-words-87'),
	('He found a group of people called the Incas','Ông ấy tìm thấy một nhóm người gọi là người Incas','','','4000-essential-english-words-87'),
	('The Incas believed that their leader, Atahualpa, was both a king and a god','Người Incas tin rằng người lãnh đạo của họ, Atahualpa, vừa là một vị vua, vừa là một vị thần','','','4000-essential-english-words-87'),
	('But Pizarro didn\'t agree','Nhưng Pizarro không đồng ý với điều đó','','','4000-essential-english-words-87'),
	('"It is a sin for a man to think he is God" he said to Atahualpa','"Đó là một tội lỗi cho người nghĩ ông ta là một vị thần" ông nói với Atahualpa','','','4000-essential-english-words-87'),
	('Atahualpa thought Pizarro was insulting his heritage','Atahualpa nghĩ Pizarro đang xúc phạm di sản của anh ta','','','4000-essential-english-words-87'),
	('He thought the blonde Spanish men held prejudices against the Incas','Anh ta nghĩ người đàn ông Tây Ban Nha tóc vàng có định kiến chống lại người Incas','','','4000-essential-english-words-87'),
	('But Atahualpa was a kind man and didn\'t want to fight the Spaniards','Nhưng Atahualpa là một người đàn ông tốt bụng và không muốn gây sự với người Tây Ban Nha','','','4000-essential-english-words-87'),
	('He said, "If I give you a room full of gold, will you leave my country in peace?"','Anh ta nói, "Nếu ta cho ngươi một căn phòng đầy vàng, ngươi có thể rời khỏi mảnh đất của ta trong hòa bình chứ?"','','','4000-essential-english-words-87'),
	('Pizarro was suspicious','Pizarro rất nghi hoặc','','','4000-essential-english-words-87'),
	('He thought Atahualpa was exaggerating','Ông ta nghĩ Atahualpa đang phóng đại','','','4000-essential-english-words-87'),
	('But a few days later, Pizarro returned to the Inca palace with his ambassadors','Nhưng vài ngày sau, Pizarro trở lại cung điện Inca với đại sứ của ông','','','4000-essential-english-words-87'),
	('He saw a room filled with stacks of gold','Ông nhìn thấy một căn phòng chứa đầy vàng','','','4000-essential-english-words-87'),
	('There were golden necklaces, cups, plates and vases','Ở đó có vòng cổ, cốc, đĩa và những chiếc bình bằng vàng','','','4000-essential-english-words-87'),
	('It was a great spectacle','Đó là một cảnh tượng tuyệt vời','','','4000-essential-english-words-87'),
	('He acknowledged that Atahualpa had told the truth','Ông ta thừa nhận Atahualpa đã nói thật','','','4000-essential-english-words-87'),
	('But after seeing the gold, he wanted all of Peru\'s gold','Nhưng sau khi nhìn thấy vàng, ông ta muốn có tất cả vàng của Peru','','','4000-essential-english-words-87'),
	('So he didn\'t leave the country','Nên ông ta không rời khỏi vùng đất đó','','','4000-essential-english-words-87'),
	('The Spanish soldiers stayed in Peru and grabbed all the gold they could find','Những người lính Tây Ban Nha ở lại Peru và lấy tất cả vàng họ có thể tìm thấy','','','4000-essential-english-words-87'),
	('But the Inca people tricked the Spaniards','Nhưng người Incas đã lừa người Tây Ban Nha','','','4000-essential-english-words-87'),
	('They mixed the gold with tin so that it was poor quality','Họ trộn vàng với thiếc để nó có chất lượng kém','','','4000-essential-english-words-87'),
	('They gave this gold to the Spaniards','Họ đưa những thỏi vàng đó cho người Tây Ban Nha','','','4000-essential-english-words-87'),
	('Meanwhile, they hid the good gold','Trong lúc ấy, họ giấu những thỏi vàng nguyên chất đi','','','4000-essential-english-words-87'),
	('They stuffed it into sacks and dragged it deep into the jungle','Họ nhét chúng vào bao và kéo chúng vào sâu trong rừng','','','4000-essential-english-words-87'),
	('The Spanish conquerors never found the gold','Người kẻ đô hộ đến từ Tây Ban Nha sẽ không bao giờ tìm thấy vàng nữa','','','4000-essential-english-words-87'),
	('People think it is still there today','Mọi người nghĩ rằng số vàng đó vẫn còn đến tận ngày hôm nay','','','4000-essential-english-words-87'),

	/* (UUID(),'4000-essential-english-words-88','The Boy Who Saved the Town','Cậu bé cứu tinh của thị trấn','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_088.mp3',NULL,'','','4000-essential-english-words','NO',88) */
	('Marcus lived in a small suburb near the sea','Marcus sống ở một vùng ngoại ô nhỏ gần biển','','','4000-essential-english-words-88'),
	('He was a stubborn boy, and he only cared about himself','Cậu là một chú bé bướng bỉnh, và cậu chỉ quan tâm tới bản thân mình','','','4000-essential-english-words-88'),
	('His father worked as a chemist for an institution and wanted Marcus to get a job there','Bố của cậu làm việc với tư cách một nhà hóa học trong một viện nghiên cứu và muốn Marcus có một công việc ở đó','','','4000-essential-english-words-88'),
	('Instead, the boy delivered milk','Thay vì đó, cậu bé đi vận chuyển sữa','','','4000-essential-english-words-88'),
	('Each morning he took dairy products to the grocers','Mỗi sáng cậu mang những sản phẩm sữa tới các tạp hóa','','','4000-essential-english-words-88'),
	('One day, Marcus was jogging down the street with a gallon of milk to give to a merchant','Một ngày, Marcus đang đi bộ xuống con phố với một ga-lông sữa để giao hàng cho một thương nhân','','','4000-essential-english-words-88'),
	('He didn\'t want to be late','Cậu không muốn bị chậm trễ','','','4000-essential-english-words-88'),
	('He ran down a path beside a large canal','Cậu đi xuống một con đường cạnh kênh đào lớn','','','4000-essential-english-words-88'),
	('A wall there kept water from coming into the town during high tide','Một bức tường ở đó đã giữ dòng nước khỏi đi vào thị trấn mỗi khi thủy triều lên','','','4000-essential-english-words-88'),
	('But Marcus saw a small hole in the wall','Nhưng Marcus đã thấy một cái lỗ nhỏ trong bức tường','','','4000-essential-english-words-88'),
	('Marcus knew that if the wall broke, it would be a tragedy for the town','Marcus biết rằng nếu bức tường bị vỡ, đó sẽ là một thảm họa cho thị trấn','','','4000-essential-english-words-88'),
	('At first, he hesitated','Ban đầu, cậu chần chừ','','','4000-essential-english-words-88'),
	('He had to choose between helping himself and helping the town','Cậu đã phải chọn giữa tự giúp mình và giúp thị trấn','','','4000-essential-english-words-88'),
	('There was only one way to save the town','Chỉ có đúng 1 cách để cứu sống thị trấn','','','4000-essential-english-words-88'),
	('It seemed crazy to him, but it was the only thing he could do','Điều này có vẻ điên rồ, nhưng là điều duy nhất cậu có thể làm','','','4000-essential-english-words-88'),
	('He poked his finger into the hole','Cậu chọc ngón tay vào trong cái lỗ','','','4000-essential-english-words-88'),
	('This didn\'t fix the problem forever, but it did postpone the tragedy','Điều này không giải quyết được vấn đề mãi mãi, nhưng nó đã trì hoãn thảm họa lại','','','4000-essential-english-words-88'),
	('His finger ached','Ngón tay của cậu bị đau','','','4000-essential-english-words-88'),
	('He felt the chill ofthe arctic water as it splashed him','Cậu cảm thấy sự lạnh giá của nước ở Cực Bắc khi nó bắn vào cậu','','','4000-essential-english-words-88'),
	('There was no one else around','Không có ai khác xung quanh cả','','','4000-essential-english-words-88'),
	('He knew he had to wait until the tide descended','Cậu biết cậu phải đợi cho tới khi thủy triều rút','','','4000-essential-english-words-88'),
	('It was very difficult, but Marcus stayed there and saved the town','Nó rất khó, nhưng Marcus đã ở đó và cứu sống thị trấn','','','4000-essential-english-words-88'),
	('Once the tide had descended, Marcus told everyone what happened','Khi nước triều hạ xuống, Marcus nói cho mọi người biết điều đã xảy ra','','','4000-essential-english-words-88'),
	('A group of people went to the wall','Một nhóm người đã tới bức tường','','','4000-essential-english-words-88'),
	('They saw the hole and fixed it','Họ thấy cái lỗ và đã sửa nó','','','4000-essential-english-words-88'),
	('Everyone was very happy with Marcus','Mọi người rất vui cùng Marcus','','','4000-essential-english-words-88'),
	('The local congress even gave him a gift for saving the town','Hội nghị địa phương thậm chí còn tặng cho cậu một món quà cho việc cứu sống thị trấn','','','4000-essential-english-words-88'),
	('He was a hero','Cậu là một người anh hùng','','','4000-essential-english-words-88'),

	/* (UUID(),'4000-essential-english-words-89','An Interesting Life','Cuộc sống thú vị','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_089.mp3',NULL,'','','4000-essential-english-words','NO',89) */
	('A man looked through some boxes with his grandson','Một người ông cùng đứa cháu nhìn qua vài chiếc hộp','','','4000-essential-english-words-89'),
	('They were filled with old photographs and objects that portrayed important events from the grandfather\'s life','Những chiếc hộp đầy những bức ảnh và đồ vật cũ tái hiện lại các sự kiện quan trọng trong cuộc đời của người ông','','','4000-essential-english-words-89'),
	('He wished to share the circumstances behind each event with his grandson','Ông mong muốn chia sẻ hoàn cảnh sau mỗi sự kiện với cháu mình','','','4000-essential-english-words-89'),
	('The grandson, however, thought his grandfather\'s stories were boring','Nhưng đứa cháu, thì trái lại, nghĩ rằng những câu chuyện của ông thật nhàm chán','','','4000-essential-english-words-89'),
	('The grandfather coped with this','Người ông đã quen với điều này','','','4000-essential-english-words-89'),
	('He ignored his grandson\'s criticism','Ông lờ đi sự phê bình của đứa cháu','','','4000-essential-english-words-89'),
	('He took a photo from the box','Ông lấy ra một tấm ảnh từ hộp','','','4000-essential-english-words-89'),
	('"That\'s the submarine I was on during the war," he explained','"Đó là chiếc tàu ngầm mà ông đã đi trong thời chiến," ông giải thích','','','4000-essential-english-words-89'),
	('The grandson gazed at it','Đứa cháu nhìn chằm chằm vào nó','','','4000-essential-english-words-89'),
	('The grandfather glanced at the next picture and frowned','Ông nhìn thoáng vào bức ảnh kế tiếp và cau mày','','','4000-essential-english-words-89'),
	('It showed a row of coffins','Bức ảnh có một hàng quan tài','','','4000-essential-english-words-89'),
	('His grandson noticed the grief in his grandfather\'s face','Đứa cháu để ý nỗi đau trên gương mặt người ông','','','4000-essential-english-words-89'),
	('"What is it?" the boy inquired','"Đây là gì vậy ông?" cậu bé hỏi','','','4000-essential-english-words-89'),
	('"This was after a nuclear bomb was dropped," the grandfather answered','"Đây là lúc sau khi một quả bom nguyên tử rơi xuống," ông trả lời','','','4000-essential-english-words-89'),
	('"It devastated a city"','"Nó đã tàn phá cả một thành phố"','','','4000-essential-english-words-89'),
	('Next the grandfather pulled a toy microscope from the box and rotated it in his hand','Sau đó ông kéo một chiếc kính hiển vi đồ chơi từ hộp ra và xoay nó trên tay','','','4000-essential-english-words-89'),
	('"Where did you get that?" the grandson asked','"Ông lấy nó ở đâu thế ạ?" cháu thắc mắc','','','4000-essential-english-words-89'),
	('"This is a souvenir I bought at the science museum," the grandfather said','"Đây là đồ lưu niệm mà ông mua ở bảo tàng khoa học," ông trả lời','','','4000-essential-english-words-89'),
	('Now the boy was really interested','Giờ thì đứa cháu cảm thấy thích thú thực sự','','','4000-essential-english-words-89'),
	('He started to understand that his grandfather was telling him a larger story','Cậu bắt đầu nhận ra ông mình đang kể một câu chuyện rộng hơn','','','4000-essential-english-words-89'),
	('It was the story of his grandfather\'s life','Đó là câu chuyện về cuộc đời ông','','','4000-essential-english-words-89'),
	('He got another photo','Cậu cầm một bức ảnh khác','','','4000-essential-english-words-89'),
	('It showed a young bride and groom','Trong đó có một cặp cô dâu chú rể trẻ','','','4000-essential-english-words-89'),
	('They were very happy','Trông họ rất hạnh phúc','','','4000-essential-english-words-89'),
	('A certificate was attached to the photo','Bức ảnh có đính một chứng nhận','','','4000-essential-english-words-89'),
	('The boy couldn\'t read it, but he traced his finger over paper','Cậu không thể đọc nhưng cậu đã làm dấu trên đó','','','4000-essential-english-words-89'),
	('"What\'s this from, Granddad?" he asked','"Đây là gì vậy ông?" cậu hỏi','','','4000-essential-english-words-89'),
	('"That\'s my marriage license from the day I married your grandmother," the grandfather said','"Đó là giấy phép kết hôn từ ngày ông cưới bà," ông đáp','','','4000-essential-english-words-89'),
	('"Wow" said the boy','"Wow" cậu thốt lên','','','4000-essential-english-words-89'),
	('"Granddad, now I know all about your life"','"Giờ thì cháy đã biết tất cả về cuộc đời ông rồi"','','','4000-essential-english-words-89'),

	/* (UUID(),'4000-essential-english-words-90','The Kitten and the Caterpillar','Mèo con và sâu bướm','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_090.mp3',NULL,'','','4000-essential-english-words','NO',90) */
	('Katie the kitten liked to play','Chú mèo con Katie rất thích chơi đùa','','','4000-essential-english-words-90'),
	('One day, Cory the caterpillar emerged from a hole in the wall while Katie was playing in the living room','Một ngày, chú sâu bướm Cory bò ra từ cái lỗ trong bức tường khi Katie đang chơi đùa ở phòng khách','','','4000-essential-english-words-90'),
	('"Hey" Katie yelled','"Này" Katie hét lên','','','4000-essential-english-words-90'),
	('"Do you want to play with me?"','"Bạn có muốn chơi cùng với tớ không?"','','','4000-essential-english-words-90'),
	('Cory was reluctant','Cory thấy bất đắc dĩ','','','4000-essential-english-words-90'),
	('He said, "I\'d rather not play with you"','"Tớ nghĩ mình không nên chơi với cậu"','','','4000-essential-english-words-90'),
	('"I have several handicaps"','"Tớ có một vài điều bất tiện"','','','4000-essential-english-words-90'),
	('"My body is very delicate"','"Cơ thể của tớ rất mỏng manh"','','','4000-essential-english-words-90'),
	('"Your claws are as sharp as hooks"','"Móng vuốt của cậu lại sắc như lưỡi há"','','','4000-essential-english-words-90'),
	('"You might cut me"','"Cậu có thể cắt vào da thịt tớ"','','','4000-essential-english-words-90'),
	('"Plus, I have no bones, not even a spine"','"Thêm nữa, tớ không có xương, thậm chí không có cả xương sống"','','','4000-essential-english-words-90'),
	('"You could easily hurt me"','"Cậu có thể dễ dàng khiến tớ bị đau đó"','','','4000-essential-english-words-90'),
	('"I swear that I won\'t hurt you," Katie said','"Tớ hứa là tớ sẽ không làm đau cậu đâu," Katie nói','','','4000-essential-english-words-90'),
	('"No, I don\'t want to," he said again','"Không, tớ không muốn chơi với cậu đâu," Cory nhắc lại','','','4000-essential-english-words-90'),
	('He hopped from the wall, but Katie pursued him','Cậu nhảy ra khỏi bờ tường, nhưng Katie đã đuổi theo cậu ấy','','','4000-essential-english-words-90'),
	('Cory ran into the kitchen and into the cupboard, but Katie chased closely behind','Cory chạy vào trong bếp và trốn trong tủ bát đĩa, nhưng Katie đã đuổi theo sát phía sau','','','4000-essential-english-words-90'),
	('Katie knocked appliances to the floor','Katie làm rơi những đồ dùng xuống sàn','','','4000-essential-english-words-90'),
	('Plates fell into the sink and broke in the basin','Những chiếc đĩa rơi vào bồn rửa và vỡ tan tành trong chậu','','','4000-essential-english-words-90'),
	('Then he ran into a bedroom','Sau đó cậu ta chạy vào phòng ngủ','','','4000-essential-english-words-90'),
	('Some laundry was on the floor','Một vài quần áo đã giặt đang ở dưới sàn','','','4000-essential-english-words-90'),
	('Cory hid under a shirt, but Katie saw him','Cory trốn sau chiếc áo nhưng Katie đã nhìn thấy cậu','','','4000-essential-english-words-90'),
	('She jumped on the shirt','Cô bé nhảy lên chiếc áo','','','4000-essential-english-words-90'),
	('Her paws left stains on the cloth, and her claws ripped the sleeves into strips','Chân Katie để lại những vết bẩn trên quần áo, móng vuốt của Katie cào rách ống tay áo thành các mảnh vải','','','4000-essential-english-words-90'),
	('However, Cory escaped','Tuy nhiên, Cory đã trốn thoát','','','4000-essential-english-words-90'),
	('He utilized a small crack in the floor to hide','Cậu ta đã tận dụng một vết nứt nhỏ trên sàn nhà để trốn đi','','','4000-essential-english-words-90'),
	('But Katie saw him','Nhưng Katie đã nhìn thấy cậu','','','4000-essential-english-words-90'),
	('"Now you are trapped" said Katie','"Bây giờ thì cậu sập bẫy rồi nhé" Katie nói','','','4000-essential-english-words-90'),
	('Cory tried to avoid Katie\'s claws','Cory đã cố gắng tránh khỏi móng vuốt của Katie','','','4000-essential-english-words-90'),
	('He moved his body as far into the hole as possible','Cậu ta đã cố gắng di chuyển thân mình thật nhanh để thoát chiếc hố','','','4000-essential-english-words-90'),
	('He didn\'t know how he\'d get out ofthe hole','Cory cũng không hiểu sao mình có thể thoát khỏi cái hố đó','','','4000-essential-english-words-90'),
	('Just then, Katie\'s owner came home','Đúng lúc này, cô chủ của Katie đã về tới nhà','','','4000-essential-english-words-90'),
	('She saw that the house was a mess','Cô thấy căn nhà thật bừa bộn','','','4000-essential-english-words-90'),
	('She took a broom and swung it at Katie','Cô lấy một cái chổi và đẩy nó vào Katie','','','4000-essential-english-words-90'),
	('She chased Katie out of the house','Rồi cô đuổi Katie ra khỏi nhà','','','4000-essential-english-words-90'),
	('Cory was safe, and Katie was left outside because she didn\'t listen to the wishes of others','Cory đã an toàn và Katie thì ở ngoài vì cô ấy không hề lắng nghe mong muốn của người khác','','','4000-essential-english-words-90');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-91','The History of Chocolate','Lịch sử của Socola','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_091.mp3',NULL,'','','4000-essential-english-words','NO',91) */
	('Many people believe that chocolate originally came from Europe','Mọi người tin rằng Socola có nguồn gốc từ Châu Âu','','','4000-essential-english-words-91'),
	('However, chocolate, called the "food of the gods," was first made in the Americas','Tuy nhiên, Socola, được gọi với cái tên "thức ăn của chúa," được ra đời đầu tiên ở Châu Mỹ','','','4000-essential-english-words-91'),
	('The first chocolate was very different from contemporary chocolate','Socola lúc đầu khác với Socola bây giờ','','','4000-essential-english-words-91'),
	('Wild chocolate trees can grow easily in the humid Amazon rainforest','Cây cacao dại có thể dễ dàng mọc ở khu rừng nhiệt đới ẩm Amazon','','','4000-essential-english-words-91'),
	('Clusters of flowers growing on these trees turn to seeds','Những chùm hoa lớn lên trên cây cacao này sẽ biến thành những hạt giống','','','4000-essential-english-words-91'),
	('About 20 to 60 cacao beans can be found in the seeds','Có khoảng 20-60 hạt cacao trong đó','','','4000-essential-english-words-91'),
	('Cacao beans are the ingredient needed to create sweet, soothing, and delicious chocolate treats','Hạt cacao là thành phần thiết yếu để tạo độ ngọt, dễ chịu và vị ngon của Socola','','','4000-essential-english-words-91'),
	('The Mayan and Aztec cultures both thought that chocolate trees were brought from paradise by gods','Cả hai nền văn hóa Maya và Aztec đều nghĩ rằng cây cacao được thượng đế mang về từ thiên đường','','','4000-essential-english-words-91'),
	('The Mayans and Aztecs used the beans from this divine tree to create a special beverage with a very pleasant odor','Người Maya và Aztec sử dụng hạt từ cây thần thánh này để tạo ra một loại thức uống đặc biệt với một mùi vị vô cùng dễ chịu','','','4000-essential-english-words-91'),
	('Surprisingly, the Aztecs believed that it would be toxic to women and children','Ngạc nhiên là, người Aztec tin rằng đồ uống này có hại cho phụ nữ và trẻ em','','','4000-essential-english-words-91'),
	('In the 1500s, the Spanish explorer Cortes met the Aztecs','Vào những năm 1500, nhà thám hiểm người Tây Ban Nha Cortes đã gặp tộc người Aztec','','','4000-essential-english-words-91'),
	('Cortes became quite interested in the plantations where the Aztecs cultivated chocolate trees','Cortes trở nên khá hứng thú với những đồn điền nơi những người Aztec trồng cây Cacao','','','4000-essential-english-words-91'),
	('When he returned to Europe, he took cacao beans with him','Khi ông quay trở về Châu Âu, ông đã đem theo những hạt Cacao bên mình','','','4000-essential-english-words-91'),
	('He introduced the people of Spain to the Aztecs\' chocolate beverage','Ông giới thiệu cho người Tây Ban Nha về đồ uống Cacao của người Aztec','','','4000-essential-english-words-91'),
	('Over the next 100 years or so, kings, queens, and members of the upper class enjoyed drinking chocolate','Trong vòng 100 năm sau đó hoặc hơn thế, các vị vua, nữ hoàng, và những người thuộc giới thượng lưu đều ưa thích loại đồ uống cacao này','','','4000-essential-english-words-91'),
	('They enjoyed it even more once they learned to add sugar to the beverage','Họ yêu thích nó đến nỗi họ đã học cách cách thêm đường vào đồ uống','','','4000-essential-english-words-91'),
	('Soon, chocolate had spread all across Europe','Chẳng mấy chốc cacao đã lan rộng khắp Châu Âu','','','4000-essential-english-words-91'),
	('New machines allowed chocolate makers to perfect their products and produce them at a very rapid rate','Những chiếc máy mới cho phép các nhà sản xuất Socola hoàn thiện sản phẩm và sản xuất với tốc độ nhanh chóng','','','4000-essential-english-words-91'),
	('Preparing the beans in special ways brought out the aroma of chocolate','Công đoạn chuẩn bị hạt theo những cách thức đặc biệt sẽ cho ra những hương vị riêng của Socola','','','4000-essential-english-words-91'),
	('The beans were combined with condensed milk to give the chocolate a smooth texture','Hạt cacao được kết hợp với sữa đặc để cho ra một loại socola có độ mịn','','','4000-essential-english-words-91'),
	('Today, contemporary chocolates with subtle flavors fill the shelves of expensive chocolate shops','Ngày nay, socola với những hương vị tinh tế lấp đầy trên những kệ hàng trong các cửa hàng socola đắt đỏ','','','4000-essential-english-words-91'),
	('The different types of chocolate available today vary widely','Những loại socola có sẵn trên thị trường hiện nay rất đa dạng','','','4000-essential-english-words-91'),
	('True chocolate lovers can tell which is best, though','Tuy vậy, những người thật sự yêu thích Socola có thể cho bạn biết loại nào là ngon nhất','','','4000-essential-english-words-91'),
	('They will tell you that the flavor of high quality chocolate stays on the palate long after you finish it','Họ sẽ cho bạn biết được rằng hương vị của loại socola chất lượng cao vẫn sẽ lưu lại trên đầu lưỡi dù bạn đã ăn hết từ lâu','','','4000-essential-english-words-91'),

	/* (UUID(),'4000-essential-english-words-92','Monkey Island','Đảo khỉ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_092.mp3',NULL,'','','4000-essential-english-words','NO',92) */
	('In the middle of the ocean, there is a small island shaped like an arc','Ở giữa lòng đại dương, có một hòn đảo nhỏ hình dạng như một vòng cung','','','4000-essential-english-words-92'),
	('Here, monkeys play on the beach and in the trees','Ở đây, những con khỉ cùng nhau chơi đùa trên bãi biển và trèo lên thân cây','','','4000-essential-english-words-92'),
	('But how did the monkeys get there?','Nhưng làm thế nào mà những con khỉ đến được đây?','','','4000-essential-english-words-92'),
	('Once, an English admiral was exploring Africa when he found hundreds of monkeys','Có một lần, đô đốc người Anh đi thám hiểm Châu Phi thì ông phát hiện ra có đến hàng trăm con khỉ','','','4000-essential-english-words-92'),
	('The admiral\'s character was mean','Bản chất của đô đốc này khá tư lợi','','','4000-essential-english-words-92'),
	('He thought, "I could sell these monkeys and become very rich"','Ông nghĩ, "Ta có thể bán những con khỉ này, kiếm được bộn tiền và trở thành người giàu có"','','','4000-essential-english-words-92'),
	('"I\'m going to take them to England"','"Ta sẽ đưa chúng về nước Anh"','','','4000-essential-english-words-92'),
	('So the admiral set traps to catch the monkeys','Vì thế ông ta đặt bẫy để bắt những con khỉ','','','4000-essential-english-words-92'),
	('He put stakes in the ground, tied string around them and made loops in the string','Ông ta cắm cọc xuống đất, cột dây xung quanh và làm những cái thòng lọng trên sợi dây','','','4000-essential-english-words-92'),
	('When the monkeys ran through the forest, their feet got caught in the loops, and they couldn\'t escape','Khi những con khỉ chạy ngang qua khu rừng, chân chúng sẽ bị mắc vào những thòng lọng, và chúng không thể trốn thoát','','','4000-essential-english-words-92'),
	('Then the admiral put the monkeys in cages on his ship and sailed away','Sau đó, đô đốc sẽ bỏ những con khỉ vào trong những cái lồng trên tàu và khởi hành','','','4000-essential-english-words-92'),
	('The cages were small and uncomfortable','Những cái lồng nhỏ hẹp và không hề thoải mái','','','4000-essential-english-words-92'),
	('There was no soft hay for the monkeys to sleep on','Chẳng có cỏ khô mềm cho những con khỉ ngủ','','','4000-essential-english-words-92'),
	('Instead, they slept on branches with sharp thorns that cut into the monkeys\' flesh','Thay vào đó, chúng ngủ trên những cành cây có gai sắc nhọn đâm vào thịt chúng','','','4000-essential-english-words-92'),
	('For dinner, he gave them tiny pieces of sour grapefruit to eat','Đến buổi tối đô đốc mới mang cho chúng những miếng bưởi chua lè nhỏ xíu để ăn','','','4000-essential-english-words-92'),
	('The monkeys grew hungry and weak','Những con khỉ đói bụng và chúng yếu dần','','','4000-essential-english-words-92'),
	('But one day, the admiral hired a new steward','Một ngày nọ, đô đốc thuê một người phục vụ mới','','','4000-essential-english-words-92'),
	('He was a kind man with a good conscience','Anh là một người tốt bụng và lương thiện','','','4000-essential-english-words-92'),
	('He was horrified to see the thin monkeys in the cages','Anh đã khiếp sợ khi bắt gặp những con khỉ ốm tong teo bị nhốt trong những chiếc lồng','','','4000-essential-english-words-92'),
	('So one night he let them out','Nên một tối anh đã thả hết chúng ra','','','4000-essential-english-words-92'),
	('The monkeys ran and played all over the ship','Những con khỉ chạy và đùa giỡn khắp con tàu','','','4000-essential-english-words-92'),
	('They attacked the admiral and the steward and ate their food','Chúng tấn công đô đốc, người phục vụ và ăn hết thức ăn của họ','','','4000-essential-english-words-92'),
	('They completely wrecked the ship','Chúng phá hủy hoàn toàn con tàu','','','4000-essential-english-words-92'),
	('One monkey ran into a kerosene lamp, and it fell over','Một con khỉ đã va phải chiếc đèn dầu và khiến nó rơi xuống sàn','','','4000-essential-english-words-92'),
	('The ship caught fire and began to sink','Con tàu bốc cháy và bắt đầu chìm xuống','','','4000-essential-english-words-92'),
	('The whole crew was lost except for the monkeys','Toàn bộ thủy thủ trên tàu đều bị chết ngoại trừ những con khỉ','','','4000-essential-english-words-92'),
	('After the accident, the monkeys jumped onto a raft','Sau tai nạn, những con khỉ nhảy lên một cái bè','','','4000-essential-english-words-92'),
	('They floated away from the fiery blaze of the ship','Chúng trôi dạt ra xa khỏi con tàu đang rực cháy kia','','','4000-essential-english-words-92'),
	('In the morning, they saw a little island in the distance','Vào buổi sáng, chúng nhìn thấy một hòn đảo nhỏ ở phía xa','','','4000-essential-english-words-92'),
	('The monkeys used a piece of wood as a paddle, and they went toward it','Những con khỉ dùng mảnh gỗ làm mái chèo, và hướng về phía hòn đảo','','','4000-essential-english-words-92'),
	('They found the island shaped like an arc','Chúng tìm thấy một hòn đảo hình vòng cung','','','4000-essential-english-words-92'),
	('They felt so happy to find a new home, and they still live there today','Chúng cảm thấy vô cùng hạnh phúc khi tìm được ngôi nhà mới và chúng vẫn sống ở đó cho đến ngày nay','','','4000-essential-english-words-92'),

	/* (UUID(),'4000-essential-english-words-93','The Young Man and the Old Man','Chàng trai trẻ và ông cụ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_093.mp3',NULL,'','','4000-essential-english-words','NO',93) */
	('A proud young man was looking for a new pastime','Một thanh niên trẻ kiêu ngạo đang tìm kiếm một trò tiêu khiển mới','','','4000-essential-english-words-93'),
	('He heard about people hiking in the national parks and decided to try it for himself','Anh ta nghe nói về những người đi bộ đường dài trong những công viên quốc gia và quyết định thử thách bản thân','','','4000-essential-english-words-93'),
	('As he started his stroll, an old man walked up to him','Khi bắt đầu chuyến ngao du của mình, có một ông cụ lại gần anh ta','','','4000-essential-english-words-93'),
	('"Don\'t go this way," the old man said','"Đừng đi lối này," cụ già nói','','','4000-essential-english-words-93'),
	('"Beware"','"Hãy coi chừng"','','','4000-essential-english-words-93'),
	('"The paths are not clear"','"Những con đường không rõ ràng"','','','4000-essential-english-words-93'),
	('"It\'s easy to become lost"','"Cháu sẽ rất dễ bị lạc đấy"','','','4000-essential-english-words-93'),
	('But the young man disagreed with the old man and bragged that he had a perfect understanding of the park','Nhưng chàng trai trẻ không đồng ý với ông và khoe khoang rằng anh ta am hiểu tường tận công viên này','','','4000-essential-english-words-93'),
	('"I studied maps of this area," he told him','"Cháu đã nghiên cứu bản đồ của khu vực này rồi," cậu ta nói','','','4000-essential-english-words-93'),
	('"I believe I have a thorough knowledge of these trails"','"Cháu tin cháu có một kiến thức sâu rộng về những con đường mòn ở đây"','','','4000-essential-english-words-93'),
	('"I won\'t become lost"','Cháu sẽ không bị lạc đâu"','','','4000-essential-english-words-93'),
	('The old man listened to the young man and then admonished him for his pride','Ông cụ nghe chàng trai trẻ nói và sau đó khuyên cậu đừng nên quá tự cao','','','4000-essential-english-words-93'),
	('"I have walked these trails my entire life," he said','"Ta đã đi bộ trên những lối mòn này cả đời rồi," ông nói','','','4000-essential-english-words-93'),
	('"If you think you will be safe, then go ahead"','"Nếu cháu nghĩ rằng cháu sẽ an toàn, vậy hãy đi đi"','','','4000-essential-english-words-93'),
	('The young man ignored the old man and started along the trail','Người thanh niên trẻ lờ đi lời nói của ông cụ và bắt đầu theo lối mòn','','','4000-essential-english-words-93'),
	('Whenever he had to choose between an easy or difficult route, he always chose the more difficult option','Bất cứ khi nào anh ta phải chọn lựa giữa tuyến đường dễ hoặc khó, anh ta luôn lựa chọn khó khăn hơn','','','4000-essential-english-words-93'),
	('In addition, he was not conscious of which direction he was going','Hơn nữa, anh ta không ý thức được mình sẽ đi về hướng nào','','','4000-essential-english-words-93'),
	('After a while, he decided to return home','Sau một lúc, anh ta quyết định quay trở về nhà','','','4000-essential-english-words-93'),
	('Because his course through the wilderness was so indirect, he had no idea where he was','Bởi vì đường đi của anh ta qua vùng hoang dã quá quanh co, anh ta không biết mình đang ở đâu','','','4000-essential-english-words-93'),
	('He looked at his map but could not pinpoint his location','Anh ta nhìn vào bản đồ nhưng không thể xác định được vị trí của mình','','','4000-essential-english-words-93'),
	('He walked one path after another but soon realized he was lost','Anh ta đi hết con đường này đến con đường khác nhưng nhanh chóng nhận ra mình đã bị lạc','','','4000-essential-english-words-93'),
	('The sun was going down, and sudden strong winds gave a hint that it might rain','Mặt trời dần xuống núi, và đột nhiên những cơn gió mạnh báo hiệu rằng trời sắp mưa','','','4000-essential-english-words-93'),
	('Immense clouds filled the sky','Những đám mây lớn bay đầy trời','','','4000-essential-english-words-93'),
	('Awesome sounds of thunder were audible from all directions','Có thể nghe thấy những âm thanh của sấm chớp từ mọi hướng','','','4000-essential-english-words-93'),
	('It echoed off the mountains','Nó vang vọng vào những vách núi','','','4000-essential-english-words-93'),
	('The thought of the eventual storm tormented the young man','Ý nghĩ về cơn bão sắp đến đã dày vò người thanh niên trẻ','','','4000-essential-english-words-93'),
	('He hurried in one direction, but soon switched out of confusion','Anh vội vã chạy về một hướng, nhưng nhanh chóng trở nên bối rối','','','4000-essential-english-words-93'),
	('Luckily, it led him out of the park','May mắn thay, con đường đó đã dẫn anh ta ra khỏi công viên','','','4000-essential-english-words-93'),
	('When he arrived home, he knew that he had acted like an idiot','Khi về được đến nhà, anh ta biết rằng mình hành động như một tên ngốc','','','4000-essential-english-words-93'),
	('He realized he was lucky to be alive','Anh ta nhận ra rằng mình thật may mắn khi vẫn còn sống','','','4000-essential-english-words-93'),
	('He decided to listen to people with more experience than himself','Người thanh niên quyết định từ nay phải biết lắng nghe những người có kinh nghiệm hơn mình','','','4000-essential-english-words-93'),

	/* (UUID(),'4000-essential-english-words-94','The Tricky Fox','Cáo xảo quyệt','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_094.mp3',NULL,'','','4000-essential-english-words','NO',94) */
	('There was a fox that lived in the forest','Xưa có một con cáo sống trong rừng','','','4000-essential-english-words-94'),
	('Fox loved to play mean tricks on the other animals','Nó thích chơi khăm các loài khác','','','4000-essential-english-words-94'),
	('One day, he used the sharp rim of a bottle to dig a pit in the ground','Một ngày nọ, chú đã dùng vành chai sắc nhọn để đào một cái hố dưới đất','','','4000-essential-english-words-94'),
	('He hid in a tree until Rabbit came to the pit\'s edge','Hắn nấp dưới cái cây cho đến khi Thỏ đến cạnh mép hố','','','4000-essential-english-words-94'),
	('Then, he jumped out and pushed Rabbit into the pit','Cáo liền nhảy ra và đẩy Thỏ xuống dưới hố ngay sau đó','','','4000-essential-english-words-94'),
	('Fox laughed and ran away','Cáo cười và bỏ chạy','','','4000-essential-english-words-94'),
	('The angry Rabbit climbed out and told the other animals what happened','Thỏ giận giữ trèo lên và đi kể cho những loài khác về chuyện vừa xảy ra','','','4000-essential-english-words-94'),
	('The others said, "That is typical behavior for Fox"','Những người khác nói: "Đó là hành vi điển hình của Cáo"','','','4000-essential-english-words-94'),
	('"He does mean things all the time"','"Hắn ta luôn có thủ đoạn"','','','4000-essential-english-words-94'),
	('"Sometimes, he is completely immoral"','"Có lúc hắn ta hoàn toàn vô đạo đức"','','','4000-essential-english-words-94'),
	('"We all disapprove of his actions, so we should teach him a lesson"','"Tất cả chúng ta đều không đồng tình với cách hành xử của hắn, chúng ta nên dạy hắn một bài học"','','','4000-essential-english-words-94'),
	('"Tomorrow, we\'ll push Fox into that pit"','"Ngày mai, ta sẽ đẩy Cáo xuống cái hố đó"','','','4000-essential-english-words-94'),
	('The next day, all of the animals hid near the pit and waited for Fox','Ngày tiếp theo, tất cả các loài sẽ nấp gần có hố và đợi Cáo','','','4000-essential-english-words-94'),
	('Fox was oblivious to the hidden animals','Cáo không hay biết những con vật đã ẩn nấu','','','4000-essential-english-words-94'),
	('He walked up to the pit to see if Rabbit was still trapped','Hắn đi đến cái hố và xem liệu Thỏ vẫn còn mắc kẹt không','','','4000-essential-english-words-94'),
	('Just then, the other animals ran up to Fox and pushed him in','Đúng lúc đó, những loài khác chạy tới và đẩy Cáo xuống hố','','','4000-essential-english-words-94'),
	('All the animals laughed and cheered, except Fox, of course','Tất cả bọn họ đều cười và ăn mừng, và dĩ nhiên là ngoại trừ Cáo','','','4000-essential-english-words-94'),
	('Fox couldn\'t get out','Cáo không thể nào thoát ra được','','','4000-essential-english-words-94'),
	('The walls of the pit were covered in damp ivy','Cái hố được phủ đầy cây tầm xuân ẩm ướt','','','4000-essential-english-words-94'),
	('It was too slippery for him to climb out','Vì quá trơn nên hắn không trèo lên được','','','4000-essential-english-words-94'),
	('He was utterly helpless','Hắn ta hoàn toàn tuyệt vọng','','','4000-essential-english-words-94'),
	('He moaned and began to weep','Nó rên rỉ và bắt đầu khóc','','','4000-essential-english-words-94'),
	('At last, he saw Eagle watching him from her roost','Cuối cùng, hắn thấy Đại Bàng ở trong tổ đang nhìn mình ','','','4000-essential-english-words-94'),
	('He yelled, "Eagle, please help me"','Hắn kêu lên: "Này, Đại Bàng hãy giúp tôi với"','','','4000-essential-english-words-94'),
	('"If I don\'t get out of here, I will perish"','"Nếu tôi không thể ra khỏi đây, tôi sẽ tiêu đời"','','','4000-essential-english-words-94'),
	('Eagle said, "You may think your tricks are trivial, but you hurt others when you do mean things"','Đại Bàng đáp: "Cậu nghĩ trò đùa của cậu vô hại, nhưng nó lại khiến người khác tổn thương"','','','4000-essential-english-words-94'),
	('"I\'ll help you if you promise to be nice"','"Tôi sẽ giúp cậu nếu cậu hứa sẽ trở nên tốt hơn"','','','4000-essential-english-words-94'),
	('Fox said, "I promise"','Cáo đáp "Tôi hứa"','','','4000-essential-english-words-94'),
	('Eagle began her flight to the bottom of the pit','Đại Bàng bắt đầu bay xuống dưới hố','','','4000-essential-english-words-94'),
	('She picked up Fox with her beak and soared out of the pit','Nó dùng mỏ nhấc cáo lên và bay vút khỏi cái hố','','','4000-essential-english-words-94'),
	('She dropped Fox safely on the ground','Nó để Cáo xuống đất an toàn','','','4000-essential-english-words-94'),
	('Fox thanked Eagle and kept his promise','Cáo cảm ơn Đại Bàng và giữ lời hứa','','','4000-essential-english-words-94'),
	('He was nice to the other animals','Anh ta trở nên tốt bụng với những loài khác','','','4000-essential-english-words-94'),
	('The animals even bebame fond of Fox, and the forest was a happy place','Con vật khác trở nên yêu mến Cáo và khu rừng đã trở thành một nơi yên bình, hạnh phúc','','','4000-essential-english-words-94'),

	/* (UUID(),'4000-essential-english-words-95','The Magic Computer','Máy tính ma thuật','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_095.mp3',NULL,'','','4000-essential-english-words','NO',95) */
	('I had a difficult geography project to finish by the end of the semester','Tôi có một bài tập địa lý khó phải hoàn thành vào cuối học kỳ','','','4000-essential-english-words-95'),
	('My teacher wanted it to be typewritten, so I went to the school computer room','Giáo viên của tôi muốn bài đấy phải được đánh máy, nên tôi đã đến phòng máy tính của trường','','','4000-essential-english-words-95'),
	('But when I got there, all the computers were turned off','Nhưng khi tôi đến đấy, thì mọi máy tính đã tắt hết','','','4000-essential-english-words-95'),
	('Apparently there was a recent problem, and technicians were fixing it','Hiển nhiên là gần đây máy đã có vấn đề, và kỹ thuật viên đang sửa chữa lại chúng','','','4000-essential-english-words-95'),
	('I knew of some private study rooms downstairs','Tôi biết có một số phòng học riêng tư ở tầng dưới','','','4000-essential-english-words-95'),
	('They were small and dark, and the computers were very old, but I had no choice','Chúng nhỏ và tối, và những chiếc máy tính thì quá cũ, nhưng tôi không còn sự lựa chọn nào khác','','','4000-essential-english-words-95'),
	('At least the computers were operating correctly','Ít nhất những chiếc máy tính này vẫn đang hoạt động bình thường','','','4000-essential-english-words-95'),
	('I typed and highlighted the assignment\'s title: "Evaluate the Government\'s Response to Global Warming"','Tôi đánh máy và làm nổi bật tiêu đề bài tập: "Đánh giá phản ứng của chính phủ về Nóng lên toàn cầu"','','','4000-essential-english-words-95'),
	('But I didn\'t know what to write in my essay','Nhưng tôi không biết viết gì trong bài luận của mình','','','4000-essential-english-words-95'),
	('Finally I decided to find a book to help me','Cuối cùng, tôi quyết định tìm một quyển sách để hỗ trợ mình','','','4000-essential-english-words-95'),
	('I went to the library, checked the book indexes and eventually found a useful book','Tôi đến thư viện, kiểm tra mục lục sách và cuối cùng đã tìm được một quyển sách hữu ích','','','4000-essential-english-words-95'),
	('Then I returned to the computer','Tiếp đó tôi quay trở lại với máy tính','','','4000-essential-english-words-95'),
	('When I looked at the screen, I saw something so weird that I nearly fainted','Khi tôi nhìn vào màn hình, tôi nhìn thấy một cái gì đó rất lạ mà tôi gần như ngất đi','','','4000-essential-english-words-95'),
	('The essay was complete','Bài luận đã được hoàn thành','','','4000-essential-english-words-95'),
	('Had somebody in cyberspace written it?','Có ai đó trong không gian mạng đã viết nó?','','','4000-essential-english-words-95'),
	('I didn\'t know, but I was very happy','Tôi không biết, nhưng tôi rất hạnh phúc','','','4000-essential-english-words-95'),
	('I printed it out and handed it in','Tôi in nó ra và nộp bài','','','4000-essential-english-words-95'),
	('I got an "A"','Tôi nhận được điểm "A"','','','4000-essential-english-words-95'),
	('After that, I used the computer for all my assignments','Sau đó, tôi sử dụng máy tính này cho tất cả bài tập của mình','','','4000-essential-english-words-95'),
	('I\'d type the title, wait awhile, and the computer would do it','Tôi gõ tiêu đề ra, đợi một lúc, và máy tính sẽ làm thay tôi','','','4000-essential-english-words-95'),
	('Every assignment was perfect; I never had to edit anything','Mọi bài tập đều hoàn hảo; tôi chẳng bao giờ phải sửa lại lại bất kỳ điều gì','','','4000-essential-english-words-95'),
	('I stopped paying attention to my teacher\'s lectures and spent my extra time in the gymnasium','Tôi dừng việc chú ý vào những bài giảng của thầy cô và dành phần lớn thời gian vào phòng tập thể dục','','','4000-essential-english-words-95'),
	('And my grades got better and better','Và điểm số của tôi ngày càng tốt hơn','','','4000-essential-english-words-95'),
	('A month later, I was walking into class when my friend said, "Are you prepared for the test?"','Một tháng sau đó, tôi đang đi vào lớp thì một người bạn của tôi hỏi, "Bạn đã chuẩn bị gì cho bài kiểm tra chưa?"','','','4000-essential-english-words-95'),
	('"What test?" I asked','"Bài kiểm tra nào cơ?" Tôi hỏi','','','4000-essential-english-words-95'),
	('"The geography test" he replied','"Bài kiểm tra địa lý" anh ta trả lời','','','4000-essential-english-words-95'),
	('"I hope you studied"','"Tôi hi vọng bạn đã ôn luyện rồi"','','','4000-essential-english-words-95'),
	('"It\'s worth seventy percent of our final grade"','"Nó chiếm 70% của điểm cuối kỳ của chúng ta đấy"','','','4000-essential-english-words-95'),
	('I failed the test, of course','Tất nhiên, tôi đã trượt bài kiểm tra','','','4000-essential-english-words-95'),
	('I was completely ignorant about the subject','Tôi hoàn toàn không biết gì về bài học','','','4000-essential-english-words-95'),
	('After that, I made a resolution never to use the magic computer again','Sau đó, tôi đã quyết tâm không bao giờ sử dụng chiếc máy tính ma thuật này lại một lần nào nữa','','','4000-essential-english-words-95'),
	('The moral of this story is that if you cheat at school, you won\'t learn anything','Bài học của câu chuyện này là nếu bạn gian lận trong học hành, bạn sẽ chẳng học được bất kỳ điều gì','','','4000-essential-english-words-95');

