INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-106','Gwen\'s New Friends','Người bạn mới quen của Gwen’s','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_106.mp3',NULL,'','','4000-essential-english-words','NO',106) */
	('Gwen walked into the gym for her next class','Gwen bước vào phòng tập thể hình cho lớp học tiếp theo của mình','','','4000-essential-english-words-106'),
	('Coach Peeves said, "Today, we\'re playing basketball"','Huấn luyện viên Peeves nói: "Hôm nay, chúng ta sẽ chơi bóng rổ"','','','4000-essential-english-words-106'),
	('"The custom is to let you choose your own teams"','"Cho phép bạn chọn đồng đội của riêng mình"','','','4000-essential-english-words-106'),
	('"However, we\'re going to do things differently"','"Tuy nhiên, chúng ta sẽ làm những điều khác biệt"','','','4000-essential-english-words-106'),
	('The coach assigned each girl to a team','Huấn luyện viên phân công mỗi cô gái về một đội','','','4000-essential-english-words-106'),
	('There were six girls per team','Có sáu cô gái mỗi đội','','','4000-essential-english-words-106'),
	('Gwen glimpsed at her teammates','Gwen nhìn thoáng qua đồng đội của mình','','','4000-essential-english-words-106'),
	('She didn\'t know any of them','Cô ấy không biết bất kỳ ai trong số họ','','','4000-essential-english-words-106'),
	('All of her friends were on the other teams','Tất cả bạn bè của cô đều ở trong các đội khác','','','4000-essential-english-words-106'),
	('She couldn\'t believe her misfortune','Cô ấy không thể tin được sự bất hạnh của mình','','','4000-essential-english-words-106'),
	('"I feel sick"','"Em cảm thấy không khỏe"','','','4000-essential-english-words-106'),
	('"May I go to the nurse?" asked Gwen','"Em có thể đến gặp y tá không?" Gwen hỏi','','','4000-essential-english-words-106'),
	('The coach could foresee Gwen\'s excuses','Huấn luyện viên có thể đoán trước lý do của Gwen','','','4000-essential-english-words-106'),
	('It wasn\'t the first time Gwen tried to leave class','Đây không phải là lần đầu tiên Gwen cố gắng rời khỏi lớp','','','4000-essential-english-words-106'),
	('With a stern voice, the coach said, "No"','Bằng một giọng nghiêm khắc, huấn luyện viên nói, "Không"','','','4000-essential-english-words-106'),
	('Gwen was vehement','Gwen phản ứng kịch liệt','','','4000-essential-english-words-106'),
	('"I don\'t know any of these girls"','"Em không biết bất kỳ ai trong số những cô gái này"','','','4000-essential-english-words-106'),
	('"Let me play on another team"','"Xin thầy hãy cho em chơi ở một đội khác"','','','4000-essential-english-words-106'),
	('"Please" she pleaded','"Làm ơn" cô nài nỉ','','','4000-essential-english-words-106'),
	('"Gwen, don\'t be disobedient"','"Gwen, đừng có không vâng lời"','','','4000-essential-english-words-106'),
	('"I don\'t want to hear any more negative comments from you"','"Tôi không muốn nghe thêm bất kỳ nhận xét tiêu cực nào từ em"','','','4000-essential-english-words-106'),
	('Gwen had no choice','Gwen không có lựa chọn nào khác','','','4000-essential-english-words-106'),
	('Then a girl smiled at her','Rồi một cô gái mỉm cười với cô','','','4000-essential-english-words-106'),
	('"Hi, I\'m Stephanie"','"Xin chào, mình là Stephanie"','','','4000-essential-english-words-106'),
	('"I was in your English class last year," she said','"Mình từng học chung lớp Tiếng Anh với cậu năm ngoái," cô nói','','','4000-essential-english-words-106'),
	('Gwen remembered her','Gwen đã nhớ ra cô ấy','','','4000-essential-english-words-106'),
	('"For the sake of the team, please try your best"','"Vì lợi ích của đội, hãy cố gắng hết sức mình"','','','4000-essential-english-words-106'),
	('"I know you\'re a good player," said Stephanie','"Mình biết bạn là một người giỏi," Stephanie nói','','','4000-essential-english-words-106'),
	('When the game started, Gwen played as best as she could','Khi trận đấu bắt đầu, Gwen đã chơi tốt nhất có thể','','','4000-essential-english-words-106'),
	('She took a long shot','Cô ấy tung một cú ném xa','','','4000-essential-english-words-106'),
	('The ball sailed through the air and went right through the hoop','Quả bóng bay vút trong không trung và trúng thẳng vào cái rổ','','','4000-essential-english-words-106'),
	('"That was awesome" said one of her teammates','"Thật tuyệt vời" một trong những đồng đội của cô nói','','','4000-essential-english-words-106'),
	('Later, Gwen fell with a loud thump','Sau đó, Gwen ngã với một tiếng đập lớn','','','4000-essential-english-words-106'),
	('"Are you OK?" asked her teammates','"Bạn không bị làm sao chứ?" đồng đội của cô hỏi','','','4000-essential-english-words-106'),
	('They were worried','Bọn họ đều lo lắng','','','4000-essential-english-words-106'),
	('She had ripped her jeans','Chiếc quần jeans của cô ấy đã bị rách','','','4000-essential-english-words-106'),
	('She had scraped her knee and had a small bruise','Cô ấy đã bị trầy xước đầu gối và có một vết bầm nhỏ','','','4000-essential-english-words-106'),
	('Gwen told her teammates, "My knee is fine, and I can stitch my pants later"','Gwen nói với các đồng đội của mình, "Đầu gối của tôi ổn, và tôi có thể khâu quần sau"','','','4000-essential-english-words-106'),
	('"Let\'s keep playing" ','"Hãy tiếp tục chơi"','','','4000-essential-english-words-106'),
	('By the end of the game, Gwen forgot altogether that she hadn\'t wanted to play, and her team won','Vào cuối trò chơi, Gwen hoàn toàn quên rằng cô ấy không muốn chơi và đội của cô ấy đã chiến thắng','','','4000-essential-english-words-106'),
	('The victory bound Gwen\'s team together','Chiến thắng đã gắn kết đội của Gwen lại với nhau','','','4000-essential-english-words-106'),
	('She had made a lot of new friends, and they were a source of happiness for her for many years','Cô ấy đã có rất nhiều người bạn mới, và họ là nguồn hạnh phúc cho cô ấy trong nhiều năm sau','','','4000-essential-english-words-106'),

	/* (UUID(),'4000-essential-english-words-107','Kara Goes Camping','Kara đi cắm trại','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_107.mp3',NULL,'','','4000-essential-english-words','NO',107) */
	('"Kara, would you like to go camping with my family?" asked Tracy','"Kara, cậu có muốn đi cắm trại với gia đình tớ không?" Tracy hỏi','','','4000-essential-english-words-107'),
	('Kara had never been camping before, but she decided to go anyway','Trước giờ Kara chưa từng đi cắm trại, nhưng dù sao thì cô ấy cũng quyết định đi','','','4000-essential-english-words-107'),
	('That weekend, they drove to Estes Park','Cuối tuần đó, họ lái xe đến Công viên Estes','','','4000-essential-english-words-107'),
	('When they arrived, Kara looked around','Khi họ đến nơi, Kara nhìn ngó xung quanh','','','4000-essential-english-words-107'),
	('She felt so far from civilization','Cô ấy cảm thấy thật cách xa với nền văn minh','','','4000-essential-english-words-107'),
	('After they set up the camp, they went for a walk','Sau khi dựng trại xong, họ đi dạo một vòng','','','4000-essential-english-words-107'),
	('Tracy\'s father, Mr.Grieves, showed them the native plants and animals','Bác Grieves, bố của Tracy đã chỉ cho họ về những loại cây cỏ và động vật địa phương','','','4000-essential-english-words-107'),
	('"Look," he said, "that\'s a fox\'s den"','"Nhìn kìa", bác ấy nói, "Kia là hang của một con cáo"','','','4000-essential-english-words-107'),
	('"Do you see that bunch of mushrooms next to it"','"Các con có nhìn thấy đám nấm ở ngay cạnh đó không"','','','4000-essential-english-words-107'),
	('"Don\'t touch them"','"Đừng đụng vào"','','','4000-essential-english-words-107'),
	('"They contain poison"','"Chúng có độc đấy"','','','4000-essential-english-words-107'),
	('Kara was bored','Kara cảm thấy buồn chán','','','4000-essential-english-words-107'),
	('She didn\'t care about nature','Cô chẳng thèm quan tâm đến thiên nhiên','','','4000-essential-english-words-107'),
	('As the day went on, mighty clouds soon loomed in the distance','Ngày trôi qua, những đám mây lớn sớm hiện ra ở phía xa','','','4000-essential-english-words-107'),
	('"It looks like stormy weather," said Tracy','"Nhìn thời tiết giống như sắp có bão vậy," Tracy nói','','','4000-essential-english-words-107'),
	('"We should go back"','"Chúng ta nên trở về nhà thôi"','','','4000-essential-english-words-107'),
	('It suddnely began to rain','Trời bỗng đổ mưa','','','4000-essential-english-words-107'),
	('They used an umbrella to shield them from the rain','Họ dùng ô để che mưa','','','4000-essential-english-words-107'),
	('Back at the camp, they ate cold sandwiches for dinner and went to sleep','Quay về lều trại, họ ăn tối bằng những chiếc bánh mì kẹp nguội và đi ngủ','','','4000-essential-english-words-107'),
	('By morning, the rain had stopped','Sáng hôm sau, mưa đã dừng hẳn','','','4000-essential-english-words-107'),
	('It was a drastic change from the previous day\'s weather','Thời tiết hôm nay khác hẳn với hôm qua','','','4000-essential-english-words-107'),
	('They folded their sleeping bags and put them in a box','Họ gập túi ngủ lại và cất vào hộp','','','4000-essential-english-words-107'),
	('Tracy closed the lid and told Kara, "Today will be fun, I promise"','Tracy đóng nắp lại và nói với Kara, "Ngày hôm nay chắc chắn sẽ rất vui, tớ hứa đấy"','','','4000-essential-english-words-107'),
	('Kara didn\'t believe her','Kara đã không tin lời cô ấy nói','','','4000-essential-english-words-107'),
	('She missed her convenient life in the city','Cô bé nhớ cuộc sống tiện nghi của mình ở thành phố','','','4000-essential-english-words-107'),
	('She was used to an urban lifestyle','Cô đã quen với một lối sống thành thị','','','4000-essential-english-words-107'),
	('After breakfast, they went for a walk','Sau bữa sáng, họ đi dạo','','','4000-essential-english-words-107'),
	('The grass was covered with dew, and it gleamed in the sunlight','Bãi cỏ được bao phủ bởi sương và nó lấp lánh trong ánh nắng mặt trời','','','4000-essential-english-words-107'),
	('Finally, they reached a lake','Cuối cùng, họ đã đến một hồ nước','','','4000-essential-english-words-107'),
	('Kara and Tracy waded into the water','Kara và Tracy đã lội xuống nước','','','4000-essential-english-words-107'),
	('The reeds swayed in the wind, and a flock of birds flew above','Những đám lau sậy đung đưa trong gió, và một đàn chim đang bay lượn trên cao','','','4000-essential-english-words-107'),
	('Kara felt very peaceful','Kara cảm thấy thật yên bình','','','4000-essential-english-words-107'),
	('That night, they made a fire','Tối hôm đó, họ đã đốt lửa trại','','','4000-essential-english-words-107'),
	('They sat around it while Mr.Grieves told scary stories','Mọi người ngồi tụ tập xung quanh nghe bác Grieves kể chuyện ma','','','4000-essential-english-words-107'),
	('Kara had a lot of fun','Kara đã có rất nhiều niềm vui','','','4000-essential-english-words-107'),
	('Camping was a good way for friends to spend time together, she realized','Cô nhận ra cắm trại là một cách hay để bạn bè dành thời gian bên nhau','','','4000-essential-english-words-107'),
	('The next day, it was time for them to leave','Ngày hôm sau, đã đến lúc họ rời khỏi đó','','','4000-essential-english-words-107'),
	('She felt sad while they exited the park','Trong khi mọi người rất hào hứng ở công viên thì cô bé lại thấy buồn','','','4000-essential-english-words-107'),
	('She didn\'t like camping at first, but she learned how fun it could be over the weekend','Ban đầu, cô ấy không thích cắm trại, nhưng cô ấy đã học được rằng cuối tuần có thể thú vị như thế nào','','','4000-essential-english-words-107'),

	/* (UUID(),'4000-essential-english-words-108','The School Play','Vở kịch ở trường','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_108.mp3',NULL,'','','4000-essential-english-words','NO',108) */
	('Peter was excited','Peter rất hào hứng','','','4000-essential-english-words-108'),
	('Next week he was going to audition for the school play','Tuần sau cậu ấy sẽ thử vai cho một vở kịch ở trường','','','4000-essential-english-words-108'),
	('Everybody knew he was a great actor','Tất cả mọi người đều biết rằng cậu ấy là một diễn viên xuất sắc','','','4000-essential-english-words-108'),
	('He was sure he would get the lead role','Cậu ấy chắc chắn mình sẽ được đóng vai chính','','','4000-essential-english-words-108'),
	('Later, his friend Robby asked him, "Have you seen the script for the play?"','Sau đó, bạn của cậu ấy, Robby, đã hỏi rằng, "Cậu đã xem kịch bản của vở kịch chưa?"','','','4000-essential-english-words-108'),
	('"Yes"','"Rồi"','','','4000-essential-english-words-108'),
	('The title is The Lost Glove—it\'s a comic play," replied Peter','"Tựa đề là Chiếc Găng Tay Bị Mất - Đó là một vở kịch hài," Peter trả lời','','','4000-essential-english-words-108'),
	('Robby said, "I want to play the part of the hermit because the hermit gets to talk with an accent"','Robby nói, "Mình muốn đóng phân đoạn của vai tu sĩ bởi vì tu sĩ chỉ cần nói bằng một giọng duy nhất"','','','4000-essential-english-words-108'),
	('"I want the lead role of the barber"','"Mình muốn đóng vai chính là thợ cắt tóc"','','','4000-essential-english-words-108'),
	('"I didn\'t know you liked acting"','"Mình không biết là cậu cũng thích diễn xuất đấy"','','','4000-essential-english-words-108'),
	('"I thought you liked choir better," said Peter','"Mình tưởng cậu thích hợp xướng hơn," Peter nói','','','4000-essential-english-words-108'),
	('"Acting is also a hobby of mine"','"Diễn xuất cũng là sở thích của mình"','','','4000-essential-english-words-108'),
	('"Do you want to practice with me?"','"Cậu có muốn luyện tập cùng mình không?"','','','4000-essential-english-words-108'),
	('"The basement at my house is quiet"','"Tầng hầm ở nhà mình rất yên tĩnh"','','','4000-essential-english-words-108'),
	('"It\'s perfect" Robby replied','"Nó khá là hoàn hảo" Robby trả lời','','','4000-essential-english-words-108'),
	('"I don\'t like practicing with others"','"Mình không thích tập luyện với người khác"','','','4000-essential-english-words-108'),
	('"It complicates the process for me," said Peter','"Nó làm phức tạp quá trình tập luyện của mình"','','','4000-essential-english-words-108'),
	('Actually, Peter didn\'t want to practice at all','Thật ra Peter không muốn tập luyện một chút nào','','','4000-essential-english-words-108'),
	('The teacher would surely reserve the lead part for him','Giáo viên chắc chắn sẽ để dành vai chính cho cậu','','','4000-essential-english-words-108'),
	('A few days later, Robby came to his house','Vài ngày sau, Robby đến nhà cậu ấy','','','4000-essential-english-words-108'),
	('Robby said, "Do you want to practice the scene on the staircase?"','Robby nói, "Cậu có muốn tập luyện phân cảnh trên cầu thang?"','','','4000-essential-english-words-108'),
	('It\'s the part where the migrant searches for a new job','Đó là phân đoạn mà người di cư tìm kiếm một công việc mới','','','4000-essential-english-words-108'),
	('Peter declined the invitation','Peter đã từ chối lời mời đó','','','4000-essential-english-words-108'),
	('"I can\'t today"','"Hôm nay tôi không thể"','','','4000-essential-english-words-108'),
	('"I need to do some errands"','"Tôi cần làm một số việc lặt vặt"','','','4000-essential-english-words-108'),
	('Then he slammed the door','Sau đó, cậu đóng sầm cửa lại','','','4000-essential-english-words-108'),
	('It was just an excuse','Đó chỉ là một cái cớ','','','4000-essential-english-words-108'),
	('Peter didn\'t want to help Robby','Peter không muốn giúp đỡ Robby','','','4000-essential-english-words-108'),
	('On the day of auditions, Peter wore his lucky leather jacket','Vào ngày thử giọng, Peter mặc chiếc áo khoác da may mắn của mình','','','4000-essential-english-words-108'),
	('He always got the best part when he wore it','Cậu ấy luôn luôn nhận được những vai diễn tốt nhất khi mặc nó','','','4000-essential-english-words-108'),
	('The teacher told him to begin, but his mind was blank','Giáo viên bảo cậu ấy bắt đầu nhưng tâm trí cậu ấy giờ đây trống rỗng','','','4000-essential-english-words-108'),
	('He couldn\'t remember the lines','Cậu không thể nhớ chính xác từng dòng','','','4000-essential-english-words-108'),
	('A week later, the teacher put a list of the parts on the wall','Một tuần sau đó, giáo viên dán một danh sách phân vai lên tường','','','4000-essential-english-words-108'),
	('Peter read the list, looking for his name','Peter đọc danh sách, tìm kiếm tên của mình','','','4000-essential-english-words-108'),
	('He was shocked by what he saw','Cậu ấy bị sốc bởi những gì mình nhìn thấy','','','4000-essential-english-words-108'),
	('He blinked his eyes and looked again','Cậu chớp mắt và nhìn lại lần nữa','','','4000-essential-english-words-108'),
	('He didn\'t get the lead part - Robby did','Cậu không được nhận vai chính – mà người đó là Robby','','','4000-essential-english-words-108'),
	('Peter pondered the situation and came to the idea that Robby justly received the part','Peter suy nghĩ về tình hình và hiểu được vấn đề rằng Robby vừa mới được nhận vai','','','4000-essential-english-words-108'),
	('He earned it by practicing','Bạn ấy đã có được nó bằng cách tập luyện','','','4000-essential-english-words-108'),
	('Next time, Peter would practice too','Lần sau Peter cũng sẽ tập luyện','','','4000-essential-english-words-108'),

	/* (UUID(),'4000-essential-english-words-109','Isaac\'s First Plane Trip','Chuyến đi bằng máy bay đầu tiên của Isaac','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_109.mp3',NULL,'','','4000-essential-english-words','NO',109) */
	('Isaac\'s family was going on vacation','Gia đình Isaac lên kế hoạch cho kỳ nghỉ','','','4000-essential-english-words-109'),
	('He was excited about the trip except for one thing','Cậu bé rất hào hứng ngoại trừ một chuyện','','','4000-essential-english-words-109'),
	('He had never been on a plane before','Đó là cậu chưa đi máy bay bao giờ','','','4000-essential-english-words-109'),
	('He was scared that his plane would have a breakdown','Cậu sợ máy bay sẽ gặp sự cố','','','4000-essential-english-words-109'),
	('Isaac got onto the plane','Isaac bước lên máy bay','','','4000-essential-english-words-109'),
	('He walked down the aisle until he found his seat','Cậu bước xuống lối đi để tìm chỗ ngồi của mình','','','4000-essential-english-words-109'),
	('He sat down and connected the ends of his seat belt','Cậu ngồi xuống và thắt dây an toàn','','','4000-essential-english-words-109'),
	('After being idle for a few minutes, the pilot announced that they were ready to leave','Sau vài phút nhàn rỗi, phi công thông báo rằng mọi thứ đã sẵn sàng để cất cánh','','','4000-essential-english-words-109'),
	('He looked out the window at the vivid colors of the sky','Qua ô cửa sổ, cậu ngắm nhìn những màu sắc sặc sỡ trên bầu trời','','','4000-essential-english-words-109'),
	('He began to feel scared','Cậu bắt đầu cảm thấy sợ hãi','','','4000-essential-english-words-109'),
	('The girl sitting next to him said, "Hi, I\'m Rachel"','Bạn gái ngồi bên cạnh cậu nói, "Chào cậu, mình là Rachel"','','','4000-essential-english-words-109'),
	('"You look nervous, but you don\'t need to be"','"Cậu trông có vẻ lo lắng, nhưng không cần phải sợ đâu"','','','4000-essential-english-words-109'),
	('Flying is fun"','Bay lượn thú vị lắm','','','4000-essential-english-words-109'),
	('"I\'m still a bit nervous," Issac said, "and I\'m getting hungry"','"Mình cũng hơi lo lắng một chút," Isaac nó, "và mình cũng đang đói nữa"','','','4000-essential-english-words-109'),
	('"The food service will begin soon"','"Dịch vụ ăn uống sẽ sớm bắt đầu thôi"','','','4000-essential-english-words-109'),
	('"Just lower the tray on the seat in front of you, and flip this switch"','"Cậu chỉ cần hạ cái khay trên ghế ở trước mặt xuống, và bật công tắc này"','','','4000-essential-english-words-109'),
	('"Then they\'ll bring your dinner"','"Rồi họ sẽ mang bữa tối đến cho cậu"','','','4000-essential-english-words-109'),
	('"Last time, they served chicken, peas, and a box of raisins," Rachel explained','"Lần trước, họ đã phục vụ thịt gà, đậu, và một hộp nho khô," Rachel giải thích','','','4000-essential-english-words-109'),
	('Then the pilot notified the passengers of bad conditions in the atmosphere','Sau đó phi công đã thông báo với hành khách về tình trạng xấu của bầu khí quyển','','','4000-essential-english-words-109'),
	('"We\'re tracking the weather: lightning, clouds, etc"','"Chúng tôi đang theo dõi thời tiết như: sấm sét, mây, vân vân"','','','4000-essential-english-words-109'),
	('"The ride might get a bit rough," he stated','"Chuyến đi có thể gặp một chút khó khăn," ông ấy nói','','','4000-essential-english-words-109'),
	('Suddenly, the plane started to shake','Đột nhiên, máy bay bắt đầu rung lắc','','','4000-essential-english-words-109'),
	('Isaac was badly afflicted by his fear','Isaac đã rất sợ hãi','','','4000-essential-english-words-109'),
	('His stomach hurt, and he thought he might vomit','Dạ dày của cậu bị đau, cậu nghĩ có thể mình sắp nôn tới nơi rồi','','','4000-essential-english-words-109'),
	('He couldn\'t believe that he was in such an unfortunate place','Không thể tin được cậu lại đi phải máy bay xui xẻo như vậy','','','4000-essential-english-words-109'),
	('Finally, the shaking stopped','Cuối cùng, rung lắc cũng kết thúc','','','4000-essential-english-words-109'),
	('Isaac was still scared, but he tried to retain a good attitude','Isaac vẫn còn sợ hãi, nhưng cậu cố gắng giữ một tinh thần vững vàng','','','4000-essential-english-words-109'),
	('"The first time I flew, the plane shook so bad that cargo started falling"','"Lần đầu tiên mình đi máy bay, máy bay đã rung lắc kinh khủng đến mức mà hành lý bắt đầu rơi ra ngoài"','','','4000-essential-english-words-109'),
	('"My parents told me to listen to music and read a chapter in my book"','"Bố mẹ bảo mình nghe nhạc và đọc một chương trong cuốn sách"','','','4000-essential-english-words-109'),
	('"It calmed me," Rachel said','"Điều đó làm mình bình tĩnh hơn," Rachel nói','','','4000-essential-english-words-109'),
	('Suddenly, the plane shook again','Bỗng nhiên máy bay lại rung lắc một lần nữa','','','4000-essential-english-words-109'),
	('This time, Isaac followed Rachel\'s advice','Lần này, Issac nghe theo lời khuyên của Rachel','','','4000-essential-english-words-109'),
	('He put on headphones and took out a book by his favorite author','Cậu bé đeo tai nghe và lấy ra một cuốn sách của một tác giả mà cậu yêu thích','','','4000-essential-english-words-109'),
	('The book and the music helped Isaac feel better','Đọc sách và nghe nhạc giúp Isaac cảm thấy tốt hơn','','','4000-essential-english-words-109'),
	('After a while, he didn\'t even notice the bad weather','Một lúc sau, cậu không còn chú ý đến thời tiết xấu nữa','','','4000-essential-english-words-109'),
	('The bad situation didn\'t feel so bad after someone helped him','Tình hình tồi tệ không còn thấy tệ sau khi có người giúp đỡ cậu','','','4000-essential-english-words-109'),

	/* (UUID(),'4000-essential-english-words-110','The Betrayal','Sự phản bội','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_110.mp3',NULL,'','','4000-essential-english-words','NO',110) */
	('A king lived in a fort with his daughter, Clara','Một vị vua sống trong 1 pháo đài cùng với con gái của ông ta, Clara','','','4000-essential-english-words-110'),
	('The king had founded a great empire, but his land was rife with enemies who wanted to take over the kingdom','Ông vua đã xây dựng 1 đế chế tuyệt vời, nhưng mảnh đất của ông đầy rẫy những kẻ thù những người mà muốn nắm quyền kiểm soát vương quốc','','','4000-essential-english-words-110'),
	('Because there was so much civil unrest, the king told Clara not to trust anyone','Bởi vì có rất nhiều bạo động quốc gia, vua cha nói với Clara không được tin bất cứ ai','','','4000-essential-english-words-110'),
	('One day, Clara was walking outside when she saw a girl sweeping the path','Một ngày nọ, Clara đang đi dạo bên ngoài khi đó cô nhìn thấy một cô gái đang quét đường','','','4000-essential-english-words-110'),
	('Clara crossed the garden, and they started talking','Clara đi qua khu vườn, và họ bắt đầu trò chuyện','','','4000-essential-english-words-110'),
	('The girl\'s name was Susie','Tên cô gái là Susie','','','4000-essential-english-words-110'),
	('Clara felt sorry for Susie because she was very poor, and Clara gave her a bracelet','Clara cảm thấy tội cho Susie bởi vì cô ấy rất nghèo, và Clara tặng cô 1 chiếc vòng tay','','','4000-essential-english-words-110'),
	('After that, Susie and Clara met every day','Sau đó, Susie và Clara gặp nhau mỗi ngày','','','4000-essential-english-words-110'),
	('Once, the King saw them talking','Một lần, nhà vua nhìn thấy họ nói chuyện với nhau','','','4000-essential-english-words-110'),
	('He told Clara, "Don\'t talk to that girl"','Ông bảo với Clara, "Đừng nói chuyện với con bé đó nữa"','','','4000-essential-english-words-110'),
	('"She could be an enemy"','"Con bé có thể là kẻ thù của chúng ta"','','','4000-essential-english-words-110'),
	('"You can\'t distrust everyone," commented Clara','"Cha không thể nghi ngờ tất cả mọi người được," Clara đưa ra ý kiến','','','4000-essential-english-words-110'),
	('"She is my sole friend"','"Cô ấy là người bạn duy nhất của con"','','','4000-essential-english-words-110'),
	('"It\'s OK to be friendly to people"','"Cư xử thân thiện với mọi người là một việc làm tốt"','','','4000-essential-english-words-110'),
	('The King said, "Don\'t argue with me"','Vị vua nói, "Đừng cãi lời ta"','','','4000-essential-english-words-110'),
	('"Stay inside from now on, and talk to no one"','"Từ giờ trở đi hãy ở yên trong phòng, và không được phép nói chuyện với bất cứ ai"','','','4000-essential-english-words-110'),
	('Clara felt lonely in the fort','Clara cảm thấy cô đơn trong pháo đài','','','4000-essential-english-words-110'),
	('But one day she saw Susie outside','Nhưng một ngày cô nhìn thấy Susie ở bên ngoài','','','4000-essential-english-words-110'),
	('She wrote her a note with a map showing a secret entrance to the fort','Cô viết cho Susie một bức thư ngắn có chứa bản đồ một lối đi bí mật đến pháo đài','','','4000-essential-english-words-110'),
	('Clara wrote: "Come at night, and we can talk together"','Clara viết: "Hãy đến vào ban đêm, và chúng ta có thể trò chuyện cùng nhau"','','','4000-essential-english-words-110'),
	('"Don\'t show anybody this note"','"Đừng cho ai thấy bức thư này nhé"','','','4000-essential-english-words-110'),
	('She threw the note to Susie, and Susie tucked it in the lining of her dress','Cô ném bức thư cho Susie, và Susie nhét nó vào lớp trong chiếc váy','','','4000-essential-english-words-110'),
	('That night Clara waited for Susie','Đêm đó Clara chờ Susie','','','4000-essential-english-words-110'),
	('But she heard something ticking, and then a loud blast','Nhưng cô nghe thấy thứ gì đó cứ kêu tích tắc, và sau đó là một tiếng nổ lớn','','','4000-essential-english-words-110'),
	('She ran into the hall, and it was full of smoke, which made her choke','Cô chạy vào đại sảnh, và ở đó khói bụi mù mịt khiến cô ngạt thở','','','4000-essential-english-words-110'),
	('A mass of soldiers were there, fighting','Một số lượng lớn binh lính đang chiến đấu ở đó','','','4000-essential-english-words-110'),
	('Clara realized that Susie had betrayed her and given the map to her father\'s enemies','Clara nhận ra Susie đã phản bội cô và đưa tấm bản đồ cho kẻ thù của cha cô','','','4000-essential-english-words-110'),
	('Clara prayed that everyone in the castle would be safe from her friend\'s treachery','Clara cầu nguyện cho những người trong lâu đài sẽ an toàn khỏi sự phản bội của bạn mình','','','4000-essential-english-words-110'),
	('At last, the fighting ceased','Cuối cùng, cuộc chiến cũng kết thúc','','','4000-essential-english-words-110'),
	('Clara found her father in the hall with his soldiers','Clara tìm thấy cha mình ở đại sảnh cùng với quân lính của ông','','','4000-essential-english-words-110'),
	('They had defeated their enemies, but there were dents in their armor from the heavy fighting','Họ đã đánh bại quân địch, nhưng trên áo giáp của họ xuất hiện những vết sứt mẻ bởi cuộc chiến nặng nề đem lại','','','4000-essential-english-words-110'),
	('Clara told her father what she had done and promised never to disobey him again','Clara kể với cha những việc mình đã làm và hứa sẽ không bao giờ trái lệnh ông một lần nào nữa','','','4000-essential-english-words-110');

