INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-131','Beethoven\'s Gift','Món quà của Beethoven','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_131.mp3',NULL,'','','4000-essential-english-words','NO',131) */
	('Beethoven was a great composer of classical music in the 1800s','Beethoven là một nhà soạn nhạc vĩ đại của âm nhạc cổ điển vào những năm 1800','','','4000-essential-english-words-131'),
	('Many biographies have been written that narrate his dominance in the music world','Nhiều tiểu sử đã được viết kể lại sự thống trị của ông trong thế giới âm nhạc','','','4000-essential-english-words-131'),
	('But do you know what really makes him special?','Nhưng bạn có biết điều gì thực sự khiến ông ấy đặc biệt không?','','','4000-essential-english-words-131'),
	('Even though millions of people got to hear his multiple masterpieces, he never did','Mặc dù hàng triệu người đã nghe nhiều kiệt tác của anh ấy, nhưng ông lại không bao giờ được nghe giai điệu đó','','','4000-essential-english-words-131'),
	('Beethoven wrote his best pieces after he went completely deaf','Beethoven đã viết những tác phẩm hay nhất của mình sau khi ông không còn nghe thấy gì nữa','','','4000-essential-english-words-131'),
	('His partiality toward classical music developed when he was very young','Sự yêu thích của ông đối với âm nhạc cổ điển phát triển khi ông còn rất trẻ','','','4000-essential-english-words-131'),
	('He wasn\'t interested in anything else as a child','Khi còn là một đứa trẻ, ông không thấy hứng thú với bất cứ thứ gì khác','','','4000-essential-english-words-131'),
	('When he was five, he learned how to play the piano','Khi lên 5, ông đã học được cách chơi piano','','','4000-essential-english-words-131'),
	('From then, nothing could stop his passion for writing and playing music','Kể từ đó, không gì có thể ngăn cản niềm đam mê của ông đối với soạn và chơi nhạc','','','4000-essential-english-words-131'),
	('When Beethoven was twenty, he began to lose his hearing','Khi Beethoven hai mươi tuổi, ông bắt đầu mất thính giác','','','4000-essential-english-words-131'),
	('He got acute, spontaneous pains in his ears','Ông đã chịu những cơn đau dữ dội, tự phát trong tai','','','4000-essential-english-words-131'),
	('His hearing kept getting worse over time','Thính giác của ông tệ dần theo thời gian','','','4000-essential-english-words-131'),
	('It was inevitable that he would eventually lose it altogether','Điều không thể tránh khỏi là cuối cùng ông sẽ mất thính giác hoàn toàn','','','4000-essential-english-words-131'),
	('It was very hard for him to keep writing music','Rất khó để ông ấy tiếp tục soạn nhạc','','','4000-essential-english-words-131'),
	('He lost the virtue of patience, and he became notorious for his aggression','Ông đánh mất tính kiên nhẫn, và trở nên nổi tiếng về sự nóng nảy của mình','','','4000-essential-english-words-131'),
	('Still, he never stopped trying','Tuy nhiên, ông vẫn không ngừng cố gắng','','','4000-essential-english-words-131'),
	('His passion for music compelled him to keep performing even after he went deaf','Niềm đam mê âm nhạc đã thôi thúc ông tiếp tục sáng tác ngay cả khi ông bị điếc','','','4000-essential-english-words-131'),
	('He couldn\'t hear himself play, but he knew that his creations sounded gorgeous','Ông không thể nghe chính mình chơi, nhưng ông biết rằng những sáng tạo của mình nghe thật rực rỡ','','','4000-essential-english-words-131'),
	('His final concert was held at a huge banquet','Buổi hòa nhạc cuối cùng của ông được tổ chức tại một bữa tiệc lớn','','','4000-essential-english-words-131'),
	('He gave the musicians a cue, and they began to play','Ông ra hiệu cho các nhạc công, và họ bắt đầu chơi','','','4000-essential-english-words-131'),
	('He directed the concert with all his heart','Ông đã chỉ đạo buổi hòa nhạc bằng cả trái tim','','','4000-essential-english-words-131'),
	('He couldn\'t hear the music, but he said that he could feel it','Ông không thể nghe nhạc, nhưng ông nói rằng mình có thể cảm nhận được nó','','','4000-essential-english-words-131'),
	('Overall, performance was one of the finest in history','Nhìn chung, đó là một trong những buổi trình diễn tuyệt  nhất trong lịch sử','','','4000-essential-english-words-131'),
	('When it was over, he turned to the crowd','Khi nó kết thúc, ông quay sang đám đông','','','4000-essential-english-words-131'),
	('They clapped and cheered wildly','Họ vỗ tay và reo hò cuồng nhiệt','','','4000-essential-english-words-131'),
	('In that beautiful moment, the applause boosted his emotions, and he began to cry','Trong khoảnh khắc tuyệt đẹp đó, tiếng vỗ tay khiến cảm xúc của ông dâng trào, và ông bắt đầu khóc','','','4000-essential-english-words-131'),
	('In 1827, he suffered from lead poisoning','Năm 1827, ông bị ngộ độc chì','','','4000-essential-english-words-131'),
	('He didn\'t survive the sickness, but his music did because great music never becomes outdated','Ông đã không qua khỏi cơn bạo bệnh, nhưng âm nhạc của ông không bao giờ trở nên lỗi thời','','','4000-essential-english-words-131'),
	('Even though Beethoven is gone, his legacy will live on forever','Mặc dù Beethoven đã ra đi, di sản của ông sẽ tồn tại mãi mãi','','','4000-essential-english-words-131'),

	/* (UUID(),'4000-essential-english-words-132','Brothers','Những người anh em','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_132.mp3',NULL,'','','4000-essential-english-words','NO',132) */
	('John and Mark were brothers, but they were quite different people','John và Mark là hai anh em, nhưng họ lại khá khác nhau','','','4000-essential-english-words-132'),
	('Mark looked very masculine','Mark trông rất nam tính','','','4000-essential-english-words-132'),
	('He had a mustache and was very muscular','Anh có một bộ ria mép và khá là cơ bắp','','','4000-essential-english-words-132'),
	('He was a sculptor','Anh là một nhà điêu khắc','','','4000-essential-english-words-132'),
	('He made things out of stone','Anh khắc các thứ từ bề mặt đá','','','4000-essential-english-words-132'),
	('Mark was a good artist, but he was not very intelligent','Mark là một nghệ sĩ giỏi, nhưng anh lại không thông minh cho lắm','','','4000-essential-english-words-132'),
	('John looked nothing like his brother','John nhìn chẳng có gì giống anh trai mình','','','4000-essential-english-words-132'),
	('He was small and weak, but he was very smart','Anh nhỏ con và yếu đuối, nhưng lại rất thông minh','','','4000-essential-english-words-132'),
	('John was an undergraduate in college, and he studied anthropology and history','John là một sinh viên chưa tốt nghiệp ở trường đại học, và anh đã nghiên cứu về nhân loại học và lịch sử','','','4000-essential-english-words-132'),
	('He knew a lot about ancient cultures','Anh biết nhiều thứ về những nền văn hóa cổ','','','4000-essential-english-words-132'),
	('The brothers loved each other very much, but they thought they had nothing in common','Hai anh em rất yêu quý nhau, nhưng họ nghĩ rằng họ chẳng có điểm chung gì cả','','','4000-essential-english-words-132'),
	('One day, the mayor appointed Mark to build a monument: a statue of Egyptian Pharaoh, Tut','Một ngày nọ, thị trưởng chỉ định Mark xây một tượng đài: một bức tượng của Pharaoh Ai Cập, Tut','','','4000-essential-english-words-132'),
	('Mark agreed to do the job, but he had a problem','Mark đồng ý làm việc, nhưng anh có một vấn đề','','','4000-essential-english-words-132'),
	('He had no idea who Pharaoh Tut was','Anh không biết Pharaoh Tut là ai cả','','','4000-essential-english-words-132'),
	('However, he thought he had the competence to build a good statue anyway','Tuy nhiên, anh nghĩ anh có đủ khả năng để xây dựng một bức tượng đẹp dù thế nào đi nữa','','','4000-essential-english-words-132'),
	('He made some crude measurements and sculpted a statue of a very old man with a tattoo on his chest','Anh đã thực hiện một số phép đo thô và điêu khắc một bức tượng về một người đàn ông già với hình xăm trên ngực','','','4000-essential-english-words-132'),
	('Mark was proud of his work, but when John saw the statue, he laughed aloud','Mark tự hào về tác phẩm của mình, nhưng khi John nhìn thấy bức tượng, anh đã phá cười lên','','','4000-essential-english-words-132'),
	('"What\'s so funny?" Mark asked','"Có gì buồn cười vậy?" Mark hỏi','','','4000-essential-english-words-132'),
	('John replied, "Your ignorance makes me laugh"','John trả lời, "Sự thiếu hiểu biết của anh làm em buồn cười"','','','4000-essential-english-words-132'),
	('"Don\'t you know that Tut was only a teenager when he was pharaoh?"','"Anh không biết là Tut mới chỉ là một thanh niên khi là Pharaoh sao?"','','','4000-essential-english-words-132'),
	('"Let me help you"','Để em giúp anh"','','','4000-essential-english-words-132'),
	('"I\'ll supervise your work"','"Em sẽ giám sát công việc của anh"','','','4000-essential-english-words-132'),
	('"I\'ll give you feedback, and we\'ll make this a great monument"','"Em sẽ góp ý cho anh và chúng ta sẽ làm nó thành một bức tượng đẹp"','','','4000-essential-english-words-132'),
	('Mark got another cube of stone','Mark lấy một khối đá khác','','','4000-essential-english-words-132'),
	('John told him what Tut looked like','John nói với anh rằng Tut trông như thế nào','','','4000-essential-english-words-132'),
	('"Make him tall with good posture," John said','"Hãy cho ông ấy cao với một dáng đứng đẹp," John nói','','','4000-essential-english-words-132'),
	('"And make sure there is symmetry in his body"','"Và đảm bảo cơ thể ông ấy được cân đối"','','','4000-essential-english-words-132'),
	('Mark conferred with John about every detail','Mark hội ý với John về từng chi tiết một','','','4000-essential-english-words-132'),
	('For ten consecutive hours, the brothers worked','Trong liên tục mười tiếng đồng hồ, hai anh em đã làm việc','','','4000-essential-english-words-132'),
	('At last, the finished statue was situated in front of the museum','Cuối cùng, bức tượng được hoàn thành đã được đặt trước cửa bảo tàng','','','4000-essential-english-words-132'),
	('Everyone applauded the brothers\' good work','Tất cả mọi người tán dương việc tốt của hai anh em','','','4000-essential-english-words-132'),
	('"We worked together very well"','"Chúng tôi đã làm việc cùng nhau rất tốt"','','','4000-essential-english-words-132'),
	('"I guess we are compatible after all," Mark said','"Tôi nghĩ cuối cùng thì chúng tôi cũng hợp nhau," Mark nói','','','4000-essential-english-words-132'),
	('John replied, "I agree"','John đáp, "Tôi đồng ý"','','','4000-essential-english-words-132'),
	('"When we combine our talents, we are capable of greatness"','"Khi chúng ta kết hợp lại những tài năng của nhau, chúng ta có khả năng tạo ra những điều tốt đẹp"','','','4000-essential-english-words-132'),

	/* (UUID(),'4000-essential-english-words-133','The Old Hound','Chú chó săn già','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_133.mp3',NULL,'','','4000-essential-english-words','NO',133) */
	('Elvis was a dog that loved to run','Elvis là một con chó rất thích chạy','','','4000-essential-english-words-133'),
	('He possessed all the criteria to be a great racing dog','Nó sở hữu tất cả các tiêu chuẩn để trở thành một chú chó đua giỏi','','','4000-essential-english-words-133'),
	('He had long legs, lean muscles, and a strong heart','Nó có đôi chân dài, nhiều cơ bắp và một trái tim khỏe mạnh','','','4000-essential-english-words-133'),
	('He was so good that he never lost a race in the northern hemisphere','Nó cực kỳ giỏi đến mức mà nó không bao giờ thua trong các cuộc thi chạy ở bán cầu bắc','','','4000-essential-english-words-133'),
	('Spectators who bet on dog races always picked Elvis to win','Khán giả, những người chơi cá cược trong các cuộc đua chó luôn chọn Elvis thắng','','','4000-essential-english-words-133'),
	('After ten years of racing, however, Elvis was getting old','Tuy nhiên, sau mười năm chạy đua, Elvis trở nên già yếu','','','4000-essential-english-words-133'),
	('His faculties were not as strong as they used to be','Những khả năng của nó đã không còn mạnh như trước','','','4000-essential-english-words-133'),
	('His owner got upset when Elvis started losing','Chủ của Elvis đã rất buồn khi nó bắt đầu thua','','','4000-essential-english-words-133'),
	('Elvis\'s owner wasn\'t a considerate person','Người chủ đó của Elvis không phải là một người tử tế','','','4000-essential-english-words-133'),
	('He degraded the dog all the time','Ông ta đay nghiến con chó suốt ngày','','','4000-essential-english-words-133'),
	('Finally, his owner decided to get rid of him','Cuối cùng, chủ của có quyết định bỏ nó đi','','','4000-essential-english-words-133'),
	('He threw Elvis in his car and took him to the middle of the forest','Ông ta ném Elvis vào trong xe hơi của mình và đưa nó đến giữa rừng','','','4000-essential-english-words-133'),
	('He tossed him out and drove away','Ông ta quăng nó ra ngoài và lái xe đi','','','4000-essential-english-words-133'),
	('Elvis was cold and scared','Elvis rất lạnh và sợ hãi','','','4000-essential-english-words-133'),
	('He decided to follow a brook into the city','Nó quyết định men theo một con suối nhỏ vào trong thành phố','','','4000-essential-english-words-133'),
	('Elvis soon found out that the city was a big and impersonal place','Elvis nhanh chóng nhận ra rằng thành phố là một nơi rất to và vô cảm','','','4000-essential-english-words-133'),
	('Everywhere he went, he saw signs that said, "No Dogs Allowed"','Tất cả mọi nơi nó đi qua, nó đều nhìn thấy những kí hiệu, "Không được phép có chó"','','','4000-essential-english-words-133'),
	('Pedestrians yelled at him','Những người đi đường mắng nó','','','4000-essential-english-words-133'),
	('He was sad, hungry and alone','Nó rất buồn, đói và cô đơn','','','4000-essential-english-words-133'),
	('He thought that all people were as cruel and uncaring as his owner has been','Nó nghĩ rằng tất cả mọi người đều độc ác và không quan tâm đến nó như người chủ cũ của mình','','','4000-essential-english-words-133'),
	('He was ready to give up when he heard a soft voice say, "What a beautiful hound"','Nó gần như là đã bỏ cuộc cho đến khi nó nghe thấy một giọng nói nhẹ nhàng nói, "Thật là một chú chó săn xinh đẹp"','','','4000-essential-english-words-133'),
	('Elvis looked up and saw an old woman','Elvis nhìn lên và thấy một bà già','','','4000-essential-english-words-133'),
	('She said, "You\'re entitled to a better life than this"','Bà ấy nói, "Mày có quyền để có một cuộc sống tốt hơn thế này"','','','4000-essential-english-words-133'),
	('"I can take you to a sanctuary for old dogs like you"','Tao có thể đưa mày đến một nơi ở cho những con chó già như mày"','','','4000-essential-english-words-133'),
	('"I\'ll cater to all your needs"','"Tao sẽ cung cấp tất cả những thứ mày cần"','','','4000-essential-english-words-133'),
	('"Would you like to come with me?"','"Mày có muốn đi với tao không?"','','','4000-essential-english-words-133'),
	('The woman escorted Elvis to a beautiful facility','Người đàn bà hộ tống Elvis đến một chỗ tuyệt đẹp','','','4000-essential-english-words-133'),
	('There was a sign on the external door that said, "Dogs Welcome"','Có một ký hiệu ở cánh cửa bên ngoài, "Chào mừng các chú chó"','','','4000-essential-english-words-133'),
	('The interior of the building was painted blue, and shiny ornaments hung from the ceiling','Nội thất của tòa nhà được sơn màu xanh, những đồ trang trí sáng bóng treo trên trần nhà','','','4000-essential-english-words-133'),
	('There was a heap of tasty bones and bread crusts for consumption','Còn có một đống xương ngon và những mẩu bánh mì khô để ăn','','','4000-essential-english-words-133'),
	('Elvis learned there were kind people in the world after all','Elvis nhận ra rằng sau tất cả, trên thế giới vẫn còn có những người tốt','','','4000-essential-english-words-133'),
	('He was so thankful that he jumped up and licked the woman\'s face','Nó cảm thấy rất biết ơn đến mức mà nó đã nhảy lên và liếm khuôn mặt của bà ấy','','','4000-essential-english-words-133'),

	/* (UUID(),'4000-essential-english-words-134','Day Without Sight','Ngày không có thị giác','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_134.mp3',NULL,'','','4000-essential-english-words','NO',134) */
	('On Friday afternoon, Sam\'s teacher had a special assignment','Vào chiều thứ Sáu, giáo viên của Sam đã đưa ra 1 nhiệm vụ đặc biệt','','','4000-essential-english-words-134'),
	('"Next week, we\'ll be studying humanitarian efforts around the world since the time of the Renaissance, including those to help the blind," she said','"Tuần tới, chúng ta sẽ nghiên cứu về những nỗ lực nhân đạo trên toàn thế giới từ thời kỳ Phục hưng bao gồm việc giúp đỡ người mù," cô ấy nói','','','4000-essential-english-words-134'),
	('"Over the weekend, I want each of you to wear a blindfold for an entire day"','"Trong cuối tuần này, cô muốn mỗi người trong các bạn đeo bịt mắt trong cả ngày"','','','4000-essential-english-words-134'),
	('"The premise of this experiment is that it will help you understand what it\'s like to be blind," she said','"Tiền đề của trải nghiệm này sẽ giúp các em hiểu việc không nhìn thấy gì sẽ như thế nào," cô ấy nói','','','4000-essential-english-words-134'),
	('Sam was a skeptic','Sam là một người đa nghi','','','4000-essential-english-words-134'),
	('He really didn\'t think the assignment would be too challenging','Cậu đã không thực sự nghĩ rằng nhiệm vụ này sẽ quá thách thức','','','4000-essential-english-words-134'),
	('On Saturday morning, Sam took a piece of cloth and tied it around his head to cover his eyes','Vào sáng thứ Bảy, Sam lấy một miếng vải và buộc nó vòng quanh đầu để che mắt','','','4000-essential-english-words-134'),
	('Then he went into the kitchen for breakfast','Sau đó cậu ấy đi vào nhà bếp để ăn sáng','','','4000-essential-english-words-134'),
	('He heard the voices of his parents and brothers but couldn\'t specify where each voice was coming from','Cậu ấy nghe thấy tiếng nói của ba mẹ và các anh em nhưng không thể xác định nơi chúng phát ra','','','4000-essential-english-words-134'),
	('He thought about how important hearing is for blind people','Cậu ấy nghĩ việc nghe thật quan trọng đối với người mù','','','4000-essential-english-words-134'),
	('"Could you pass me the newspaper, please?" he asked','"Em có thể đưa cho anh tờ báo được không?" cậu ấy hỏi','','','4000-essential-english-words-134'),
	('Just then, he remembered he couldn\'t see the words on the page','Ngay sau đó, cậu ấy nhớ ra mình không thể nhìn thấy các dòng chữ trên tờ báo','','','4000-essential-english-words-134'),
	('He wondered if Braille newspapers were ever made','Cậu ấy tự hỏi liệu rằng báo chữ nổi đã được làm ra chưa','','','4000-essential-english-words-134'),
	('After finishing breakfast, his brothers asked him to play soccer','Sau bữa sáng, các anh em trai rủ cậu cùng chơi bóng đá','','','4000-essential-english-words-134'),
	('As he followed them, he accidentally walked into the baker\'s rack','Khi đi theo họ, cậu ấy đã vô tình va vào kệ tủ của người thợ làm bánh','','','4000-essential-english-words-134'),
	('He also found that he couldn\'t play soccer','Cậu ấy cũng nhận ra rằng mình không thể chơi bóng đá','','','4000-essential-english-words-134'),
	('He wouldn\'t be able to coordinate his actions without being able to see','Cậu sẽ không thể phối hợp các hoạt động trong khi không nhìn thấy gì','','','4000-essential-english-words-134'),
	('Without his optic senses, he had no spatial awareness','Không có thị giác, cậu không có nhận thức về không gian','','','4000-essential-english-words-134'),
	('Furthermore, he couldn\'t do simultaneous activities because he had to make sure he was safe first','Hơn thế nữa, cậu không thể thực hiện các hành động đồng thời vì cậu phải đảm bảo mình an toàn trước','','','4000-essential-english-words-134'),
	('He sat on the lawn','Cậu ấy ngồi trên bãi cỏ','','','4000-essential-english-words-134'),
	('Suddenly, he realized that though he couldn\'t see, his other senses worked perfectly fine','Bất chợt, cậu nhận ra rằng vì mình không thể nhìn thấy, các giác quan khác hoạt động hoàn toàn ổn','','','4000-essential-english-words-134'),
	('In fact, he began to realize new and different aspects of common objects','Thực tế, cậu bắt đậu nhận ra khía cạnh mới và khác nhau của những vật thông thường','','','4000-essential-english-words-134'),
	('For example, he took a flower bud and felt it with his finger','Ví dụ, cậu bé nhặt lấy 1 nụ hoa và cảm nhận nó bằng ngón tay','','','4000-essential-english-words-134'),
	('He realized for the first time that it seemed to be covered with wax','Lần đầu tiên cậu bé nhận thấy rằng nó có vẻ như được bao phủ bằng lông','','','4000-essential-english-words-134'),
	('His hypothesis about being blind was disproved','Giả thuyết của cậu bé về việc bị mù đã bị bác bỏ','','','4000-essential-english-words-134'),
	('The informative experiment had an imprint on him','Trải nghiệm hữu ích đã để lại một dấu ấn cho cậu bé','','','4000-essential-english-words-134'),
	('It showed him sight was an asset that should be appreciated and taught him to revere the talents of blind people','Nó cho cậu thấy rằng thị lực của cậu chính là 1 vốn quý nên được coi trọng và dạy cậu tôn trọng những tài năng của người mù','','','4000-essential-english-words-134'),

	/* (UUID(),'4000-essential-english-words-135','The Big Ship','Con tàu lớn','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_135.mp3',NULL,'','','4000-essential-english-words','NO',135) */
	('Ernest looked at his fleet of ships','Ernest nhìn đội tàu của mình','','','4000-essential-english-words-135'),
	('Usually, he used them for his firm, which imported marble statues from other countries','Thường ngày, ông dùng chúng cho công ty của mình để nhập khẩu những bức tượng đá cẩm thạch từ các nước khác','','','4000-essential-english-words-135'),
	('But today he was going fishing','Nhưng hôm nay ông đi câu cá','','','4000-essential-english-words-135'),
	('And the ship he chose was his favorite','Và ông đã chọn con tàu yêu thích của mình','','','4000-essential-english-words-135'),
	('It had an elaborate painting on the side that showed a naval battle','Nó có một bức tranh tinh vi trên mặt về một trận chiến hải quân','','','4000-essential-english-words-135'),
	('It also had some new updates to its computer system','Nó cũng có một số cập nhật mới trên hệ thống máy tính','','','4000-essential-english-words-135'),
	('His favorite ship\'s latest acquisition was a device with a small grid to show the ship\'s exact location','Trang bị mới nhất cho con tàu ưa thích của ông là một thiết bị với đường kẻ ô nhỏ cho biết vị trí chính xác của con tàu','','','4000-essential-english-words-135'),
	('This new accessory kept Ernest from getting lost','Trang bị mới này giúp Ernest khỏi bị lạc','','','4000-essential-english-words-135'),
	('At daybreak, Ernest happily sailed the temperate waters until he was far from land','Lúc rạng đông, Ernest vui vẻ ra khơi trong vùng nước ấm cho đến khi ông ra xa đất liền','','','4000-essential-english-words-135'),
	('Then he saw a small boat in the distance','Sau đó ông nhìn thấy một chiếc thuyền nhỏ ở đằng xa','','','4000-essential-english-words-135'),
	('There was an old man standing next to its mast','Ở đó có một ông già đang đứng bên cạnh cột buồm','','','4000-essential-english-words-135'),
	('He was waving his arms in the air','Ông ta đang vẫy tay trên không trung','','','4000-essential-english-words-135'),
	('There was also a boy with his head hanging over the boat\'s edge','Ở đó cũng có một cậu bé đang chấp chới nhô đầu bên mép tàu','','','4000-essential-english-words-135'),
	('Ernest inferred that the boy was suffering from nausea','Ernest đoán rằng cậu bé đang phải chịu đựng việc nôn mửa','','','4000-essential-english-words-135'),
	('Both of their clothes were saturated with sea water','Quần áo của cả hai người đã ướt đẫm nước biển','','','4000-essential-english-words-135'),
	('Ernest assumed that they were in trouble','Ernest cho rằng họ đang gặp rắc rối','','','4000-essential-english-words-135'),
	('Most people never realized, but Ernest had an innate desire to help people','Hầu hết mọi người không bao giờ nhận ra, nhưng Ernest có mong muốn bẩm sinh để giúp đỡ mọi người','','','4000-essential-english-words-135'),
	('He began sailing toward them, eager to facilitate their rescue and thus solve their dilemma','Ông bắt đầu tiến đến gần họ, cố gắng tạo điều kiện thuận tiện cho việc giải cứu và giải quyết tình thế khó xử của họ','','','4000-essential-english-words-135'),
	('As he got closer to the boat, he was shocked by its simplicity','Khi ông tiến gần đến tàu, ông đã bị sốc bởi sự đơn giản của nó','','','4000-essential-english-words-135'),
	('The boat\'s wood looked no stronger than cardboard, and the equipment was old','Gỗ của tàu trông không vững chắc hơn bìa cứng là bao, và các trang thiết bị đã cũ','','','4000-essential-english-words-135'),
	('Still, there were several large fish in a pouch in the boat','Tuy nhiên, vẫn có một vài con cá lớn trong một túi nhỏ bên trong thuyền','','','4000-essential-english-words-135'),
	('Ernest threw a large package onto the boat','Ernest ném một cái túi lớn lên trên thuyền','','','4000-essential-english-words-135'),
	('He yelled, "Here. You can inflate this boat to get you back to land"','Ông hét lên, "Đây này. Hai người có thể bơm con thuyền này để trờ về đất liền"','','','4000-essential-english-words-135'),
	('"Get out of here" screamed the old man','"Ra khỏi đây ngay" Ông già hét lên','','','4000-essential-english-words-135'),
	('Ernest was confused','Ernest cảm thấy bối rối','','','4000-essential-english-words-135'),
	('"Don\'t you need help?" he asked','"Ông không cần giúp gì sao?" Ernest hỏi','','','4000-essential-english-words-135'),
	('"Your ship doesn\'t seem adequate enough to sail so far away from land"','"Tàu của ông có vẻ không đủ chắc chắn để ra khơi xa đất liền"','','','4000-essential-english-words-135'),
	('"You\'ve just scared away a huge fish," the boy said','"Chú vừa dọa sợ mất một con cá lớn" cậu bé nói','','','4000-essential-english-words-135'),
	('"We waved to let you know you were too close to us"','"Chúng tôi vẫy tay để chú biết rằng chú ở quá gần chúng tôi"','','','4000-essential-english-words-135'),
	('Ernest turned around and headed home','Ernest quay đầu và trở về nhà','','','4000-essential-english-words-135'),
	('He learned that it\'s better not to help unless asked to','Ông ấy học được rằng tốt hơn hết là không giúp đỡ trừ khi được yêu cầu','','','4000-essential-english-words-135'),
	('Otherwise, you might not help anyone at all','Nếu không thì bạn sẽ chẳng giúp được bất cứ ai','','','4000-essential-english-words-135');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-136','The History of Parachutes','Lịch sử của những chiếc dù','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_136.mp3',NULL,'','','4000-essential-english-words','NO',136) */
	('Scientists who study archeology say that there may be some evidence of prehistoric parachutes','Các nhà khoa học nghiên cứu khảo cổ học nói rằng có thể có một số bằng chứng về những chiếc dù thời tiền sử','','','4000-essential-english-words-136'),
	('But the first written history of the device comes from China about 2,100 years ago','Nhưng lịch sử được viết ra đầu tiên của thiết bị này đến từ Trung Quốc khoảng 2.100 năm trước','','','4000-essential-english-words-136'),
	('Scientists cite an ancient book that describes parachutes','Các nhà khoa học trích dẫn một cuốn sách cổ mô tả về những chiếc dù','','','4000-essential-english-words-136'),
	('However, there is no archeological evidence that proves that an actual parachute was ever made','Tuy nhiên, không có bằng chứng khảo cổ học nào chứng minh rằng một chiếc dù thực sự đã từng được tạo ra','','','4000-essential-english-words-136'),
	('Later, people from northern Africa and Italy also had ideas about a similar invention','Sau đó, những người từ Bắc Phi và Ý cũng có ý tưởng về một phát minh tương tự','','','4000-essential-english-words-136'),
	('In fact, a Leonardo Da Vinci\'s drawing corresponds closely with the modern parachute design','Trên thực tế, bản vẽ của Leonardo Da Vinci gần giống với thiết kế của chiếc dù hiện đại','','','4000-essential-english-words-136'),
	('In 1783, French scientist Sebastian Lenormand invented the first modern parachute','Năm 1783, nhà khoa học người Pháp Sebastian Lenormand đã phát minh ra chiếc dù hiện đại đầu tiên','','','4000-essential-english-words-136'),
	('Sebastian brainstormed with other scientists to come up with a way to help people jump safely out of burning buildings','Sebastian đã đưa ra các ý kiến cùng các nhà khoa học khác để tìm ra cách giúp mọi người nhảy ra khỏi tòa nhà đang cháy một cách an toàn','','','4000-essential-english-words-136'),
	('He thought the solution was to give people an object to restrict their speed while they traveled toward the ground','Ông nghĩ rằng giải pháp là cung cấp cho mọi người một vật thể để hạn chế tốc độ của họ khi họ di chuyển về phía mặt đất','','','4000-essential-english-words-136'),
	('Many people thought that he was up to some kind of fraud, but Sebastian had a lot of integrity','Nhiều người cho rằng ông ấy đang lừa đảo, nhưng Sebastian rất chính trực','','','4000-essential-english-words-136'),
	('His budget was limited, so he first tested his theory by using two umbrellas','Ngân sách của ông có hạn, vì vậy lần đầu tiên ông thử nghiệm lý thuyết của mình bằng cách sử dụng hai chiếc ô','','','4000-essential-english-words-136'),
	('He jumped out of a tree and found that the umbrellas worked','Ông ấy nhảy ra khỏi một cái cây và thấy rằng những chiếc ô có tác dụng','','','4000-essential-english-words-136'),
	('Next, he refined his invention','Tiếp theo, ông hoàn thiện phát minh của mình','','','4000-essential-english-words-136'),
	('Rather than using umbrellas, he knit a large parachute','Thay vì sử dụng ô, ông ấy đan một chiếc dù lớn','','','4000-essential-english-words-136'),
	('Finally, he jumped off a tall building on a French estate and landed safely in the courtyard','Cuối cùng, ông nhảy khỏi một tòa nhà cao trong một khu đất ở Pháp và hạ cánh an toàn xuống dưới sân','','','4000-essential-english-words-136'),
	('Sebastian\'s work gave another man an idea','Việc làm của Sebastian đã cho một người đàn ông khác một ý tưởng','','','4000-essential-english-words-136'),
	('Jean-Pierre Blanchard had a different outlook than Sebastian','Jean-Pierre Blanchard có cách nhìn khác với Sebastian','','','4000-essential-english-words-136'),
	('He was a hot air balloon addict','Ông ấy là một người nghiện khinh khí cầu','','','4000-essential-english-words-136'),
	('He was one of the first people to ride in a hot air balloon powered by hydrogen gas','Ông là một trong những người đầu tiên lái khinh khí cầu chạy bằng khí hydro','','','4000-essential-english-words-136'),
	('He was a proponent of using the parachutes to exit from hot air balloons','Ông là người đề xuất việc sử dụng dù để thoát khỏi khinh khí cầu','','','4000-essential-english-words-136'),
	('Starting in 1785, he used his dog to show that animals could land safely from hot air balloons by using parachutes','Bắt đầu từ năm 1785, ông sử dụng con chó của mình để chứng minh rằng động vật có thể hạ cánh an toàn từ khinh khí cầu bằng cách sử dụng dù','','','4000-essential-english-words-136'),
	('Then, in 1793, he was faced with a chaotic experience','Sau đó, vào năm 1793, ông phải đối mặt với một trải nghiệm hỗn loạn','','','4000-essential-english-words-136'),
	('The hot air balloon he was riding in burst and started to fall','Khinh khí cầu mà ông ấy đang lái đã vỡ tung và bắt đầu rơi xuống','','','4000-essential-english-words-136'),
	('He was forced to use a parachute himself','Ông buộc phải tự mình sử dụng một chiếc dù','','','4000-essential-english-words-136'),
	('And much to his relief, it saved his life','Và thật là nhẹ nhõm khi nó đã cứu mạng ông','','','4000-essential-english-words-136'),

	/* (UUID(),'4000-essential-english-words-137','I Didn\'t Do It','Tôi không thể làm được','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_137.mp3',NULL,'','','4000-essential-english-words','NO',137) */
	('Billy was in big trouble','Billy gặp rắc rối lớn','','','4000-essential-english-words-137'),
	('The day before, a donor gave the school a painting with a sports theme','Ngày hôm trước, một người quyên góp tặng trường học một bức tranh với đề tài thể thao','','','4000-essential-english-words-137'),
	('It showed a referee congratulating two athletes','Bức tranh vẽ một trọng tài đang chúc mừng hai vận động viên','','','4000-essential-english-words-137'),
	('The principal hung the painting in front of the office, hoping that it would be a stimulus for students to play sports','Hiệu trưởng treo bức tranh ở phía trước của văn phòng, hy vọng rằng đây sẽ là một sự khuyến khích cho học sinh chơi thể thao','','','4000-essential-english-words-137'),
	('The next morning, however, the painting was destroyed','Tuy nhiên vào sáng hôm sau, bức tranh đã bị hủy hoại','','','4000-essential-english-words-137'),
	('There was graffiti on it, and it had many holes in it','Có vết vẽ trên tường và có rất nhiều lỗ trên bức tranh','','','4000-essential-english-words-137'),
	('The worst part was that one of Billy\'s fellow students said she thought she saw Billy do it','Điều tồi tệ nhất là một trong những học sinh bạn thân của Billy nói rằng cô nghĩ rằng mình đã thấy Billy làm điều đó','','','4000-essential-english-words-137'),
	('But Billy didn\'t do it','Nhưng Billy đã không làm như việc đó','','','4000-essential-english-words-137'),
	('The principal called Billy\'s parents and said, "Billy won\'t tell us the truth"','Hiệu trưởng mời cha mẹ của Billy và nói, "Billy sẽ không nói cho chúng ta sự thật"','','','4000-essential-english-words-137'),
	('"He\'s a chronic liar, and he ruined the painting"','"Cậu là một kẻ thường xuyên nói dối, và cậu đã hủy hoại bức tranh"','','','4000-essential-english-words-137'),
	('"If you don\'t pay for it, we\'ll terminate his education here"','"Nếu hai người không trả tiền cho bức tranh đó, chúng tôi sẽ đình chỉ việc học của cậu ở đây"','','','4000-essential-english-words-137'),
	('Billy\'s parents didn\'t have enough money to pay for the painting and for his tuition','Cha mẹ của Billy không có đủ tiền để trả cho bức tranh cũng như học phí của Billy','','','4000-essential-english-words-137'),
	('But Billy\'s parents had an idea','Nhưng họ có một ý tưởng','','','4000-essential-english-words-137'),
	('That afternoon, they went to see Mr.Meyers, an attorney','Chiều hôm đó, họ đã đến gặp ông Meyers, một luật sư','','','4000-essential-english-words-137'),
	('"Mr.Meyers, my son has been implicated in a crime he says he didn\'t do," Billy\'s father said','"Ông Meyers, con trai tôi đã bị gán cho một tội ác mà nó nói rằng nó không làm", cha Billy nói','','','4000-essential-english-words-137'),
	('"Everybody believes the gossip"','"Mọi người đều tin vào tin đồn nhảm"','','','4000-essential-english-words-137'),
	('"Even some of our own kin think he did it"','"Ngay cả một số họ hàng của chúng tôi cũng nghĩ rằng thằng bé đã làm điều đó"','','','4000-essential-english-words-137'),
	('"I believe you"','"Tôi tin ông"','','','4000-essential-english-words-137'),
	('"My suspicion is that the tape from the security cameras will show who really did it," said Mr.Meyers','"Sự nghi ngờ của tôi là đoạn băng từ camera an ninh sẽ cho chúng ta thấy người thực sự làm điều đó", ông Meyers nói','','','4000-essential-english-words-137'),
	('The next day, Mr.Meyers received a packet with the videotape from the school','Ngày hôm sau, ông Meyers nhận được một cái túi với các băng video từ trường học','','','4000-essential-english-words-137'),
	('It showed another student who resembled Billy walking up to the painting and writing on it','Đoạn băng cho thấy một học sinh trông giống như Billy đi về phía bức tranh và vẽ lên đó','','','4000-essential-english-words-137'),
	('Then the student took a knife by the shaft and started to stab large holes in it','Sau đó, cậu ta lấy một con dao sắc và bắt đầu đâm nhiều lỗ lớn vào bức tranh','','','4000-essential-english-words-137'),
	('Finally, he severed the rope that held up the painting, and it fell to the floor','Cuối cùng, cậu ta cắt đứt dây buộc giữ bức tranh, và nó rơi xuống sàn','','','4000-essential-english-words-137'),
	('Mr.Meyers showed the tape to the principal','Ông Meyers cho hiệu trưởng xem đoạn băng','','','4000-essential-english-words-137'),
	('"Clearly, that\'s not Billy," he said','"Rõ ràng người đó không phải là Billy", ông nói','','','4000-essential-english-words-137'),
	('"This boy is actually responsible and needs some discipline"','"Cậu bé này là thực sự có trách nhiệm và cần kỉ luật"','','','4000-essential-english-words-137'),
	('Billy was happy that someone believed him','Billy rất vui khi có người tin mình','','','4000-essential-english-words-137'),
	('He said to Mr.Meyers, "When I graduate and go to university, I will major in law, so I can be a guardian of justice like you"','Cậu nói với ông Meyers, "Khi cháu tốt nghiệp và vào đại học, cháu sẽ học luật để có thể trở thành một người bảo vệ công lý như ông"','','','4000-essential-english-words-137'),

	/* (UUID(),'4000-essential-english-words-138','The Soldier\'s Decision','Quyết định của người lính','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_138.mp3',NULL,'','','4000-essential-english-words','NO',138) */
	('A soldier was captured while fighting in an enemy king\'s land','Một nguời lính đã bị bắt trong khi chiến đấu ở vùng đất của một vị vua đối địch','','','4000-essential-english-words-138'),
	('It was well known that this king would make captives fight one another','Ai cũng biết rằng vị vua này sẽ cho những người bị bắt giữ chiến đấu với nhau','','','4000-essential-english-words-138'),
	('This was commonplace during his reign','Điều này đã trở nên bình thường trong suốt triều đại của ông','','','4000-essential-english-words-138'),
	('For these fights, the king had built several large arenas','Để phục vụ cho các cuộc chiến này, vị vua đã cho xây dựng một vài vũ đài lớn','','','4000-essential-english-words-138'),
	('He often awarded the winners by setting them free or even having them join his elite army corps','Ông thường tặng thưởng những người chiến thắng bằng cách cho họ tự do hoặc thậm chí để họ tham gia lực lượng quân đội tinh nhuệ của mình','','','4000-essential-english-words-138'),
	('The soldier, however, decided he had seen too much violence','Tuy nhiên người lính đã quyết định khi anh ấy đã nhìn thấy quá nhiều bạo lực','','','4000-essential-english-words-138'),
	('He now felt that all life was sacred','Bây giờ anh ấy cảm thấy rằng mọi sự sống đều là thiêng liêng','','','4000-essential-english-words-138'),
	('The night before his first match, he made a risky decision','Đêm trước trận đấu đầu tiên của mình, anh đã thực hiện một quyết định mạo hiểm','','','4000-essential-english-words-138'),
	('He decided that he would not engage in combat','Anh quyết định rằng anh sẽ không tham gia vào trận đấu','','','4000-essential-english-words-138'),
	('He knew he may never be set free, but it was a decision that he was willing to accept','Anh ấy biết mình có thể không bao giờ có được tự do, nhưng đó là một quyết định mà anh sẵn sàng chấp nhận','','','4000-essential-english-words-138'),
	('In the morning, he was led from the prisoners\' compound to one of the king\'s arenas','Vào buổi sáng, anh được dẫn dắt từ nhà lao của các tù nhân đến một trong các vũ đài của nhà vua','','','4000-essential-english-words-138'),
	('A gate coated in rust stood between him and the auditorium\'s floor','Một cánh cổng gỉ sét ngăn cách anh và khán phòng','','','4000-essential-english-words-138'),
	('He was worried, but he knew what he had to do','Anh cảm thấy lo lắng, nhưng anh biết những gì mình cần phải làm','','','4000-essential-english-words-138'),
	('When the gate opened, he calmly walked to the center of the arena and sat','Khi cánh cổng mở ra, anh bình tĩnh bước đến trung tâm của vũ đài và ngồi xuống','','','4000-essential-english-words-138'),
	('He started to meditate','Anh bắt đầu ngồi thiền','','','4000-essential-english-words-138'),
	('His foe Darius, who was skilled in the realm of sword fighting and was typically not very aggressive, would not fight the quiet soldier until he attacked Darius first','Kẻ địch của anh ấy, Darius, người có kỹ năng cao trong lĩnh vực đấu kiếm và không phải là kiểu người quá hung hãn, sẽ không đánh lại người lính lặng yên kia cho đến khi anh ấy tấn công Darius trước','','','4000-essential-english-words-138'),
	('Darius tried to provoke him by hacking at the air close to his head with his sword','Darius đã cố gắng khiêu khích người lính bằng cách chém cây kiếm mạnh vào không khí gần sát với đầu của anh ấy','','','4000-essential-english-words-138'),
	('But the soldier was not distracted','Nhưng người lính không bị mất tập trung','','','4000-essential-english-words-138'),
	('He sat quietly, as if he were dumb, and looked calmly up at the sky','Anh vẫn ngồi yên, như thể anh bị câm, và bình tĩnh nhìn lên bầu trời','','','4000-essential-english-words-138'),
	('Even when Darius nicked him on the cheek with the edge of his sword, the soldier did not move','Ngay cả khi Darius cắt vào má anh ấy với lưỡi gươm của mình, người lính cũng không di chuyển','','','4000-essential-english-words-138'),
	('At last he threw down his sword and shield and gave up','Cuối cùng Darius ném thanh kiếm và cái khiên của mình xuống và bỏ cuộc','','','4000-essential-english-words-138'),
	('"I can\'t fight someone who refuses to fight me" Darius shouted to the king','"Tôi không thế đánh với ai đó từ chối đấu với tôi" Darius hét lên với vua','','','4000-essential-english-words-138'),
	('The king was very impressed with the soldier','Nhà vua đã rất ấn tượng với người lính','','','4000-essential-english-words-138'),
	('Never in any battle had he seen someone so brave','Chưa bao giờ trong bất kỳ trận chiến nào ông thấy một người dũng cảm như vậy','','','4000-essential-english-words-138'),
	('As a result, he gave the peaceful soldier amnesty','Kết quả là, ông đã cho ân xá người lính vì hòa bình đó','','','4000-essential-english-words-138'),
	('The soldier\'s actions proved to the king and everyone in the arena that peace was more powerful than fighting','Hành động của người lính đã chứng minh cho nhà vua và tất cả mọi người trong vũ đài rằng hòa bình mạnh hơn rất nhiều so với chiến tranh','','','4000-essential-english-words-138'),

	/* (UUID(),'4000-essential-english-words-139','Jane\'s Pride','Niềm kiêu hãnh của Jane','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_139.mp3',NULL,'','','4000-essential-english-words','NO',139) */
	('Jane and her father, Mike, owned a secondhand boat','Jane và cha cô ấy - Mike sở hữu một chiếc thuyền đã qua sử dụng','','','4000-essential-english-words-139'),
	('They called it "High Hopes"','Họ gọi nó là "Niềm hy vọng lớn"','','','4000-essential-english-words-139'),
	('The two loved to spend time together on the ocean and would often go on long fishing trips','Hai cha con thích dành thời gian cùng nhau ở trên biển và thường xuyên có những chuyến đi câu dài ngày','','','4000-essential-english-words-139'),
	('Mike taught Jane how to perform important tasks','Mike dạy con gái Jane cách để thực hiện các nhiệm vụ quan trọng','','','4000-essential-english-words-139'),
	('Jane learned how to steer the boat and adjust the sails','Jane đã học cách lái thuyền và điều chỉnh cánh buồm','','','4000-essential-english-words-139'),
	('She learned how to put grease on the intricate gears of the motor','Cô học được cách để tra dầu vào các bánh răng phức tạp của động cơ','','','4000-essential-english-words-139'),
	('She learned how to submerge the anchor and secure it by putting a rope in a slot','Cô học cách thả mỏ neo và bảo đảm an toàn bằng cách đặt một sợi dây thừng vào một rãnh','','','4000-essential-english-words-139'),
	('Jane liked helping her father, but she thought that she wasn\'t very good at it','Jane thích giúp đỡ cha mình, nhưng cô nghĩ cô không giỏi cho lắm','','','4000-essential-english-words-139'),
	('Sometimes, she omitted important steps and made frequent mistakes','Thỉnh thoảng, cô bỏ qua những bước quan trọng và thường xuyên mắc lỗi','','','4000-essential-english-words-139'),
	('Jane thought she wasn\'t capable of manual labor','Jane nghĩ rằng cô không có khả năng trong việc lao động chân tay','','','4000-essential-english-words-139'),
	('Mike wanted to prove to her that she was indeed capable and important','Mike muốn chứng minh cho cô rằng cô thực sự có đủ khả năng và là người quan trọng','','','4000-essential-english-words-139'),
	('He thought of a tactic to test Jane\'s skills in the context of a catastrophe','Ông nghĩ ra một chiến thuật để kiểm tra kĩ năng của Jane trong hoàn cảnh một tai họa','','','4000-essential-english-words-139'),
	('He hid under the deck and pretended to be trapped','Ông trốn dưới sàn và giả vờ mình bị mắc kẹt','','','4000-essential-english-words-139'),
	('He shouted, "Jane, I can\'t get out"','Ông hét lên, "Jane, cha không thể thoát ra"','','','4000-essential-english-words-139'),
	('"You have to get back to the dock and find help"','"Con phải quay lại bến tàu và tìm giúp đỡ"','','','4000-essential-english-words-139'),
	('Jane began to panic','Jane bắt đầu hoảng loạn','','','4000-essential-english-words-139'),
	('She thought she might make her usual mistakes, which would precipitate a disaster','Cô nghĩ rằng mình sẽ phạm phải những sai lầm quen thuộc của mình, và điều đó sẽ dẫn tới một thảm họa','','','4000-essential-english-words-139'),
	('However, she had to listen to her dad and act accordingly','Tuy nhiên, cô phải nghe lời cha mình và hành động sao cho phù hợp','','','4000-essential-english-words-139'),
	('She pulled up the anchor with all of her might','Cô kéo mỏ neo lên với tất cả sức của mình','','','4000-essential-english-words-139'),
	('She remembered to overlap the sails to offset the wind','Cô nhớ phải chồng các cánh buồm lên nhau để cân bằng hướng gió','','','4000-essential-english-words-139'),
	('She steered the boat around buoys where the water was shallow','Cô chèo lái con thuyền quanh những cái phao cứu nạn nơi nước đã nông','','','4000-essential-english-words-139'),
	('When they got to shore, Mike came out from under the deck','Khi họ đã đến bờ, Mike đi ra từ boong tàu','','','4000-essential-english-words-139'),
	('Jane said, "I thought you were trapped"','Jane nói, "Con tưởng rằng cha đang bị mắc kẹt"','','','4000-essential-english-words-139'),
	('Mike laughed','Mike cười','','','4000-essential-english-words-139'),
	('He said, "It wasn\'t a genuine emergency"','Ông nói, "Đó không phải là một tình huống khẩn cấp thật"','','','4000-essential-english-words-139'),
	('"I distorted the truth to test your abilities"','"Cha đã xuyên tạc sự thật để kiểm tra khả năng của con"','','','4000-essential-english-words-139'),
	('"Look at what a great job you did getting the boat home safely"','"Hãy nhìn xem con đã làm được những gì để đưa con tàu trở về an toàn"','','','4000-essential-english-words-139'),
	('"I knew you could do it"','"Cha biết con có thể làm được mà"','','','4000-essential-english-words-139'),
	('To honor his daughter, Mike decided to rename his boat','Để tôn vinh con gái mình, Mike quyết định đổi tên cho chiếc thuyền','','','4000-essential-english-words-139'),
	('He designated it "Jane\'s Pride" and painted the name on the fore of the ship','Ông chỉ rõ nó là "Niềm kiêu hãnh của Jane" và sơn tên lên mũi tàu','','','4000-essential-english-words-139'),
	('Jane finally had something to be proud of','Jane cuối cùng cũng có thứ gì đó để được tự hào','','','4000-essential-english-words-139'),

	/* (UUID(),'4000-essential-english-words-140','Microchips','Vi mạch','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_140.mp3',NULL,'','','4000-essential-english-words','NO',140) */
	('The bond between humans and computers is becoming more intimate than ever before','Mối liên kết giữa con người và máy tính ngày càng trở nên mật thiết hơn bao giờ hết','','','4000-essential-english-words-140'),
	('Scientists are now putting microchips inside people\'s bodies','Các nhà khoa học hiện nay đang đưa vi mạch vào bên trong cơ thể người','','','4000-essential-english-words-140'),
	('They are made up of compressed electrical circuits that can detect and record data about the body','Chúng được tạo thành từ những mạch điện nén có thể phát hiện và ghi lại các dữ liệu về cơ thể người','','','4000-essential-english-words-140'),
	('They are tiny, but they hold the equivalent amount of data as most computers','Chúng rất nhỏ, nhưng lưu trữ lượng dữ liệu tương đương với hầu hết máy tính','','','4000-essential-english-words-140'),
	('A microchip is put to use inside a person with a simple procedure','Một vi mạch được đưa vào sử dụng bên trong cơ thể người với 1 cuộc phẫu thuật đơn giản','','','4000-essential-english-words-140'),
	('First, a doctor must put data about the patient onto a chip','Đầu tiên, bác sĩ phải đưa dữ liệu về bệnh nhân vào vi mạch','','','4000-essential-english-words-140'),
	('Input about the person\'s age, race, gender, and medical history is stored on the chip','Dữ liệu về tuổi, chủng tộc, giới tính và tiền sử bệnh án của người đó được lưu trữ trên con chip','','','4000-essential-english-words-140'),
	('The second phase of the process involves putting it in the person\'s skin','Giai đoạn thứ 2 của quá trình bao gồm việc đưa con chip vào da của người đó','','','4000-essential-english-words-140'),
	('The doctor pinches a piece of skin and cuts a tiny hole with a tool shaped like a spiral','Bác sĩ kẹp 1 mẩu da và cắt 1 lỗ nhỏ bằng 1 công cụ có hình xoắn ốc','','','4000-essential-english-words-140'),
	('The chip is inserted, and the skin is allowed to heal','Con chip được đưa vào cơ thể, và da được chữa lành','','','4000-essential-english-words-140'),
	('At last, it begins the task of putting data into its database','Cuối cùng, nó bắt đầu nhiệm vụ đưa dữ liệu vào cơ sở dữ liệu của nó','','','4000-essential-english-words-140'),
	('Microchips scan the patient\'s body to record what is happening on the quantum level','Các vi mạch quét cơ thể bệnh nhân để ghi lại những gì đang xảy ra ở cấp độ lượng tử','','','4000-essential-english-words-140'),
	('They can find problems with the person\'s metabolism and organs','Chúng có thể tìm ra các vấn đề về sự trao đổi chất và nội tạng của người đó','','','4000-essential-english-words-140'),
	('They can also detect viral infections','Chúng cũng có thể phát hiện ra việc nhiễm virus','','','4000-essential-english-words-140'),
	('They can find the aggregate number of immune and infected cells and present the results in a ratio','Chúng có thể phát hiện tổng số lượng tế bào miễn dịch và tế bào đã bị nhiễm bệnh và trình bày kết quả theo tỷ lệ','','','4000-essential-english-words-140'),
	('They can even tell doctors what type of antibiotic to give to the patient','Chúng thậm chí có thể cho bác sĩ biết loại kháng sinh nào có thể dùng cho bệnh nhân','','','4000-essential-english-words-140'),
	('To recover the chip\'s data, the doctor uses a special magnet that copies it','Để khôi phục dữ liệu con chip, bác sĩ sử dụng 1 nam châm đặc biệt để sao chép dữ liệu','','','4000-essential-english-words-140'),
	('This way, the doctor can put the information from the chip onto a computer','Bằng cách này, bác sĩ có thể đưa thông tin từ con chip vào máy tính','','','4000-essential-english-words-140'),
	('Then they can find out exactly what is wrong with the person','Sau đó, họ có thể tìm ra chính xác điều gì bất thường xảy ra với cơ thể người bệnh','','','4000-essential-english-words-140'),
	('The idea of putting chips in humans is still very new','Ý tưởng đưa vi mạch vào cơ thể người vẫn còn rất mới','','','4000-essential-english-words-140'),
	('However, it is now becoming more prevalent','Tuy nhiên, nó ngày càng trở nên phổ biến hơn','','','4000-essential-english-words-140'),
	('Scientists and doctors are hopeful about the future uses of microchips','Các nhà khoa học và các bác sĩ kỳ vọng vào những ứng dụng trong tương lai của vi mạch','','','4000-essential-english-words-140'),
	('Someday, all new babies might get a microchip soon after they are born','Một ngày nào đó, tất cả em bé có thể sẽ nhận 1 vi mạch ngay khi chúng được sinh ra','','','4000-essential-english-words-140'),
	('Doctors will be able to know about any problems from the very beginning','Các bác sĩ sẽ có thể biết được bất kể vấn đề gì ngay từ đầu','','','4000-essential-english-words-140'),
	('It is obvious that medicine and computers complement each other well','Rõ ràng là y học và máy tính bổ sung rất tốt cho nhau','','','4000-essential-english-words-140');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-141','The Twins','Song sinh','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_141.mp3',NULL,'','','4000-essential-english-words','NO',141) */
	('Katie and Alice were twins','Katie và Alice là một cặp song sinh','','','4000-essential-english-words-141'),
	('They were so alike that few people could tell the siblings apart','Họ giống nhau tới nỗi rất ít người có thể phân biệt được chị em họ','','','4000-essential-english-words-141'),
	('They were almost like clones','Họ giống nhau như bản sao vậy','','','4000-essential-english-words-141'),
	('They even used the same colloquial language as each other','Họ thậm chí còn sử dụng cùng một ngôn ngữ thông tục với nhau','','','4000-essential-english-words-141'),
	('They were best friends','Họ là bạn thân của nhau','','','4000-essential-english-words-141'),
	('But the twins\' attributes were not all identical','Nhưng tính cách của cặp sinh đôi không hoàn toàn giống nhau','','','4000-essential-english-words-141'),
	('Alice liked humanities, and Katie was a good linguist','Alice thích khoa học nhân văn, còn Katie là một nhà ngôn ngữ học giỏi','','','4000-essential-english-words-141'),
	('One summer, Katie decided to be a participant at a summer camp in France','Một mùa hè, Katie quyết định trở thành thành viên của một trại hè ở Pháp','','','4000-essential-english-words-141'),
	('Alice wasn\'t interested in the French language, so she didn\'t go','Alice không quan tâm đến tiếng Pháp, vì vậy cô đã không đi','','','4000-essential-english-words-141'),
	('But she felt angry that Katie wanted to spend the summer away from her','Nhưng cô cảm thấy tức giận vì Katie muốn dành cả mùa hè ở một nơi xa cô','','','4000-essential-english-words-141'),
	('Two months later, Katie returned','Hai tháng sau, Katie quay về','','','4000-essential-english-words-141'),
	('Alice dashed to the airport to greet her sister','Alice vội vã tới sân bay để chào đón em gái của cô','','','4000-essential-english-words-141'),
	('But when Alice saw Katie, she was astounded','Nhưng khi Alice thấy Katie, cô bị kinh ngạc','','','4000-essential-english-words-141'),
	('Katie was now bilingual, and she looked completely different','Katie bây giờ là người nói được hai thứ tiếng, và cô ấy trông hoàn toàn khác','','','4000-essential-english-words-141'),
	('She was wearing nice clothes, cosmetics and looked skinnier','Cô mặc quần áo đẹp, sử dụng mỹ phẩm và trông gầy hơn','','','4000-essential-english-words-141'),
	('Alice felt very messy next to her','Alice cảm thấy rất luộm thuộm khi ở cạnh cô','','','4000-essential-english-words-141'),
	('She was just wearing a fluorescent t-shirt, and her hair had knots in it','Cô chỉ mặc một chiếc áo sơ mi huỳnh quang, và tóc thì buộc túm','','','4000-essential-english-words-141'),
	('When Alice asked Katie about France, Katie was vague and didn\'t say much','Khi Alice hỏi Katie về Pháp, Katie mập mờ và không nói nhiều','','','4000-essential-english-words-141'),
	('It made Alice furious and filled her with disgust because in the past they\'d always told each other everything','Điều này làm cho Alice tức giận và tràn ngập sự phẫn nộ bởi trong quá khứ họ luôn luôn kể cho nhau mọi thứ','','','4000-essential-english-words-141'),
	('Now there was a huge gulf between them','Bây giờ đã có một hố sâu lớn ngăn cách họ','','','4000-essential-english-words-141'),
	('Over the weeks, the sisters spoke even less','Trong nhiều tuần, thậm chí hai chị em còn nói chuyện ít hơn nữa','','','4000-essential-english-words-141'),
	('Two months later, it was the twins\' birthday','Hai tháng sau, ngày sinh nhật của cặp sinh đôi','','','4000-essential-english-words-141'),
	('All their lives, they\'d had a ritual','Có một nghi thức trong suốt cuộc đời họ','','','4000-essential-english-words-141'),
	('Before their birthday, they\'d talk all night long','Trước ngày sinh nhật, họ sẽ nói chuyện với nhau cả đêm','','','4000-essential-english-words-141'),
	('That night, Alice came into Katie\'s bedroom','Đêm đó, Alice đi vào phòng ngủ của Katie','','','4000-essential-english-words-141'),
	('"I\'m sorry I haven\'t spoken much lately," Katie said','"Em xin lỗi em vì đã không nói chuyện nhiều thời gian gần đây" Katie nói','','','4000-essential-english-words-141'),
	('"I understand"','"Chị hiểu"','','','4000-essential-english-words-141'),
	('"You have new friends now," said Alice, angrily','"Bây giờ em đã có bạn bè mới," Alice tức giận nói','','','4000-essential-english-words-141'),
	('Katie said, "My French friends don\'t write much nowadays"','Katie nói, "Những người bạn Pháp của em bây giờ không viết nhiều"','','','4000-essential-english-words-141'),
	('"For a while, I thought they were more exciting than my friends at home"','Đã có lúc em nghĩ rằng họ thú vị hơn bạn bè ở nhà của em"','','','4000-essential-english-words-141'),
	('"But I was wrong"','Nhưng em đã sai','','','4000-essential-english-words-141'),
	('"You\'re my sister, and you\'ll always be my best friend"','"Chị là chị gái của em, và chị sẽ luôn là người bạn tuyệt vời nhất của em"','','','4000-essential-english-words-141'),
	('Alice said, "I\'m sorry, too"','Alice nói, "Chị cũng xin lỗi"','','','4000-essential-english-words-141'),
	('"I wanted our relationship to stay the same forever"','"Chị muốn mối quan hệ của chúng ta được như trước mãi mãi"','','','4000-essential-english-words-141'),
	('"But it\'s totally plausible for twins to have different interests"','"Nhưng hoàn toàn hợp lý khi các cặp song sinh có những sở thích khác nhau"','','','4000-essential-english-words-141'),
	('"We can still be best friends without being together all the time"','"Chúng ta lúc nào cũng có thể là bạn thân mặc dù không ở bên nhau"','','','4000-essential-english-words-141'),

	/* (UUID(),'4000-essential-english-words-142','The New Bioco','Công ty New Bioco','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_142.mp3',NULL,'','','4000-essential-english-words','NO',142) */
	('Jack got a new job at a biotechnology company called Bioco','Jack nhận một công việc mới tại một công ty công nghệ sinh học được gọi là Bioco','','','4000-essential-english-words-142'),
	('Bioco manufactured drugs to treat diabetes and high cholesterol','Bioco sản xuất thuốc để điều trị bệnh tiểu đường và nồng độ cholesterol cao','','','4000-essential-english-words-142'),
	('Jack\'s job was to use a tiny mechanism to get nectar from flowers','Công việc của Jack là sử dụng một máy móc nhỏ để lấy mật hoa từ hoa','','','4000-essential-english-words-142'),
	('The nectar was a main ingredient in the drugs','Mật hoa là một thành phần chính trong các loại thuốc','','','4000-essential-english-words-142'),
	('Jack liked his job, and he thought that Bioco was a caring company','Jack thích công việc của mình và anh nghĩ rằng Bioco là một công ty có tâm','','','4000-essential-english-words-142'),
	('However, Jack soon learned that the company wasn\'t as kind as he first thought','Tuy nhiên, Jack đã sớm biết rằng công ty không tốt như anh nghĩ lúc đầu','','','4000-essential-english-words-142'),
	('Bioco\'s motto was "Make the Earth a Better Place"','Phương châm của Bioco là "Làm cho Trái đất trở nên một nơi tốt đẹp hơn"','','','4000-essential-english-words-142'),
	('However, this motto was deceptive','Tuy nhiên, phương châm này lại dối trá','','','4000-essential-english-words-142'),
	('The company actually did a number of really bad things to the environment','Công ty đã làm một số việc thực sự tồi tệ đối với môi trường','','','4000-essential-english-words-142'),
	('The company produced a lot of smog and harmful acid','Công ty tạo ra nhiều khói bụi và axit có hại','','','4000-essential-english-words-142'),
	('Bioco poured the acid in a nearby river, which caused erosion and made fish prone to illness','Bioco đã đổ axit vào một con sông gần đó, gây xói mòn và khiến cá dễ bị bệnh','','','4000-essential-english-words-142'),
	('After a few weeks at the new job, Jack saw all the bad things Bioco was doing','Sau một vài tuần ở công việc mới, Jack đã nhìn thấy tất cả những điều tồi tệ mà Bioco đang làm','','','4000-essential-english-words-142'),
	('He had always had strong ethics, and he knew he had to do something','Anh luôn chú trọng về phần đạo đức và anh biết mình phải làm điều gì đó','','','4000-essential-english-words-142'),
	('One day, while the Bioco workers were eating in the cafeteria, Jack stood up and gave a speech','Một ngày nọ, trong khi các công nhân của Bioco đang ăn trong căng tin, Jack đứng lên và phát biểu','','','4000-essential-english-words-142'),
	('He said, "My fellow coworkers, I know you have all seen the evil things our company is doing"','Anh ấy nói, "Các đồng nghiệp của tôi, tôi biết các bạn đều đã thấy những điều xấu xa mà công ty chúng ta đang làm"','','','4000-essential-english-words-142'),
	('"I have a notion that we can fix them if we form a coalition"','"Tôi có ý kiến rằng chúng ta có thể sửa chữa chúng nếu chúng ta thành lập một liên minh"','','','4000-essential-english-words-142'),
	('"We can go to the administration and tell them we\'ll quit if they don\'t eliminate the problems"','"Chúng ta có thể đến gặp cơ quan quản lý và nói với họ rằng chúng ta sẽ nghỉ việc nếu họ không loại bỏ các vấn đề"','','','4000-essential-english-words-142'),
	('"They\'ll have no choice but to listen to us"','"Họ sẽ không có lựa chọn nào khác ngoài việc lắng nghe chúng ta"','','','4000-essential-english-words-142'),
	('Jack explained what they were to do','Jack giải thích những gì họ phải làm','','','4000-essential-english-words-142'),
	('His coworkers liked his explicit plan','Các đồng nghiệp thích kế hoạch rõ ràng của anh','','','4000-essential-english-words-142'),
	('They went to the administrative offices and demanded that Bioco stop damaging the environment, or they all would quit','Họ đã đến văn phòng hành chính và yêu cầu Bioco ngừng việc hủy hoại môi trường, nếu không tất cả sẽ nghỉ việc','','','4000-essential-english-words-142'),
	('One supervisor said to them, "Thank you for being straightforward about this issue"','Một giám sát viên nói với họ, "Cảm ơn các bạn đã thẳng thắn về vấn đề này"','','','4000-essential-english-words-142'),
	('"Since I can\'t afford to lose all of you workers, I guess we\'ll just have to fix things"','"Vì tôi không thể để mất tất cả nhân công như các bạn nên tôi đề nghị chúng ta sẽ phải sửa chữa mọi thứ"','','','4000-essential-english-words-142'),
	('Jack, his supervisor, and his coworkers spent the next month designing a new framework for the company','Jack, người giám sát của anh và các đồng nghiệp của anh đã dành cả tháng tiếp theo để thiết kế một cơ cấu tổ chức mới cho công ty','','','4000-essential-english-words-142'),
	('They cleaned up the acid from the river and minimized the amount of air pollution the company released','Họ đã làm sạch axit từ sông và giảm thiểu lượng ô nhiễm không khí mà công ty thải ra','','','4000-essential-english-words-142'),
	('At last, the company motto became apt','Cuối cùng, phương châm của công ty đã trở nên phù hợp','','','4000-essential-english-words-142'),

	/* (UUID(),'4000-essential-english-words-143','How Comet Got His Tail','Sao chổi có đuôi như thế nào','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_143.mp3',NULL,'','','4000-essential-english-words','NO',143) */
	('A solitary rock roamed through the cold gloom of outer space','Một tảng đá đơn độc lang thang trong không gian u ám lạnh lẽo','','','4000-essential-english-words-143'),
	('It slowly drifted through the debris of broken asteroids with a feeling of sadness','Nó buồn bã trôi dạt chầm chậm qua những mảnh vụn của các tiểu hành tinh bị vỡ','','','4000-essential-english-words-143'),
	('In the vast and beautiful galaxy, it was only a tiny rock','Trong dải ngân hà rộng lớn và xinh đẹp, nó chỉ là một tảng đá nhỏ','','','4000-essential-english-words-143'),
	('It felt like an insignificant atom','Nó cảm thấy mình giống như một nguyên tử tầm thường','','','4000-essential-english-words-143'),
	('In its journeys it encountered many amazing objects','Trong chuyến hành trình của mình, nó gặp được nhiều thứ tuyệt vời','','','4000-essential-english-words-143'),
	('It flew by beautiful crescent moons that were covered with craters and moon dust','Nó bay qua những mặt trăng hình lưỡi liềm tuyệt đẹp, thứ được bao phủ bởi những miệng núi lửa và bụi mặt trăng','','','4000-essential-english-words-143'),
	('"Why can\'t I be as beautiful as them?" it thought','Nó nghĩ "Tại sao mình không thể đẹp như họ nhỉ?"','','','4000-essential-english-words-143'),
	('The rock passed a gigantic planet','Tảng đá bay qua một hành tinh khổng lồ','','','4000-essential-english-words-143'),
	('The sphere had a circumference hundreds of times larger than the breadth of the small rock','Quả cầu có chu vi lớn hơn hàng trăm lần so với bề rộng của tảng đá nhỏ','','','4000-essential-english-words-143'),
	('"Why can\'t I be as large as that?" it wondered','Nó thắc mắc là "Tại sao mình không thể lớn như vậy nhỉ?"','','','4000-essential-english-words-143'),
	('The rock was filled with despair','Tảng đá mang trong mình đầy nỗi tuyệt vọng','','','4000-essential-english-words-143'),
	('It was surrounded by beauty and greatness, yet it was just a small and ugly fragment of rock','Nó được bao quanh bởi vẻ đẹp và sự cao cả, nhưng nó chỉ là một mảnh đá nhỏ và xấu xí','','','4000-essential-english-words-143'),
	('One day, it approached the area of an astronomical star','Một ngày nọ, nó đến gần khu vực của sao thiên văn','','','4000-essential-english-words-143'),
	('"What\'s wrong?" the star asked','ngôi sao hỏi "Có chuyện gì vậy?"','','','4000-essential-english-words-143'),
	('"Oh, I wish I had a higher status in the galaxy"','"Ồ, tôi ước mình có địa vị cao hơn trong dải ngân hà"','','','4000-essential-english-words-143'),
	('"All the other objects are so beautiful and large," the rock replied','"Tất cả các vật thể khác đều rất đẹp và to lớn," đá trả lời','','','4000-essential-english-words-143'),
	('"But I\'m just an ugly rock"','"Nhưng tôi chỉ là một hòn đá xấu xí"','','','4000-essential-english-words-143'),
	('The star considered the problem','Ngôi sao suy xét vấn đề này','','','4000-essential-english-words-143'),
	('At last it said, "You don\'t have to worry anymore"','Cuối cùng nó nói, "Anh không cần phải lo lắng nữa"','','','4000-essential-english-words-143'),
	('"I think I can help"','"Tôi nghĩ tôi có thể giúp anh"','','','4000-essential-english-words-143'),
	('The star radiated its light brighter and hotter than it had ever done before','Ngôi sao tỏa sáng, ánh sáng của nó sáng và nóng hơn bất kỳ lúc nào','','','4000-essential-english-words-143'),
	('"Come a little closer," the star said to the rock','ngôi sao nói với hòn đá "Hãy đến gần đây hơn một chút,"','','','4000-essential-english-words-143'),
	('The rock drifted closer to the star','Tảng đá trôi lại gần ngôi sao hơn','','','4000-essential-english-words-143'),
	('Suddenly, the ice that was embedded in the rock\'s tiny cracks melted and became steam','Đột nhiên, tảng băng nằm trong các khe nứt nhỏ của tảng đá tan chảy và trở thành hơi nước','','','4000-essential-english-words-143'),
	('Then the steam extended behind the comet to form a brilliant tail','Sau đó, hơi nước lan rộng ra phía sau sao chổi để tạo thành một cái đuôi rực rỡ','','','4000-essential-english-words-143'),
	('The tail shined with all the colors of the spectrum','Cái đuôi tỏa sáng với tất cả các màu sắc của quang phổ','','','4000-essential-english-words-143'),
	('The little rock had become a beautiful comet','Hòn đá nhỏ đã trở thành một ngôi sao chổi xinh đẹp','','','4000-essential-english-words-143'),
	('It looked so amazing','Nó trông rất tuyệt vời','','','4000-essential-english-words-143'),
	('It realized that the star helped it change its appearance','Nó nhận ra rằng ngôi sao đã giúp nó thay đổi bề ngoài','','','4000-essential-english-words-143'),
	('"Thank you," the comet said and then flew away with its new beautiful tail following behind it like a galactic cape','sao chổi nói "Cảm ơn," và sau đó bay đi với cái đuôi mới tuyệt đẹp theo sau nó giống như một chiếc áo choàng thiên hà','','','4000-essential-english-words-143'),

	/* (UUID(),'4000-essential-english-words-144','The Resourceful Landlord','Người chủ nhà tháo vát','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_144.mp3',NULL,'','','4000-essential-english-words','NO',144) */
	('A kind landlord was afraid that he would lose his apartment building','Một người chủ nhà tốt bụng lo sợ rằng ông ấy sẽ mất đi tòa nhà chung cư của mình','','','4000-essential-english-words-144'),
	('He needed to make some mandatory repairs to the old building, or his tenants would have to leave by the end of the month','Ông cần tiến hành một vài sửa chữa bắt buộc cho tòa nhà cũ, nếu không thì những người thuê nhà sẽ phải rời đi vào cuối tháng','','','4000-essential-english-words-144'),
	('Without tenants to lease the rooms, the landlord would be unable to pay his mortgage','Nếu không có người muốn thuê phòng, chủ nhà sẽ không thể trả tiền thế chấp','','','4000-essential-english-words-144'),
	('He\'d be bankrupt, and the bank would take his building','Ông sẽ phá sản, và ngân hàng sẽ lấy tòa nhà của ông ấy','','','4000-essential-english-words-144'),
	('But he didn\'t have the money whereby he could employ the personnel needed to make the repairs','Nhưng anh ta không có tiền để có thể thuê nhân viên cần thiết để sửa chữa','','','4000-essential-english-words-144'),
	('It would seem like he did not want to conform to the city\'s codes before the forthcoming inspection','Dường như là ông không muốn tuân theo bộ luật của thành phố trước khi đợt kiểm tra sắp tới','','','4000-essential-english-words-144'),
	('He had requested an extension, but it was denied by the city','Ông đã yêu cầu được gia hạn, nhưng bị từ chối bởi thành phố','','','4000-essential-english-words-144'),
	('He held a meeting with his tenants and explained the unfortunate situation','Ông đã tổ chức gặp mặt những người thuê nhà và giải thích tình huống không may','','','4000-essential-english-words-144'),
	('"If the building does not meet the appropriate standards for safety and hygiene," he said, "the city will expel everyone"','"Nếu như tòa nhà không đáp ứng được những tiêu chí phù hợp về an toàn và vệ sinh," ông nói, "thành phố sẽ trục xuất tất cả mọi người"','','','4000-essential-english-words-144'),
	('The tenants were all sad for the kind old man','Những người thuê nhà đều cảm thấy buồn cho ông chủ tốt bụng','','','4000-essential-english-words-144'),
	('"Maybe we can help," the hairdresser who lived on the first floor stated','‘‘Có lẽ chúng tôi có thể giúp,’’ người thợ cắt tóc sống ở tầng một phát biểu','','','4000-essential-english-words-144'),
	('The other tenants agreed','Những người thuê nhà khác đồng ý','','','4000-essential-english-words-144'),
	('One tenant had worked for the city\'s utilities','Một người thuê nhà đã làm việc cho ngành phục vụ cộng đồng của thành phố','','','4000-essential-english-words-144'),
	('He knew a lot about plumbing, so that\'s how he helped','Anh biết nhiều về hệ thống ống nước/nghề hàn chì, và đó là cách anh đã giúp','','','4000-essential-english-words-144'),
	('Another tenant was a carpenter; he mended the holes in the floor and walls','Một người thuê nhà khác là một thợ mộc, anh đã vá lại những cái lỗ trên sàn và tường','','','4000-essential-english-words-144'),
	('Others cleaned the building from top to bottom so that it was more hygienic','Những người khác đã lau dọn tòa nhà hết từ trên xuống dưới nên nó đã hợp vệ sinh hơn','','','4000-essential-english-words-144'),
	('They even furnished some of the apartments with new beds, dressers, and chairs','Họ thậm chí còn trang bị cho vài căn hộ giường, tủ và ghế mới','','','4000-essential-english-words-144'),
	('When they were done, all of the people dispersed, and the landlord went home to rest','Khi họ đã xong việc, tất cả mọi người giải tán, và người chủ nhà về nhà để nghỉ ngơi','','','4000-essential-english-words-144'),
	('When the deadline of the inspection arrived, the apartment building was hygienic and safe','Khi đã đến kì hạn kiểm tra, tòa nhà chung cư đã hợp vệ sinh và an toàn','','','4000-essential-english-words-144'),
	('The landlord couldn\'t believe it','Người chủ nhà không thể tin được','','','4000-essential-english-words-144'),
	('His old building now looked like one of the trendiest buildings in town','Tòa nhà của ông bây giờ giống như một trong những tòa nhà hợp thời nhất trong thị trấn','','','4000-essential-english-words-144'),
	('The building passed its inspection, and the landlord and the tenants had a big party','Tòa nhà đã vượt qua kì kiểm tra, và người chủ nhà và những người thuê nhà đã có một bữa tiệc lớn','','','4000-essential-english-words-144'),
	('"Thank you all so much," the landlord said during the party','"Cảm ơn mọi người rất nhiều," người chủ nhà nói trong bữa tiệc','','','4000-essential-english-words-144'),
	('"I could never have done it by myself"','"Tôi sẽ không bao giờ có thể làm được nó một mình"','','','4000-essential-english-words-144'),
	('"But by working together, we now all have a beautiful place to live"','"Nhưng bằng cách làm việc cùng nhau, bây giờ chúng ta đều có một nơi tuyệt đẹp để sống"','','','4000-essential-english-words-144'),

	/* (UUID(),'4000-essential-english-words-145','The Man and the Monkey','Người đàn ông và con khỉ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_145.mp3',NULL,'','','4000-essential-english-words','NO',145) */
	('While flying over a jungle, a wealthy executive\'s private plane crashed','Khi đang bay qua một khu rừng, chiếc máy bay riêng của một giám đốc điều hành giàu có gặp tai nạn','','','4000-essential-english-words-145'),
	('Some of the crew were hurt, so the pilot decided to stay with them and wait for help','Một số phi hành đoàn đã bị thương, nên người phi công đã quyết định ở lại cùng họ để chờ sự cứu viện','','','4000-essential-english-words-145'),
	('The arrogant executive, though, didn\'t care about the welfare of the pilot and crew','Ông giám đốc điều hành kiêu ngạo mặc dù không quan tâm đến sự an toàn của phi hành đoàn','','','4000-essential-english-words-145'),
	('Rather, he thought he could walkout of the jungle and find a town to stay in','Đúng hơn là ông ta nghĩ rằng ông có thể đi bộ ra khỏi khu rừng và tìm một thị trấn để trú ngụ','','','4000-essential-english-words-145'),
	('He followed a trail through a canyon and along a creek','Ông đi theo một con đường mòn qua một hẻm núi và dọc theo một con lạch','','','4000-essential-english-words-145'),
	('The jungle was actually very stunning','Khu rừng đó thực sự rất đẹp','','','4000-essential-english-words-145'),
	('If the arrogant executive had stopped to look around, he might have perceived the jungle\'s beauty','Nếu như người giám đốc điều hành kiêu ngạo ấy đã dừng chân lại để nhìn xung quanh, ông ta có thể đã cảm nhận được vẻ đẹp của khu rừng','','','4000-essential-english-words-145'),
	('But he was in a nasty mood and had no care for the aesthetic value of the jungle','Nhưng ông đang ở trong một tâm trạng bực bội và không có bất kỳ sự quan tâm nào dành cho giá trị thẩm mỹ của khu rừng','','','4000-essential-english-words-145'),
	('He continued to walk up the steep incline of the jungle\'s hills','Ông tiếp tục đi bộ ra khỏi sườn dốc của ngọn đồi trong rừng','','','4000-essential-english-words-145'),
	('Soon, he was lost','Không lâu sau, ông bị lạc','','','4000-essential-english-words-145'),
	('Several days passed, and fatigue and hunger weakened him','Một vài ngày trôi qua, sự mệt mỏi và cơn đói đã làm ông trở nên yếu ớt','','','4000-essential-english-words-145'),
	('He was very tired and afraid','Ông rất mệt và sợ','','','4000-essential-english-words-145'),
	('Just then, a monkey came out of the trees','Vừa lúc đó, một con khỉ chui ra khỏi những cái cây','','','4000-essential-english-words-145'),
	('It was carrying a twig covered in honey','Nó đang mang trên mình một cành cây được bao phủ bởi mật ong','','','4000-essential-english-words-145'),
	('It walked up to a mound where termites lived','Nó di chuyển đến một gò đất nơi có những con mối sinh sống','','','4000-essential-english-words-145'),
	('He then used the twig like a drill to make a hole in the mound',' Sau đó, nó dùng cành cây như một mũi khoan để tạo một lỗ hổng trên gò đất','','','4000-essential-english-words-145'),
	('Then very carefully, it removed the twig from the hole','Sau đó, nó rất cẩn thận lấy cành cây ra khỏi cái lỗ','','','4000-essential-english-words-145'),
	('The sticky twig was covered with termites','Những cành cây dính đầy mối mọt','','','4000-essential-english-words-145'),
	('Instead of eating the bugs, the monkey offered them to the executive, but he didn\'t want what the monkey offered',' Thay vì ăn những con bọ, con khỉ đã dâng chúng cho ông giám đốc điều hành, nhưng ông ta không muốn những thứ con khỉ cung cấp','','','4000-essential-english-words-145'),
	('He shouted at the monkey, "Get away from me, you stupid primate"','Ông ta hét vào mặt con khỉ, "Tránh xa tôi ra, đồ linh trưởng ngu ngốc"','','','4000-essential-english-words-145'),
	('The executive\'s stereotype of the monkey was wrong','Định kiến của người giám đốc điều hành với con khỉ đã sai','','','4000-essential-english-words-145'),
	('The monkey was not stupid','Con khỉ không hề ngu ngốc','','','4000-essential-english-words-145'),
	('It knew how to find food, whereas the executive did not','Nó biết cách tìm kiếm thức ăn, trong khi người điều hành thì không','','','4000-essential-english-words-145'),
	('He refused the help of the monkey, thereby leaving himself to starve','Anh ta từ chối sự giúp đỡ của con khỉ, do đó khiến bản thân càng rất đói','','','4000-essential-english-words-145'),
	('When the executive was finally found, he was very skinny and sick','Khi người điều hành cuối cùng được tìm thấy, ông ta rất gầy và ốm yếu','','','4000-essential-english-words-145'),
	('He had not eaten for a very longtime','Ông ta đã không ăn trong một khoảng thời gian dài','','','4000-essential-english-words-145'),
	('Because he held a bias against the primitive ways of the monkey, he had gone hungry and almost died',' Chỉ vì có những thành kiến với những cách thức nguyên thủy của loài khỉ, ông ta đã đói và gần như chết','','','4000-essential-english-words-145'),
	('The executive didn\'t understand that it was his arrogant attitude that had caused all of his problems','Người giám đốc điều hành không hiểu rằng chính thái độ kiêu ngạo của ông ta đã gây ra tất cả các vấn đề cho chính mình','','','4000-essential-english-words-145');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-146','Cosmo\'s Flight','Chuyến bay của Cosmo','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_146.mp3',NULL,'','','4000-essential-english-words','NO',146) */
	('When Cosmo woke up, he was crying','Khi Cosmo tỉnh dậy, cậu ấy đang khóc','','','4000-essential-english-words-146'),
	('He had a dream that he was falling','Cậu có một giấc mơ rằng cậu đang rơi xuống','','','4000-essential-english-words-146'),
	('This dream had recurred for the previous five nights','Giấc mơ này đã lặp lại trong năm đêm trước đó','','','4000-essential-english-words-146'),
	('Cosmo was scared that his dreams were a preview of what was going to happen on his flight the next day','Cosmo rất sợ hãi rằng giấc mơ của cậu ấy là điềm báo cho những thứ sắp sửa xảy ra trong chuyến bay của cậu vào hôm sau','','','4000-essential-english-words-146'),
	('Cosmo was a supernatural being who was about to turn 15 years old','Cosmo là một sinh vật siêu nhiên sắp tròn 15 tuổi','','','4000-essential-english-words-146'),
	('In his culture, boys of his age were required to participate in an important rite','Trong nền văn hóa của cậu, những cậu bé ở độ tuổi của cậu bắt buộc phải tham gia vào một hành trình quan trọng','','','4000-essential-english-words-146'),
	('They were given wings and instructed to orbit the Earth','Họ được trao cho những chiếc cánh và được hướng dẫn cách bay quanh Trái Đất','','','4000-essential-english-words-146'),
	('After successful flights, the boys officially became men','Sau những chuyến bay thành công, những cậu bé chính thức trở thành những người đàn ông','','','4000-essential-english-words-146'),
	('Cosmo certainly wanted to be a man, but he was scared','Cosmo dĩ nhiên muốn trở thành một người đàn ông, nhưng cậu bé rất lo sợ','','','4000-essential-english-words-146'),
	('He went to the oracle of a god named Dano','Cậu bé đến gặp một vị thần tiên tri tên Dino','','','4000-essential-english-words-146'),
	('Cosmo said, "I\'m not sure I can make such a long trip"','Cosmo nói rằng, "Con không chắc rằng con có thể thực hiện một chuyến bay dài hay không"','','','4000-essential-english-words-146'),
	('"What if I get tired?"','"Nếu như con mệt mỏi thì sao?"','','','4000-essential-english-words-146'),
	('"What if my strength stalls, and I can\'t stay in the air"','"Chuyện gì sẽ xảy ra nếu sức lực của con biến mất và con không thể giữ bản thân trong không trung?"','','','4000-essential-english-words-146'),
	('"I\'ll crash and die"','"Con sẽ gặp tai nạn và chết mất"','','','4000-essential-english-words-146'),
	('Dano replied, "Don\'t be afraid"','Ngài Dino trả lời, "Đừng sợ hãi"','','','4000-essential-english-words-146'),
	('"You have all the relevant skills in your personal inventory that have been building up over the years"','"Con có tất cả những kỹ năng thích hợp và hành trang cá nhân của con đã được tích lũy trên không trung"','','','4000-essential-english-words-146'),
	('"To ease your worry, let me tell you a little about what will happen tomorrow"','"Để xoa dịu sự lo lắng của con, ta sẽ tiết lộ cho con một chút về những gì sẽ xảy ra vào ngày mai"','','','4000-essential-english-words-146'),
	('"You\'ll begin over Africa"','"Con sẽ bắt đầu bay qua Châu Phi"','','','4000-essential-english-words-146'),
	('"You\'ll keep flying north until you come to the Himalayas"','"Con tiếp tục bay về hướng Bắc cho tới khi tới được dãy Himalaya"','','','4000-essential-english-words-146'),
	('"The mountaintops will look like small loaves of bread at such a high distance"','"Những đỉnh núi sẽ trông như những lát bánh mì nhỏ khi ở một độ cao như vậy"','','','4000-essential-english-words-146'),
	('"The rivers of the world will look like pieces of blue string that cross the globe"','"Dòng sông của thế giới sẽ trông như những mảnh sợi chỉ màu xanh lam xuyên qua địa cầu"','','','4000-essential-english-words-146'),
	('"Keep your body horizontal when flying against the winds of the Pacific Ocean"','"Hãy giữ cơ thể nằm ngang khi bay ngược luồng gió đến từ biển Thái Bình Dương"','','','4000-essential-english-words-146'),
	('"Keep your eyes open and enjoy the beauty of the Earth"','"Hãy mở mắt và tận hưởng cái đẹp của thế giới"','','','4000-essential-english-words-146'),
	('"You will be fine, you\'ll see"','"Con sẽ ổn thôi, con thấy đấy"','','','4000-essential-english-words-146'),
	('Cosmo replied, "Thanks for the overview of my journey, I\'ll do my best"',' Cosmo trả lời, "Cảm ơn ngài vì cái nhìn tổng quan về cuộc hành trình của con. Con sẽ làm hết sức mình"','','','4000-essential-english-words-146'),
	('The next morning, Cosmo was provided with a divine set of wings and sent on his way','Buổi sáng hôm sau, Cosmo được cung cấp một bộ cánh thần và lên đường','','','4000-essential-english-words-146'),
	('He flapped his wings and went high above the Earth','Cậu đập nhẹ đôi cánh và bay cao trên Trái Đất','','','4000-essential-english-words-146'),
	('He flew over mountains, oceans, and glaciers','Cậu đã bay qua những ngọn núi, những đại dương và cả những dòng sông băng','','','4000-essential-english-words-146'),
	('After a while, his inward thoughts were no longer about falling','Sau một lúc, cậu không còn nghĩ đến việc bị rơi xuống nữa','','','4000-essential-english-words-146'),
	('He was actually having fun','Cậu đang thực sự đang vui vẻ','','','4000-essential-english-words-146'),
	('He began to hum a song as he enjoyed the view','Cậu bắt đầu ngân nga một bài ca vừa thưởng thức cảnh đẹp','','','4000-essential-english-words-146'),
	('When he reached home, his tribe was there to greet him','Khi cậu về đến nơi, bộ lạc của cậu bé đã ở đó chào đón họ','','','4000-essential-english-words-146'),
	('The chief said, "On behalf of the tribe, I declare you a man"','Tù trưởng nói, "Thay mặt cho bộ tộc, ta tuyên bố con là một người đàn ông"','','','4000-essential-english-words-146'),
	('"We\'re proud of you, Cosmo"','"Chúng ta tự hào về con, Cosmo"','','','4000-essential-english-words-146'),
	('Cosmo was proud of himself, too','Cosmo cũng rất tự hào về bản thân cậu','','','4000-essential-english-words-146'),

	/* (UUID(),'4000-essential-english-words-147','The First Organ Transplant','Người cấy ghép nội tạng đầu tiên','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_147.mp3',NULL,'','','4000-essential-english-words','NO',147) */
	('In 1954, a man named Richard was dying of kidney disease','Năm 1954, một người đàn ông tên là Richard đang hấp hối vì bệnh thận','','','4000-essential-english-words-147'),
	('He wouldn\'t survive for long unless he got a new kidney right away','Anh ta sẽ không sống được bao lâu trừ khi anh ta có một quả thận mới ngay lập tức','','','4000-essential-english-words-147'),
	('Richard\'s twin brother, Robert, was willing to donate one of his kidneys to his dying brother','Anh trai sinh đôi của Richard, Robert, sẵn sàng hiến một quả thận của mình cho người anh trai đang hấp hối của mình','','','4000-essential-english-words-147'),
	('At the time, however, no doctor had ever performed a successful internal organ transplant','Tuy nhiên, vào thời điểm đó, chưa có bác sĩ nào từng thực hiện ca ghép nội tạng thành công','','','4000-essential-english-words-147'),
	('The idea of taking an organ out of one person and putting it into another was just a fantasy','Ý tưởng lấy một cơ quan của một người và đưa nó vào một người khác chỉ là một điều viển vông','','','4000-essential-english-words-147'),
	('But the brothers decided to be brave and found a doctor who could make organ transplants a reality','Nhưng hai anh em quyết định dũng cảm và tìm một bác sĩ có thể biến việc cấy ghép nội tạng thành hiện thực','','','4000-essential-english-words-147'),
	('Since Richard and Robert were twins, their heredity was identical','Vì Richard và Robert là anh em sinh đôi nên di truyền của họ giống hệt nhau','','','4000-essential-english-words-147'),
	('They had the exact same biological traits','Họ có những đặc điểm sinh học giống hệt nhau','','','4000-essential-english-words-147'),
	('Even their kidneys were identical on the cellular level','Ngay cả thận của họ cũng giống hệt nhau ở cấp độ tế bào','','','4000-essential-english-words-147'),
	('Therefore, Robert\'s working kidney could be substituted for Richard\'s bad one','Do đó, quả thận đang hoạt động của Robert có thể được thay thế cho quả thận xấu của Richard','','','4000-essential-english-words-147'),
	('Richard\'s body could adapt to the new organ if the operation was done correctly','Cơ thể của Richard có thể thích nghi với cơ quan mới nếu ca phẫu thuật được thực hiện chính xác','','','4000-essential-english-words-147'),
	('The twins went to Dr.Murray, who was a pioneer of new surgical methods','Cặp song sinh tìm đến bác sĩ Murray, người đi tiên phong trong các phương pháp phẫu thuật mới','','','4000-essential-english-words-147'),
	('His dynamic team of surgeons performed the transplant','Đội ngũ bác sĩ phẫu thuật năng động của ông ấy đã thực hiện ca cấy ghép','','','4000-essential-english-words-147'),
	('Dr.Murray made sure his surgeons followed a rigid sequence of directions so that no mistakes were made','Tiến sĩ Murray đảm bảo các bác sĩ phẫu thuật của ông tuân theo một trình tự hướng dẫn chặt chẽ để không có sai sót nào được thực hiện','','','4000-essential-english-words-147'),
	('First, they made a minimal cut in Richard\'s side and removed the bad kidney','Đầu tiên, họ thực hiện một vết cắt nhỏ bên cạnh của Richard và loại bỏ quả thận xấu','','','4000-essential-english-words-147'),
	('Then, they made another small cut in Robert\'s side, removed his kidney, and transferred it into Richard\'s body','Sau đó, họ thực hiện một vết cắt nhỏ khác ở bên hông của Robert, cắt bỏ quả thận của anh ấy và chuyển nó vào cơ thể của Richard','','','4000-essential-english-words-147'),
	('Finally, they sewed up the respective cuts','Cuối cùng, họ khâu lại các vết cắt tương ứng','','','4000-essential-english-words-147'),
	('The entire operation only took about one hour','Toàn bộ quá trình chỉ diễn ra trong khoảng một giờ','','','4000-essential-english-words-147'),
	('After the surgery, it was clear that both brothers were going to be OK','Sau khi phẫu thuật, rõ ràng là sức khỏe của hai anh em đều sẽ ổn','','','4000-essential-english-words-147'),
	('The operation was confirmed a success','Ca phẫu thuật đã được xác nhận là thành công','','','4000-essential-english-words-147'),
	('Richard\'s new kidney worked great','Quả thận mới của Richard đã hoạt động tốt','','','4000-essential-english-words-147'),
	('Doctors prescribed medicine for the pain caused by the surgery','Các bác sĩ đã kê đơn thuốc cho cơn đau do phẫu thuật gây ra','','','4000-essential-english-words-147'),
	('Since Richard was still weak, he used physical therapy to revive his strength','Vì Richard vẫn còn yếu nên anh đã dùng vật lý trị liệu để hồi sinh sức mạnh','','','4000-essential-english-words-147'),
	('At last, Richard\'s transition into a healthy, happy person was complete','Cuối cùng, quá trình chuyển đổi của Richard trở thành một người khỏe mạnh, hạnh phúc đã hoàn tất','','','4000-essential-english-words-147'),
	('Dr.Murray became a hero in the medical world','Bác sĩ Murray đã trở thành một anh hùng trong giới y khoa','','','4000-essential-english-words-147'),
	('His success gave other doctors confidence to try organ transplants themselves','Thành công của ông đã khiến các bác sĩ khác tự tin để thử cấy ghép nội tạng','','','4000-essential-english-words-147'),
	('Now, doctors perform life-saving transplants and surgeries every day','Hiện nay, các bác sĩ thực hiện những ca ghép tạng và các ca phẫu thuật cứu sống người bệnh mỗi ngày','','','4000-essential-english-words-147'),

	/* (UUID(),'4000-essential-english-words-148','The Lottery','Xổ số kiến thiết','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_148.mp3',NULL,'','','4000-essential-english-words','NO',148) */
	('Joe was watching television when he heard a knock at the door','Joe đang xem TV thì nghe thấy tiếng gõ cửa','','','4000-essential-english-words-148'),
	('He thought, "Who could that be?"','Anh nghĩ, "Có thể là ai nhỉ?"','','','4000-essential-english-words-148'),
	('"It\'s probably one of the naughty neighborhood children"','"Chắc là một trong những đứa trẻ con hàng xóm nghịch ngợm đây"','','','4000-essential-english-words-148'),
	('Joe stood up and walked to the door','Joe đứng dậy và đi về phía cửa','','','4000-essential-english-words-148'),
	('When he opened it, he saw a beautiful woman','Khi mở cửa, anh nhìn thấy một người phụ nữ xinh đẹp','','','4000-essential-english-words-148'),
	('She said, "Good morning, Joe"','Cô ấy nói, "Chào buổi sáng, Joe"','','','4000-essential-english-words-148'),
	('"I have great news"','"Tôi có một tin tốt đây"','','','4000-essential-english-words-148'),
	('"You\'re the recipient of this check for one million dollars"','"Cậu là người được nhận tấm séc trị giá một triệu đô"','','','4000-essential-english-words-148'),
	('"You won the lottery"','"Cậu đã trúng xổ số"','','','4000-essential-english-words-148'),
	('Joe couldn\'t believe it','Joe không thể tin nổi','','','4000-essential-english-words-148'),
	('His mind was overloaded with emotions','Tâm trí cậu tràn ngập những cảm xúc','','','4000-essential-english-words-148'),
	('Joe said, "Thank you. Thank you"','Joe nói, "Cảm ơn. Cảm ơn"','','','4000-essential-english-words-148'),
	('After he calmed down, Joe made a photocopy of the check in case he misplaced the original one','Sau khi Joe bình tĩnh lại, anh ta sao chép một bản của tờ séc để phòng trường hợp thất lạc bản gốc','','','4000-essential-english-words-148'),
	('He sat and thought about what he wanted to do with the money','Anh ta ngồi xuống và nghĩ về điều mình muốn làm với số tiền đó','','','4000-essential-english-words-148'),
	('He didn\'t want to spend it in an arbitrary way','Joe không muốn tiêu nó một cách tùy tiện','','','4000-essential-english-words-148'),
	('Joe thought, "I know there are others who need this money more than I do"','Joe nghĩ, "Mình biết có nhiều người cần số tiền này hơn mình"','','','4000-essential-english-words-148'),
	('"I\'ve always loved animals, so I think I\'ll buy things for the zoo"','"Mình luôn yêu quý động vật, nên mình nghĩ mình sẽ mua một vài thứ cho sở thú"','','','4000-essential-english-words-148'),
	('Joe knew that the zoo was in bad shape','Joe biết rằng sở thú đang ở trong tình trạng khá tệ','','','4000-essential-english-words-148'),
	('The cages were too small, and they weren\'t insulated from the cold','Những chiếc chuồng quá nhỏ, và những con thú không tránh được khỏi cái lạnh','','','4000-essential-english-words-148'),
	('Animals couldn\'t thrive in such conditions','Chúng không thể lớn lên trong điều kiện như thế được','','','4000-essential-english-words-148'),
	('He took out some stationery and wrote a letter to the zoo','Joe lấy giấy bút ra và viết một bức thư cho sở thú','','','4000-essential-english-words-148'),
	('He offered to help the zoo buy huge cages for the large mammals and reptiles','Anh ta đề nghị được giúp đỡ sở thú bằng cách mua những chiếc chuồng lớn cho các loài động vật có vú và bò sát lớn','','','4000-essential-english-words-148'),
	('He offered to buy healthy food for the orangutans to increase their longevity','Anh ta đề nghị để mình mua thực phẩm lành mạnh cho những con đười ươi để tăng tuổi thọ của chúng','','','4000-essential-english-words-148'),
	('He even said that he would buy new glass walls for the aquarium because the old ones were cracked','Thậm chí, Joe còn nói rằng sẽ mua những bức tường kính mới cho bể cá vì những tấm cũ đã bị nứt rồi','','','4000-essential-english-words-148'),
	('Joe\'s act of philanthropy intrigued the zookeeper','Hành động nhân đức của Joe đã thu hút sự chú ý của người trông coi sở thú','','','4000-essential-english-words-148'),
	('He probed Joe to learn why he spent his money to improve the zoo','Anh ta thăm dò Joe đế biết tại sao anh dùng tiền của mình để cải thiện sở thú','','','4000-essential-english-words-148'),
	('It wasn\'t a social convention for a person to be so gracious','Nó không phù hợp với lẽ thông thường ở xã hội khi có một người lại tử tế đến thế','','','4000-essential-english-words-148'),
	('Joe told the zookeeper, "I know it\'s not the norm, but my ultimate decision to help I these animals is better than anything I could have done for myself"','Joe nói với người trông coi sở thú rằng, "Tôi biết nó không phải là điều bình thường, nhưng quyết định cuối cùng của tôi khi hỗ trợ những loài vật này cao cả hơn nhiều so với bất cứ điều gì tôi làm cho chính mình"','','','4000-essential-english-words-148'),
	('"If I ever write an autobiography, I will write that this was the happiest day of my life"','"Nếu tôi có viết tự truyện, tôi sẽ viết rằng đấy là ngày hạnh phúc nhất cuộc đời tôi"','','','4000-essential-english-words-148'),

	/* (UUID(),'4000-essential-english-words-149','Jen\'s New Job','Công việc mới của Jen','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_149.mp3',NULL,'','','4000-essential-english-words','NO',149) */
	('The history museum needed to recruit a new tour guide','Bảo tàng lịch sử cần tuyển dụng một hướng dẫn viên mới','','','4000-essential-english-words-149'),
	('The director interviewed dozens of applicants before he decided to hire Jen','Giám đốc đã phỏng vấn rất nhiều ứng cử viên trước khi quyết định thuê Jen','','','4000-essential-english-words-149'),
	('She was chosen because she was friendly, punctual and had a great attitude','Jen được chọn bởi cô ấy rất thân thiện, đúng giờ và có một thái độ tuyệt vời','','','4000-essential-english-words-149'),
	('On her first day, Jen got to work and prepared to give her first tour','Vào ngày đi làm đầu tiên, Jen phải làm việc và chuẩn bị cho chuyến đi đầu tiên','','','4000-essential-english-words-149'),
	('She looked at the names on the register','Cô nhìn vào các cái tên của những người đăng ký','','','4000-essential-english-words-149'),
	('She saw that the Queen of England and a diplomat were visiting the museum','Cô thấy Nữ hoàng Anh và một nhà ngoại giao đã đến thăm bảo tàng','','','4000-essential-english-words-149'),
	('She thought, "It\'s my very first day, and I have to impress a monarch"','Cô ấy nghĩ, "Đây là ngày làm việc đầu tiên của mình, và mình cần phải gây ấn tượng với nữ hoàng"','','','4000-essential-english-words-149'),
	('I hope I don\'t humiliate myself in front of a person of such renown"','"Mình hi vọng mình không làm bẽ mặt bản thân trước một người tiếng tăm lưng lẫy"','','','4000-essential-english-words-149'),
	('Jen was nervous','Jen rất lo lắng','','','4000-essential-english-words-149'),
	('She took a deep breath and said, "Hello, everyone"','Cô ấy hít một hơi dài rồi nói, "Xin chào mọi người"','','','4000-essential-english-words-149'),
	('"I\'m going to talk to you about the chronology of ancient Egypt"','"Hôm nay tôi sẽ giới thiệu cho mọi người bảng niên đại  của Ai Cập cổ đại"','','','4000-essential-english-words-149'),
	('As she turned around to show the group some artifacts, she bumped into a fossil of an authentic elephant tusk','Vì cô ấy quay lại đế chỉ cho cả nhóm một vài đồ tạo tác, cô ấy chạm vào một hoá thạch của một chiếc vòi voi thật','','','4000-essential-english-words-149'),
	('It fell to the ground and broke into a million pieces','Nó rơi xuống đất và vỡ thành hàng triệu mảnh nhỏ','','','4000-essential-english-words-149'),
	('"Oh no" said Jen in a subtle voice','"Ôi không" Jen khẽ kêu lên','','','4000-essential-english-words-149'),
	('"I sure hope the rest of the tour goes better than this"','"Tôi hi vọng chắc chắn phần còn lại của chuyến đi sẽ tốt hơn thế này"','','','4000-essential-english-words-149'),
	('The rest of the tour did not go any better','Nhưng không tốt hơn một chút nào cả','','','4000-essential-english-words-149'),
	('She tripped over an antique vase and broke a piece off of it','Cô ấy vướng chân vào một cái bình cổ và làm vỡ vụn nó','','','4000-essential-english-words-149'),
	('As she was reading an excerpt from a lyric poem, she sneezed and tore a page of the epic','Khi cô ấy đọc một trích đoạn từ một  bài thơ trữ tình , cô hắt xì và xé tan trang sử thi','','','4000-essential-english-words-149'),
	('After the tour, Jen approached the queen to apologize','Sau chuyến đi, Jen gặp Nữ hoàng để nói lời xin lỗi','','','4000-essential-english-words-149'),
	('She said, "I\'m sorry, your Majesty"','Cô nói, "Tôi xin lỗi thưa Nữ hoàng"','','','4000-essential-english-words-149'),
	('"I was a terrible tour guide"','"Tôi quả là một hướng dẫn viên tồi tệ"','','','4000-essential-english-words-149'),
	('"Let me give you a refund for the money you spent"','"Đế tôi trả lại số tiền mà Người đã phải bỏ ra"','','','4000-essential-english-words-149'),
	('The queen laughed','Nữ hoàng mỉm cười','','','4000-essential-english-words-149'),
	('She said, "I don\'t want my money back, Jen"','Nữ hoàng nói, "Ta không muốn lấy lại tiền, Jen"','','','4000-essential-english-words-149'),
	('"I loved the tour"','"Ta rất thích chuyến tham quan này"','','','4000-essential-english-words-149'),
	('"You just have to be a little more careful and work hard to become the best at your job"','"Cô chỉ cần cẩn thận hơn một chút và làm việc thật chăm chỉ đế làm tốt công việc của mình"','','','4000-essential-english-words-149'),
	('"Hard work precedes success"','"Chăm chỉ tới trước thành công"','','','4000-essential-english-words-149'),
	('Jen smiled and thanked the queen','Jen cười và cảm ơn Nữ hoàng','','','4000-essential-english-words-149'),
	('She decided to be extra careful from then on','Cô ấy quyết định cẩn thận hơn nhiều kế từ sau đó','','','4000-essential-english-words-149'),
	('She was persistent and worked hard','Cô ấy đã rất kiên trì và chăm chỉ','','','4000-essential-english-words-149'),
	('In time, Jen became the best tour guide at the museum','Đến giờ, Jen đã trở thành hướng dẫn viên giỏi nhất ở viện bảo tàng','','','4000-essential-english-words-149'),

	/* (UUID(),'4000-essential-english-words-150','The Demon\'s Bridge','Cầu quỷ','BOOKS_IELTS_BOOK_01_4000_ESSENTIAL_ENGLISH_WORDS_150.mp3',NULL,'','','4000-essential-english-words','NO',150) */
	('A young woman\'s cow had crossed the river in the morning when the water level was moderate','Vào một buổi sáng, con bò của người phụ nữ trẻ băng qua sông khi mà mực nước vẫn còn vừa phải','','','4000-essential-english-words-150'),
	('But when the woman returned with her dog to get the cow, she was overwhelmed by how high the water had risen','Nhưng khi cô quay lại cùng với con chó của mình để đón con bò về, cô ấy kinh ngạc bởi mực nước dâng quá cao','','','4000-essential-english-words-150'),
	('Even if she crossed, she still couldn\'t tow her cow back through the river','Ngay cả khi vượt qua sông, cô ấy cũng không thể kéo con bò qua lại được','','','4000-essential-english-words-150'),
	('"What am I going to do?" she wondered','"Mình phải làm gì bây giờ?" Cô thắc mắc','','','4000-essential-english-words-150'),
	('Suddenly, a man appeared across the river','Một người đàn ông đột nhiên xuất hiện ở bên kia sông','','','4000-essential-english-words-150'),
	('"A fragile young lady like you shouldn\'t have to struggle across a river," he said','"Một người phụ nữ trẻ yếu ớt như cô không nên cố vượt qua con sông như thế này," anh ta nói','','','4000-essential-english-words-150'),
	('"I\'ll build you a bridge"','"Tôi sẽ xây cho cô một cây cầu"','','','4000-essential-english-words-150'),
	('The man was an enigma','Người đàn ông này là một người kì lạ','','','4000-essential-english-words-150'),
	('The young woman\'s perception of him was that he was a sociable person','Cảm nhận của cô gái trẻ về anh ấy là một người dễ gần','','','4000-essential-english-words-150'),
	('He was talkative, yet something was strange about him','Anh ta hoạt ngôn, nhưng có gì đó là lạ về anh ta','','','4000-essential-english-words-150'),
	('"I don\'t want to be a burden to you, sir," the woman replied','"Tôi không muốn trở thành gánh nặng cho anh," Người phụ nữ đáp','','','4000-essential-english-words-150'),
	('"Don\'t worry," he told her as he began crafting a bridge','"Đừng lo," anh ta nói khi anh ta bắt đầu bắt tay xây một cây cầu','','','4000-essential-english-words-150'),
	('He merged the pieces of the bridge together with amazing speed','Anh ta hợp nhất các phần của cây cầu với một tốc độ đáng kinh ngạc','','','4000-essential-english-words-150'),
	('Soon, it was finished','Ngay sau đó, cây cầu đã hoàn thiện','','','4000-essential-english-words-150'),
	('"Oh, but how can I pay you for your work?" ','"Ồ, nhưng tôi phải trả công cho anh thế nào đây?"','','','4000-essential-english-words-150'),
	('"Let\'s compromise"','"Hãy thoả thuận một chút nào"','','','4000-essential-english-words-150'),
	('"I am sure that we can find a fair solution"','"Tôi chắc rằng chúng ta có thể tìm được một cách giải quyết công bằng"','','','4000-essential-english-words-150'),
	('"What do you think?" The woman asked','"Anh nghĩ sao?" người phụ nữ hỏi','','','4000-essential-english-words-150'),
	('"The only currency I need is the first living thing that crosses the bridge," the man replied','"Điều duy nhất tôi cần là một sinh vật sống đầu tiên đi qua cây cầu này," anh ta nói','','','4000-essential-english-words-150'),
	('She thought, "This deal sounds weird"','Cô nghĩ, "giao kèo này nghe thật kì quái"','','','4000-essential-english-words-150'),
	('"Maybe he\'s actually a river demon"','"Có lẽ anh ta thật ra là một con quỷ sông"','','','4000-essential-english-words-150'),
	('She shivered because she realized that he had taken advantage of her innocence and rigged the deal somehow','Cô ấy rùng mình vì cô nhận ra anh ta đã lợi dụng sự ngây thơ và dàn xếp thỏa thuận bằng một cách nào đó','','','4000-essential-english-words-150'),
	('But she had a plan of her own','Nhưng cô đã có kế hoạch của mình','','','4000-essential-english-words-150'),
	('She pulled a piece of bread from her pocket and threw it across the bridge','Cô lấy một mẩu bánh mì từ trong túi áo ra và ném qua cầu','','','4000-essential-english-words-150'),
	('Her dog ran after it','Con chó đuổi theo nó','','','4000-essential-english-words-150'),
	('"The dog is the first living thing across the bridge," she said to the man','"Con chó đó là vật sống đầu tiên băng qua cây cầu," cô ấy nói với người đàn ông kia','','','4000-essential-english-words-150'),
	('The man was angry','Hắn ta nổi giận','','','4000-essential-english-words-150'),
	('He suddenly changed into a hybrid of a human and a fish','Hắn bỗng nhiên biến thành một người lai cá','','','4000-essential-english-words-150'),
	('"You crook" he shouted','"Ngươi là kẻ lừa đảo," hắn quát lên','','','4000-essential-english-words-150'),
	('"You tricked me"','"Cô lừa ta"','','','4000-essential-english-words-150'),
	('"I have no use for your dog"','"Ta không cần con chó của cô"','','','4000-essential-english-words-150'),
	('He screamed and dove into the river','Anh ta hét to rồi lặn xuống sông','','','4000-essential-english-words-150'),
	('The woman tramped across the bridge to the other side and had a happy reunion with her dog and cow','Cô gái nhanh chóng bước qua qua cầu để sang bên kia sông và có cuộc đoàn tụ vui vẻ cùng con chó và bò của mình','','','4000-essential-english-words-150');

